//! Everything the app remembers between runs: projects, sessions (with their
//! messages) and settings. Saved as one JSON file in the user's data folder.

use serde::{Deserialize, Serialize};
use std::path::PathBuf;

pub fn now() -> i64 {
    chrono::Utc::now().timestamp()
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Project {
    pub id: u64,
    pub name: String,
    pub path: String,
}

#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq)]
pub enum Role {
    User,
    Assistant,
    Tool,
    Shell,
    Notice,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct ToolCall {
    pub id: String,
    pub name: String,
    /// Arguments as the JSON text the model sent.
    pub args: String,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Message {
    pub role: Role,
    pub text: String,
    #[serde(default)]
    pub tool_calls: Vec<ToolCall>,
    #[serde(default)]
    pub tool_call_id: String,
    #[serde(default)]
    pub tool_name: String,
    /// For tool and shell results: the short title shown in the timeline.
    #[serde(default)]
    pub title: String,
    #[serde(default = "yes")]
    pub ok: bool,
    #[serde(default)]
    pub agent: String,
    #[serde(default)]
    pub model: String,
    #[serde(default)]
    pub time: i64,
}

fn yes() -> bool {
    true
}

impl Message {
    pub fn new(role: Role, text: impl Into<String>) -> Self {
        Self {
            role,
            text: text.into(),
            tool_calls: vec![],
            tool_call_id: String::new(),
            tool_name: String::new(),
            title: String::new(),
            ok: true,
            agent: String::new(),
            model: String::new(),
            time: now(),
        }
    }
}

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
pub struct Todo {
    pub content: String,
    /// pending, in_progress, completed or cancelled
    pub status: String,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Session {
    pub id: u64,
    pub project_id: u64,
    pub title: String,
    pub created: i64,
    pub updated: i64,
    #[serde(default)]
    pub messages: Vec<Message>,
    #[serde(default = "build_agent")]
    pub agent: String,
    /// Prompt tokens of the latest request: how full the context is.
    #[serde(default)]
    pub context_tokens: u64,
    #[serde(default)]
    pub total_tokens: u64,
    #[serde(default)]
    pub cost: f64,
    #[serde(default)]
    pub todos: Vec<Todo>,
    #[serde(default)]
    pub changed_files: Vec<String>,
    #[serde(default)]
    pub unread: bool,
}

fn build_agent() -> String {
    "build".into()
}

#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq)]
pub enum Scheme {
    System,
    Light,
    Dark,
}

#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq)]
pub enum Perm {
    Allow,
    Ask,
    Deny,
}

impl Perm {
    pub fn label(self) -> &'static str {
        match self {
            Perm::Allow => "Allow",
            Perm::Ask => "Ask",
            Perm::Deny => "Deny",
        }
    }
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Perms {
    pub read: Perm,
    pub edit: Perm,
    pub list: Perm,
    pub glob: Perm,
    pub grep: Perm,
    pub bash: Perm,
    pub webfetch: Perm,
    pub todowrite: Perm,
    pub external_directory: Perm,
    pub doom_loop: Perm,
}

impl Default for Perms {
    fn default() -> Self {
        Self {
            read: Perm::Allow,
            edit: Perm::Ask,
            list: Perm::Allow,
            glob: Perm::Allow,
            grep: Perm::Allow,
            bash: Perm::Ask,
            webfetch: Perm::Ask,
            todowrite: Perm::Allow,
            external_directory: Perm::Ask,
            doom_loop: Perm::Ask,
        }
    }
}

impl Perms {
    pub fn get(&self, tool: &str) -> Perm {
        match tool {
            "read" => self.read,
            "edit" | "write" => self.edit,
            "list" => self.list,
            "glob" => self.glob,
            "grep" => self.grep,
            "bash" => self.bash,
            "webfetch" => self.webfetch,
            "todowrite" => self.todowrite,
            "external_directory" => self.external_directory,
            "doom_loop" => self.doom_loop,
            _ => Perm::Ask,
        }
    }
    pub fn rows(&mut self) -> Vec<(&'static str, &'static str, &mut Perm)> {
        vec![
            ("Read", "Reading a file", &mut self.read),
            ("Edit", "Modify files, including edits and writes", &mut self.edit),
            ("List", "List files within a folder", &mut self.list),
            ("Glob", "Match files using patterns", &mut self.glob),
            ("Grep", "Search file contents", &mut self.grep),
            ("Shell", "Run shell commands", &mut self.bash),
            ("Web Fetch", "Fetch content from a web address", &mut self.webfetch),
            ("Todo Write", "Update the todo list", &mut self.todowrite),
            ("Outside folder", "Access files outside the project folder", &mut self.external_directory),
            ("Repeat guard", "Repeated tool calls with identical input", &mut self.doom_loop),
        ]
    }
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Settings {
    pub base_url: String,
    pub api_key: String,
    pub models: Vec<String>,
    pub model: String,
    pub color_scheme: Scheme,
    pub zoom: f32,
    pub shell: String,
    pub auto_accept: bool,
    pub perms: Perms,
    /// Dollars per million input / output tokens, for the cost shown in the header.
    pub price_in: f64,
    pub price_out: f64,
    pub context_limit: u64,
    pub max_steps: u32,
}

impl Default for Settings {
    fn default() -> Self {
        Self {
            base_url: "https://api.openai.com/v1".into(),
            api_key: String::new(),
            models: vec!["gpt-4.1-mini".into(), "gpt-4.1".into(), "gpt-4o".into()],
            model: "gpt-4.1-mini".into(),
            color_scheme: Scheme::System,
            zoom: 1.0,
            shell: String::new(),
            auto_accept: false,
            perms: Perms::default(),
            price_in: 0.0,
            price_out: 0.0,
            context_limit: 128_000,
            max_steps: 50,
        }
    }
}

#[derive(Serialize, Deserialize, Clone, Debug, Default)]
pub struct Store {
    pub projects: Vec<Project>,
    pub sessions: Vec<Session>,
    #[serde(default)]
    pub settings: Settings,
    #[serde(default)]
    pub open_tabs: Vec<u64>,
    #[serde(default)]
    pub active_tab: Option<u64>,
    #[serde(default)]
    pub closed_tabs: Vec<u64>,
    #[serde(default)]
    pub next_id: u64,
}

pub fn data_file() -> PathBuf {
    let base = dirs::data_dir().unwrap_or_else(|| PathBuf::from("."));
    base.join("Codeloft").join("state.json")
}

impl Store {
    pub fn load() -> Self {
        let path = data_file();
        let mut store = std::fs::read_to_string(&path)
            .ok()
            .and_then(|t| serde_json::from_str::<Store>(&t).ok())
            .unwrap_or_else(Store::first_run);
        store.open_tabs.retain(|id| store.sessions.iter().any(|s| s.id == *id));
        if store.next_id == 0 {
            store.next_id = 1000;
        }
        store
    }

    /// The first time the app starts: one project (the Documents folder) and a
    /// welcome session that explains how to connect an AI service.
    fn first_run() -> Self {
        let docs = dirs::document_dir()
            .or_else(dirs::home_dir)
            .unwrap_or_else(|| PathBuf::from("."));
        let project = Project {
            id: 1,
            name: "My Documents".into(),
            path: docs.to_string_lossy().to_string(),
        };
        let t = now();
        let mut welcome = Session {
            id: 2,
            project_id: 1,
            title: "Welcome to Codeloft".into(),
            created: t,
            updated: t,
            messages: vec![],
            agent: "build".into(),
            context_tokens: 0,
            total_tokens: 0,
            cost: 0.0,
            todos: vec![],
            changed_files: vec![],
            unread: false,
        };
        welcome.messages.push(Message::new(Role::User, "What can you do?"));
        let mut a = Message::new(
            Role::Assistant,
            "I'm a coding assistant that works inside a project folder.\n\n\
**What I can do:**\n\
- Read, search and list the files in your project\n\
- Edit and create files (I ask before every change)\n\
- Run shell commands like `cargo build` or `npm test` (I ask first)\n\
- Keep a todo list while I work on bigger tasks\n\n\
**To get started:** open **Settings** (Ctrl+,) and enter your AI service address, \
API key and model. Any OpenAI-compatible service works, including local ones such as \
Ollama (`http://localhost:11434/v1`).\n\n\
Use **Build** to make changes, or switch to **Plan** (Ctrl+.) to only look and plan. \
Press Ctrl+Shift+X to type shell commands directly.",
        );
        a.agent = "build".into();
        welcome.messages.push(a);
        Store {
            projects: vec![project],
            sessions: vec![welcome],
            settings: Settings::default(),
            open_tabs: vec![2],
            active_tab: Some(2),
            closed_tabs: vec![],
            next_id: 1000,
        }
    }

    pub fn save(&self) {
        let path = data_file();
        if let Some(dir) = path.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        if let Ok(text) = serde_json::to_string_pretty(self) {
            let tmp = path.with_extension("json.tmp");
            if std::fs::write(&tmp, text).is_ok() {
                let _ = std::fs::rename(&tmp, &path);
            }
        }
    }

    pub fn new_id(&mut self) -> u64 {
        self.next_id += 1;
        self.next_id
    }

    pub fn session(&self, id: u64) -> Option<&Session> {
        self.sessions.iter().find(|s| s.id == id)
    }
    pub fn session_mut(&mut self, id: u64) -> Option<&mut Session> {
        self.sessions.iter_mut().find(|s| s.id == id)
    }
    pub fn project(&self, id: u64) -> Option<&Project> {
        self.projects.iter().find(|p| p.id == id)
    }
}

