//! The coding agent: talks to an OpenAI-compatible chat service, runs the
//! tools the model asks for (read, list, glob, grep, edit, write, bash,
//! webfetch, todowrite) inside the project folder, and asks the person for
//! permission where the settings say so. Runs on its own thread and reports
//! back through a channel.

use crate::store::{Message, Perm, Perms, Role, Todo, ToolCall};
use serde_json::{json, Value};
use std::collections::HashSet;
use std::io::Read;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::{channel, Receiver, RecvTimeoutError, Sender};
use std::sync::Arc;
use std::time::{Duration, Instant};

/// Longest tool output handed back to the model, in characters.
pub const MAX_OUTPUT: usize = 30_000;
/// Lines `read` returns when the model gives no limit.
pub const READ_DEFAULT_LIMIT: usize = 2000;
/// Longest line `read` returns before cutting it.
pub const READ_MAX_LINE: usize = 2000;
/// Most entries `list`, `glob` and `grep` return.
pub const LIST_LIMIT: usize = 100;
/// Shell commands stop after this many milliseconds unless the model asks for longer.
pub const BASH_DEFAULT_TIMEOUT_MS: u64 = 120_000;
pub const BASH_MAX_TIMEOUT_MS: u64 = 600_000;
/// The same call this many times in a row triggers the repeat guard.
pub const DOOM_LOOP_THRESHOLD: usize = 3;
/// Folders never listed or searched.
pub const IGNORED_DIRS: &[&str] = &[
    "node_modules", ".git", "target", "dist", "build", ".next", "__pycache__", ".venv", "vendor", ".idea", ".vscode",
];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PermReply {
    Once,
    Always,
    Deny,
}

pub struct PermissionRequest {
    pub tool: String,
    pub title: String,
    pub detail: String,
    pub reply: Sender<PermReply>,
}

pub enum AgentEvent {
    Assistant { text: String, tool_calls: Vec<ToolCall> },
    ToolResult { call_id: String, name: String, title: String, output: String, ok: bool },
    Permission(PermissionRequest),
    Usage { prompt: u64, completion: u64 },
    Todos(Vec<Todo>),
    FileChanged(String),
    Status(String),
    AlwaysAllowed(String),
    Compacted(String),
    Done,
    Error(String),
}

#[derive(Clone)]
pub struct RunConfig {
    pub base_url: String,
    pub api_key: String,
    pub model: String,
    pub agent: String,
    pub project_dir: PathBuf,
    pub perms: Perms,
    pub auto_accept: bool,
    pub always: HashSet<String>,
    pub shell: String,
    pub max_steps: u32,
    pub compact: bool,
}

pub struct Run {
    pub rx: Receiver<AgentEvent>,
    pub cancel: Arc<AtomicBool>,
}

pub fn spawn(cfg: RunConfig, history: Vec<Message>, ctx: eframe::egui::Context) -> Run {
    let (tx, rx) = channel();
    let cancel = Arc::new(AtomicBool::new(false));
    let c2 = cancel.clone();
    std::thread::spawn(move || {
        let tx2 = tx.clone();
        let ctx2 = ctx.clone();
        let send = move |e: AgentEvent| {
            let _ = tx2.send(e);
            ctx2.request_repaint();
        };
        let result = if cfg.compact { compact(&cfg, &history, &send) } else { run_loop(cfg, history, &c2, &send) };
        match result {
            Ok(()) => send(AgentEvent::Done),
            Err(e) => {
                if c2.load(Ordering::Relaxed) {
                    send(AgentEvent::Done)
                } else {
                    send(AgentEvent::Error(e))
                }
            }
        }
    });
    Run { rx, cancel }
}

fn system_prompt(cfg: &RunConfig) -> String {
    let os = std::env::consts::OS;
    let date = chrono::Local::now().format("%A %B %-d, %Y");
    let mode = if cfg.agent == "plan" {
        "You are in PLAN mode: look around, read and search, then explain a clear plan. \
         Do not edit or write files and do not run commands that change anything."
    } else {
        "You are in BUILD mode: make the changes the user asks for, verify them, and report briefly."
    };
    format!(
        "You are a careful, friendly coding assistant working inside the user's project folder.\n\
         {mode}\n\
         Project folder: {dir}\nPlatform: {os}\nToday: {date}\n\n\
         Use the tools to inspect files before changing them. Paths may be relative to the project folder. \
         Prefer `edit` for small changes and `write` for new files. Keep a todo list with `todowrite` for \
         tasks with several steps. Answer concisely in Markdown; the person may not be a programmer, so \
         explain results in plain words.",
        dir = cfg.project_dir.display()
    )
}

fn tool_specs(agent: &str) -> Value {
    let mut tools = vec![
        tool("read", "Read a text file. Returns numbered lines.", json!({
            "type":"object","properties":{
                "filePath":{"type":"string","description":"Path of the file"},
                "offset":{"type":"integer","description":"First line to read (0-based)"},
                "limit":{"type":"integer","description":"Number of lines to read"}},
            "required":["filePath"]})),
        tool("list", "List files and folders in a folder.", json!({
            "type":"object","properties":{"path":{"type":"string","description":"Folder (default: project folder)"}}})),
        tool("glob", "Find files whose path matches a pattern such as **/*.rs.", json!({
            "type":"object","properties":{"pattern":{"type":"string"},"path":{"type":"string"}},"required":["pattern"]})),
        tool("grep", "Search file contents with a regular expression.", json!({
            "type":"object","properties":{"pattern":{"type":"string"},"path":{"type":"string"},
                "include":{"type":"string","description":"File pattern to include, e.g. *.ts"}},"required":["pattern"]})),
        tool("webfetch", "Fetch a web page or file over http(s) and return its text.", json!({
            "type":"object","properties":{"url":{"type":"string"}},"required":["url"]})),
        tool("todowrite", "Replace the todo list shown to the user.", json!({
            "type":"object","properties":{"todos":{"type":"array","items":{"type":"object","properties":{
                "content":{"type":"string"},"status":{"type":"string","enum":["pending","in_progress","completed","cancelled"]}},
                "required":["content","status"]}}},"required":["todos"]})),
        tool("bash", "Run a shell command in the project folder and return its output.", json!({
            "type":"object","properties":{"command":{"type":"string"},
                "description":{"type":"string","description":"5-10 words saying what it does"},
                "timeout":{"type":"integer","description":"Milliseconds, at most 600000"}},"required":["command"]})),
    ];
    if agent != "plan" {
        tools.push(tool("edit", "Replace exact text in a file. oldString must appear exactly once unless replaceAll is true.", json!({
            "type":"object","properties":{"filePath":{"type":"string"},"oldString":{"type":"string"},
                "newString":{"type":"string"},"replaceAll":{"type":"boolean"}},"required":["filePath","oldString","newString"]})));
        tools.push(tool("write", "Create or overwrite a file with the given content.", json!({
            "type":"object","properties":{"filePath":{"type":"string"},"content":{"type":"string"}},"required":["filePath","content"]})));
    }
    Value::Array(tools)
}

fn tool(name: &str, desc: &str, params: Value) -> Value {
    json!({"type":"function","function":{"name":name,"description":desc,"parameters":params}})
}

/// Turn the session's messages into the chat format the service expects.
fn to_wire(history: &[Message]) -> Vec<Value> {
    let mut out = vec![];
    let mut open_calls: HashSet<String> = HashSet::new();
    for m in history {
        match m.role {
            Role::User => out.push(json!({"role":"user","content":m.text})),
            Role::Assistant => {
                if m.tool_calls.is_empty() {
                    out.push(json!({"role":"assistant","content":m.text}));
                } else {
                    let calls: Vec<Value> = m
                        .tool_calls
                        .iter()
                        .map(|c| {
                            open_calls.insert(c.id.clone());
                            json!({"id":c.id,"type":"function","function":{"name":c.name,"arguments":c.args}})
                        })
                        .collect();
                    let content = if m.text.is_empty() { Value::Null } else { Value::String(m.text.clone()) };
                    out.push(json!({"role":"assistant","content":content,"tool_calls":calls}));
                }
            }
            Role::Tool => {
                if open_calls.remove(&m.tool_call_id) {
                    out.push(json!({"role":"tool","tool_call_id":m.tool_call_id,"content":m.text}));
                }
            }
            Role::Shell => out.push(json!({"role":"user","content":
                format!("I ran this shell command myself:\n$ {}\n\nOutput:\n{}", m.title, m.text)})),
            Role::Notice => {}
        }
    }
    // A run stopped half-way can leave calls without answers; close them so the service accepts the history.
    let mut fixed = vec![];
    let mut pending: Vec<String> = vec![];
    for v in out {
        let role = v["role"].as_str().unwrap_or("").to_string();
        if role != "tool" && !pending.is_empty() {
            for id in pending.drain(..) {
                fixed.push(json!({"role":"tool","tool_call_id":id,"content":"(interrupted)"}));
            }
        }
        if role == "tool" {
            let id = v["tool_call_id"].as_str().unwrap_or("").to_string();
            pending.retain(|p| *p != id);
        }
        if let Some(calls) = v["tool_calls"].as_array() {
            for c in calls {
                pending.push(c["id"].as_str().unwrap_or("").to_string());
            }
        }
        fixed.push(v);
    }
    for id in pending {
        fixed.push(json!({"role":"tool","tool_call_id":id,"content":"(interrupted)"}));
    }
    fixed
}

fn chat(cfg: &RunConfig, messages: &[Value], tools: Option<&Value>) -> Result<Value, String> {
    if cfg.base_url.trim().is_empty() {
        return Err("No AI service is set. Open Settings and enter the service address, API key and model.".into());
    }
    let url = format!("{}/chat/completions", cfg.base_url.trim().trim_end_matches('/'));
    let mut body = json!({"model": cfg.model, "messages": messages});
    if let Some(t) = tools {
        body["tools"] = t.clone();
    }
    let mut req = ureq::post(&url)
        .config()
        .http_status_as_error(false)
        .timeout_global(Some(Duration::from_secs(600)))
        .build()
        .header("Content-Type", "application/json");
    if !cfg.api_key.trim().is_empty() {
        req = req.header("Authorization", &format!("Bearer {}", cfg.api_key.trim()));
    }
    let mut resp = req.send_json(&body).map_err(|e| format!("Couldn't reach the AI service: {e}"))?;
    let status = resp.status().as_u16();
    let text = resp.body_mut().read_to_string().map_err(|e| format!("Couldn't read the answer: {e}"))?;
    if status >= 400 {
        let msg = serde_json::from_str::<Value>(&text)
            .ok()
            .and_then(|v| v["error"]["message"].as_str().map(String::from))
            .unwrap_or_else(|| text.chars().take(400).collect());
        return Err(format!("The AI service answered {status}: {msg}"));
    }
    serde_json::from_str(&text).map_err(|e| format!("The answer wasn't readable ({e})"))
}

fn compact(cfg: &RunConfig, history: &[Message], send: &dyn Fn(AgentEvent)) -> Result<(), String> {
    send(AgentEvent::Status("Summarizing the session".into()));
    let mut msgs = vec![json!({"role":"system","content":
        "Summarize the conversation so far so the work can continue from the summary alone: the goal, \
         what was done, which files matter, decisions made and what is left to do. Be specific and brief."})];
    msgs.extend(to_wire(history));
    msgs.push(json!({"role":"user","content":"Write the summary now."}));
    let v = chat(cfg, &msgs, None)?;
    usage(&v, send);
    let text = v["choices"][0]["message"]["content"].as_str().unwrap_or("").to_string();
    send(AgentEvent::Compacted(text));
    Ok(())
}

fn usage(v: &Value, send: &dyn Fn(AgentEvent)) {
    if let Some(u) = v.get("usage") {
        send(AgentEvent::Usage {
            prompt: u["prompt_tokens"].as_u64().unwrap_or(0),
            completion: u["completion_tokens"].as_u64().unwrap_or(0),
        });
    }
}

fn run_loop(mut cfg: RunConfig, mut history: Vec<Message>, cancel: &AtomicBool, send: &dyn Fn(AgentEvent)) -> Result<(), String> {
    let tools = tool_specs(&cfg.agent);
    let mut recent: Vec<String> = vec![];
    for step in 0..cfg.max_steps.max(1) {
        if cancel.load(Ordering::Relaxed) {
            return Ok(());
        }
        send(AgentEvent::Status(if step == 0 { "Thinking".into() } else { "Considering next steps".into() }));
        let mut msgs = vec![json!({"role":"system","content":system_prompt(&cfg)})];
        msgs.extend(to_wire(&history));
        let v = chat(&cfg, &msgs, Some(&tools))?;
        if cancel.load(Ordering::Relaxed) {
            return Ok(());
        }
        usage(&v, send);
        let m = &v["choices"][0]["message"];
        let text = m["content"].as_str().unwrap_or("").trim().to_string();
        let calls: Vec<ToolCall> = m["tool_calls"]
            .as_array()
            .map(|a| {
                a.iter()
                    .enumerate()
                    .map(|(i, c)| ToolCall {
                        id: c["id"].as_str().map(String::from).unwrap_or_else(|| format!("call_{step}_{i}")),
                        name: c["function"]["name"].as_str().unwrap_or("").to_string(),
                        args: match &c["function"]["arguments"] {
                            Value::String(s) => s.clone(),
                            other => other.to_string(),
                        },
                    })
                    .collect()
            })
            .unwrap_or_default();
        send(AgentEvent::Assistant { text: text.clone(), tool_calls: calls.clone() });
        let mut am = Message::new(Role::Assistant, text);
        am.tool_calls = calls.clone();
        history.push(am);
        if calls.is_empty() {
            return Ok(());
        }
        for call in calls {
            if cancel.load(Ordering::Relaxed) {
                return Ok(());
            }
            let key = format!("{}:{}", call.name, call.args);
            recent.push(key.clone());
            let repeated = recent.len() >= DOOM_LOOP_THRESHOLD
                && recent[recent.len() - DOOM_LOOP_THRESHOLD..].iter().all(|k| *k == key);
            let args: Value = serde_json::from_str(&call.args).unwrap_or(json!({}));
            let (title, output, ok) = execute(&mut cfg, &call.name, &args, repeated, cancel, send);
            let mut tm = Message::new(Role::Tool, output.clone());
            tm.tool_call_id = call.id.clone();
            tm.tool_name = call.name.clone();
            history.push(tm);
            send(AgentEvent::ToolResult { call_id: call.id, name: call.name, title, output, ok });
        }
    }
    send(AgentEvent::Error(format!("Stopped after {} steps. Send a message to continue.", cfg.max_steps)));
    Ok(())
}

/// Ask the person (unless settings already decide). Returns true when allowed.
fn permit(cfg: &mut RunConfig, tool: &str, title: &str, detail: &str, cancel: &AtomicBool, send: &dyn Fn(AgentEvent)) -> Result<(), String> {
    let level = cfg.perms.get(tool);
    if level == Perm::Deny {
        return Err(format!("The {tool} tool is turned off in Settings → Permissions."));
    }
    if level == Perm::Allow || cfg.auto_accept || cfg.always.contains(tool) {
        return Ok(());
    }
    let (rtx, rrx) = channel();
    send(AgentEvent::Permission(PermissionRequest {
        tool: tool.into(),
        title: title.into(),
        detail: detail.into(),
        reply: rtx,
    }));
    loop {
        match rrx.recv_timeout(Duration::from_millis(200)) {
            Ok(PermReply::Once) => return Ok(()),
            Ok(PermReply::Always) => {
                cfg.always.insert(tool.into());
                send(AgentEvent::AlwaysAllowed(tool.into()));
                return Ok(());
            }
            Ok(PermReply::Deny) => return Err("The user rejected this. Ask what to do instead.".into()),
            Err(RecvTimeoutError::Timeout) => {
                if cancel.load(Ordering::Relaxed) {
                    return Err("Interrupted".into());
                }
            }
            Err(RecvTimeoutError::Disconnected) => return Err("Interrupted".into()),
        }
    }
}

fn resolve(cfg: &RunConfig, p: &str) -> PathBuf {
    let p = p.trim();
    let path = Path::new(p);
    let full = if p.is_empty() { cfg.project_dir.clone() } else if path.is_absolute() { path.to_path_buf() } else { cfg.project_dir.join(path) };
    normalize(&full)
}

fn normalize(p: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in p.components() {
        match c {
            std::path::Component::ParentDir => {
                out.pop();
            }
            std::path::Component::CurDir => {}
            other => out.push(other.as_os_str()),
        }
    }
    out
}

pub fn rel(cfg_dir: &Path, p: &Path) -> String {
    p.strip_prefix(cfg_dir).map(|r| r.to_string_lossy().replace('\\', "/")).unwrap_or_else(|_| p.to_string_lossy().to_string())
}

fn inside(cfg: &RunConfig, p: &Path) -> bool {
    p.starts_with(normalize(&cfg.project_dir))
}

fn cut(mut s: String, max: usize) -> String {
    if s.chars().count() > max {
        s = s.chars().take(max).collect::<String>() + "\n\n(output truncated)";
    }
    s
}

fn execute(cfg: &mut RunConfig, name: &str, a: &Value, repeated: bool, cancel: &AtomicBool, send: &dyn Fn(AgentEvent)) -> (String, String, bool) {
    let s = |k: &str| a[k].as_str().unwrap_or("").to_string();
    let path_arg = if a["filePath"].is_string() { s("filePath") } else { s("path") };
    let target = resolve(cfg, &path_arg);
    let shown = rel(&cfg.project_dir, &target);
    let title = match name {
        "bash" => s("command"),
        "glob" | "grep" => s("pattern"),
        "webfetch" => s("url"),
        "todowrite" => "Updated todos".into(),
        _ => if shown.is_empty() { ".".into() } else { shown.clone() },
    };
    let fail = |msg: String| (title.clone(), msg, false);

    if repeated {
        if let Err(e) = permit(cfg, "doom_loop", "Same call repeated", &format!("{name} was called {DOOM_LOOP_THRESHOLD} times with the same input"), cancel, send) {
            return fail(e);
        }
    }
    let touches_path = matches!(name, "read" | "list" | "glob" | "grep" | "edit" | "write");
    if touches_path && !inside(cfg, &target) {
        if let Err(e) = permit(cfg, "external_directory", "Outside the project folder", &target.display().to_string(), cancel, send) {
            return fail(e);
        }
    }
    if cfg.agent == "plan" && matches!(name, "edit" | "write") {
        return fail("Plan mode can't change files. Switch to Build to make changes.".into());
    }
    let detail = match name {
        "edit" => format!("Edit {shown}"),
        "write" => format!("Write {shown}"),
        "bash" => format!("$ {}", s("command")),
        "webfetch" => format!("Fetch {}", s("url")),
        _ => format!("{name} {shown}"),
    };
    let perm_tool = if name == "write" { "edit" } else { name };
    if let Err(e) = permit(cfg, perm_tool, &tool_label(name), &detail, cancel, send) {
        return fail(e);
    }

    let result: Result<String, String> = match name {
        "read" => read_file(&target, a["offset"].as_u64().unwrap_or(0) as usize, a["limit"].as_u64().map(|v| v as usize).unwrap_or(READ_DEFAULT_LIMIT)),
        "list" => list_dir(&target),
        "glob" => glob(&target, &s("pattern"), &cfg.project_dir),
        "grep" => grep(&target, &s("pattern"), &s("include"), &cfg.project_dir),
        "write" => {
            let content = s("content");
            if let Some(d) = target.parent() {
                let _ = std::fs::create_dir_all(d);
            }
            std::fs::write(&target, &content)
                .map(|_| {
                    send(AgentEvent::FileChanged(shown.clone()));
                    format!("Wrote {} lines to {shown}", content.lines().count())
                })
                .map_err(|e| format!("Couldn't write {shown}: {e}"))
        }
        "edit" => edit_file(&target, &s("oldString"), &s("newString"), a["replaceAll"].as_bool().unwrap_or(false)).map(|r| {
            send(AgentEvent::FileChanged(shown.clone()));
            r
        }),
        "bash" => {
            let t = a["timeout"].as_u64().unwrap_or(BASH_DEFAULT_TIMEOUT_MS).min(BASH_MAX_TIMEOUT_MS);
            send(AgentEvent::Status("Running commands".into()));
            run_shell(&cfg.shell, &s("command"), &cfg.project_dir, t, cancel).map(|(out, code)| {
                if code == 0 { out } else { format!("{out}\n\nCommand exited with code {code}") }
            })
        }
        "webfetch" => webfetch(&s("url")),
        "todowrite" => {
            let todos: Vec<Todo> = a["todos"]
                .as_array()
                .map(|arr| {
                    arr.iter()
                        .map(|t| Todo {
                            content: t["content"].as_str().unwrap_or("").into(),
                            status: t["status"].as_str().unwrap_or("pending").into(),
                        })
                        .collect()
                })
                .unwrap_or_default();
            let n = todos.len();
            send(AgentEvent::Todos(todos));
            Ok(format!("Todo list updated ({n} items)"))
        }
        other => Err(format!("Unknown tool: {other}")),
    };
    match result {
        Ok(out) => (title, cut(out, MAX_OUTPUT), true),
        Err(e) => fail(e),
    }
}

pub fn tool_label(name: &str) -> String {
    match name {
        "read" => "Read",
        "list" => "List",
        "glob" => "Glob",
        "grep" => "Grep",
        "edit" => "Edit",
        "write" => "Write",
        "bash" => "Shell",
        "webfetch" => "Webfetch",
        "todowrite" => "Todos",
        "doom_loop" => "Repeat guard",
        "external_directory" => "Outside folder",
        other => other,
    }
    .to_string()
}

fn read_file(p: &Path, offset: usize, limit: usize) -> Result<String, String> {
    let bytes = std::fs::read(p).map_err(|e| format!("Couldn't read {}: {e}", p.display()))?;
    if bytes.iter().take(8000).any(|b| *b == 0) {
        return Err("That file is binary, not text.".into());
    }
    let text = String::from_utf8_lossy(&bytes);
    let lines: Vec<&str> = text.lines().collect();
    let mut out = String::new();
    for (i, line) in lines.iter().enumerate().skip(offset).take(limit) {
        let l: String = line.chars().take(READ_MAX_LINE).collect();
        out.push_str(&format!("{:05}| {}\n", i + 1, l));
    }
    if offset + limit < lines.len() {
        out.push_str(&format!("\n(File has more lines. Use offset {} to read further.)", offset + limit));
    }
    if out.is_empty() {
        out = "(empty file)".into();
    }
    Ok(out)
}

pub fn ignored(name: &str) -> bool {
    IGNORED_DIRS.contains(&name)
}

fn list_dir(p: &Path) -> Result<String, String> {
    let mut entries: Vec<(bool, String)> = std::fs::read_dir(p)
        .map_err(|e| format!("Couldn't list {}: {e}", p.display()))?
        .filter_map(|e| e.ok())
        .map(|e| (e.path().is_dir(), e.file_name().to_string_lossy().to_string()))
        .filter(|(_, n)| !ignored(n))
        .collect();
    entries.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.to_lowercase().cmp(&b.1.to_lowercase())));
    let total = entries.len();
    let mut out: Vec<String> = entries.into_iter().take(LIST_LIMIT).map(|(d, n)| if d { format!("{n}/") } else { n }).collect();
    if total > LIST_LIMIT {
        out.push(format!("… and {} more", total - LIST_LIMIT));
    }
    Ok(if out.is_empty() { "(empty folder)".into() } else { out.join("\n") })
}

/// Glob pattern (`*`, `**`, `?`) to a regular expression.
fn glob_regex(pattern: &str) -> Option<regex::Regex> {
    let mut re = String::from("(?i)^");
    let chars: Vec<char> = pattern.replace('\\', "/").chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '*' if i + 1 < chars.len() && chars[i + 1] == '*' => {
                re.push_str(".*");
                i += 1;
                if i + 1 < chars.len() && chars[i + 1] == '/' {
                    i += 1;
                    re.push_str("/?");
                }
            }
            '*' => re.push_str("[^/]*"),
            '?' => re.push_str("[^/]"),
            '{' => re.push('('),
            '}' => re.push(')'),
            ',' => re.push('|'),
            c => re.push_str(&regex::escape(&c.to_string())),
        }
        i += 1;
    }
    re.push('$');
    regex::Regex::new(&re).ok()
}

fn walk(root: &Path) -> impl Iterator<Item = walkdir::DirEntry> {
    walkdir::WalkDir::new(root)
        .into_iter()
        .filter_entry(|e| e.depth() == 0 || !ignored(&e.file_name().to_string_lossy()))
        .filter_map(|e| e.ok())
        .filter(|e| e.file_type().is_file())
}

fn glob(root: &Path, pattern: &str, project: &Path) -> Result<String, String> {
    let re = glob_regex(pattern).ok_or("That pattern isn't valid.")?;
    let has_slash = pattern.contains('/');
    let mut hits = vec![];
    for e in walk(root) {
        let r = rel(root, e.path());
        let name = e.file_name().to_string_lossy().to_string();
        if re.is_match(&r) || (!has_slash && re.is_match(&name)) {
            hits.push(rel(project, e.path()));
            if hits.len() >= LIST_LIMIT {
                hits.push("(more results not shown)".into());
                break;
            }
        }
    }
    Ok(if hits.is_empty() { "No files found".into() } else { hits.join("\n") })
}

fn grep(root: &Path, pattern: &str, include: &str, project: &Path) -> Result<String, String> {
    let re = regex::Regex::new(pattern).map_err(|e| format!("That pattern isn't valid: {e}"))?;
    let inc = if include.is_empty() { None } else { glob_regex(include) };
    let mut hits = vec![];
    'files: for e in walk(root) {
        if let Some(inc) = &inc {
            if !inc.is_match(&e.file_name().to_string_lossy()) {
                continue;
            }
        }
        if e.metadata().map(|m| m.len() > 5_000_000).unwrap_or(true) {
            continue;
        }
        let Ok(text) = std::fs::read_to_string(e.path()) else { continue };
        for (i, line) in text.lines().enumerate() {
            if re.is_match(line) {
                let l: String = line.trim().chars().take(200).collect();
                hits.push(format!("{}:{}: {}", rel(project, e.path()), i + 1, l));
                if hits.len() >= LIST_LIMIT {
                    hits.push("(more matches not shown)".into());
                    break 'files;
                }
            }
        }
    }
    Ok(if hits.is_empty() { "No matches found".into() } else { hits.join("\n") })
}

fn edit_file(p: &Path, old: &str, new: &str, all: bool) -> Result<String, String> {
    if old.is_empty() {
        if p.exists() {
            return Err("oldString is empty but the file already exists; use write to replace it.".into());
        }
        if let Some(d) = p.parent() {
            let _ = std::fs::create_dir_all(d);
        }
        std::fs::write(p, new).map_err(|e| e.to_string())?;
        return Ok("Created the file".into());
    }
    let text = std::fs::read_to_string(p).map_err(|e| format!("Couldn't read {}: {e}", p.display()))?;
    // Files saved on Windows may use CRLF; match either way.
    let crlf = text.contains("\r\n");
    let (old2, new2) = if crlf && !old.contains("\r\n") {
        (old.replace('\n', "\r\n"), new.replace('\n', "\r\n"))
    } else {
        (old.to_string(), new.to_string())
    };
    let count = text.matches(&old2).count();
    if count == 0 {
        return Err("oldString was not found in the file. Read the file again and copy the text exactly.".into());
    }
    if count > 1 && !all {
        return Err(format!("oldString appears {count} times. Give more surrounding text or set replaceAll."));
    }
    let out = if all { text.replace(&old2, &new2) } else { text.replacen(&old2, &new2, 1) };
    std::fs::write(p, out).map_err(|e| e.to_string())?;
    Ok(format!("Edited the file ({count} replacement{})", if count == 1 { "" } else { "s" }))
}

pub fn shell_program(pref: &str) -> (String, Vec<String>) {
    let pref = pref.trim();
    if !pref.is_empty() {
        let lower = pref.to_lowercase();
        if lower.contains("powershell") || lower.contains("pwsh") {
            return (pref.into(), vec!["-NoProfile".into(), "-Command".into()]);
        }
        if lower.ends_with("cmd") || lower.ends_with("cmd.exe") {
            return (pref.into(), vec!["/C".into()]);
        }
        return (pref.into(), vec!["-c".into()]);
    }
    if cfg!(windows) {
        ("powershell".into(), vec!["-NoProfile".into(), "-ExecutionPolicy".into(), "Bypass".into(), "-Command".into()])
    } else {
        ("sh".into(), vec!["-c".into()])
    }
}

/// Run one command; returns combined output and the exit code.
pub fn run_shell(shell: &str, command: &str, dir: &Path, timeout_ms: u64, cancel: &AtomicBool) -> Result<(String, i32), String> {
    let (prog, mut args) = shell_program(shell);
    args.push(command.to_string());
    let mut cmd = std::process::Command::new(&prog);
    cmd.args(&args)
        .current_dir(dir)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        cmd.creation_flags(0x0800_0000); // no console window
    }
    let mut child = cmd.spawn().map_err(|e| format!("Couldn't start {prog}: {e}"))?;
    let mut so = child.stdout.take().unwrap();
    let mut se = child.stderr.take().unwrap();
    let t1 = std::thread::spawn(move || {
        let mut v = vec![];
        let _ = so.read_to_end(&mut v);
        v
    });
    let t2 = std::thread::spawn(move || {
        let mut v = vec![];
        let _ = se.read_to_end(&mut v);
        v
    });
    let start = Instant::now();
    let mut note = String::new();
    let code = loop {
        if let Ok(Some(st)) = child.try_wait() {
            break st.code().unwrap_or(-1);
        }
        if cancel.load(Ordering::Relaxed) {
            let _ = child.kill();
            note = "\n\nCommand cancelled".into();
            break -1;
        }
        if start.elapsed() > Duration::from_millis(timeout_ms) {
            let _ = child.kill();
            note = format!("\n\nCommand timed out after {} s", timeout_ms / 1000);
            break -1;
        }
        std::thread::sleep(Duration::from_millis(50));
    };
    let out = t1.join().unwrap_or_default();
    let err = t2.join().unwrap_or_default();
    let mut text = String::from_utf8_lossy(&out).to_string();
    let e = String::from_utf8_lossy(&err);
    if !e.trim().is_empty() {
        if !text.is_empty() {
            text.push('\n');
        }
        text.push_str(&e);
    }
    text.push_str(&note);
    if text.trim().is_empty() {
        text = "(no output)".into();
    }
    Ok((cut(text, MAX_OUTPUT), code))
}

fn webfetch(url: &str) -> Result<String, String> {
    if !(url.starts_with("http://") || url.starts_with("https://")) {
        return Err("Only http and https addresses can be fetched.".into());
    }
    let mut r = ureq::get(url)
        .config()
        .timeout_global(Some(Duration::from_secs(30)))
        .build()
        .call()
        .map_err(|e| format!("Couldn't fetch {url}: {e}"))?;
    let text = r.body_mut().read_to_string().map_err(|e| e.to_string())?;
    let stripped = if text.contains("<html") || text.contains("<body") { strip_html(&text) } else { text };
    Ok(cut(stripped, 50_000))
}

fn strip_html(s: &str) -> String {
    let no_script = regex::Regex::new(r"(?is)<(script|style)[^>]*>.*?</(script|style)>").unwrap().replace_all(s, "");
    let tags = regex::Regex::new(r"(?s)<[^>]+>").unwrap().replace_all(&no_script, " ");
    let ws = regex::Regex::new(r"[ \t]+").unwrap().replace_all(&tags, " ");
    let nl = regex::Regex::new(r"\n\s*\n+").unwrap().replace_all(&ws, "\n\n");
    nl.replace("&nbsp;", " ").replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">").replace("&quot;", "\"")
}

toolUseResult.content:
//! The coding agent: talks to an OpenAI-compatible chat service, runs the
//! tools the model asks for (read, list, glob, grep, edit, write, bash,
//! webfetch, todowrite) inside the project folder, and asks the person for
//! permission where the settings say so. Runs on its own thread and reports
//! back through a channel.

use crate::store::{Message, Perm, Perms, Role, Todo, ToolCall};
use serde_json::{json, Value};
use std::collections::HashSet;
use std::io::Read;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::{channel, Receiver, RecvTimeoutError, Sender};
use std::sync::Arc;
use std::time::{Duration, Instant};

/// Longest tool output handed back to the model, in characters.
pub const MAX_OUTPUT: usize = 30_000;
/// Lines `read` returns when the model gives no limit.
pub const READ_DEFAULT_LIMIT: usize = 2000;
/// Longest line `read` returns before cutting it.
pub const READ_MAX_LINE: usize = 2000;
/// Most entries `list`, `glob` and `grep` return.
pub const LIST_LIMIT: usize = 100;
/// Shell commands stop after this many milliseconds unless the model asks for longer.
pub const BASH_DEFAULT_TIMEOUT_MS: u64 = 120_000;
pub const BASH_MAX_TIMEOUT_MS: u64 = 600_000;
/// The same call this many times in a row triggers the repeat guard.
pub const DOOM_LOOP_THRESHOLD: usize = 3;
/// Folders never listed or searched.
pub const IGNORED_DIRS: &[&str] = &[
    "node_modules", ".git", "target", "dist", "build", ".next", "__pycache__", ".venv", "vendor", ".idea", ".vscode",
];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PermReply {
    Once,
    Always,
    Deny,
}

pub struct PermissionRequest {
    pub tool: String,
    pub title: String,
    pub detail: String,
    pub reply: Sender<PermReply>,
}

pub enum AgentEvent {
    Assistant { text: String, tool_calls: Vec<ToolCall> },
    ToolResult { call_id: String, name: String, title: String, output: String, ok: bool },
    Permission(PermissionRequest),
    Usage { prompt: u64, completion: u64 },
    Todos(Vec<Todo>),
    FileChanged(String),
    Status(String),
    AlwaysAllowed(String),
    Compacted(String),
    Done,
    Error(String),
}

#[derive(Clone)]
pub struct RunConfig {
    pub base_url: String,
    pub api_key: String,
    pub model: String,
    pub agent: String,
    pub project_dir: PathBuf,
    pub perms: Perms,
    pub auto_accept: bool,
    pub always: HashSet<String>,
    pub shell: String,
    pub max_steps: u32,
    pub compact: bool,
}

pub struct Run {
    pub rx: Receiver<AgentEvent>,
    pub cancel: Arc<AtomicBool>,
}

pub fn spawn(cfg: RunConfig, history: Vec<Message>, ctx: eframe::egui::Context) -> Run {
    let (tx, rx) = channel();
    let cancel = Arc::new(AtomicBool::new(false));
    let c2 = cancel.clone();
    std::thread::spawn(move || {
        let tx2 = tx.clone();
        let ctx2 = ctx.clone();
        let send = move |e: AgentEvent| {
            let _ = tx2.send(e);
            ctx2.request_repaint();
        };
        let result = if cfg.compact { compact(&cfg, &history, &send) } else { run_loop(cfg, history, &c2, &send) };
        match result {
            Ok(()) => send(AgentEvent::Done),
            Err(e) => {
                if c2.load(Ordering::Relaxed) {
                    send(AgentEvent::Done)
                } else {
                    send(AgentEvent::Error(e))
                }
            }
        }
    });
    Run { rx, cancel }
}

fn system_prompt(cfg: &RunConfig) -> String {
    let os = std::env::consts::OS;
    let date = chrono::Local::now().format("%A %B %-d, %Y");
    let mode = if cfg.agent == "plan" {
        "You are in PLAN mode: look around, read and search, then explain a clear plan. \
         Do not edit or write files and do not run commands that change anything."
    } else {
        "You are in BUILD mode: make the changes the user asks for, verify them, and report briefly."
    };
    format!(
        "You are a careful, friendly coding assistant working inside the user's project folder.\n\
         {mode}\n\
         Project folder: {dir}\nPlatform: {os}\nToday: {date}\n\n\
         Use the tools to inspect files before changing them. Paths may be relative to the project folder. \
         Prefer `edit` for small changes and `write` for new files. Keep a todo list with `todowrite` for \
         tasks with several steps. Answer concisely in Markdown; the person may not be a programmer, so \
         explain results in plain words.",
        dir = cfg.project_dir.display()
    )
}

fn tool_specs(agent: &str) -> Value {
    let mut tools = vec![
        tool("read", "Read a text file. Returns numbered lines.", json!({
            "type":"object","properties":{
                "filePath":{"type":"string","description":"Path of the file"},
                "offset":{"type":"integer","description":"First line to read (0-based)"},
                "limit":{"type":"integer","description":"Number of lines to read"}},
            "required":["filePath"]})),
        tool("list", "List files and folders in a folder.", json!({
            "type":"object","properties":{"path":{"type":"string","description":"Folder (default: project folder)"}}})),
        tool("glob", "Find files whose path matches a pattern such as **/*.rs.", json!({
            "type":"object","properties":{"pattern":{"type":"string"},"path":{"type":"string"}},"required":["pattern"]})),
        tool("grep", "Search file contents with a regular expression.", json!({
            "type":"object","properties":{"pattern":{"type":"string"},"path":{"type":"string"},
                "include":{"type":"string","description":"File pattern to include, e.g. *.ts"}},"required":["pattern"]})),
        tool("webfetch", "Fetch a web page or file over http(s) and return its text.", json!({
            "type":"object","properties":{"url":{"type":"string"}},"required":["url"]})),
        tool("todowrite", "Replace the todo list shown to the user.", json!({
            "type":"object","properties":{"todos":{"type":"array","items":{"type":"object","properties":{
                "content":{"type":"string"},"status":{"type":"string","enum":["pending","in_progress","completed","cancelled"]}},
                "required":["content","status"]}}},"required":["todos"]})),
        tool("bash", "Run a shell command in the project folder and return its output.", json!({
            "type":"object","properties":{"command":{"type":"string"},
                "description":{"type":"string","description":"5-10 words saying what it does"},
                "timeout":{"type":"integer","description":"Milliseconds, at most 600000"}},"required":["command"]})),
    ];
    if agent != "plan" {
        tools.push(tool("edit", "Replace exact text in a file. oldString must appear exactly once unless replaceAll is true.", json!({
            "type":"object","properties":{"filePath":{"type":"string"},"oldString":{"type":"string"},
                "newString":{"type":"string"},"replaceAll":{"type":"boolean"}},"required":["filePath","oldString","newString"]})));
        tools.push(tool("write", "Create or overwrite a file with the given content.", json!({
            "type":"object","properties":{"filePath":{"type":"string"},"content":{"type":"string"}},"required":["filePath","content"]})));
    }
    Value::Array(tools)
}

fn tool(name: &str, desc: &str, params: Value) -> Value {
    json!({"type":"function","function":{"name":name,"description":desc,"parameters":params}})
}

/// Turn the session's messages into the chat format the service expects.
fn to_wire(history: &[Message]) -> Vec<Value> {
    let mut out = vec![];
    let mut open_calls: HashSet<String> = HashSet::new();
    for m in history {
        match m.role {
            Role::User => out.push(json!({"role":"user","content":m.text})),
            Role::Assistant => {
                if m.tool_calls.is_empty() {
                    out.push(json!({"role":"assistant","content":m.text}));
                } else {
                    let calls: Vec<Value> = m
                        .tool_calls
                        .iter()
                        .map(|c| {
                            open_calls.insert(c.id.clone());
                            json!({"id":c.id,"type":"function","function":{"name":c.name,"arguments":c.args}})
                        })
                        .collect();
                    let content = if m.text.is_empty() { Value::Null } else { Value::String(m.text.clone()) };
                    out.push(json!({"role":"assistant","content":content,"tool_calls":calls}));
                }
            }
            Role::Tool => {
                if open_calls.remove(&m.tool_call_id) {
                    out.push(json!({"role":"tool","tool_call_id":m.tool_call_id,"content":m.text}));
                }
            }
            Role::Shell => out.push(json!({"role":"user","content":
                format!("I ran this shell command myself:\n$ {}\n\nOutput:\n{}", m.title, m.text)})),
            Role::Notice => {}
        }
    }
    // A run stopped half-way can leave calls without answers; close them so the service accepts the history.
    let mut fixed = vec![];
    let mut pending: Vec<String> = vec![];
    for v in out {
        let role = v["role"].as_str().unwrap_or("").to_string();
        if role != "tool" && !pending.is_empty() {
            for id in pending.drain(..) {
                fixed.push(json!({"role":"tool","tool_call_id":id,"content":"(interrupted)"}));
            }
        }
        if role == "tool" {
            let id = v["tool_call_id"].as_str().unwrap_or("").to_string();
            pending.retain(|p| *p != id);
        }
        if let Some(calls) = v["tool_calls"].as_array() {
            for c in calls {
                pending.push(c["id"].as_str().unwrap_or("").to_string());
            }
        }
        fixed.push(v);
    }
    for id in pending {
        fixed.push(json!({"role":"tool","tool_call_id":id,"content":"(interrupted)"}));
    }
    fixed
}

fn chat(cfg: &RunConfig, messages: &[Value], tools: Option<&Value>) -> Result<Value, String> {
    if cfg.base_url.trim().is_empty() {
        return Err("No AI service is set. Open Settings and enter the service address, API key and model.".into());
    }
    let url = format!("{}/chat/completions", cfg.base_url.trim().trim_end_matches('/'));
    let mut body = json!({"model": cfg.model, "messages": messages});
    if let Some(t) = tools {
        body["tools"] = t.clone();
    }
    let mut req = ureq::post(&url)
        .config()
        .http_status_as_error(false)
        .timeout_global(Some(Duration::from_secs(600)))
        .build()
        .header("Content-Type", "application/json");
    if !cfg.api_key.trim().is_empty() {
        req = req.header("Authorization", &format!("Bearer {}", cfg.api_key.trim()));
    }
    let mut resp = req.send_json(&body).map_err(|e| format!("Couldn't reach the AI service: {e}"))?;
    let status = resp.status().as_u16();
    let text = resp.body_mut().read_to_string().map_err(|e| format!("Couldn't read the answer: {e}"))?;
    if status >= 400 {
        let msg = serde_json::from_str::<Value>(&text)
            .ok()
            .and_then(|v| v["error"]["message"].as_str().map(String::from))
            .unwrap_or_else(|| text.chars().take(400).collect());
        return Err(format!("The AI service answered {status}: {msg}"));
    }
    serde_json::from_str(&text).map_err(|e| format!("The answer wasn't readable ({e})"))
}

fn compact(cfg: &RunConfig, history: &[Message], send: &dyn Fn(AgentEvent)) -> Result<(), String> {
    send(AgentEvent::Status("Summarizing the session".into()));
    let mut msgs = vec![json!({"role":"system","content":
        "Summarize the conversation so far so the work can continue from the summary alone: the goal, \
         what was done, which files matter, decisions made and what is left to do. Be specific and brief."})];
    msgs.extend(to_wire(history));
    msgs.push(json!({"role":"user","content":"Write the summary now."}));
    let v = chat(cfg, &msgs, None)?;
    usage(&v, send);
    let text = v["choices"][0]["message"]["content"].as_str().unwrap_or("").to_string();
    send(AgentEvent::Compacted(text));
    Ok(())
}

fn usage(v: &Value, send: &dyn Fn(AgentEvent)) {
    if let Some(u) = v.get("usage") {
        send(AgentEvent::Usage {
            prompt: u["prompt_tokens"].as_u64().unwrap_or(0),
            completion: u["completion_tokens"].as_u64().unwrap_or(0),
        });
    }
}

fn run_loop(mut cfg: RunConfig, mut history: Vec<Message>, cancel: &AtomicBool, send: &dyn Fn(AgentEvent)) -> Result<(), String> {
    let tools = tool_specs(&cfg.agent);
    let mut recent: Vec<String> = vec![];
    for step in 0..cfg.max_steps.max(1) {
        if cancel.load(Ordering::Relaxed) {
            return Ok(());
        }
        send(AgentEvent::Status(if step == 0 { "Thinking".into() } else { "Considering next steps".into() }));
        let mut msgs = vec![json!({"role":"system","content":system_prompt(&cfg)})];
        msgs.extend(to_wire(&history));
        let v = chat(&cfg, &msgs, Some(&tools))?;
        if cancel.load(Ordering::Relaxed) {
            return Ok(());
        }
        usage(&v, send);
        let m = &v["choices"][0]["message"];
        let text = m["content"].as_str().unwrap_or("").trim().to_string();
        let calls: Vec<ToolCall> = m["tool_calls"]
            .as_array()
            .map(|a| {
                a.iter()
                    .enumerate()
                    .map(|(i, c)| ToolCall {
                        id: c["id"].as_str().map(String::from).unwrap_or_else(|| format!("call_{step}_{i}")),
                        name: c["function"]["name"].as_str().unwrap_or("").to_string(),
                        args: match &c["function"]["arguments"] {
                            Value::String(s) => s.clone(),
                            other => other.to_string(),
                        },
                    })
                    .collect()
            })
            .unwrap_or_default();
        send(AgentEvent::Assistant { text: text.clone(), tool_calls: calls.clone() });
        let mut am = Message::new(Role::Assistant, text);
        am.tool_calls = calls.clone();
        history.push(am);
        if calls.is_empty() {
            return Ok(());
        }
        for call in calls {
            if cancel.load(Ordering::Relaxed) {
                return Ok(());
            }
            let key = format!("{}:{}", call.name, call.args);
            recent.push(key.clone());
            let repeated = recent.len() >= DOOM_LOOP_THRESHOLD
                && recent[recent.len() - DOOM_LOOP_THRESHOLD..].iter().all(|k| *k == key);
            let args: Value = serde_json::from_str(&call.args).unwrap_or(json!({}));
            let (title, output, ok) = execute(&mut cfg, &call.name, &args, repeated, cancel, send);
            let mut tm = Message::new(Role::Tool, output.clone());
            tm.tool_call_id = call.id.clone();
            tm.tool_name = call.name.clone();
            history.push(tm);
            send(AgentEvent::ToolResult { call_id: call.id, name: call.name, title, output, ok });
        }
    }
    send(AgentEvent::Error(format!("Stopped after {} steps. Send a message to continue.", cfg.max_steps)));
    Ok(())
}

/// Ask the person (unless settings already decide). Returns true when allowed.
fn permit(cfg: &mut RunConfig, tool: &str, title: &str, detail: &str, cancel: &AtomicBool, send: &dyn Fn(AgentEvent)) -> Result<(), String> {
    let level = cfg.perms.get(tool);
    if level == Perm::Deny {
        return Err(format!("The {tool} tool is turned off in Settings → Permissions."));
    }
    if level == Perm::Allow || cfg.auto_accept || cfg.always.contains(tool) {
        return Ok(());
    }
    let (rtx, rrx) = channel();
    send(AgentEvent::Permission(PermissionRequest {
        tool: tool.into(),
        title: title.into(),
        detail: detail.into(),
        reply: rtx,
    }));
    loop {
        match rrx.recv_timeout(Duration::from_millis(200)) {
            Ok(PermReply::Once) => return Ok(()),
            Ok(PermReply::Always) => {
                cfg.always.insert(tool.into());
                send(AgentEvent::AlwaysAllowed(tool.into()));
                return Ok(());
            }
            Ok(PermReply::Deny) => return Err("The user rejected this. Ask what to do instead.".into()),
            Err(RecvTimeoutError::Timeout) => {
                if cancel.load(Ordering::Relaxed) {
                    return Err("Interrupted".into());
                }
            }
            Err(RecvTimeoutError::Disconnected) => return Err("Interrupted".into()),
        }
    }
}

fn resolve(cfg: &RunConfig, p: &str) -> PathBuf {
    let p = p.trim();
    let path = Path::new(p);
    let full = if p.is_empty() { cfg.project_dir.clone() } else if path.is_absolute() { path.to_path_buf() } else { cfg.project_dir.join(path) };
    normalize(&full)
}

fn normalize(p: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in p.components() {
        match c {
            std::path::Component::ParentDir => {
                out.pop();
            }
            std::path::Component::CurDir => {}
            other => out.push(other.as_os_str()),
        }
    }
    out
}

pub fn rel(cfg_dir: &Path, p: &Path) -> String {
    p.strip_prefix(cfg_dir).map(|r| r.to_string_lossy().replace('\\', "/")).unwrap_or_else(|_| p.to_string_lossy().to_string())
}

fn inside(cfg: &RunConfig, p: &Path) -> bool {
    p.starts_with(normalize(&cfg.project_dir))
}

fn cut(mut s: String, max: usize) -> String {
    if s.chars().count() > max {
        s = s.chars().take(max).collect::<String>() + "\n\n(output truncated)";
    }
    s
}

fn execute(cfg: &mut RunConfig, name: &str, a: &Value, repeated: bool, cancel: &AtomicBool, send: &dyn Fn(AgentEvent)) -> (String, String, bool) {
    let s = |k: &str| a[k].as_str().unwrap_or("").to_string();
    let path_arg = if a["filePath"].is_string() { s("filePath") } else { s("path") };
    let target = resolve(cfg, &path_arg);
    let shown = rel(&cfg.project_dir, &target);
    let title = match name {
        "bash" => s("command"),
        "glob" | "grep" => s("pattern"),
        "webfetch" => s("url"),
        "todowrite" => "Updated todos".into(),
        _ => if shown.is_empty() { ".".into() } else { shown.clone() },
    };
    let fail = |msg: String| (title.clone(), msg, false);

    if repeated {
        if let Err(e) = permit(cfg, "doom_loop", "Same call repeated", &format!("{name} was called {DOOM_LOOP_THRESHOLD} times with the same input"), cancel, send) {
            return fail(e);
        }
    }
    let touches_path = matches!(name, "read" | "list" | "glob" | "grep" | "edit" | "write");
    if touches_path && !inside(cfg, &target) {
        if let Err(e) = permit(cfg, "external_directory", "Outside the project folder", &target.display().to_string(), cancel, send) {
            return fail(e);
        }
    }
    if cfg.agent == "plan" && matches!(name, "edit" | "write") {
        return fail("Plan mode can't change files. Switch to Build to make changes.".into());
    }
    let detail = match name {
        "edit" => format!("Edit {shown}"),
        "write" => format!("Write {shown}"),
        "bash" => format!("$ {}", s("command")),
        "webfetch" => format!("Fetch {}", s("url")),
        _ => format!("{name} {shown}"),
    };
    let perm_tool = if name == "write" { "edit" } else { name };
    if let Err(e) = permit(cfg, perm_tool, &tool_label(name), &detail, cancel, send) {
        return fail(e);
    }

    let result: Result<String, String> = match name {
        "read" => read_file(&target, a["offset"].as_u64().unwrap_or(0) as usize, a["limit"].as_u64().map(|v| v as usize).unwrap_or(READ_DEFAULT_LIMIT)),
        "list" => list_dir(&target),
        "glob" => glob(&target, &s("pattern"), &cfg.project_dir),
        "grep" => grep(&target, &s("pattern"), &s("include"), &cfg.project_dir),
        "write" => {
            let content = s("content");
            if let Some(d) = target.parent() {
                let _ = std::fs::create_dir_all(d);
            }
            std::fs::write(&target, &content)
                .map(|_| {
                    send(AgentEvent::FileChanged(shown.clone()));
                    format!("Wrote {} lines to {shown}", content.lines().count())
                })
                .map_err(|e| format!("Couldn't write {shown}: {e}"))
        }
        "edit" => edit_file(&target, &s("oldString"), &s("newString"), a["replaceAll"].as_bool().unwrap_or(false)).map(|r| {
            send(AgentEvent::FileChanged(shown.clone()));
            r
        }),
        "bash" => {
            let t = a["timeout"].as_u64().unwrap_or(BASH_DEFAULT_TIMEOUT_MS).min(BASH_MAX_TIMEOUT_MS);
            send(AgentEvent::Status("Running commands".into()));
            run_shell(&cfg.shell, &s("command"), &cfg.project_dir, t, cancel).map(|(out, code)| {
                if code == 0 { out } else { format!("{out}\n\nCommand exited with code {code}") }
            })
        }
        "webfetch" => webfetch(&s("url")),
        "todowrite" => {
            let todos: Vec<Todo> = a["todos"]
                .as_array()
                .map(|arr| {
                    arr.iter()
                        .map(|t| Todo {
                            content: t["content"].as_str().unwrap_or("").into(),
                            status: t["status"].as_str().unwrap_or("pending").into(),
                        })
                        .collect()
                })
                .unwrap_or_default();
            let n = todos.len();
            send(AgentEvent::Todos(todos));
            Ok(format!("Todo list updated ({n} items)"))
        }
        other => Err(format!("Unknown tool: {other}")),
    };
    match result {
        Ok(out) => (title, cut(out, MAX_OUTPUT), true),
        Err(e) => fail(e),
    }
}

pub fn tool_label(name: &str) -> String {
    match name {
        "read" => "Read",
        "list" => "List",
        "glob" => "Glob",
        "grep" => "Grep",
        "edit" => "Edit",
        "write" => "Write",
        "bash" => "Shell",
        "webfetch" => "Webfetch",
        "todowrite" => "Todos",
        "doom_loop" => "Repeat guard",
        "external_directory" => "Outside folder",
        other => other,
    }
    .to_string()
}

fn read_file(p: &Path, offset: usize, limit: usize) -> Result<String, String> {
    let bytes = std::fs::read(p).map_err(|e| format!("Couldn't read {}: {e}", p.display()))?;
    if bytes.iter().take(8000).any(|b| *b == 0) {
        return Err("That file is binary, not text.".into());
    }
    let text = String::from_utf8_lossy(&bytes);
    let lines: Vec<&str> = text.lines().collect();
    let mut out = String::new();
    for (i, line) in lines.iter().enumerate().skip(offset).take(limit) {
        let l: String = line.chars().take(READ_MAX_LINE).collect();
        out.push_str(&format!("{:05}| {}\n", i + 1, l));
    }
    if offset + limit < lines.len() {
        out.push_str(&format!("\n(File has more lines. Use offset {} to read further.)", offset + limit));
    }
    if out.is_empty() {
        out = "(empty file)".into();
    }
    Ok(out)
}

pub fn ignored(name: &str) -> bool {
    IGNORED_DIRS.contains(&name)
}

fn list_dir(p: &Path) -> Result<String, String> {
    let mut entries: Vec<(bool, String)> = std::fs::read_dir(p)
        .map_err(|e| format!("Couldn't list {}: {e}", p.display()))?
        .filter_map(|e| e.ok())
        .map(|e| (e.path().is_dir(), e.file_name().to_string_lossy().to_string()))
        .filter(|(_, n)| !ignored(n))
        .collect();
    entries.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.to_lowercase().cmp(&b.1.to_lowercase())));
    let total = entries.len();
    let mut out: Vec<String> = entries.into_iter().take(LIST_LIMIT).map(|(d, n)| if d { format!("{n}/") } else { n }).collect();
    if total > LIST_LIMIT {
        out.push(format!("… and {} more", total - LIST_LIMIT));
    }
    Ok(if out.is_empty() { "(empty folder)".into() } else { out.join("\n") })
}

/// Glob pattern (`*`, `**`, `?`) to a regular expression.
fn glob_regex(pattern: &str) -> Option<regex::Regex> {
    let mut re = String::from("(?i)^");
    let chars: Vec<char> = pattern.replace('\\', "/").chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '*' if i + 1 < chars.len() && chars[i + 1] == '*' => {
                re.push_str(".*");
                i += 1;
                if i + 1 < chars.len() && chars[i + 1] == '/' {
                    i += 1;
                    re.push_str("/?");
                }
            }
            '*' => re.push_str("[^/]*"),
            '?' => re.push_str("[^/]"),
            '{' => re.push('('),
            '}' => re.push(')'),
            ',' => re.push('|'),
            c => re.push_str(&regex::escape(&c.to_string())),
        }
        i += 1;
    }
    re.push('$');
    regex::Regex::new(&re).ok()
}

fn walk(root: &Path) -> impl Iterator<Item = walkdir::DirEntry> {
    walkdir::WalkDir::new(root)
        .into_iter()
        .filter_entry(|e| e.depth() == 0 || !ignored(&e.file_name().to_string_lossy()))
        .filter_map(|e| e.ok())
        .filter(|e| e.file_type().is_file())
}

fn glob(root: &Path, pattern: &str, project: &Path) -> Result<String, String> {
    let re = glob_regex(pattern).ok_or("That pattern isn't valid.")?;
    let has_slash = pattern.contains('/');
    let mut hits = vec![];
    for e in walk(root) {
        let r = rel(root, e.path());
        let name = e.file_name().to_string_lossy().to_string();
        if re.is_match(&r) || (!has_slash && re.is_match(&name)) {
            hits.push(rel(project, e.path()));
            if hits.len() >= LIST_LIMIT {
                hits.push("(more results not shown)".into());
                break;
            }
        }
    }
    Ok(if hits.is_empty() { "No files found".into() } else { hits.join("\n") })
}

fn grep(root: &Path, pattern: &str, include: &str, project: &Path) -> Result<String, String> {
    let re = regex::Regex::new(pattern).map_err(|e| format!("That pattern isn't valid: {e}"))?;
    let inc = if include.is_empty() { None } else { glob_regex(include) };
    let mut hits = vec![];
    'files: for e in walk(root) {
        if let Some(inc) = &inc {
            if !inc.is_match(&e.file_name().to_string_lossy()) {
                continue;
            }
        }
        if e.metadata().map(|m| m.len() > 5_000_000).unwrap_or(true) {
            continue;
        }
        let Ok(text) = std::fs::read_to_string(e.path()) else { continue };
        for (i, line) in text.lines().enumerate() {
            if re.is_match(line) {
                let l: String = line.trim().chars().take(200).collect();
                hits.push(format!("{}:{}: {}", rel(project, e.path()), i + 1, l));
                if hits.len() >= LIST_LIMIT {
                    hits.push("(more matches not shown)".into());
                    break 'files;
                }
            }
        }
    }
    Ok(if hits.is_empty() { "No matches found".into() } else { hits.join("\n") })
}

fn edit_file(p: &Path, old: &str, new: &str, all: bool) -> Result<String, String> {
    if old.is_empty() {
        if p.exists() {
            return Err("oldString is empty but the file already exists; use write to replace it.".into());
        }
        if let Some(d) = p.parent() {
            let _ = std::fs::create_dir_all(d);
        }
        std::fs::write(p, new).map_err(|e| e.to_string())?;
        return Ok("Created the file".into());
    }
    let text = std::fs::read_to_string(p).map_err(|e| format!("Couldn't read {}: {e}", p.display()))?;
    // Files saved on Windows may use CRLF; match either way.
    let crlf = text.contains("\r\n");
    let (old2, new2) = if crlf && !old.contains("\r\n") {
        (old.replace('\n', "\r\n"), new.replace('\n', "\r\n"))
    } else {
        (old.to_string(), new.to_string())
    };
    let count = text.matches(&old2).count();
    if count == 0 {
        return Err("oldString was not found in the file. Read the file again and copy the text exactly.".into());
    }
    if count > 1 && !all {
        return Err(format!("oldString appears {count} times. Give more surrounding text or set replaceAll."));
    }
    let out = if all { text.replace(&old2, &new2) } else { text.replacen(&old2, &new2, 1) };
    std::fs::write(p, out).map_err(|e| e.to_string())?;
    Ok(format!("Edited the file ({count} replacement{})", if count == 1 { "" } else { "s" }))
}

pub fn shell_program(pref: &str) -> (String, Vec<String>) {
    let pref = pref.trim();
    if !pref.is_empty() {
        let lower = pref.to_lowercase();
        if lower.contains("powershell") || lower.contains("pwsh") {
            return (pref.into(), vec!["-NoProfile".into(), "-Command".into()]);
        }
        if lower.ends_with("cmd") || lower.ends_with("cmd.exe") {
            return (pref.into(), vec!["/C".into()]);
        }
        return (pref.into(), vec!["-c".into()]);
    }
    if cfg!(windows) {
        ("powershell".into(), vec!["-NoProfile".into(), "-ExecutionPolicy".into(), "Bypass".into(), "-Command".into()])
    } else {
        ("sh".into(), vec!["-c".into()])
    }
}

/// Run one command; returns combined output and the exit code.
pub fn run_shell(shell: &str, command: &str, dir: &Path, timeout_ms: u64, cancel: &AtomicBool) -> Result<(String, i32), String> {
    let (prog, mut args) = shell_program(shell);
    args.push(command.to_string());
    let mut cmd = std::process::Command::new(&prog);
    cmd.args(&args)
        .current_dir(dir)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        cmd.creation_flags(0x0800_0000); // no console window
    }
    let mut child = cmd.spawn().map_err(|e| format!("Couldn't start {prog}: {e}"))?;
    let mut so = child.stdout.take().unwrap();
    let mut se = child.stderr.take().unwrap();
    let t1 = std::thread::spawn(move || {
        let mut v = vec![];
        let _ = so.read_to_end(&mut v);
        v
    });
    let t2 = std::thread::spawn(move || {
        let mut v = vec![];
        let _ = se.read_to_end(&mut v);
        v
    });
    let start = Instant::now();
    let mut note = String::new();
    let code = loop {
        if let Ok(Some(st)) = child.try_wait() {
            break st.code().unwrap_or(-1);
        }
        if cancel.load(Ordering::Relaxed) {
            let _ = child.kill();
            note = "\n\nCommand cancelled".into();
            break -1;
        }
        if start.elapsed() > Duration::from_millis(timeout_ms) {
            let _ = child.kill();
            note = format!("\n\nCommand timed out after {} s", timeout_ms / 1000);
            break -1;
        }
        std::thread::sleep(Duration::from_millis(50));
    };
    let out = t1.join().unwrap_or_default();
    let err = t2.join().unwrap_or_default();
    let mut text = String::from_utf8_lossy(&out).to_string();
    let e = String::from_utf8_lossy(&err);
    if !e.trim().is_empty() {
        if !text.is_empty() {
            text.push('\n');
        }
        text.push_str(&e);
    }
    text.push_str(&note);
    if text.trim().is_empty() {
        text = "(no output)".into();
    }
    Ok((cut(text, MAX_OUTPUT), code))
}

fn webfetch(url: &str) -> Result<String, String> {
    if !(url.starts_with("http://") || url.starts_with("https://")) {
        return Err("Only http and https addresses can be fetched.".into());
    }
    let mut r = ureq::get(url)
        .config()
        .timeout_global(Some(Duration::from_secs(30)))
        .build()
        .call()
        .map_err(|e| format!("Couldn't fetch {url}: {e}"))?;
    let text = r.body_mut().read_to_string().map_err(|e| e.to_string())?;
    let stripped = if text.contains("<html") || text.contains("<body") { strip_html(&text) } else { text };
    Ok(cut(stripped, 50_000))
}

fn strip_html(s: &str) -> String {
    let no_script = regex::Regex::new(r"(?is)<(script|style)[^>]*>.*?</(script|style)>").unwrap().replace_all(s, "");
    let tags = regex::Regex::new(r"(?s)<[^>]+>").unwrap().replace_all(&no_script, " ");
    let ws = regex::Regex::new(r"[ \t]+").unwrap().replace_all(&tags, " ");
    let nl = regex::Regex::new(r"\n\s*\n+").unwrap().replace_all(&ws, "\n\n");
    nl.replace("&nbsp;", " ").replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">").replace("&quot;", "\"")
}

input.content:
//! The coding agent: talks to an OpenAI-compatible chat service, runs the
//! tools the model asks for (read, list, glob, grep, edit, write, bash,
//! webfetch, todowrite) inside the project folder, and asks the person for
//! permission where the settings say so. Runs on its own thread and reports
//! back through a channel.

use crate::store::{Message, Perm, Perms, Role, Todo, ToolCall};
use serde_json::{json, Value};
use std::collections::HashSet;
use std::io::Read;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::{channel, Receiver, RecvTimeoutError, Sender};
use std::sync::Arc;
use std::time::{Duration, Instant};

/// Longest tool output handed back to the model, in characters.
pub const MAX_OUTPUT: usize = 30_000;
/// Lines `read` returns when the model gives no limit.
pub const READ_DEFAULT_LIMIT: usize = 2000;
/// Longest line `read` returns before cutting it.
pub const READ_MAX_LINE: usize = 2000;
/// Most entries `list`, `glob` and `grep` return.
pub const LIST_LIMIT: usize = 100;
/// Shell commands stop after this many milliseconds unless the model asks for longer.
pub const BASH_DEFAULT_TIMEOUT_MS: u64 = 120_000;
pub const BASH_MAX_TIMEOUT_MS: u64 = 600_000;
/// The same call this many times in a row triggers the repeat guard.
pub const DOOM_LOOP_THRESHOLD: usize = 3;
/// Folders never listed or searched.
pub const IGNORED_DIRS: &[&str] = &[
    "node_modules", ".git", "target", "dist", "build", ".next", "__pycache__", ".venv", "vendor", ".idea", ".vscode",
];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PermReply {
    Once,
    Always,
    Deny,
}

pub struct PermissionRequest {
    pub tool: String,
    pub title: String,
    pub detail: String,
    pub reply: Sender<PermReply>,
}

pub enum AgentEvent {
    Assistant { text: String, tool_calls: Vec<ToolCall> },
    ToolResult { call_id: String, name: String, title: String, output: String, ok: bool },
    Permission(PermissionRequest),
    Usage { prompt: u64, completion: u64 },
    Todos(Vec<Todo>),
    FileChanged(String),
    Status(String),
    AlwaysAllowed(String),
    Compacted(String),
    Done,
    Error(String),
}

#[derive(Clone)]
pub struct RunConfig {
    pub base_url: String,
    pub api_key: String,
    pub model: String,
    pub agent: String,
    pub project_dir: PathBuf,
    pub perms: Perms,
    pub auto_accept: bool,
    pub always: HashSet<String>,
    pub shell: String,
    pub max_steps: u32,
    pub compact: bool,
}

pub struct Run {
    pub rx: Receiver<AgentEvent>,
    pub cancel: Arc<AtomicBool>,
}

pub fn spawn(cfg: RunConfig, history: Vec<Message>, ctx: eframe::egui::Context) -> Run {
    let (tx, rx) = channel();
    let cancel = Arc::new(AtomicBool::new(false));
    let c2 = cancel.clone();
    std::thread::spawn(move || {
        let tx2 = tx.clone();
        let ctx2 = ctx.clone();
        let send = move |e: AgentEvent| {
            let _ = tx2.send(e);
            ctx2.request_repaint();
        };
        let result = if cfg.compact { compact(&cfg, &history, &send) } else { run_loop(cfg, history, &c2, &send) };
        match result {
            Ok(()) => send(AgentEvent::Done),
            Err(e) => {
                if c2.load(Ordering::Relaxed) {
                    send(AgentEvent::Done)
                } else {
                    send(AgentEvent::Error(e))
                }
            }
        }
    });
    Run { rx, cancel }
}

fn system_prompt(cfg: &RunConfig) -> String {
    let os = std::env::consts::OS;
    let date = chrono::Local::now().format("%A %B %-d, %Y");
    let mode = if cfg.agent == "plan" {
        "You are in PLAN mode: look around, read and search, then explain a clear plan. \
         Do not edit or write files and do not run commands that change anything."
    } else {
        "You are in BUILD mode: make the changes the user asks for, verify them, and report briefly."
    };
    format!(
        "You are a careful, friendly coding assistant working inside the user's project folder.\n\
         {mode}\n\
         Project folder: {dir}\nPlatform: {os}\nToday: {date}\n\n\
         Use the tools to inspect files before changing them. Paths may be relative to the project folder. \
         Prefer `edit` for small changes and `write` for new files. Keep a todo list with `todowrite` for \
         tasks with several steps. Answer concisely in Markdown; the person may not be a programmer, so \
         explain results in plain words.",
        dir = cfg.project_dir.display()
    )
}

fn tool_specs(agent: &str) -> Value {
    let mut tools = vec![
        tool("read", "Read a text file. Returns numbered lines.", json!({
            "type":"object","properties":{
                "filePath":{"type":"string","description":"Path of the file"},
                "offset":{"type":"integer","description":"First line to read (0-based)"},
                "limit":{"type":"integer","description":"Number of lines to read"}},
            "required":["filePath"]})),
        tool("list", "List files and folders in a folder.", json!({
            "type":"object","properties":{"path":{"type":"string","description":"Folder (default: project folder)"}}})),
        tool("glob", "Find files whose path matches a pattern such as **/*.rs.", json!({
            "type":"object","properties":{"pattern":{"type":"string"},"path":{"type":"string"}},"required":["pattern"]})),
        tool("grep", "Search file contents with a regular expression.", json!({
            "type":"object","properties":{"pattern":{"type":"string"},"path":{"type":"string"},
                "include":{"type":"string","description":"File pattern to include, e.g. *.ts"}},"required":["pattern"]})),
        tool("webfetch", "Fetch a web page or file over http(s) and return its text.", json!({
            "type":"object","properties":{"url":{"type":"string"}},"required":["url"]})),
        tool("todowrite", "Replace the todo list shown to the user.", json!({
            "type":"object","properties":{"todos":{"type":"array","items":{"type":"object","properties":{
                "content":{"type":"string"},"status":{"type":"string","enum":["pending","in_progress","completed","cancelled"]}},
                "required":["content","status"]}}},"required":["todos"]})),
        tool("bash", "Run a shell command in the project folder and return its output.", json!({
            "type":"object","properties":{"command":{"type":"string"},
                "description":{"type":"string","description":"5-10 words saying what it does"},
                "timeout":{"type":"integer","description":"Milliseconds, at most 600000"}},"required":["command"]})),
    ];
    if agent != "plan" {
        tools.push(tool("edit", "Replace exact text in a file. oldString must appear exactly once unless replaceAll is true.", json!({
            "type":"object","properties":{"filePath":{"type":"string"},"oldString":{"type":"string"},
                "newString":{"type":"string"},"replaceAll":{"type":"boolean"}},"required":["filePath","oldString","newString"]})));
        tools.push(tool("write", "Create or overwrite a file with the given content.", json!({
            "type":"object","properties":{"filePath":{"type":"string"},"content":{"type":"string"}},"required":["filePath","content"]})));
    }
    Value::Array(tools)
}

fn tool(name: &str, desc: &str, params: Value) -> Value {
    json!({"type":"function","function":{"name":name,"description":desc,"parameters":params}})
}

/// Turn the session's messages into the chat format the service expects.
fn to_wire(history: &[Message]) -> Vec<Value> {
    let mut out = vec![];
    let mut open_calls: HashSet<String> = HashSet::new();
    for m in history {
        match m.role {
            Role::User => out.push(json!({"role":"user","content":m.text})),
            Role::Assistant => {
                if m.tool_calls.is_empty() {
                    out.push(json!({"role":"assistant","content":m.text}));
                } else {
                    let calls: Vec<Value> = m
                        .tool_calls
                        .iter()
                        .map(|c| {
                            open_calls.insert(c.id.clone());
                            json!({"id":c.id,"type":"function","function":{"name":c.name,"arguments":c.args}})
                        })
                        .collect();
                    let content = if m.text.is_empty() { Value::Null } else { Value::String(m.text.clone()) };
                    out.push(json!({"role":"assistant","content":content,"tool_calls":calls}));
                }
            }
            Role::Tool => {
                if open_calls.remove(&m.tool_call_id) {
                    out.push(json!({"role":"tool","tool_call_id":m.tool_call_id,"content":m.text}));
                }
            }
            Role::Shell => out.push(json!({"role":"user","content":
                format!("I ran this shell command myself:\n$ {}\n\nOutput:\n{}", m.title, m.text)})),
            Role::Notice => {}
        }
    }
    // A run stopped half-way can leave calls without answers; close them so the service accepts the history.
    let mut fixed = vec![];
    let mut pending: Vec<String> = vec![];
    for v in out {
        let role = v["role"].as_str().unwrap_or("").to_string();
        if role != "tool" && !pending.is_empty() {
            for id in pending.drain(..) {
                fixed.push(json!({"role":"tool","tool_call_id":id,"content":"(interrupted)"}));
            }
        }
        if role == "tool" {
            let id = v["tool_call_id"].as_str().unwrap_or("").to_string();
            pending.retain(|p| *p != id);
        }
        if let Some(calls) = v["tool_calls"].as_array() {
            for c in calls {
                pending.push(c["id"].as_str().unwrap_or("").to_string());
            }
        }
        fixed.push(v);
    }
    for id in pending {
        fixed.push(json!({"role":"tool","tool_call_id":id,"content":"(interrupted)"}));
    }
    fixed
}

fn chat(cfg: &RunConfig, messages: &[Value], tools: Option<&Value>) -> Result<Value, String> {
    if cfg.base_url.trim().is_empty() {
        return Err("No AI service is set. Open Settings and enter the service address, API key and model.".into());
    }
    let url = format!("{}/chat/completions", cfg.base_url.trim().trim_end_matches('/'));
    let mut body = json!({"model": cfg.model, "messages": messages});
    if let Some(t) = tools {
        body["tools"] = t.clone();
    }
    let mut req = ureq::post(&url)
        .config()
        .http_status_as_error(false)
        .timeout_global(Some(Duration::from_secs(600)))
        .build()
        .header("Content-Type", "application/json");
    if !cfg.api_key.trim().is_empty() {
        req = req.header("Authorization", &format!("Bearer {}", cfg.api_key.trim()));
    }
    let mut resp = req.send_json(&body).map_err(|e| format!("Couldn't reach the AI service: {e}"))?;
    let status = resp.status().as_u16();
    let text = resp.body_mut().read_to_string().map_err(|e| format!("Couldn't read the answer: {e}"))?;
    if status >= 400 {
        let msg = serde_json::from_str::<Value>(&text)
            .ok()
            .and_then(|v| v["error"]["message"].as_str().map(String::from))
            .unwrap_or_else(|| text.chars().take(400).collect());
        return Err(format!("The AI service answered {status}: {msg}"));
    }
    serde_json::from_str(&text).map_err(|e| format!("The answer wasn't readable ({e})"))
}

fn compact(cfg: &RunConfig, history: &[Message], send: &dyn Fn(AgentEvent)) -> Result<(), String> {
    send(AgentEvent::Status("Summarizing the session".into()));
    let mut msgs = vec![json!({"role":"system","content":
        "Summarize the conversation so far so the work can continue from the summary alone: the goal, \
         what was done, which files matter, decisions made and what is left to do. Be specific and brief."})];
    msgs.extend(to_wire(history));
    msgs.push(json!({"role":"user","content":"Write the summary now."}));
    let v = chat(cfg, &msgs, None)?;
    usage(&v, send);
    let text = v["choices"][0]["message"]["content"].as_str().unwrap_or("").to_string();
    send(AgentEvent::Compacted(text));
    Ok(())
}

fn usage(v: &Value, send: &dyn Fn(AgentEvent)) {
    if let Some(u) = v.get("usage") {
        send(AgentEvent::Usage {
            prompt: u["prompt_tokens"].as_u64().unwrap_or(0),
            completion: u["completion_tokens"].as_u64().unwrap_or(0),
        });
    }
}

fn run_loop(mut cfg: RunConfig, mut history: Vec<Message>, cancel: &AtomicBool, send: &dyn Fn(AgentEvent)) -> Result<(), String> {
    let tools = tool_specs(&cfg.agent);
    let mut recent: Vec<String> = vec![];
    for step in 0..cfg.max_steps.max(1) {
        if cancel.load(Ordering::Relaxed) {
            return Ok(());
        }
        send(AgentEvent::Status(if step == 0 { "Thinking".into() } else { "Considering next steps".into() }));
        let mut msgs = vec![json!({"role":"system","content":system_prompt(&cfg)})];
        msgs.extend(to_wire(&history));
        let v = chat(&cfg, &msgs, Some(&tools))?;
        if cancel.load(Ordering::Relaxed) {
            return Ok(());
        }
        usage(&v, send);
        let m = &v["choices"][0]["message"];
        let text = m["content"].as_str().unwrap_or("").trim().to_string();
        let calls: Vec<ToolCall> = m["tool_calls"]
            .as_array()
            .map(|a| {
                a.iter()
                    .enumerate()
                    .map(|(i, c)| ToolCall {
                        id: c["id"].as_str().map(String::from).unwrap_or_else(|| format!("call_{step}_{i}")),
                        name: c["function"]["name"].as_str().unwrap_or("").to_string(),
                        args: match &c["function"]["arguments"] {
                            Value::String(s) => s.clone(),
                            other => other.to_string(),
                        },
                    })
                    .collect()
            })
            .unwrap_or_default();
        send(AgentEvent::Assistant { text: text.clone(), tool_calls: calls.clone() });
        let mut am = Message::new(Role::Assistant, text);
        am.tool_calls = calls.clone();
        history.push(am);
        if calls.is_empty() {
            return Ok(());
        }
        for call in calls {
            if cancel.load(Ordering::Relaxed) {
                return Ok(());
            }
            let key = format!("{}:{}", call.name, call.args);
            recent.push(key.clone());
            let repeated = recent.len() >= DOOM_LOOP_THRESHOLD
                && recent[recent.len() - DOOM_LOOP_THRESHOLD..].iter().all(|k| *k == key);
            let args: Value = serde_json::from_str(&call.args).unwrap_or(json!({}));
            let (title, output, ok) = execute(&mut cfg, &call.name, &args, repeated, cancel, send);
            let mut tm = Message::new(Role::Tool, output.clone());
            tm.tool_call_id = call.id.clone();
            tm.tool_name = call.name.clone();
            history.push(tm);
            send(AgentEvent::ToolResult { call_id: call.id, name: call.name, title, output, ok });
        }
    }
    send(AgentEvent::Error(format!("Stopped after {} steps. Send a message to continue.", cfg.max_steps)));
    Ok(())
}

/// Ask the person (unless settings already decide). Returns true when allowed.
fn permit(cfg: &mut RunConfig, tool: &str, title: &str, detail: &str, cancel: &AtomicBool, send: &dyn Fn(AgentEvent)) -> Result<(), String> {
    let level = cfg.perms.get(tool);
    if level == Perm::Deny {
        return Err(format!("The {tool} tool is turned off in Settings → Permissions."));
    }
    if level == Perm::Allow || cfg.auto_accept || cfg.always.contains(tool) {
        return Ok(());
    }
    let (rtx, rrx) = channel();
    send(AgentEvent::Permission(PermissionRequest {
        tool: tool.into(),
        title: title.into(),
        detail: detail.into(),
        reply: rtx,
    }));
    loop {
        match rrx.recv_timeout(Duration::from_millis(200)) {
            Ok(PermReply::Once) => return Ok(()),
            Ok(PermReply::Always) => {
                cfg.always.insert(tool.into());
                send(AgentEvent::AlwaysAllowed(tool.into()));
                return Ok(());
            }
            Ok(PermReply::Deny) => return Err("The user rejected this. Ask what to do instead.".into()),
            Err(RecvTimeoutError::Timeout) => {
                if cancel.load(Ordering::Relaxed) {
                    return Err("Interrupted".into());
                }
            }
            Err(RecvTimeoutError::Disconnected) => return Err("Interrupted".into()),
        }
    }
}

fn resolve(cfg: &RunConfig, p: &str) -> PathBuf {
    let p = p.trim();
    let path = Path::new(p);
    let full = if p.is_empty() { cfg.project_dir.clone() } else if path.is_absolute() { path.to_path_buf() } else { cfg.project_dir.join(path) };
    normalize(&full)
}

fn normalize(p: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in p.components() {
        match c {
            std::path::Component::ParentDir => {
                out.pop();
            }
            std::path::Component::CurDir => {}
            other => out.push(other.as_os_str()),
        }
    }
    out
}

pub fn rel(cfg_dir: &Path, p: &Path) -> String {
    p.strip_prefix(cfg_dir).map(|r| r.to_string_lossy().replace('\\', "/")).unwrap_or_else(|_| p.to_string_lossy().to_string())
}

fn inside(cfg: &RunConfig, p: &Path) -> bool {
    p.starts_with(normalize(&cfg.project_dir))
}

fn cut(mut s: String, max: usize) -> String {
    if s.chars().count() > max {
        s = s.chars().take(max).collect::<String>() + "\n\n(output truncated)";
    }
    s
}

fn execute(cfg: &mut RunConfig, name: &str, a: &Value, repeated: bool, cancel: &AtomicBool, send: &dyn Fn(AgentEvent)) -> (String, String, bool) {
    let s = |k: &str| a[k].as_str().unwrap_or("").to_string();
    let path_arg = if a["filePath"].is_string() { s("filePath") } else { s("path") };
    let target = resolve(cfg, &path_arg);
    let shown = rel(&cfg.project_dir, &target);
    let title = match name {
        "bash" => s("command"),
        "glob" | "grep" => s("pattern"),
        "webfetch" => s("url"),
        "todowrite" => "Updated todos".into(),
        _ => if shown.is_empty() { ".".into() } else { shown.clone() },
    };
    let fail = |msg: String| (title.clone(), msg, false);

    if repeated {
        if let Err(e) = permit(cfg, "doom_loop", "Same call repeated", &format!("{name} was called {DOOM_LOOP_THRESHOLD} times with the same input"), cancel, send) {
            return fail(e);
        }
    }
    let touches_path = matches!(name, "read" | "list" | "glob" | "grep" | "edit" | "write");
    if touches_path && !inside(cfg, &target) {
        if let Err(e) = permit(cfg, "external_directory", "Outside the project folder", &target.display().to_string(), cancel, send) {
            return fail(e);
        }
    }
    if cfg.agent == "plan" && matches!(name, "edit" | "write") {
        return fail("Plan mode can't change files. Switch to Build to make changes.".into());
    }
    let detail = match name {
        "edit" => format!("Edit {shown}"),
        "write" => format!("Write {shown}"),
        "bash" => format!("$ {}", s("command")),
        "webfetch" => format!("Fetch {}", s("url")),
        _ => format!("{name} {shown}"),
    };
    let perm_tool = if name == "write" { "edit" } else { name };
    if let Err(e) = permit(cfg, perm_tool, &tool_label(name), &detail, cancel, send) {
        return fail(e);
    }

    let result: Result<String, String> = match name {
        "read" => read_file(&target, a["offset"].as_u64().unwrap_or(0) as usize, a["limit"].as_u64().map(|v| v as usize).unwrap_or(READ_DEFAULT_LIMIT)),
        "list" => list_dir(&target),
        "glob" => glob(&target, &s("pattern"), &cfg.project_dir),
        "grep" => grep(&target, &s("pattern"), &s("include"), &cfg.project_dir),
        "write" => {
            let content = s("content");
            if let Some(d) = target.parent() {
                let _ = std::fs::create_dir_all(d);
            }
            std::fs::write(&target, &content)
                .map(|_| {
                    send(AgentEvent::FileChanged(shown.clone()));
                    format!("Wrote {} lines to {shown}", content.lines().count())
                })
                .map_err(|e| format!("Couldn't write {shown}: {e}"))
        }
        "edit" => edit_file(&target, &s("oldString"), &s("newString"), a["replaceAll"].as_bool().unwrap_or(false)).map(|r| {
            send(AgentEvent::FileChanged(shown.clone()));
            r
        }),
        "bash" => {
            let t = a["timeout"].as_u64().unwrap_or(BASH_DEFAULT_TIMEOUT_MS).min(BASH_MAX_TIMEOUT_MS);
            send(AgentEvent::Status("Running commands".into()));
            run_shell(&cfg.shell, &s("command"), &cfg.project_dir, t, cancel).map(|(out, code)| {
                if code == 0 { out } else { format!("{out}\n\nCommand exited with code {code}") }
            })
        }
        "webfetch" => webfetch(&s("url")),
        "todowrite" => {
            let todos: Vec<Todo> = a["todos"]
                .as_array()
                .map(|arr| {
                    arr.iter()
                        .map(|t| Todo {
                            content: t["content"].as_str().unwrap_or("").into(),
                            status: t["status"].as_str().unwrap_or("pending").into(),
                        })
                        .collect()
                })
                .unwrap_or_default();
            let n = todos.len();
            send(AgentEvent::Todos(todos));
            Ok(format!("Todo list updated ({n} items)"))
        }
        other => Err(format!("Unknown tool: {other}")),
    };
    match result {
        Ok(out) => (title, cut(out, MAX_OUTPUT), true),
        Err(e) => fail(e),
    }
}

pub fn tool_label(name: &str) -> String {
    match name {
        "read" => "Read",
        "list" => "List",
        "glob" => "Glob",
        "grep" => "Grep",
        "edit" => "Edit",
        "write" => "Write",
        "bash" => "Shell",
        "webfetch" => "Webfetch",
        "todowrite" => "Todos",
        "doom_loop" => "Repeat guard",
        "external_directory" => "Outside folder",
        other => other,
    }
    .to_string()
}

fn read_file(p: &Path, offset: usize, limit: usize) -> Result<String, String> {
    let bytes = std::fs::read(p).map_err(|e| format!("Couldn't read {}: {e}", p.display()))?;
    if bytes.iter().take(8000).any(|b| *b == 0) {
        return Err("That file is binary, not text.".into());
    }
    let text = String::from_utf8_lossy(&bytes);
    let lines: Vec<&str> = text.lines().collect();
    let mut out = String::new();
    for (i, line) in lines.iter().enumerate().skip(offset).take(limit) {
        let l: String = line.chars().take(READ_MAX_LINE).collect();
        out.push_str(&format!("{:05}| {}\n", i + 1, l));
    }
    if offset + limit < lines.len() {
        out.push_str(&format!("\n(File has more lines. Use offset {} to read further.)", offset + limit));
    }
    if out.is_empty() {
        out = "(empty file)".into();
    }
    Ok(out)
}

pub fn ignored(name: &str) -> bool {
    IGNORED_DIRS.contains(&name)
}

fn list_dir(p: &Path) -> Result<String, String> {
    let mut entries: Vec<(bool, String)> = std::fs::read_dir(p)
        .map_err(|e| format!("Couldn't list {}: {e}", p.display()))?
        .filter_map(|e| e.ok())
        .map(|e| (e.path().is_dir(), e.file_name().to_string_lossy().to_string()))
        .filter(|(_, n)| !ignored(n))
        .collect();
    entries.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.to_lowercase().cmp(&b.1.to_lowercase())));
    let total = entries.len();
    let mut out: Vec<String> = entries.into_iter().take(LIST_LIMIT).map(|(d, n)| if d { format!("{n}/") } else { n }).collect();
    if total > LIST_LIMIT {
        out.push(format!("… and {} more", total - LIST_LIMIT));
    }
    Ok(if out.is_empty() { "(empty folder)".into() } else { out.join("\n") })
}

/// Glob pattern (`*`, `**`, `?`) to a regular expression.
fn glob_regex(pattern: &str) -> Option<regex::Regex> {
    let mut re = String::from("(?i)^");
    let chars: Vec<char> = pattern.replace('\\', "/").chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '*' if i + 1 < chars.len() && chars[i + 1] == '*' => {
                re.push_str(".*");
                i += 1;
                if i + 1 < chars.len() && chars[i + 1] == '/' {
                    i += 1;
                    re.push_str("/?");
                }
            }
            '*' => re.push_str("[^/]*"),
            '?' => re.push_str("[^/]"),
            '{' => re.push('('),
            '}' => re.push(')'),
            ',' => re.push('|'),
            c => re.push_str(&regex::escape(&c.to_string())),
        }
        i += 1;
    }
    re.push('$');
    regex::Regex::new(&re).ok()
}

fn walk(root: &Path) -> impl Iterator<Item = walkdir::DirEntry> {
    walkdir::WalkDir::new(root)
        .into_iter()
        .filter_entry(|e| e.depth() == 0 || !ignored(&e.file_name().to_string_lossy()))
        .filter_map(|e| e.ok())
        .filter(|e| e.file_type().is_file())
}

fn glob(root: &Path, pattern: &str, project: &Path) -> Result<String, String> {
    let re = glob_regex(pattern).ok_or("That pattern isn't valid.")?;
    let has_slash = pattern.contains('/');
    let mut hits = vec![];
    for e in walk(root) {
        let r = rel(root, e.path());
        let name = e.file_name().to_string_lossy().to_string();
        if re.is_match(&r) || (!has_slash && re.is_match(&name)) {
            hits.push(rel(project, e.path()));
            if hits.len() >= LIST_LIMIT {
                hits.push("(more results not shown)".into());
                break;
            }
        }
    }
    Ok(if hits.is_empty() { "No files found".into() } else { hits.join("\n") })
}

fn grep(root: &Path, pattern: &str, include: &str, project: &Path) -> Result<String, String> {
    let re = regex::Regex::new(pattern).map_err(|e| format!("That pattern isn't valid: {e}"))?;
    let inc = if include.is_empty() { None } else { glob_regex(include) };
    let mut hits = vec![];
    'files: for e in walk(root) {
        if let Some(inc) = &inc {
            if !inc.is_match(&e.file_name().to_string_lossy()) {
                continue;
            }
        }
        if e.metadata().map(|m| m.len() > 5_000_000).unwrap_or(true) {
            continue;
        }
        let Ok(text) = std::fs::read_to_string(e.path()) else { continue };
        for (i, line) in text.lines().enumerate() {
            if re.is_match(line) {
                let l: String = line.trim().chars().take(200).collect();
                hits.push(format!("{}:{}: {}", rel(project, e.path()), i + 1, l));
                if hits.len() >= LIST_LIMIT {
                    hits.push("(more matches not shown)".into());
                    break 'files;
                }
            }
        }
    }
    Ok(if hits.is_empty() { "No matches found".into() } else { hits.join("\n") })
}

fn edit_file(p: &Path, old: &str, new: &str, all: bool) -> Result<String, String> {
    if old.is_empty() {
        if p.exists() {
            return Err("oldString is empty but the file already exists; use write to replace it.".into());
        }
        if let Some(d) = p.parent() {
            let _ = std::fs::create_dir_all(d);
        }
        std::fs::write(p, new).map_err(|e| e.to_string())?;
        return Ok("Created the file".into());
    }
    let text = std::fs::read_to_string(p).map_err(|e| format!("Couldn't read {}: {e}", p.display()))?;
    // Files saved on Windows may use CRLF; match either way.
    let crlf = text.contains("\r\n");
    let (old2, new2) = if crlf && !old.contains("\r\n") {
        (old.replace('\n', "\r\n"), new.replace('\n', "\r\n"))
    } else {
        (old.to_string(), new.to_string())
    };
    let count = text.matches(&old2).count();
    if count == 0 {
        return Err("oldString was not found in the file. Read the file again and copy the text exactly.".into());
    }
    if count > 1 && !all {
        return Err(format!("oldString appears {count} times. Give more surrounding text or set replaceAll."));
    }
    let out = if all { text.replace(&old2, &new2) } else { text.replacen(&old2, &new2, 1) };
    std::fs::write(p, out).map_err(|e| e.to_string())?;
    Ok(format!("Edited the file ({count} replacement{})", if count == 1 { "" } else { "s" }))
}

pub fn shell_program(pref: &str) -> (String, Vec<String>) {
    let pref = pref.trim();
    if !pref.is_empty() {
        let lower = pref.to_lowercase();
        if lower.contains("powershell") || lower.contains("pwsh") {
            return (pref.into(), vec!["-NoProfile".into(), "-Command".into()]);
        }
        if lower.ends_with("cmd") || lower.ends_with("cmd.exe") {
            return (pref.into(), vec!["/C".into()]);
        }
        return (pref.into(), vec!["-c".into()]);
    }
    if cfg!(windows) {
        ("powershell".into(), vec!["-NoProfile".into(), "-ExecutionPolicy".into(), "Bypass".into(), "-Command".into()])
    } else {
        ("sh".into(), vec!["-c".into()])
    }
}

/// Run one command; returns combined output and the exit code.
pub fn run_shell(shell: &str, command: &str, dir: &Path, timeout_ms: u64, cancel: &AtomicBool) -> Result<(String, i32), String> {
    let (prog, mut args) = shell_program(shell);
    args.push(command.to_string());
    let mut cmd = std::process::Command::new(&prog);
    cmd.args(&args)
        .current_dir(dir)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        cmd.creation_flags(0x0800_0000); // no console window
    }
    let mut child = cmd.spawn().map_err(|e| format!("Couldn't start {prog}: {e}"))?;
    let mut so = child.stdout.take().unwrap();
    let mut se = child.stderr.take().unwrap();
    let t1 = std::thread::spawn(move || {
        let mut v = vec![];
        let _ = so.read_to_end(&mut v);
        v
    });
    let t2 = std::thread::spawn(move || {
        let mut v = vec![];
        let _ = se.read_to_end(&mut v);
        v
    });
    let start = Instant::now();
    let mut note = String::new();
    let code = loop {
        if let Ok(Some(st)) = child.try_wait() {
            break st.code().unwrap_or(-1);
        }
        if cancel.load(Ordering::Relaxed) {
            let _ = child.kill();
            note = "\n\nCommand cancelled".into();
            break -1;
        }
        if start.elapsed() > Duration::from_millis(timeout_ms) {
            let _ = child.kill();
            note = format!("\n\nCommand timed out after {} s", timeout_ms / 1000);
            break -1;
        }
        std::thread::sleep(Duration::from_millis(50));
    };
    let out = t1.join().unwrap_or_default();
    let err = t2.join().unwrap_or_default();
    let mut text = String::from_utf8_lossy(&out).to_string();
    let e = String::from_utf8_lossy(&err);
    if !e.trim().is_empty() {
        if !text.is_empty() {
            text.push('\n');
        }
        text.push_str(&e);
    }
    text.push_str(&note);
    if text.trim().is_empty() {
        text = "(no output)".into();
    }
    Ok((cut(text, MAX_OUTPUT), code))
}

fn webfetch(url: &str) -> Result<String, String> {
    if !(url.starts_with("http://") || url.starts_with("https://")) {
        return Err("Only http and https addresses can be fetched.".into());
    }
    let mut r = ureq::get(url)
        .config()
        .timeout_global(Some(Duration::from_secs(30)))
        .build()
        .call()
        .map_err(|e| format!("Couldn't fetch {url}: {e}"))?;
    let text = r.body_mut().read_to_string().map_err(|e| e.to_string())?;
    let stripped = if text.contains("<html") || text.contains("<body") { strip_html(&text) } else { text };
    Ok(cut(stripped, 50_000))
}

fn strip_html(s: &str) -> String {
    let no_script = regex::Regex::new(r"(?is)<(script|style)[^>]*>.*?</(script|style)>").unwrap().replace_all(s, "");
    let tags = regex::Regex::new(r"(?s)<[^>]+>").unwrap().replace_all(&no_script, " ");
    let ws = regex::Regex::new(r"[ \t]+").unwrap().replace_all(&tags, " ");
    let nl = regex::Regex::new(r"\n\s*\n+").unwrap().replace_all(&ws, "\n\n");
    nl.replace("&nbsp;", " ").replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">").replace("&quot;", "\"")
}

