fn hex(s: &str) -> Color32 {
    let s = s.trim_start_matches('#');
    let p = |i: usize| u8::from_str_radix(&s[i..i + 2], 16).unwrap_or(0);
    if s.len() == 8 {
        Color32::from_rgba_unmultiplied(p(0), p(2), p(4), p(6))
    } else {
        Color32::from_rgb(p(0), p(2), p(4))
    }
}

