pub fn apply(ctx: &egui::Context, p: &Pal) {
    ctx.set_theme(if p.dark { egui::Theme::Dark } else { egui::Theme::Light });
    ctx.all_styles_mut(|style| {
        let v = &mut style.visuals;
        *v = if p.dark { egui::Visuals::dark() } else { egui::Visuals::light() };
        v.panel_fill = p.bg_base;
        v.window_fill = p.bg_panel;
        v.extreme_bg_color = p.bg_panel;
        v.faint_bg_color = p.bg_weak;
        v.code_bg_color = p.code_bg;
        v.override_text_color = None;
        v.hyperlink_color = p.interactive;
        v.selection.bg_fill = if p.dark { Color32::from_rgb(0x1d, 0x3a, 0x7a) } else { Color32::from_rgb(0xcf, 0xdf, 0xff) };
        v.selection.stroke = Stroke::new(1.0, p.interactive);
        v.window_stroke = Stroke::new(1.0, p.border_weak);
        v.window_corner_radius = egui::CornerRadius::same(10);
        v.menu_corner_radius = egui::CornerRadius::same(8);
        v.window_shadow = egui::Shadow { offset: [0, 8], blur: 24, spread: 0, color: Color32::from_black_alpha(if p.dark { 120 } else { 30 }) };
        v.popup_shadow = egui::Shadow { offset: [0, 4], blur: 16, spread: 0, color: Color32::from_black_alpha(if p.dark { 100 } else { 24 }) };
        for w in [&mut v.widgets.noninteractive, &mut v.widgets.inactive, &mut v.widgets.hovered, &mut v.widgets.active, &mut v.widgets.open] {
            w.corner_radius = egui::CornerRadius::same(6);
        }
        v.widgets.noninteractive.bg_stroke = Stroke::new(1.0, p.border_weak);
        v.widgets.noninteractive.fg_stroke = Stroke::new(1.0, p.text_strong);
        v.widgets.inactive.bg_fill = p.bg_weak;
        v.widgets.inactive.weak_bg_fill = p.bg_weak;
        v.widgets.inactive.fg_stroke = Stroke::new(1.0, p.text_strong);
        v.widgets.inactive.bg_stroke = Stroke::NONE;
        v.widgets.hovered.bg_fill = p.bg_hover;
        v.widgets.hovered.weak_bg_fill = p.bg_hover;
        v.widgets.hovered.fg_stroke = Stroke::new(1.0, p.text_strong);
        v.widgets.hovered.bg_stroke = Stroke::new(1.0, p.border_weak);
        v.widgets.active.bg_fill = p.bg_hover;
        v.widgets.active.weak_bg_fill = p.bg_hover;
        v.widgets.active.fg_stroke = Stroke::new(1.0, p.text_strong);
        style.spacing.item_spacing = Vec2::new(8.0, 6.0);
        style.spacing.button_padding = Vec2::new(10.0, 5.0);
        style.spacing.interact_size.y = 28.0;
        style.text_styles.insert(egui::TextStyle::Body, egui::FontId::proportional(14.0));
        style.text_styles.insert(egui::TextStyle::Button, egui::FontId::proportional(14.0));
        style.text_styles.insert(egui::TextStyle::Small, egui::FontId::proportional(12.0));
        style.text_styles.insert(egui::TextStyle::Monospace, egui::FontId::monospace(13.0));
        style.text_styles.insert(egui::TextStyle::Heading, egui::FontId::proportional(20.0));
    });
}

/// Use the system UI font (Segoe UI on Windows) and a system code font when present.
pub fn fonts(ctx: &egui::Context) {
    let mut defs = FontDefinitions::default();
    let candidates_sans = [
        "C:\\Windows\\Fonts\\segoeui.ttf",
        "/System/Library/Fonts/SFNS.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
    ];
    let candidates_bold = ["C:\\Windows\\Fonts\\segoeuisb.ttf", "C:\\Windows\\Fonts\\segoeuib.ttf"];
    let candidates_mono = ["C:\\Windows\\Fonts\\consola.ttf", "/System/Library/Fonts/Menlo.ttc", "/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf"];
    if let Some(bytes) = candidates_sans.iter().find_map(|p| std::fs::read(p).ok()) {
        defs.font_data.insert("sys-sans".into(), std::sync::Arc::new(FontData::from_owned(bytes)));
        defs.families.entry(FontFamily::Proportional).or_default().insert(0, "sys-sans".into());
    }
    if let Some(bytes) = candidates_bold.iter().find_map(|p| std::fs::read(p).ok()) {
        defs.font_data.insert("sys-bold".into(), std::sync::Arc::new(FontData::from_owned(bytes)));
        let mut fam = vec!["sys-bold".to_string()];
        fam.extend(defs.families.get(&FontFamily::Proportional).cloned().unwrap_or_default());
        defs.families.insert(FontFamily::Name("bold".into()), fam);
    } else {
        let fam = defs.families.get(&FontFamily::Proportional).cloned().unwrap_or_default();
        defs.families.insert(FontFamily::Name("bold".into()), fam);
    }
    if let Some(bytes) = candidates_mono.iter().find_map(|p| std::fs::read(p).ok()) {
        defs.font_data.insert("sys-mono".into(), std::sync::Arc::new(FontData::from_owned(bytes)));
        defs.families.entry(FontFamily::Monospace).or_default().insert(0, "sys-mono".into());
    }
    ctx.set_fonts(defs);
}

pub fn bold(size: f32) -> egui::FontId {
    egui::FontId::new(size, FontFamily::Name("bold".into()))
}

// ---- Icons, drawn with lines so nothing is copied from the original ----

pub fn icon_menu(p: &egui::Painter, c: Pos2, col: Color32) {
    let s = Stroke::new(1.4, col);
    for dy in [-4.0, 0.0, 4.0] {
        p.line_segment([c + Vec2::new(-6.0, dy), c + Vec2::new(6.0, dy)], s);
    }
}

pub fn icon_grid(p: &egui::Painter, c: Pos2, col: Color32) {
    let s = Stroke::new(1.3, col);
    for (dx, dy) in [(-4.0, -4.0), (4.0, -4.0), (-4.0, 4.0), (4.0, 4.0)] {
        let r = Rect::from_center_size(c + Vec2::new(dx, dy), Vec2::splat(5.5));
        p.rect_stroke(r, 1.5, s, egui::StrokeKind::Middle);
    }
}

pub fn icon_search(p: &egui::Painter, c: Pos2, col: Color32) {
    let s = Stroke::new(1.4, col);
    p.circle_stroke(c + Vec2::new(-1.5, -1.5), 5.0, s);
    p.line_segment([c + Vec2::new(2.2, 2.2), c + Vec2::new(6.0, 6.0)], s);
}

pub fn icon_plus(p: &egui::Painter, c: Pos2, col: Color32, r: f32) {
    let s = Stroke::new(1.4, col);
    p.line_segment([c + Vec2::new(-r, 0.0), c + Vec2::new(r, 0.0)], s);
    p.line_segment([c + Vec2::new(0.0, -r), c + Vec2::new(0.0, r)], s);
}

pub fn icon_close(p: &egui::Painter, c: Pos2, col: Color32, r: f32) {
    let s = Stroke::new(1.3, col);
    p.line_segment([c + Vec2::new(-r, -r), c + Vec2::new(r, r)], s);
    p.line_segment([c + Vec2::new(-r, r), c + Vec2::new(r, -r)], s);
}

pub fn icon_dots(p: &egui::Painter, c: Pos2, col: Color32) {
    for dx in [-5.0, 0.0, 5.0] {
        p.circle_filled(c + Vec2::new(dx, 0.0), 1.3, col);
    }
}

pub fn icon_panel(p: &egui::Painter, c: Pos2, col: Color32, right: bool) {
    let s = Stroke::new(1.3, col);
    let r = Rect::from_center_size(c, Vec2::new(14.0, 12.0));
    p.rect_stroke(r, 2.0, s, egui::StrokeKind::Middle);
    let x = if right { r.right() - 5.0 } else { r.left() + 5.0 };
    p.line_segment([Pos2::new(x, r.top()), Pos2::new(x, r.bottom())], s);
}

pub fn icon_tree(p: &egui::Painter, c: Pos2, col: Color32) {
    let s = Stroke::new(1.3, col);
    let o = c + Vec2::new(-6.0, -5.0);
    p.rect_stroke(Rect::from_min_size(o, Vec2::new(5.0, 4.0)), 1.0, s, egui::StrokeKind::Middle);
    p.line_segment([o + Vec2::new(2.5, 4.0), o + Vec2::new(2.5, 10.0)], s);
    p.line_segment([o + Vec2::new(2.5, 6.5), o + Vec2::new(7.0, 6.5)], s);
    p.line_segment([o + Vec2::new(2.5, 10.0), o + Vec2::new(7.0, 10.0)], s);
    p.rect_stroke(Rect::from_min_size(o + Vec2::new(7.0, 5.0), Vec2::new(5.0, 3.0)), 1.0, s, egui::StrokeKind::Middle);
    p.rect_stroke(Rect::from_min_size(o + Vec2::new(7.0, 8.5), Vec2::new(5.0, 3.0)), 1.0, s, egui::StrokeKind::Middle);
}

pub fn icon_arrow_up(p: &egui::Painter, c: Pos2, col: Color32) {
    let s = Stroke::new(1.8, col);
    p.line_segment([c + Vec2::new(0.0, 5.0), c + Vec2::new(0.0, -5.0)], s);
    p.line_segment([c + Vec2::new(-4.5, -0.5), c + Vec2::new(0.0, -5.0)], s);
    p.line_segment([c + Vec2::new(4.5, -0.5), c + Vec2::new(0.0, -5.0)], s);
}

pub fn icon_stop(p: &egui::Painter, c: Pos2, col: Color32) {
    p.rect_filled(Rect::from_center_size(c, Vec2::splat(8.0)), 1.5, col);
}

pub fn icon_gear(p: &egui::Painter, c: Pos2, col: Color32) {
    let s = Stroke::new(1.3, col);
    p.circle_stroke(c, 2.5, s);
    p.circle_stroke(c, 5.5, s);
    for i in 0..8 {
        let a = i as f32 * std::f32::consts::TAU / 8.0;
        let d = Vec2::angled(a);
        p.line_segment([c + d * 5.5, c + d * 7.5], s);
    }
}

pub fn icon_warning(p: &egui::Painter, c: Pos2, col: Color32) {
    let s = Stroke::new(1.3, col);
    let a = c + Vec2::new(0.0, -6.0);
    let b = c + Vec2::new(-7.0, 6.0);
    let d = c + Vec2::new(7.0, 6.0);
    p.line_segment([a, b], s);
    p.line_segment([b, d], s);
    p.line_segment([d, a], s);
    p.line_segment([c + Vec2::new(0.0, -2.0), c + Vec2::new(0.0, 2.0)], s);
    p.circle_filled(c + Vec2::new(0.0, 4.0), 0.9, col);
}

pub fn icon_chevron(p: &egui::Painter, c: Pos2, col: Color32, open: bool) {
    let s = Stroke::new(1.3, col);
    if open {
        p.line_segment([c + Vec2::new(-3.5, -1.5), c + Vec2::new(0.0, 2.0)], s);
        p.line_segment([c + Vec2::new(3.5, -1.5), c + Vec2::new(0.0, 2.0)], s);
    } else {
        p.line_segment([c + Vec2::new(-1.5, -3.5), c + Vec2::new(2.0, 0.0)], s);
        p.line_segment([c + Vec2::new(-1.5, 3.5), c + Vec2::new(2.0, 0.0)], s);
    }
}

pub fn icon_folder(p: &egui::Painter, c: Pos2, col: Color32) {
    let s = Stroke::new(1.2, col);
    let r = Rect::from_center_size(c + Vec2::new(0.0, 1.0), Vec2::new(13.0, 9.0));
    p.rect_stroke(r, 1.5, s, egui::StrokeKind::Middle);
    p.line_segment([r.left_top() + Vec2::new(0.0, 0.0), r.left_top() + Vec2::new(4.0, -2.0)], s);
    p.line_segment([r.left_top() + Vec2::new(4.0, -2.0), r.left_top() + Vec2::new(6.5, 0.0)], s);
}

pub fn icon_file(p: &egui::Painter, c: Pos2, col: Color32) {
    let s = Stroke::new(1.2, col);
    let r = Rect::from_center_size(c, Vec2::new(10.0, 13.0));
    p.rect_stroke(r, 1.5, s, egui::StrokeKind::Middle);
    p.line_segment([r.left_top() + Vec2::new(2.5, 4.0), r.right_top() + Vec2::new(-2.5, 4.0)], s);
    p.line_segment([r.left_top() + Vec2::new(2.5, 7.0), r.right_top() + Vec2::new(-2.5, 7.0)], s);
}

/// Small square with the project's first letter, like the original's project avatar.
pub fn avatar(ui: &mut egui::Ui, pal: &Pal, name: &str, size: f32) -> egui::Response {
    let (rect, resp) = ui.allocate_exact_size(Vec2::splat(size), egui::Sense::hover());
    let letter = name.chars().find(|c| c.is_alphanumeric()).unwrap_or('?').to_uppercase().to_string();
    ui.painter().rect_filled(rect, 3.0, pal.avatar_bg);
    ui.painter().text(rect.center(), egui::Align2::CENTER_CENTER, letter, bold(size * 0.62), if pal.dark { Color32::BLACK } else { Color32::WHITE });
    resp
}

/// Ring that fills with the share of the context window in use.
pub fn context_ring(p: &egui::Painter, c: Pos2, r: f32, frac: f32, pal: &Pal) {
    p.circle_stroke(c, r, Stroke::new(1.5, pal.border_base));
    let frac = frac.clamp(0.0, 1.0);
    if frac > 0.0 {
        let n = 40;
        let pts: Vec<Pos2> = (0..=n)
            .map(|i| {
                let a = -std::f32::consts::FRAC_PI_2 + frac * std::f32::consts::TAU * i as f32 / n as f32;
                c + Vec2::angled(a) * r
            })
            .collect();
        let col = if frac > 0.9 { pal.critical } else if frac > 0.7 { pal.warning } else { pal.text_base };
        p.add(egui::Shape::line(pts, Stroke::new(1.8, col)));
    }
}

/// A clickable square with an icon drawn by `draw`.
pub fn icon_button(ui: &mut egui::Ui, pal: &Pal, size: f32, tip: &str, draw: impl FnOnce(&egui::Painter, Pos2, Color32)) -> egui::Response {
    let (rect, resp) = ui.allocate_exact_size(Vec2::splat(size), egui::Sense::click());
    if resp.hovered() {
        ui.painter().rect_filled(rect, 6.0, pal.bg_hover);
    }
    let col = if resp.hovered() { pal.text_strong } else { pal.icon };
    draw(ui.painter(), rect.center(), col);
    resp.on_hover_text(tip)
}

