//! The window: top tab bar, home page (projects + sessions), session screen
//! (chat timeline, composer, review/files pane), settings and the command
//! palette.

use crate::agent::{self, AgentEvent, PermReply, PermissionRequest};
use crate::markdown;
use crate::store::{now, Message, Perm, Project, Role, Scheme, Session, Store};
use crate::theme::{self, bold, Pal};
use eframe::egui::{self, Align, Align2, Color32, FontId, Key, Layout, Modifiers, Pos2, Rect, RichText, Sense, Stroke, Vec2};
use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

/// Chat panel width before the person drags the divider (original: DEFAULT_SESSION_WIDTH).
pub const SESSION_WIDTH_DEFAULT: f32 = 600.0;
pub const SESSION_WIDTH_MIN: f32 = 400.0;
pub const SIDE_PANE_MIN: f32 = 320.0;
pub const FILE_TREE_WIDTH: f32 = 200.0;
pub const TOPBAR_H: f32 = 44.0;
pub const INSET: f32 = 8.0;
pub const HOME_MAX_W: f32 = 1080.0;
pub const HOME_PROJECTS_W: f32 = 280.0;
pub const HOME_SESSIONS_MAX_W: f32 = 720.0;
pub const SESSION_ROW_H: f32 = 40.0;
pub const TITLE_MAX_CHARS: usize = 50;
pub const MAX_TAB_W: f32 = 224.0;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Screen {
    Home,
    Session(u64),
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum SettingsTab {
    General,
    Models,
    Permissions,
    Shortcuts,
    About,
}

struct ActiveRun {
    run: agent::Run,
    status: String,
    pending: Option<PermissionRequest>,
    started: f64,
}

struct OpenFile {
    path: PathBuf,
    text: Result<String, String>,
}

struct Palette {
    query: String,
    selected: usize,
}

#[derive(Clone)]
enum Cmd {
    NewSession,
    Home,
    Settings,
    ToggleReview,
    ToggleShell,
    CycleAgent,
    ChooseModel(String),
    Undo,
    Compact,
    Rename,
    Delete,
    Export,
    AddProject,
    AutoAccept,
    OpenSession(u64),
    CloseTab,
}

struct Shot {
    path: PathBuf,
    frames: u32,
    requested: bool,
    image: Arc<Mutex<Option<Arc<egui::ColorImage>>>>,
}

pub struct App {
    store: Store,
    pal: Pal,
    applied_dark: Option<bool>,
    applied_zoom: f32,
    screen: Screen,
    drafts: HashMap<u64, String>,
    shell_mode: bool,
    runs: HashMap<u64, ActiveRun>,
    queues: HashMap<u64, Vec<String>>,
    always: HashMap<u64, HashSet<String>>,
    show_review: bool,
    show_tree: bool,
    session_width: f32,
    files: Vec<OpenFile>,
    active_file: Option<usize>,
    expanded: HashSet<PathBuf>,
    settings_open: bool,
    settings_tab: SettingsTab,
    palette: Option<Palette>,
    add_project: Option<String>,
    rename: Option<(u64, String)>,
    confirm_delete: Option<u64>,
    home_search: String,
    home_project: Option<u64>,
    toasts: Vec<(String, f64)>,
    shot: Option<Shot>,
    dirty: bool,
    last_save: f64,
    expanded_tools: HashSet<(u64, usize)>,
    stick_bottom: bool,
    focus_composer: bool,
    show_key: bool,
    models_text: String,
}

impl App {
    pub fn new(cc: &eframe::CreationContext<'_>, screenshot: Option<PathBuf>) -> Self {
        theme::fonts(&cc.egui_ctx);
        let store = Store::load();
        let screen = match store.active_tab {
            Some(id) if store.open_tabs.contains(&id) => Screen::Session(id),
            _ => Screen::Home,
        };
        let models_text = store.settings.models.join("\n");
        let mut app = Self {
            store,
            pal: Pal::light(),
            applied_dark: None,
            applied_zoom: 0.0,
            screen,
            drafts: HashMap::new(),
            shell_mode: false,
            runs: HashMap::new(),
            queues: HashMap::new(),
            always: HashMap::new(),
            show_review: true,
            show_tree: false,
            session_width: SESSION_WIDTH_DEFAULT,
            files: vec![],
            active_file: None,
            expanded: HashSet::new(),
            settings_open: false,
            settings_tab: SettingsTab::General,
            palette: None,
            add_project: None,
            rename: None,
            confirm_delete: None,
            home_search: String::new(),
            home_project: None,
            toasts: vec![],
            shot: screenshot.map(|path| Shot { path, frames: 0, requested: false, image: Arc::new(Mutex::new(None)) }),
            dirty: false,
            last_save: 0.0,
            expanded_tools: HashSet::new(),
            stick_bottom: true,
            focus_composer: true,
            show_key: false,
            models_text,
        };
        app.ensure_tab_state();
        app
    }

    fn ensure_tab_state(&mut self) {
        if let Screen::Session(id) = self.screen {
            if self.store.session(id).is_none() {
                self.screen = Screen::Home;
            }
        }
    }

    fn toast(&mut self, text: impl Into<String>, t: f64) {
        self.toasts.push((text.into(), t + 3.5));
    }

    fn project_of(&self, sid: u64) -> Option<&Project> {
        let pid = self.store.session(sid)?.project_id;
        self.store.project(pid)
    }

    // ------------------------------------------------------------ actions

    fn open_session(&mut self, id: u64) {
        if !self.store.open_tabs.contains(&id) {
            self.store.open_tabs.push(id);
        }
        self.store.closed_tabs.retain(|t| *t != id);
        self.store.active_tab = Some(id);
        if let Some(s) = self.store.session_mut(id) {
            s.unread = false;
        }
        self.screen = Screen::Session(id);
        self.stick_bottom = true;
        self.focus_composer = true;
        self.files.clear();
        self.active_file = None;
        self.dirty = true;
    }

    fn new_session(&mut self, project: Option<u64>) {
        let pid = project
            .or(self.home_project)
            .or_else(|| match self.screen {
                Screen::Session(s) => self.store.session(s).map(|s| s.project_id),
                Screen::Home => None,
            })
            .or_else(|| self.store.projects.first().map(|p| p.id));
        let Some(pid) = pid else {
            self.add_project = Some(String::new());
            return;
        };
        let id = self.store.new_id();
        let t = now();
        self.store.sessions.push(Session {
            id,
            project_id: pid,
            title: "New session".into(),
            created: t,
            updated: t,
            messages: vec![],
            agent: "build".into(),
            context_tokens: 0,
            total_tokens: 0,
            cost: 0.0,
            todos: vec![],
            changed_files: vec![],
            unread: false,
        });
        self.open_session(id);
    }

    fn close_tab(&mut self, id: u64) {
        let idx = self.store.open_tabs.iter().position(|t| *t == id);
        self.store.open_tabs.retain(|t| *t != id);
        // An empty session that was never used goes away with its tab.
        let empty = self.store.session(id).map(|s| s.messages.is_empty()).unwrap_or(false);
        if empty && !self.runs.contains_key(&id) {
            self.store.sessions.retain(|s| s.id != id);
        } else {
            self.store.closed_tabs.retain(|t| *t != id);
            self.store.closed_tabs.push(id);
        }
        if self.screen == Screen::Session(id) {
            let next = idx.and_then(|i| self.store.open_tabs.get(i.min(self.store.open_tabs.len().saturating_sub(1))).copied());
            match next {
                Some(n) => self.open_session(n),
                None => {
                    self.screen = Screen::Home;
                    self.store.active_tab = None;
                }
            }
        }
        self.dirty = true;
    }

    fn delete_session(&mut self, id: u64) {
        if let Some(r) = self.runs.remove(&id) {
            r.run.cancel.store(true, std::sync::atomic::Ordering::Relaxed);
        }
        self.store.open_tabs.retain(|t| *t != id);
        self.store.closed_tabs.retain(|t| *t != id);
        self.store.sessions.retain(|s| s.id != id);
        if self.screen == Screen::Session(id) {
            match self.store.open_tabs.last().copied() {
                Some(n) => self.open_session(n),
                None => self.screen = Screen::Home,
            }
        }
        self.dirty = true;
    }

    fn run_config(&self, sid: u64, compact: bool) -> Option<agent::RunConfig> {
        let s = self.store.session(sid)?;
        let p = self.store.project(s.project_id)?;
        let st = &self.store.settings;
        Some(agent::RunConfig {
            base_url: st.base_url.clone(),
            api_key: st.api_key.clone(),
            model: st.model.clone(),
            agent: s.agent.clone(),
            project_dir: PathBuf::from(&p.path),
            perms: st.perms.clone(),
            auto_accept: st.auto_accept,
            always: self.always.get(&sid).cloned().unwrap_or_default(),
            shell: st.shell.clone(),
            max_steps: st.max_steps,
            compact,
        })
    }

    fn submit(&mut self, sid: u64, ctx: &egui::Context, t: f64) {
        let text = self.drafts.get(&sid).cloned().unwrap_or_default();
        let text = text.trim().to_string();
        if text.is_empty() {
            return;
        }
        self.drafts.insert(sid, String::new());
        if self.shell_mode {
            self.run_user_shell(sid, text, ctx, t);
            return;
        }
        if text.starts_with('/') {
            if self.slash(sid, &text, ctx, t) {
                return;
            }
        }
        if self.runs.contains_key(&sid) {
            self.queues.entry(sid).or_default().push(text);
            return;
        }
        self.send_prompt(sid, text, ctx, t);
    }

    /// Built-in slash commands. Returns true when handled.
    fn slash(&mut self, sid: u64, text: &str, ctx: &egui::Context, t: f64) -> bool {
        match text.split_whitespace().next().unwrap_or("") {
            "/new" => self.new_session(None),
            "/compact" | "/summarize" => self.compact(sid, ctx, t),
            "/undo" => self.undo(sid),
            "/plan" => self.set_agent(sid, "plan"),
            "/build" => self.set_agent(sid, "build"),
            "/settings" => self.settings_open = true,
            "/export" => self.export(sid, t),
            _ => return false,
        }
        true
    }

    fn set_agent(&mut self, sid: u64, agent: &str) {
        if let Some(s) = self.store.session_mut(sid) {
            s.agent = agent.into();
            self.dirty = true;
        }
    }

    fn send_prompt(&mut self, sid: u64, text: String, ctx: &egui::Context, t: f64) {
        let model = self.store.settings.model.clone();
        let Some(s) = self.store.session_mut(sid) else { return };
        let mut m = Message::new(Role::User, text.clone());
        m.agent = s.agent.clone();
        m.model = model;
        s.messages.push(m);
        if s.title == "New session" || s.title.is_empty() {
            s.title = make_title(&text);
        }
        s.updated = now();
        let history = s.messages.clone();
        self.stick_bottom = true;
        self.dirty = true;
        if let Some(cfg) = self.run_config(sid, false) {
            let run = agent::spawn(cfg, history, ctx.clone());
            self.runs.insert(sid, ActiveRun { run, status: "Thinking".into(), pending: None, started: t });
        }
    }

    fn run_user_shell(&mut self, sid: u64, command: String, ctx: &egui::Context, t: f64) {
        let Some(p) = self.project_of(sid) else { return };
        let dir = PathBuf::from(&p.path);
        let shell = self.store.settings.shell.clone();
        let (tx, rx) = std::sync::mpsc::channel();
        let cancel = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let c2 = cancel.clone();
        let ctx2 = ctx.clone();
        let cmd2 = command.clone();
        std::thread::spawn(move || {
            let (out, ok) = match agent::run_shell(&shell, &cmd2, &dir, agent::BASH_DEFAULT_TIMEOUT_MS, &c2) {
                Ok((o, code)) => (if code == 0 { o } else { format!("{o}\n\nCommand exited with code {code}") }, code == 0),
                Err(e) => (e, false),
            };
            let _ = tx.send(AgentEvent::ToolResult { call_id: String::new(), name: "user_shell".into(), title: cmd2, output: out, ok });
            let _ = tx.send(AgentEvent::Done);
            ctx2.request_repaint();
        });
        self.runs.insert(sid, ActiveRun { run: agent::Run { rx, cancel }, status: "Running commands".into(), pending: None, started: t });
        let _ = command;
        self.stick_bottom = true;
    }

    fn compact(&mut self, sid: u64, ctx: &egui::Context, t: f64) {
        if self.runs.contains_key(&sid) {
            return;
        }
        let Some(s) = self.store.session(sid) else { return };
        if s.messages.is_empty() {
            return;
        }
        let history = s.messages.clone();
        if let Some(cfg) = self.run_config(sid, true) {
            let run = agent::spawn(cfg, history, ctx.clone());
            self.runs.insert(sid, ActiveRun { run, status: "Summarizing".into(), pending: None, started: t });
        }
    }

    fn undo(&mut self, sid: u64) {
        if self.runs.contains_key(&sid) {
            return;
        }
        let Some(s) = self.store.session_mut(sid) else { return };
        if let Some(i) = s.messages.iter().rposition(|m| m.role == Role::User || m.role == Role::Shell) {
            let m = s.messages[i].clone();
            s.messages.truncate(i);
            let back = if m.role == Role::Shell { m.title } else { m.text };
            self.drafts.insert(sid, back);
            self.dirty = true;
        }
    }

    fn export(&mut self, sid: u64, t: f64) {
        let Some(s) = self.store.session(sid) else { return };
        let dir = dirs::download_dir().or_else(dirs::home_dir).unwrap_or_else(|| PathBuf::from("."));
        let safe: String = s.title.chars().map(|c| if c.is_alphanumeric() || c == ' ' || c == '-' { c } else { '_' }).collect();
        let path = dir.join(format!("session-{}.json", safe.trim().replace(' ', "-")));
        let res = serde_json::to_string_pretty(s).map_err(|e| e.to_string()).and_then(|j| std::fs::write(&path, j).map_err(|e| e.to_string()));
        match res {
            Ok(()) => self.toast(format!("Exported to {}", path.display()), t),
            Err(e) => self.toast(format!("Export failed: {e}"), t),
        }
    }

    fn stop(&mut self, sid: u64) {
        if let Some(r) = self.runs.get(&sid) {
            r.run.cancel.store(true, std::sync::atomic::Ordering::Relaxed);
        }
    }

    fn add_project_path(&mut self, path: &str, t: f64) {
        let path = path.trim().trim_matches('"').to_string();
        let pb = PathBuf::from(&path);
        if !pb.is_dir() {
            self.toast("That folder doesn't exist", t);
            return;
        }
        if let Some(p) = self.store.projects.iter().find(|p| Path::new(&p.path) == pb.as_path()) {
            self.home_project = Some(p.id);
            return;
        }
        let name = pb.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_else(|| path.clone());
        let id = self.store.new_id();
        self.store.projects.push(Project { id, name, path });
        self.home_project = Some(id);
        self.dirty = true;
    }

    fn run_cmd(&mut self, cmd: Cmd, ctx: &egui::Context, t: f64) {
        let sid = match self.screen {
            Screen::Session(s) => Some(s),
            Screen::Home => None,
        };
        match cmd {
            Cmd::NewSession => self.new_session(None),
            Cmd::Home => self.screen = Screen::Home,
            Cmd::Settings => self.settings_open = true,
            Cmd::ToggleReview => self.show_review = !self.show_review,
            Cmd::ToggleShell => self.shell_mode = !self.shell_mode,
            Cmd::CycleAgent => {
                if let Some(s) = sid.and_then(|s| self.store.session_mut(s)) {
                    s.agent = if s.agent == "build" { "plan".into() } else { "build".into() };
                    self.dirty = true;
                }
            }
            Cmd::ChooseModel(m) => {
                self.store.settings.model = m;
                self.dirty = true;
            }
            Cmd::Undo => {
                if let Some(s) = sid {
                    self.undo(s)
                }
            }
            Cmd::Compact => {
                if let Some(s) = sid {
                    self.compact(s, ctx, t)
                }
            }
            Cmd::Rename => {
                if let Some(s) = sid.and_then(|s| self.store.session(s)) {
                    self.rename = Some((s.id, s.title.clone()));
                }
            }
            Cmd::Delete => self.confirm_delete = sid,
            Cmd::Export => {
                if let Some(s) = sid {
                    self.export(s, t)
                }
            }
            Cmd::AddProject => self.add_project = Some(String::new()),
            Cmd::AutoAccept => {
                self.store.settings.auto_accept = !self.store.settings.auto_accept;
                let msg = if self.store.settings.auto_accept { "Auto-accepting permissions" } else { "Stopped auto-accepting permissions" };
                self.toast(msg, t);
                self.dirty = true;
            }
            Cmd::OpenSession(id) => self.open_session(id),
            Cmd::CloseTab => {
                if let Some(s) = sid {
                    self.close_tab(s)
                }
            }
        }
    }

    // ------------------------------------------------------------ agent events

    fn pump(&mut self, ctx: &egui::Context, t: f64) {
        let ids: Vec<u64> = self.runs.keys().copied().collect();
        let mut finished = vec![];
        for sid in ids {
            loop {
                let ev = match self.runs.get(&sid) {
                    Some(r) => match r.run.rx.try_recv() {
                        Ok(e) => e,
                        Err(std::sync::mpsc::TryRecvError::Empty) => break,
                        Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                            finished.push(sid);
                            break;
                        }
                    },
                    None => break,
                };
                let model = self.store.settings.model.clone();
                let (pin, pout) = (self.store.settings.price_in, self.store.settings.price_out);
                let active = self.screen == Screen::Session(sid);
                match ev {
                    AgentEvent::Assistant { text, tool_calls } => {
                        if let Some(s) = self.store.session_mut(sid) {
                            let mut m = Message::new(Role::Assistant, text);
                            m.tool_calls = tool_calls;
                            m.agent = s.agent.clone();
                            m.model = model;
                            s.messages.push(m);
                            s.updated = now();
                        }
                    }
                    AgentEvent::ToolResult { call_id, name, title, output, ok } => {
                        if let Some(s) = self.store.session_mut(sid) {
                            let role = if name == "user_shell" { Role::Shell } else { Role::Tool };
                            let mut m = Message::new(role, output);
                            m.tool_call_id = call_id;
                            m.tool_name = name;
                            m.title = title;
                            m.ok = ok;
                            s.messages.push(m);
                            s.updated = now();
                        }
                        if let Some(r) = self.runs.get_mut(&sid) {
                            r.pending = None;
                        }
                    }
                    AgentEvent::Permission(req) => {
                        if let Some(r) = self.runs.get_mut(&sid) {
                            r.pending = Some(req);
                        }
                    }
                    AgentEvent::Usage { prompt, completion } => {
                        if let Some(s) = self.store.session_mut(sid) {
                            s.context_tokens = prompt + completion;
                            s.total_tokens += prompt + completion;
                            s.cost += prompt as f64 * pin / 1e6 + completion as f64 * pout / 1e6;
                        }
                    }
                    AgentEvent::Todos(todos) => {
                        if let Some(s) = self.store.session_mut(sid) {
                            s.todos = todos;
                        }
                    }
                    AgentEvent::FileChanged(f) => {
                        if let Some(s) = self.store.session_mut(sid) {
                            if !s.changed_files.contains(&f) {
                                s.changed_files.push(f);
                            }
                        }
                        if active {
                            for of in self.files.iter_mut() {
                                of.text = read_text(&of.path);
                            }
                        }
                    }
                    AgentEvent::Status(st) => {
                        if let Some(r) = self.runs.get_mut(&sid) {
                            r.status = st;
                        }
                    }
                    AgentEvent::AlwaysAllowed(tool) => {
                        self.always.entry(sid).or_default().insert(tool);
                    }
                    AgentEvent::Compacted(text) => {
                        if let Some(s) = self.store.session_mut(sid) {
                            s.messages.clear();
                            s.messages.push(Message::new(Role::Notice, "Session compacted"));
                            let mut m = Message::new(Role::Assistant, format!("**Summary of the session so far**\n\n{text}"));
                            m.agent = s.agent.clone();
                            s.messages.push(m);
                        }
                    }
                    AgentEvent::Done => finished.push(sid),
                    AgentEvent::Error(e) => {
                        if let Some(s) = self.store.session_mut(sid) {
                            let mut m = Message::new(Role::Notice, e);
                            m.ok = false;
                            s.messages.push(m);
                        }
                        finished.push(sid);
                    }
                }
                self.dirty = true;
                if active {
                    self.stick_bottom = true;
                }
            }
        }
        for sid in finished {
            if self.runs.remove(&sid).is_some() {
                if self.screen != Screen::Session(sid) {
                    if let Some(s) = self.store.session_mut(sid) {
                        s.unread = true;
                    }
                }
                let next = self.queues.get_mut(&sid).and_then(|q| if q.is_empty() { None } else { Some(q.remove(0)) });
                if let Some(text) = next {
                    self.send_prompt(sid, text, ctx, t);
                }
            }
        }
    }

    // ------------------------------------------------------------ keyboard

    fn shortcuts(&mut self, ctx: &egui::Context, t: f64) {
        let cmd = Modifiers::COMMAND;
        let cs = Modifiers::COMMAND | Modifiers::SHIFT;
        let mut todo: Vec<Cmd> = vec![];
        ctx.input_mut(|i| {
            if i.consume_key(cmd, Key::T) || i.consume_key(cmd, Key::N) {
                todo.push(Cmd::NewSession);
            }
            if i.consume_key(cmd, Key::Comma) {
                todo.push(Cmd::Settings);
            }
            if i.consume_key(cmd, Key::K) || i.consume_key(cs, Key::P) {
                self.palette = Some(Palette { query: String::new(), selected: 0 });
            }
            if i.consume_key(cs, Key::R) {
                todo.push(Cmd::ToggleReview);
            }
            if i.consume_key(cs, Key::X) {
                todo.push(Cmd::ToggleShell);
            }
            if i.consume_key(cmd, Key::Period) {
                todo.push(Cmd::CycleAgent);
            }
            if i.consume_key(cmd, Key::W) {
                todo.push(Cmd::CloseTab);
            }
            if i.consume_key(cs, Key::A) {
                todo.push(Cmd::AutoAccept);
            }
            if i.consume_key(cmd, Key::OpenBracket) {
                self.cycle_tab(-1);
            }
            if i.consume_key(cmd, Key::CloseBracket) {
                self.cycle_tab(1);
            }
            if i.consume_key(cs, Key::T) {
                if let Some(id) = self.store.closed_tabs.pop() {
                    todo.push(Cmd::OpenSession(id));
                }
            }
            if i.consume_key(cmd, Key::O) {
                todo.push(Cmd::AddProject);
            }
            if i.consume_key(cmd, Key::Quote) {
                let ms = self.store.settings.models.clone();
                if !ms.is_empty() {
                    let cur = ms.iter().position(|m| *m == self.store.settings.model).map(|p| (p + 1) % ms.len()).unwrap_or(0);
                    todo.push(Cmd::ChooseModel(ms[cur].clone()));
                }
            }
        });
        if let Screen::Session(sid) = self.screen {
            if self.runs.contains_key(&sid) && self.palette.is_none() && !self.settings_open && ctx.input(|i| i.key_pressed(Key::Escape)) {
                self.stop(sid);
            }
        }
        for c in todo {
            self.run_cmd(c, ctx, t);
        }
    }

    fn cycle_tab(&mut self, dir: i32) {
        if self.store.open_tabs.is_empty() {
            return;
        }
        let n = self.store.open_tabs.len() as i32;
        let cur = match self.screen {
            Screen::Session(s) => self.store.open_tabs.iter().position(|t| *t == s).map(|p| p as i32).unwrap_or(-1),
            Screen::Home => -1,
        };
        let next = ((cur + dir) % n + n) % n;
        let id = self.store.open_tabs[next as usize];
        self.open_session(id);
    }

    // ------------------------------------------------------------ drawing: top bar

    fn top_bar(&mut self, ui: &mut egui::Ui, rect: Rect, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        let mut bar = ui.new_child(egui::UiBuilder::new().max_rect(rect.shrink2(Vec2::new(10.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        let mut todo: Vec<Cmd> = vec![];
        let menu = theme::icon_button(&mut bar, &pal, 30.0, "Menu", theme::icon_menu);
        egui::Popup::menu(&menu).show(|ui| {
            ui.set_min_width(200.0);
            if ui.button("New session          Ctrl+T").clicked() {
                todo.push(Cmd::NewSession);
            }
            if ui.button("Add project…         Ctrl+O").clicked() {
                todo.push(Cmd::AddProject);
            }
            if ui.button("Search everything    Ctrl+K").clicked() {
                self.palette = Some(Palette { query: String::new(), selected: 0 });
            }
            ui.separator();
            if ui.button("Settings             Ctrl+,").clicked() {
                todo.push(Cmd::Settings);
            }
        });
        bar.add_space(2.0);
        if theme::icon_button(&mut bar, &pal, 30.0, "Home", theme::icon_grid).clicked() {
            todo.push(Cmd::Home);
        }
        bar.add_space(2.0);
        if theme::icon_button(&mut bar, &pal, 30.0, "Search everything (Ctrl+K)", theme::icon_search).clicked() {
            self.palette = Some(Palette { query: String::new(), selected: 0 });
        }
        bar.add_space(8.0);

        // Session tabs
        let right_reserved = 44.0;
        let avail = (bar.available_width() - right_reserved - 36.0).max(80.0);
        let n = self.store.open_tabs.len().max(1) as f32;
        let tab_w = (avail / n - 4.0).clamp(90.0, MAX_TAB_W);
        let tabs = self.store.open_tabs.clone();
        let mut close: Option<u64> = None;
        for id in tabs {
            let Some(s) = self.store.session(id) else { continue };
            let pname = self.store.project(s.project_id).map(|p| p.name.clone()).unwrap_or_default();
            let title = s.title.clone();
            let unread = s.unread;
            let running = self.runs.contains_key(&id);
            let active = self.screen == Screen::Session(id);
            let (r, resp) = bar.allocate_exact_size(Vec2::new(tab_w, 30.0), Sense::click());
            let fill = if active {
                if pal.dark { pal.bg_weak } else { Color32::from_rgb(0xeb, 0xeb, 0xeb) }
            } else if resp.hovered() {
                pal.bg_hover
            } else {
                Color32::TRANSPARENT
            };
            bar.painter().rect_filled(r, 6.0, fill);
            let av = Rect::from_center_size(Pos2::new(r.left() + 16.0, r.center().y), Vec2::splat(16.0));
            bar.painter().rect_filled(av, 3.0, pal.avatar_bg);
            let letter = pname.chars().find(|c| c.is_alphanumeric()).unwrap_or('?').to_uppercase().to_string();
            bar.painter().text(av.center(), Align2::CENTER_CENTER, letter, bold(10.0), if pal.dark { Color32::BLACK } else { Color32::WHITE });
            if running {
                let a = t as f32 * 5.0;
                bar.painter().circle_filled(av.right_top() + Vec2::new(-1.0, 1.0) + Vec2::angled(a) * 0.5, 3.0, pal.interactive);
            } else if unread {
                bar.painter().circle_filled(av.right_top() + Vec2::new(-1.0, 1.0), 3.0, pal.interactive);
            }
            let text_rect = Rect::from_min_max(Pos2::new(r.left() + 30.0, r.top()), Pos2::new(r.right() - 24.0, r.bottom()));
            let galley = bar.painter().layout_no_wrap(title.clone(), FontId::proportional(13.5), if active { pal.text_strong } else { pal.text_base });
            let clipped = bar.painter().with_clip_rect(text_rect);
            clipped.galley(Pos2::new(text_rect.left(), r.center().y - galley.size().y / 2.0), galley, pal.text_strong);
            if resp.hovered() || active {
                let cr = Rect::from_center_size(Pos2::new(r.right() - 13.0, r.center().y), Vec2::splat(18.0));
                let cresp = bar.interact(cr, egui::Id::new(("tabclose", id)), Sense::click());
                if cresp.hovered() {
                    bar.painter().rect_filled(cr, 4.0, pal.bg_hover);
                }
                theme::icon_close(bar.painter(), cr.center(), if cresp.hovered() { pal.text_strong } else { pal.icon }, 3.5);
                if cresp.clicked() {
                    close = Some(id);
                }
            }
            if resp.clicked() && close.is_none() {
                todo.push(Cmd::OpenSession(id));
            }
            if resp.middle_clicked() {
                close = Some(id);
            }
            resp.on_hover_text(format!("{pname} / {title}"));
            bar.add_space(4.0);
        }
        if theme::icon_button(&mut bar, &pal, 28.0, "New session (Ctrl+T)", |p, c, col| theme::icon_plus(p, c, col, 5.5)).clicked() {
            todo.push(Cmd::NewSession);
        }
        bar.with_layout(Layout::right_to_left(Align::Center), |ui| {
            if theme::icon_button(ui, &pal, 30.0, "Settings (Ctrl+,)", theme::icon_gear).clicked() {
                todo.push(Cmd::Settings);
            }
        });
        if let Some(c) = close {
            self.close_tab(c);
        }
        for c in todo {
            self.run_cmd(c, ctx, t);
        }
    }

    // ------------------------------------------------------------ drawing: home

    fn home(&mut self, ui: &mut egui::Ui, rect: Rect, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        card(ui, &pal, rect);
        let mut todo: Vec<Cmd> = vec![];
        let mut cui = ui.new_child(egui::UiBuilder::new().max_rect(rect.shrink(1.0)).layout(Layout::top_down(Align::Min)));
        egui::ScrollArea::vertical().id_salt("home-scroll").auto_shrink([false, false]).show(&mut cui, |ui| {
            let full = ui.available_width();
            let wide = full >= 900.0;
            let content_w = full.min(HOME_MAX_W) - if wide { 48.0 } else { 24.0 };
            let left_pad = ((full - content_w) / 2.0).max(12.0);
            ui.add_space(if wide { 48.0 } else { 24.0 });
            ui.horizontal_top(|ui| {
                ui.add_space(left_pad);
                if wide {
                    ui.allocate_ui_with_layout(Vec2::new(HOME_PROJECTS_W, 0.0), Layout::top_down(Align::Min), |ui| {
                        ui.set_width(HOME_PROJECTS_W);
                        self.home_projects(ui, &mut todo, t);
                    });
                    ui.add_space(32.0);
                }
                let sw = (content_w - if wide { HOME_PROJECTS_W + 32.0 } else { 0.0 }).min(HOME_SESSIONS_MAX_W);
                ui.allocate_ui_with_layout(Vec2::new(sw, 0.0), Layout::top_down(Align::Min), |ui| {
                    ui.set_width(sw);
                    if !wide {
                        self.home_projects_compact(ui, &mut todo);
                    }
                    self.home_sessions(ui, &mut todo);
                });
            });
            ui.add_space(64.0);
        });
        for c in todo {
            self.run_cmd(c, ctx, t);
        }
    }

    fn home_projects(&mut self, ui: &mut egui::Ui, todo: &mut Vec<Cmd>, _t: f64) {
        let pal = self.pal;
        if primary_button(ui, &pal, "New session", ui.available_width()).clicked() {
            todo.push(Cmd::NewSession);
        }
        ui.add_space(20.0);
        section_label(ui, &pal, "Projects");
        ui.add_space(4.0);
        let all_sel = self.home_project.is_none();
        if list_row(ui, &pal, all_sel, 32.0, |ui| {
            let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
            theme::icon_grid(ui.painter(), r.center(), pal.icon);
            ui.label(RichText::new("All projects").color(pal.text_strong));
        })
        .clicked()
        {
            self.home_project = None;
        }
        let projects = self.store.projects.clone();
        let mut remove: Option<u64> = None;
        for p in &projects {
            let sel = self.home_project == Some(p.id);
            let missing = !Path::new(&p.path).is_dir();
            let resp = list_row(ui, &pal, sel, 32.0, |ui| {
                theme::avatar(ui, &pal, &p.name, 16.0);
                ui.label(RichText::new(&p.name).color(if missing { pal.text_weak } else { pal.text_strong }));
            });
            let resp = resp.on_hover_text(if missing { format!("Project folder not found\n{}", p.path) } else { p.path.clone() });
            if resp.clicked() {
                self.home_project = Some(p.id);
            }
            resp.context_menu(|ui| {
                if ui.button("New session here").clicked() {
                    self.home_project = Some(p.id);
                    todo.push(Cmd::NewSession);
                }
                if ui.button("Open folder").clicked() {
                    open_in_file_manager(Path::new(&p.path));
                }
                if ui.button("Remove from list").clicked() {
                    remove = Some(p.id);
                }
            });
        }
        if let Some(id) = remove {
            self.store.projects.retain(|p| p.id != id);
            let gone: Vec<u64> = self.store.sessions.iter().filter(|s| s.project_id == id).map(|s| s.id).collect();
            for g in gone {
                self.delete_session(g);
            }
            if self.home_project == Some(id) {
                self.home_project = None;
            }
            self.dirty = true;
        }
        if list_row(ui, &pal, false, 32.0, |ui| {
            let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
            theme::icon_plus(ui.painter(), r.center(), pal.icon, 5.0);
            ui.label(RichText::new("Add project").color(pal.text_base));
        })
        .clicked()
        {
            todo.push(Cmd::AddProject);
        }
        ui.add_space(24.0);
        egui::Frame::NONE.fill(pal.bg_weak).corner_radius(8).inner_margin(12).show(ui, |ui| {
            ui.set_width(ui.available_width());
            ui.label(RichText::new("Tip").font(bold(12.5)).color(pal.text_strong));
            ui.label(RichText::new("Connect any OpenAI-compatible service in Settings to use other models, including local ones.").size(12.5).color(pal.text_base));
        });
        ui.add_space(12.0);
        ui.horizontal(|ui| {
            if ui.link(RichText::new("Settings").color(pal.text_base)).clicked() {
                todo.push(Cmd::Settings);
            }
            ui.label(RichText::new("·").color(pal.text_weaker));
            if ui.link(RichText::new("Shortcuts").color(pal.text_base)).clicked() {
                self.settings_tab = SettingsTab::Shortcuts;
                todo.push(Cmd::Settings);
            }
        });
    }

    fn home_projects_compact(&mut self, ui: &mut egui::Ui, todo: &mut Vec<Cmd>) {
        let pal = self.pal;
        ui.horizontal(|ui| {
            let label = self.home_project.and_then(|id| self.store.project(id)).map(|p| p.name.clone()).unwrap_or("All projects".into());
            egui::ComboBox::from_id_salt("home-proj").selected_text(label).show_ui(ui, |ui| {
                ui.selectable_value(&mut self.home_project, None, "All projects");
                for p in self.store.projects.clone() {
                    ui.selectable_value(&mut self.home_project, Some(p.id), p.name.clone());
                }
            });
            if ui.button("Add project").clicked() {
                todo.push(Cmd::AddProject);
            }
            if primary_button(ui, &pal, "New session", 120.0).clicked() {
                todo.push(Cmd::NewSession);
            }
        });
        ui.add_space(12.0);
    }

    fn home_sessions(&mut self, ui: &mut egui::Ui, todo: &mut Vec<Cmd>) {
        let pal = self.pal;
        let scope = self.home_project.and_then(|id| self.store.project(id)).map(|p| p.name.clone());
        let hint = match &scope {
            Some(n) => format!("Search sessions in {n}"),
            None => "Search sessions".into(),
        };
        let search = egui::Frame::NONE
            .fill(pal.bg_weak)
            .corner_radius(8)
            .inner_margin(egui::Margin::symmetric(10, 8))
            .show(ui, |ui| {
                ui.horizontal(|ui| {
                    let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
                    theme::icon_search(ui.painter(), r.center(), pal.icon);
                    ui.add(
                        egui::TextEdit::singleline(&mut self.home_search)
                            .hint_text(RichText::new(hint).color(pal.text_weak))
                            .frame(egui::Frame::NONE)
                            .desired_width(f32::INFINITY),
                    )
                })
                .inner
            })
            .inner;
        if ui.input(|i| i.modifiers.command && i.key_pressed(Key::F)) {
            search.request_focus();
        }
        ui.add_space(18.0);

        let q = self.home_search.to_lowercase();
        let mut list: Vec<&Session> = self
            .store
            .sessions
            .iter()
            .filter(|s| self.home_project.map(|p| s.project_id == p).unwrap_or(true))
            .filter(|s| !s.messages.is_empty() || self.store.open_tabs.contains(&s.id))
            .filter(|s| q.is_empty() || s.title.to_lowercase().contains(&q) || s.messages.iter().any(|m| m.text.to_lowercase().contains(&q)))
            .collect();
        list.sort_by(|a, b| b.updated.cmp(&a.updated));

        if list.is_empty() {
            ui.add_space(40.0);
            ui.vertical_centered(|ui| {
                if q.is_empty() {
                    ui.label(RichText::new("Nothing here yet").font(bold(16.0)).color(pal.text_strong));
                    ui.label(RichText::new("Create a session to get started").color(pal.text_base));
                    ui.add_space(12.0);
                    if primary_button(ui, &pal, "New session", 140.0).clicked() {
                        todo.push(Cmd::NewSession);
                    }
                } else {
                    ui.label(RichText::new(format!("No sessions found for \"{}\"", self.home_search)).color(pal.text_base));
                }
            });
            return;
        }

        let today = chrono::Local::now().date_naive();
        let yesterday = today.pred_opt().unwrap_or(today);
        let day = |s: &Session| {
            chrono::DateTime::from_timestamp(s.updated, 0)
                .map(|d| d.with_timezone(&chrono::Local).date_naive())
                .unwrap_or(today)
        };
        let groups: Vec<(&str, Vec<&Session>)> = {
            let td: Vec<&Session> = list.iter().copied().filter(|s| day(s) == today).collect();
            let yd: Vec<&Session> = list.iter().copied().filter(|s| day(s) == yesterday).collect();
            let od: Vec<&Session> = list.iter().copied().filter(|s| day(s) != today && day(s) != yesterday).collect();
            let older_title = if td.is_empty() && yd.is_empty() { "Recent sessions" } else { "Older" };
            vec![("Today", td), ("Yesterday", yd), (older_title, od)].into_iter().filter(|g| !g.1.is_empty()).collect()
        };
        let mut delete: Option<u64> = None;
        let n_groups = groups.len();
        for (gi, (title, sessions)) in groups.into_iter().enumerate() {
            section_label(ui, &pal, title);
            ui.add_space(6.0);
            for s in sessions {
                let pname = self.store.project(s.project_id).map(|p| p.name.clone()).unwrap_or_default();
                let running = self.runs.contains_key(&s.id);
                let w = ui.available_width();
                let (r, resp) = ui.allocate_exact_size(Vec2::new(w, SESSION_ROW_H), Sense::click());
                if resp.hovered() {
                    ui.painter().rect_filled(r, 6.0, pal.bg_weak);
                }
                let mut x = r.left() + 12.0;
                if s.unread || running {
                    ui.painter().circle_filled(Pos2::new(r.left() + 5.0, r.center().y), 3.0, pal.interactive);
                }
                let tg = ui.painter().layout_no_wrap(s.title.clone(), bold(14.0), pal.text_strong);
                let max_title = (w * 0.6).max(120.0);
                let title_rect = Rect::from_min_size(Pos2::new(x, r.top()), Vec2::new(max_title, r.height()));
                let tw = tg.size().x.min(max_title);
                ui.painter().with_clip_rect(title_rect).galley(Pos2::new(x, r.center().y - tg.size().y / 2.0), tg, pal.text_strong);
                x += tw + 10.0;
                if self.home_project.is_none() {
                    ui.painter().text(Pos2::new(x, r.center().y), Align2::LEFT_CENTER, &pname, FontId::proportional(13.0), pal.text_weak);
                }
                let right = if running { "Working…".to_string() } else { time_ago(s.updated) };
                if resp.hovered() {
                    let cr = Rect::from_center_size(Pos2::new(r.right() - 16.0, r.center().y), Vec2::splat(22.0));
                    let cresp = ui.interact(cr, egui::Id::new(("hdel", s.id)), Sense::click()).on_hover_text("Delete session");
                    if cresp.hovered() {
                        ui.painter().rect_filled(cr, 4.0, pal.bg_hover);
                    }
                    theme::icon_close(ui.painter(), cr.center(), pal.icon, 4.0);
                    if cresp.clicked() {
                        delete = Some(s.id);
                    }
                } else {
                    ui.painter().text(Pos2::new(r.right() - 10.0, r.center().y), Align2::RIGHT_CENTER, right, FontId::proportional(13.0), pal.text_weak);
                }
                if resp.clicked() && delete.is_none() {
                    todo.push(Cmd::OpenSession(s.id));
                }
            }
            if gi + 1 < n_groups {
                ui.add_space(24.0);
            }
        }
        if let Some(d) = delete {
            self.confirm_delete = Some(d);
        }
    }

    // ------------------------------------------------------------ drawing: session

    fn session_screen(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        let avail = rect.width();
        let (left, right) = if self.show_review && avail >= SESSION_WIDTH_MIN + SIDE_PANE_MIN + INSET {
            let w = self.session_width.clamp(SESSION_WIDTH_MIN, (avail - SIDE_PANE_MIN - INSET).max(SESSION_WIDTH_MIN));
            let l = Rect::from_min_size(rect.min, Vec2::new(w, rect.height()));
            let r = Rect::from_min_max(Pos2::new(l.right() + INSET, rect.top()), rect.max);
            // draggable divider
            let handle = Rect::from_min_max(Pos2::new(l.right(), rect.top()), Pos2::new(r.left(), rect.bottom()));
            let hr = ui.interact(handle, egui::Id::new("divider"), Sense::drag()).on_hover_cursor(egui::CursorIcon::ResizeHorizontal);
            if hr.dragged() {
                self.session_width = (self.session_width + hr.drag_delta().x).clamp(SESSION_WIDTH_MIN, avail - SIDE_PANE_MIN - INSET);
            }
            if hr.hovered() || hr.dragged() {
                ui.painter().line_segment([handle.center_top() + Vec2::new(0.0, 12.0), handle.center_bottom() - Vec2::new(0.0, 12.0)], Stroke::new(2.0, pal.interactive));
            }
            (l, Some(r))
        } else {
            (rect, None)
        };
        self.chat_panel(ui, left, sid, ctx, t);
        if let Some(r) = right {
            self.side_pane(ui, r, sid);
        }
    }

    fn chat_panel(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        card(ui, &pal, rect);
        let Some(session) = self.store.session(sid).cloned() else { return };
        let project = self.store.project(session.project_id).cloned();
        let pname = project.as_ref().map(|p| p.name.clone()).unwrap_or("(no project)".into());
        let mut todo: Vec<Cmd> = vec![];

        // header
        let header = Rect::from_min_size(rect.min, Vec2::new(rect.width(), 48.0));
        let mut h = ui.new_child(egui::UiBuilder::new().max_rect(header.shrink2(Vec2::new(16.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        theme::avatar(&mut h, &pal, &pname, 16.0);
        h.add_space(2.0);
        let pl = h.add(egui::Label::new(RichText::new(&pname).color(pal.text_base)).sense(Sense::click()));
        if pl.clicked() {
            self.home_project = Some(session.project_id);
            todo.push(Cmd::Home);
        }
        h.label(RichText::new("/").color(pal.text_weaker));
        let title_w = (h.available_width() - 200.0).max(60.0);
        let tl = h.add_sized(
            Vec2::new(title_w.min(h.fonts_mut(|f| f.layout_no_wrap(session.title.clone(), FontId::proportional(14.0), pal.text_strong).size().x) + 4.0), 20.0),
            egui::Label::new(RichText::new(&session.title).color(pal.text_strong)).truncate().sense(Sense::click()),
        );
        if tl.double_clicked() {
            todo.push(Cmd::Rename);
        }
        let more = theme::icon_button(&mut h, &pal, 26.0, "Session actions", theme::icon_dots);
        egui::Popup::menu(&more).show(|ui| {
            ui.set_min_width(190.0);
            if ui.button("Rename session").clicked() {
                todo.push(Cmd::Rename);
            }
            if ui.button("Compact session").clicked() {
                todo.push(Cmd::Compact);
            }
            if ui.button("Undo last message").clicked() {
                todo.push(Cmd::Undo);
            }
            if ui.button("Export session").clicked() {
                todo.push(Cmd::Export);
            }
            ui.separator();
            if ui.button(RichText::new("Delete session").color(pal.critical)).clicked() {
                todo.push(Cmd::Delete);
            }
        });
        h.with_layout(Layout::right_to_left(Align::Center), |ui| {
            if theme::icon_button(ui, &pal, 28.0, "Toggle review (Ctrl+Shift+R)", |p, c, col| theme::icon_panel(p, c, col, true)).clicked() {
                todo.push(Cmd::ToggleReview);
            }
            ui.add_space(6.0);
            let cost = format!("${:.2}", session.cost);
            ui.label(RichText::new(cost).color(pal.text_weak));
            ui.label(RichText::new("·").color(pal.text_weak));
            ui.label(RichText::new(compact_num(session.context_tokens)).color(pal.text_weak));
            let (r, resp) = ui.allocate_exact_size(Vec2::splat(18.0), Sense::hover());
            let frac = session.context_tokens as f32 / self.store.settings.context_limit.max(1) as f32;
            theme::context_ring(ui.painter(), r.center(), 7.0, frac, &pal);
            resp.on_hover_text(format!(
                "Context: {} of {} tokens ({:.0}%)\nTotal used: {} tokens\nCost: ${:.4}",
                session.context_tokens,
                self.store.settings.context_limit,
                frac * 100.0,
                session.total_tokens,
                session.cost
            ));
        });

        // composer region (bottom), measured first so the timeline gets the rest
        let content_w = (rect.width() - 40.0).min(760.0);
        let col_left = rect.center().x - content_w / 2.0;
        let comp_h = self.composer_height(sid, content_w, ui);
        let comp_rect = Rect::from_min_size(Pos2::new(col_left, rect.bottom() - comp_h - 12.0), Vec2::new(content_w, comp_h));
        let tl_rect = Rect::from_min_max(Pos2::new(rect.left() + 1.0, header.bottom()), Pos2::new(rect.right() - 1.0, comp_rect.top() - 4.0));

        // timeline
        let mut tl = ui.new_child(egui::UiBuilder::new().max_rect(tl_rect).layout(Layout::top_down(Align::Min)));
        let stick = std::mem::replace(&mut self.stick_bottom, false);
        let running = self.runs.get(&sid).map(|r| (r.status.clone(), r.started));
        egui::ScrollArea::vertical()
            .id_salt(("timeline", sid))
            .auto_shrink([false, false])
            .stick_to_bottom(true)
            .show(&mut tl, |ui| {
                let pad = ((ui.available_width() - content_w) / 2.0).max(16.0);
                ui.add_space(8.0);
                ui.horizontal_top(|ui| {
                    ui.add_space(pad);
                    ui.vertical(|ui| {
                        ui.set_width(content_w);
                        if session.messages.is_empty() {
                            self.empty_session(ui, &session, project.as_ref());
                        }
                        self.timeline(ui, &session);
                        if let Some((status, started)) = &running {
                            ui.add_space(6.0);
                            ui.horizontal(|ui| {
                                let txt = format!("{status}…");
                                let phase = ((t - started) * 2.0).sin() as f32 * 0.5 + 0.5;
                                let col = lerp_color(pal.text_weak, pal.text_strong, phase);
                                ui.add(egui::Spinner::new().size(12.0).color(pal.text_weak));
                                ui.label(RichText::new(txt).color(col));
                                ui.label(RichText::new(format!("{}s", (t - started) as u64)).color(pal.text_weaker));
                            });
                            ctx.request_repaint_after(std::time::Duration::from_millis(50));
                        }
                        ui.add_space(24.0);
                    });
                });
                if stick {
                    ui.scroll_to_cursor(Some(Align::BOTTOM));
                }
            });

        self.composer(ui, comp_rect, sid, &session, ctx, t);
        for c in todo {
            self.run_cmd(c, ctx, t);
        }
    }

    fn empty_session(&self, ui: &mut egui::Ui, s: &Session, p: Option<&Project>) {
        let pal = self.pal;
        ui.add_space(60.0);
        ui.vertical_centered(|ui| {
            ui.label(RichText::new("New session").font(bold(20.0)).color(pal.text_strong));
            ui.add_space(4.0);
            if let Some(p) = p {
                ui.label(RichText::new(&p.path).monospace().color(pal.text_weak));
            }
            ui.add_space(14.0);
            let tips = [
                ("Build", "makes changes: edits files and runs commands, asking first"),
                ("Plan", "only reads and explains — switch with Ctrl+."),
                ("Shell", "type commands yourself with Ctrl+Shift+X"),
            ];
            for (a, b) in tips {
                ui.horizontal(|ui| {
                    ui.add_space((ui.available_width() - 420.0).max(0.0) / 2.0);
                    ui.label(RichText::new(a).font(bold(13.5)).color(pal.text_strong));
                    ui.label(RichText::new(b).size(13.5).color(pal.text_base));
                });
            }
            let _ = s;
        });
        ui.add_space(20.0);
    }

    fn timeline(&mut self, ui: &mut egui::Ui, s: &Session) {
        let pal = self.pal;
        let results: HashMap<&str, &Message> = s.messages.iter().filter(|m| m.role == Role::Tool).map(|m| (m.tool_call_id.as_str(), m)).collect();
        for (i, m) in s.messages.iter().enumerate() {
            match m.role {
                Role::User => {
                    ui.add_space(14.0);
                    let maxw = ui.available_width() * 0.82;
                    ui.with_layout(Layout::right_to_left(Align::Min), |ui| {
                        egui::Frame::NONE.fill(pal.bg_weak).corner_radius(10).inner_margin(egui::Margin::symmetric(14, 10)).show(ui, |ui| {
                            ui.set_max_width(maxw);
                            ui.add(egui::Label::new(RichText::new(&m.text).color(pal.text_strong)).wrap());
                        });
                    });
                    if !m.agent.is_empty() {
                        ui.with_layout(Layout::right_to_left(Align::Min), |ui| {
                            let label = format!("{} · {}", cap(&m.agent), m.model);
                            ui.label(RichText::new(label).size(11.5).color(pal.text_weaker));
                        });
                    }
                    ui.add_space(8.0);
                }
                Role::Assistant => {
                    if !m.text.is_empty() {
                        ui.add_space(4.0);
                        markdown::show(ui, &pal, &m.text);
                    }
                    for c in &m.tool_calls {
                        let res = results.get(c.id.as_str()).copied();
                        self.tool_row(ui, s.id, i, c.name.as_str(), &c.args, res);
                    }
                }
                Role::Tool => {} // drawn with its call
                Role::Shell => {
                    let key = (s.id, i);
                    let open = self.expanded_tools.contains(&key);
                    ui.add_space(6.0);
                    let resp = ui
                        .horizontal(|ui| {
                            let lab = if m.ok { "Shell finished" } else { "Shell failed" };
                            ui.label(RichText::new(lab).color(if m.ok { pal.interactive } else { pal.critical }));
                            ui.label(RichText::new("·").color(pal.text_weak));
                            ui.add(egui::Label::new(RichText::new(&m.title).color(pal.text_weak)).truncate());
                        })
                        .response
                        .interact(Sense::click());
                    if resp.clicked() {
                        toggle(&mut self.expanded_tools, key);
                    }
                    if open {
                        output_box(ui, &pal, &format!("$ {}\n{}", m.title, m.text));
                    }
                }
                Role::Notice => {
                    ui.add_space(8.0);
                    let col = if m.ok { pal.text_base } else { pal.critical };
                    egui::Frame::NONE
                        .stroke(Stroke::new(1.0, if m.ok { pal.border_weak } else { pal.critical.gamma_multiply(0.5) }))
                        .corner_radius(8)
                        .inner_margin(egui::Margin::symmetric(12, 8))
                        .show(ui, |ui| {
                            ui.set_width(ui.available_width());
                            ui.add(egui::Label::new(RichText::new(&m.text).color(col)).wrap());
                        });
                    ui.add_space(8.0);
                }
            }
        }
    }

    fn tool_row(&mut self, ui: &mut egui::Ui, sid: u64, idx: usize, name: &str, args: &str, res: Option<&Message>) {
        let pal = self.pal;
        let a: serde_json::Value = serde_json::from_str(args).unwrap_or_default();
        let get = |k: &str| a[k].as_str().unwrap_or("").to_string();
        let subject = match name {
            "bash" => {
                let d = get("description");
                if d.is_empty() { get("command") } else { d }
            }
            "glob" | "grep" => get("pattern"),
            "webfetch" => get("url"),
            "todowrite" => format!("{} todos", a["todos"].as_array().map(|v| v.len()).unwrap_or(0)),
            _ => {
                let p = if a["filePath"].is_string() { get("filePath") } else { get("path") };
                if p.is_empty() { ".".into() } else { p }
            }
        };
        let key = (sid, idx * 1000 + (fxhash(args) % 997) as usize);
        let open = self.expanded_tools.contains(&key);
        let (status_col, label) = match res {
            None => (pal.text_weak, agent::tool_label(name)),
            Some(r) if !r.ok => (pal.critical, format!("{} failed", agent::tool_label(name))),
            Some(_) => (if name == "bash" { pal.interactive } else { pal.text_strong }, if name == "bash" { "Shell finished".into() } else { agent::tool_label(name) }),
        };
        ui.add_space(3.0);
        let resp = ui
            .horizontal(|ui| {
                if res.is_none() {
                    ui.add(egui::Spinner::new().size(11.0).color(pal.text_weak));
                }
                ui.label(RichText::new(label).color(status_col));
                ui.label(RichText::new("·").color(pal.text_weak));
                ui.add(egui::Label::new(RichText::new(&subject).color(pal.text_weak)).truncate());
            })
            .response
            .interact(Sense::click())
            .on_hover_cursor(egui::CursorIcon::PointingHand);
        if resp.clicked() {
            toggle(&mut self.expanded_tools, key);
        }
        if open {
            let mut body = String::new();
            match name {
                "bash" => body.push_str(&format!("$ {}\n", get("command"))),
                "edit" => body.push_str(&format!("- {}\n+ {}\n\n", get("oldString").replace('\n', "\n- "), get("newString").replace('\n', "\n+ "))),
                "write" => body.push_str(&format!("{}\n\n", get("content").chars().take(4000).collect::<String>())),
                _ => {}
            }
            if let Some(r) = res {
                body.push_str(&r.text);
            } else {
                body.push_str("Running…");
            }
            output_box(ui, &pal, &body);
        }
    }

    fn composer_height(&self, sid: u64, w: f32, ui: &egui::Ui) -> f32 {
        let text = self.drafts.get(&sid).map(|s| s.as_str()).unwrap_or("");
        let lines = text.lines().count().max(1) as f32
            + text.lines().map(|l| (l.chars().count() as f32 * 7.6 / (w - 40.0)).floor()).sum::<f32>();
        let input_h = (lines.min(10.0) * 19.0).max(40.0);
        let mut h = input_h + 24.0 + 44.0;
        if let Some(r) = self.runs.get(&sid) {
            if r.pending.is_some() {
                h += 120.0;
            }
        }
        if self.queues.get(&sid).map(|q| !q.is_empty()).unwrap_or(false) {
            h += 34.0;
        }
        if let Some(s) = self.store.session(sid) {
            if !s.todos.is_empty() && s.todos.iter().any(|t| t.status != "completed" && t.status != "cancelled") {
                h += 34.0;
            }
        }
        let _ = ui;
        h
    }

    fn composer(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64, s: &Session, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        let mut c = ui.new_child(egui::UiBuilder::new().max_rect(rect).layout(Layout::top_down(Align::Min)));
        c.set_width(rect.width());

        // todo pill
        let open_todos: Vec<_> = s.todos.iter().filter(|t| t.status != "completed" && t.status != "cancelled").collect();
        if !open_todos.is_empty() {
            let done = s.todos.iter().filter(|t| t.status == "completed").count();
            let current = s.todos.iter().find(|t| t.status == "in_progress").or(open_todos.first().copied());
            let resp = egui::Frame::NONE
                .fill(pal.bg_weak)
                .corner_radius(8)
                .inner_margin(egui::Margin::symmetric(10, 5))
                .show(&mut c, |ui| {
                    ui.horizontal(|ui| {
                        ui.label(RichText::new(format!("{done} of {} todos done", s.todos.len())).size(12.5).color(pal.text_base));
                        if let Some(cur) = current {
                            ui.label(RichText::new("·").color(pal.text_weak));
                            ui.add(egui::Label::new(RichText::new(&cur.content).size(12.5).color(pal.text_strong)).truncate());
                        }
                    });
                })
                .response;
            resp.on_hover_ui(|ui| {
                for t in &s.todos {
                    let mark = match t.status.as_str() {
                        "completed" => "✔",
                        "in_progress" => "▶",
                        "cancelled" => "✖",
                        _ => "○",
                    };
                    ui.label(format!("{mark} {}", t.content));
                }
            });
            c.add_space(6.0);
        }

        // queued prompts
        if let Some(q) = self.queues.get(&sid).cloned() {
            if !q.is_empty() {
                c.horizontal(|ui| {
                    ui.label(RichText::new(format!("{} queued", q.len())).size(12.5).color(pal.text_base));
                    ui.add(egui::Label::new(RichText::new(&q[0]).size(12.5).color(pal.text_weak)).truncate());
                    if ui.small_button("Remove").clicked() {
                        self.queues.entry(sid).or_default().clear();
                    }
                });
                c.add_space(4.0);
            }
        }

        // permission dock
        let mut reply: Option<PermReply> = None;
        if let Some(run) = self.runs.get(&sid) {
            if let Some(req) = &run.pending {
                egui::Frame::NONE
                    .fill(pal.bg_panel)
                    .stroke(Stroke::new(1.0, pal.border_base))
                    .corner_radius(10)
                    .inner_margin(egui::Margin::symmetric(14, 12))
                    .show(&mut c, |ui| {
                        ui.set_width(ui.available_width());
                        ui.horizontal(|ui| {
                            let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
                            theme::icon_warning(ui.painter(), r.center(), pal.warning);
                            ui.label(RichText::new(format!("Permission required · {}", req.title)).font(bold(14.0)).color(pal.text_strong));
                        });
                        ui.add_space(2.0);
                        ui.add(egui::Label::new(RichText::new(&req.detail).monospace().color(pal.text_base)).truncate());
                        ui.add_space(8.0);
                        ui.horizontal(|ui| {
                            if primary_button(ui, &pal, "Allow once", 100.0).clicked() {
                                reply = Some(PermReply::Once);
                            }
                            if ui.add(egui::Button::new("Allow always").min_size(Vec2::new(100.0, 30.0))).on_hover_text("Allow this kind of action for the rest of this session").clicked() {
                                reply = Some(PermReply::Always);
                            }
                            if ui.add(egui::Button::new(RichText::new("Deny").color(pal.critical)).min_size(Vec2::new(70.0, 30.0))).clicked() {
                                reply = Some(PermReply::Deny);
                            }
                        });
                    });
                c.add_space(6.0);
            }
        }
        if let Some(rp) = reply {
            if let Some(run) = self.runs.get_mut(&sid) {
                if let Some(req) = run.pending.take() {
                    let _ = req.reply.send(rp);
                }
            }
        }

        // the box
        let shell = self.shell_mode;
        let running = self.runs.contains_key(&sid);
        let mut send = false;
        egui::Frame::NONE
            .fill(pal.bg_panel)
            .stroke(Stroke::new(1.0, if shell { pal.interactive.gamma_multiply(0.6) } else { pal.border_base }))
            .corner_radius(10)
            .inner_margin(egui::Margin { left: 12, right: 8, top: 10, bottom: 6 })
            .shadow(egui::Shadow { offset: [0, 2], blur: 8, spread: 0, color: Color32::from_black_alpha(if pal.dark { 60 } else { 10 }) })
            .show(&mut c, |ui| {
                ui.set_width(ui.available_width());
                let draft = self.drafts.entry(sid).or_default();
                let hint = if shell { "Enter shell command… \"git status\"".to_string() } else { "Ask anything, / for commands…".to_string() };
                let te = egui::TextEdit::multiline(draft)
                    .hint_text(RichText::new(hint).color(pal.text_weak))
                    .frame(egui::Frame::NONE)
                    .desired_rows(2)
                    .desired_width(f32::INFINITY)
                    .font(if shell { egui::TextStyle::Monospace } else { egui::TextStyle::Body })
                    .return_key(egui::KeyboardShortcut::new(Modifiers::SHIFT, Key::Enter));
                let out = ui.add(te);
                if self.focus_composer && self.palette.is_none() && !self.settings_open {
                    out.request_focus();
                    self.focus_composer = false;
                }
                if out.has_focus() && ui.input(|i| i.key_pressed(Key::Enter) && !i.modifiers.shift) {
                    send = true;
                }
                if out.has_focus() && draft.is_empty() && ui.input(|i| i.key_pressed(Key::Escape)) && shell {
                    self.shell_mode = false;
                }
                if !shell && draft == "!" {
                    draft.clear();
                    self.shell_mode = true;
                }
                ui.add_space(4.0);
                ui.horizontal(|ui| {
                    // mode / agent
                    if shell {
                        let r = ui.add(egui::Button::new(RichText::new("Shell").color(pal.interactive)).fill(pal.interactive_bg));
                        if r.on_hover_text("Leave shell mode (Ctrl+Shift+X)").clicked() {
                            self.shell_mode = false;
                        }
                    } else {
                        let agent = cap(&s.agent);
                        let r = ui.add(egui::Button::new(RichText::new(agent).color(pal.text_strong)).fill(Color32::TRANSPARENT));
                        if r.on_hover_text("Switch agent (Ctrl+.)").clicked() {
                            if let Some(ss) = self.store.session_mut(sid) {
                                ss.agent = if ss.agent == "build" { "plan".into() } else { "build".into() };
                                self.dirty = true;
                            }
                        }
                        let model = self.store.settings.model.clone();
                        let mr = ui.add(egui::Button::new(RichText::new(&model).color(pal.text_base)).fill(Color32::TRANSPARENT)).on_hover_text("Choose model (Ctrl+')");
                        egui::Popup::menu(&mr).show(|ui| {
                            ui.set_min_width(220.0);
                            ui.label(RichText::new("Models").size(12.0).color(pal.text_weak));
                            for m in self.store.settings.models.clone() {
                                if ui.selectable_label(m == self.store.settings.model, &m).clicked() {
                                    self.store.settings.model = m;
                                    self.dirty = true;
                                }
                            }
                            ui.separator();
                            if ui.button("Manage models…").clicked() {
                                self.settings_tab = SettingsTab::Models;
                                self.settings_open = true;
                            }
                        });
                        if self.store.settings.auto_accept {
                            ui.label(RichText::new("auto-accept").size(12.0).color(pal.warning)).on_hover_text("Permission requests are approved automatically (Ctrl+Shift+A)");
                        }
                    }
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        let (r, resp) = ui.allocate_exact_size(Vec2::splat(30.0), Sense::click());
                        let empty = self.drafts.get(&sid).map(|d| d.trim().is_empty()).unwrap_or(true);
                        if running && empty {
                            ui.painter().circle_filled(r.center(), 15.0, pal.primary_btn);
                            theme::icon_stop(ui.painter(), r.center(), pal.primary_text);
                            if resp.on_hover_text("Stop (Esc)").clicked() {
                                self.stop(sid);
                            }
                        } else {
                            let fill = if empty { pal.text_weaker } else { pal.primary_btn };
                            ui.painter().circle_filled(r.center(), 15.0, fill);
                            theme::icon_arrow_up(ui.painter(), r.center(), pal.primary_text);
                            if resp.on_hover_text(if running { "Queue (Enter)" } else { "Send (Enter)" }).clicked() {
                                send = true;
                            }
                        }
                        ui.add_space(2.0);
                        let tip = if shell { "Prompt mode (Ctrl+Shift+X)" } else { "Shell mode (Ctrl+Shift+X)" };
                        if ui.add(egui::Button::new(RichText::new(">_").monospace().color(if shell { pal.interactive } else { pal.icon })).fill(Color32::TRANSPARENT)).on_hover_text(tip).clicked() {
                            self.shell_mode = !self.shell_mode;
                        }
                    });
                });
            });
        if send {
            if let Some(d) = self.drafts.get_mut(&sid) {
                *d = d.trim_end_matches('\n').to_string();
            }
            self.submit(sid, ctx, t);
            self.focus_composer = true;
        }
    }

    // ------------------------------------------------------------ drawing: review / files

    fn side_pane(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64) {
        let pal = self.pal;
        card(ui, &pal, rect);
        let Some(session) = self.store.session(sid).cloned() else { return };
        let Some(project) = self.store.project(session.project_id).cloned() else { return };
        let root = PathBuf::from(&project.path);

        // tab row
        let tabs_rect = Rect::from_min_size(rect.min, Vec2::new(rect.width(), 48.0));
        let mut tr = ui.new_child(egui::UiBuilder::new().max_rect(tabs_rect.shrink2(Vec2::new(12.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        let n_changed = session.changed_files.len();
        let review_sel = self.active_file.is_none();
        if file_tab(&mut tr, &pal, &format!("Review{}", if n_changed > 0 { format!(" ({n_changed})") } else { String::new() }), review_sel, None).0 {
            self.active_file = None;
        }
        let mut close: Option<usize> = None;
        for (i, f) in self.files.iter().enumerate() {
            let name = f.path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
            let (clicked, closed) = file_tab(&mut tr, &pal, &name, self.active_file == Some(i), Some(f.text.is_err()));
            if clicked {
                self.active_file = Some(i);
            }
            if closed {
                close = Some(i);
            }
        }
        tr.with_layout(Layout::right_to_left(Align::Center), |ui| {
            if theme::icon_button(ui, &pal, 28.0, "Hide review (Ctrl+Shift+R)", |p, c, col| theme::icon_panel(p, c, col, true)).clicked() {
                self.show_review = false;
            }
        });
        if let Some(i) = close {
            self.files.remove(i);
            self.active_file = match self.active_file {
                Some(a) if a == i => if self.files.is_empty() { None } else { Some(i.min(self.files.len() - 1)) },
                Some(a) if a > i => Some(a - 1),
                other => other,
            };
        }
        let y1 = tabs_rect.bottom();
        ui.painter().line_segment([Pos2::new(rect.left(), y1), Pos2::new(rect.right(), y1)], Stroke::new(1.0, pal.border_weak));

        // project row
        let prow = Rect::from_min_size(Pos2::new(rect.left(), y1), Vec2::new(rect.width(), 46.0));
        let mut pr = ui.new_child(egui::UiBuilder::new().max_rect(prow.shrink2(Vec2::new(16.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        if theme::icon_button(&mut pr, &pal, 26.0, "Toggle file tree", theme::icon_tree).clicked() {
            self.show_tree = !self.show_tree;
        }
        pr.add_space(4.0);
        pr.label(RichText::new(&project.name).font(bold(14.0)).color(pal.text_strong));
        pr.add(egui::Label::new(RichText::new(&project.path).size(12.0).color(pal.text_weak)).truncate());
        let y2 = prow.bottom();
        ui.painter().line_segment([Pos2::new(rect.left(), y2), Pos2::new(rect.right(), y2)], Stroke::new(1.0, pal.border_weak));

        let body = Rect::from_min_max(Pos2::new(rect.left() + 1.0, y2 + 1.0), Pos2::new(rect.right() - 1.0, rect.bottom() - 6.0));
        let (tree_rect, view_rect) = if self.show_tree && body.width() > FILE_TREE_WIDTH + 160.0 {
            let tr = Rect::from_min_size(body.min, Vec2::new(FILE_TREE_WIDTH, body.height()));
            let vr = Rect::from_min_max(Pos2::new(tr.right() + 1.0, body.top()), body.max);
            ui.painter().line_segment([Pos2::new(tr.right(), body.top()), Pos2::new(tr.right(), body.bottom())], Stroke::new(1.0, pal.border_weak));
            (Some(tr), vr)
        } else {
            (None, body)
        };
        let mut open: Option<PathBuf> = None;
        if let Some(tr) = tree_rect {
            let mut tu = ui.new_child(egui::UiBuilder::new().max_rect(tr.shrink2(Vec2::new(6.0, 6.0))).layout(Layout::top_down(Align::Min)));
            egui::ScrollArea::vertical().id_salt("tree").auto_shrink([false, false]).show(&mut tu, |ui| {
                self.tree(ui, &root, 0, &mut open);
            });
        }
        let mut vu = ui.new_child(egui::UiBuilder::new().max_rect(view_rect.shrink2(Vec2::new(16.0, 10.0))).layout(Layout::top_down(Align::Min)));
        match self.active_file {
            Some(i) if i < self.files.len() => {
                let f = &self.files[i];
                match &f.text {
                    Ok(text) => {
                        egui::ScrollArea::both().id_salt(("file", i)).auto_shrink([false, false]).show(&mut vu, |ui| {
                            let digits = text.lines().count().to_string().len().max(2);
                            let mut job = egui::text::LayoutJob::default();
                            for (n, line) in text.lines().enumerate() {
                                job.append(&format!("{:>w$}  ", n + 1, w = digits), 0.0, egui::TextFormat { font_id: FontId::monospace(12.5), color: pal.text_weaker, ..Default::default() });
                                job.append(line, 0.0, egui::TextFormat { font_id: FontId::monospace(12.5), color: pal.text_strong, ..Default::default() });
                                job.append("\n", 0.0, egui::TextFormat::default());
                            }
                            ui.add(egui::Label::new(job).extend());
                        });
                    }
                    Err(e) => {
                        vu.label(RichText::new(e).color(pal.text_weak));
                    }
                }
            }
            _ => {
                egui::ScrollArea::vertical().id_salt("review").auto_shrink([false, false]).show(&mut vu, |ui| {
                    if session.changed_files.is_empty() {
                        if tree_rect.is_none() {
                            ui.label(RichText::new("Files").size(12.5).color(pal.text_weak));
                            ui.add_space(4.0);
                            self.tree(ui, &root, 0, &mut open);
                        } else {
                            ui.add_space(30.0);
                            ui.vertical_centered(|ui| {
                                ui.label(RichText::new("No changes yet").color(pal.text_base));
                                ui.label(RichText::new("Files the assistant edits show up here.").size(12.5).color(pal.text_weak));
                            });
                        }
                    } else {
                        let n = session.changed_files.len();
                        ui.label(RichText::new(format!("{n} Changed file{}", if n == 1 { "" } else { "s" })).font(bold(14.0)).color(pal.text_strong));
                        ui.add_space(6.0);
                        for f in &session.changed_files {
                            let r = list_row(ui, &pal, false, 30.0, |ui| {
                                let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
                                theme::icon_file(ui.painter(), r.center(), pal.icon);
                                ui.label(RichText::new(f).color(pal.text_strong));
                            });
                            if r.clicked() {
                                open = Some(root.join(f));
                            }
                        }
                    }
                });
            }
        }
        if let Some(p) = open {
            self.open_file(p);
        }
    }

    fn tree(&mut self, ui: &mut egui::Ui, dir: &Path, depth: usize, open: &mut Option<PathBuf>) {
        let pal = self.pal;
        let Ok(rd) = std::fs::read_dir(dir) else {
            ui.label(RichText::new("Project folder not found").color(pal.text_weak));
            return;
        };
        let mut entries: Vec<(bool, String, PathBuf)> = rd
            .filter_map(|e| e.ok())
            .map(|e| (e.path().is_dir(), e.file_name().to_string_lossy().to_string(), e.path()))
            .filter(|(_, n, _)| !n.starts_with('.') && !agent::ignored(n))
            .collect();
        entries.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.to_lowercase().cmp(&b.1.to_lowercase())));
        for (is_dir, name, path) in entries.into_iter().take(500) {
            let expanded = self.expanded.contains(&path);
            let resp = list_row(ui, &pal, false, 24.0, |ui| {
                ui.add_space(depth as f32 * 12.0);
                let (r, _) = ui.allocate_exact_size(Vec2::splat(14.0), Sense::hover());
                if is_dir {
                    theme::icon_chevron(ui.painter(), r.center(), pal.icon, expanded);
                } else {
                    theme::icon_file(ui.painter(), r.center(), pal.text_weaker);
                }
                ui.add(egui::Label::new(RichText::new(&name).size(13.0).color(if is_dir { pal.text_strong } else { pal.text_base })).truncate().selectable(false));
            });
            if resp.clicked() {
                if is_dir {
                    toggle(&mut self.expanded, path.clone());
                } else {
                    *open = Some(path.clone());
                }
            }
            if is_dir && expanded {
                self.tree(ui, &path, depth + 1, open);
            }
        }
    }

    fn open_file(&mut self, p: PathBuf) {
        if let Some(i) = self.files.iter().position(|f| f.path == p) {
            self.files[i].text = read_text(&p);
            self.active_file = Some(i);
            return;
        }
        let text = read_text(&p);
        self.files.push(OpenFile { path: p, text });
        self.active_file = Some(self.files.len() - 1);
        self.show_review = true;
    }

    // ------------------------------------------------------------ dialogs

    fn dialogs(&mut self, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        // add project
        if let Some(mut path) = self.add_project.take() {
            let mut keep = true;
            let mut add = false;
            egui::Modal::new(egui::Id::new("addproj")).show(ctx, |ui| {
                ui.set_width(460.0);
                ui.label(RichText::new("Add project").font(bold(17.0)).color(pal.text_strong));
                ui.label(RichText::new("Pick the folder the assistant should work in.").color(pal.text_base));
                ui.add_space(10.0);
                ui.horizontal(|ui| {
                    let r = ui.add(egui::TextEdit::singleline(&mut path).hint_text("C:\\Users\\you\\my-project").desired_width(340.0));
                    r.request_focus();
                    if r.lost_focus() && ui.input(|i| i.key_pressed(Key::Enter)) {
                        add = true;
                    }
                    if ui.button("Browse…").clicked() {
                        if let Some(p) = rfd::FileDialog::new().set_title("Choose a project folder").pick_folder() {
                            path = p.to_string_lossy().to_string();
                            add = true;
                        }
                    }
                });
                ui.add_space(12.0);
                ui.horizontal(|ui| {
                    if primary_button(ui, &pal, "Add project", 110.0).clicked() {
                        add = true;
                    }
                    if ui.button("Cancel").clicked() || ui.input(|i| i.key_pressed(Key::Escape)) {
                        keep = false;
                    }
                });
            });
            if add {
                self.add_project_path(&path, t);
                keep = false;
            }
            if keep {
                self.add_project = Some(path);
            }
        }
        // rename
        if let Some((id, mut title)) = self.rename.take() {
            let mut keep = true;
            let mut save = false;
            egui::Modal::new(egui::Id::new("rename")).show(ctx, |ui| {
                ui.set_width(380.0);
                ui.label(RichText::new("Rename session").font(bold(17.0)).color(pal.text_strong));
                ui.add_space(8.0);
                let r = ui.add(egui::TextEdit::singleline(&mut title).desired_width(f32::INFINITY));
                r.request_focus();
                if ui.input(|i| i.key_pressed(Key::Enter)) {
                    save = true;
                }
                ui.add_space(10.0);
                ui.horizontal(|ui| {
                    if primary_button(ui, &pal, "Save", 80.0).clicked() {
                        save = true;
                    }
                    if ui.button("Cancel").clicked() || ui.input(|i| i.key_pressed(Key::Escape)) {
                        keep = false;
                    }
                });
            });
            if save {
                if let Some(s) = self.store.session_mut(id) {
                    if !title.trim().is_empty() {
                        s.title = title.trim().to_string();
                    }
                }
                self.dirty = true;
                keep = false;
            }
            if keep {
                self.rename = Some((id, title));
            }
        }
        // delete
        if let Some(id) = self.confirm_delete {
            let title = self.store.session(id).map(|s| s.title.clone()).unwrap_or_default();
            let mut close = false;
            egui::Modal::new(egui::Id::new("delete")).show(ctx, |ui| {
                ui.set_width(380.0);
                ui.label(RichText::new("Delete session?").font(bold(17.0)).color(pal.text_strong));
                ui.label(RichText::new(format!("\"{title}\" and its messages will be removed. Files on disk are not touched.")).color(pal.text_base));
                ui.add_space(12.0);
                ui.horizontal(|ui| {
                    if ui.add(egui::Button::new(RichText::new("Delete").color(Color32::WHITE)).fill(pal.critical)).clicked() {
                        self.delete_session(id);
                        close = true;
                    }
                    if ui.button("Cancel").clicked() || ui.input(|i| i.key_pressed(Key::Escape)) {
                        close = true;
                    }
                });
            });
            if close {
                self.confirm_delete = None;
            }
        }
        if self.settings_open {
            self.settings(ctx, t);
        }
        if self.palette.is_some() {
            self.palette_ui(ctx, t);
        }
    }

    fn settings(&mut self, ctx: &egui::Context, _t: f64) {
        let pal = self.pal;
        let mut close = false;
        egui::Modal::new(egui::Id::new("settings")).show(ctx, |ui| {
            let size = Vec2::new(760.0_f32.min(ctx.content_rect().width() - 60.0), 520.0_f32.min(ctx.content_rect().height() - 60.0));
            ui.set_min_size(size);
            ui.set_max_size(size);
            ui.horizontal_top(|ui| {
                ui.vertical(|ui| {
                    ui.set_width(160.0);
                    ui.label(RichText::new("Settings").font(bold(17.0)).color(pal.text_strong));
                    ui.add_space(10.0);
                    for (tab, name) in [
                        (SettingsTab::General, "General"),
                        (SettingsTab::Models, "Models"),
                        (SettingsTab::Permissions, "Permissions"),
                        (SettingsTab::Shortcuts, "Shortcuts"),
                        (SettingsTab::About, "About"),
                    ] {
                        if list_row(ui, &pal, self.settings_tab == tab, 30.0, |ui| {
                            ui.label(RichText::new(name).color(pal.text_strong));
                        })
                        .clicked()
                        {
                            self.settings_tab = tab;
                        }
                    }
                    ui.add_space(ui.available_height() - 36.0);
                    if ui.button("Close").clicked() {
                        close = true;
                    }
                });
                ui.separator();
                ui.vertical(|ui| {
                    egui::ScrollArea::vertical().id_salt("settings-body").auto_shrink([false, false]).show(ui, |ui| {
                        ui.set_width(ui.available_width() - 8.0);
                        self.settings_body(ui);
                    });
                });
            });
            if ui.input(|i| i.key_pressed(Key::Escape)) {
                close = true;
            }
        });
        if close {
            self.settings_open = false;
            self.dirty = true;
            self.focus_composer = true;
        }
    }

