    fn palette_ui(&mut self, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        let Some(mut p) = self.palette.take() else { return };
        let mut items: Vec<(String, String, Cmd)> = vec![
            ("New session".into(), "Ctrl+T".into(), Cmd::NewSession),
            ("Go home".into(), "".into(), Cmd::Home),
            ("Add project".into(), "Ctrl+O".into(), Cmd::AddProject),
            ("Open settings".into(), "Ctrl+,".into(), Cmd::Settings),
            ("Toggle review".into(), "Ctrl+Shift+R".into(), Cmd::ToggleReview),
            ("Toggle shell mode".into(), "Ctrl+Shift+X".into(), Cmd::ToggleShell),
            ("Cycle agent".into(), "Ctrl+.".into(), Cmd::CycleAgent),
            ("Auto-accept permissions".into(), "Ctrl+Shift+A".into(), Cmd::AutoAccept),
        ];
        if matches!(self.screen, Screen::Session(_)) {
            items.extend([
                ("Undo last message".into(), "".into(), Cmd::Undo),
                ("Compact session".into(), "".into(), Cmd::Compact),
                ("Rename session".into(), "".into(), Cmd::Rename),
                ("Export session".into(), "".into(), Cmd::Export),
                ("Delete session".into(), "".into(), Cmd::Delete),
                ("Close tab".into(), "Ctrl+W".into(), Cmd::CloseTab),
            ]);
        }
        for m in &self.store.settings.models {
            items.push((format!("Use model: {m}"), "".into(), Cmd::ChooseModel(m.clone())));
        }
        let mut sessions: Vec<&Session> = self.store.sessions.iter().filter(|s| !s.messages.is_empty()).collect();
        sessions.sort_by(|a, b| b.updated.cmp(&a.updated));
        for s in sessions.into_iter().take(200) {
            let pn = self.store.project(s.project_id).map(|p| p.name.clone()).unwrap_or_default();
            items.push((s.title.clone(), pn, Cmd::OpenSession(s.id)));
        }
        let q = p.query.to_lowercase();
        let filtered: Vec<(String, String, Cmd)> = items.into_iter().filter(|(a, b, _)| q.is_empty() || a.to_lowercase().contains(&q) || b.to_lowercase().contains(&q)).collect();
        let mut chosen: Option<Cmd> = None;
        let mut close = false;
        let modal = egui::Modal::new(egui::Id::new("palette")).show(ctx, |ui| {
            ui.set_width(560.0);
            let r = ui.add(egui::TextEdit::singleline(&mut p.query).hint_text("Search commands and sessions").desired_width(f32::INFINITY).font(egui::TextStyle::Body));
            r.request_focus();
            if r.changed() {
                p.selected = 0;
            }
            ui.input(|i| {
                if i.key_pressed(Key::ArrowDown) {
                    p.selected = (p.selected + 1).min(filtered.len().saturating_sub(1));
                }
                if i.key_pressed(Key::ArrowUp) {
                    p.selected = p.selected.saturating_sub(1);
                }
            });
            ui.add_space(6.0);
            egui::ScrollArea::vertical().max_height(360.0).show(ui, |ui| {
                for (i, (a, b, c)) in filtered.iter().enumerate() {
                    let sel = i == p.selected;
                    let resp = list_row(ui, &pal, sel, 30.0, |ui| {
                        ui.label(RichText::new(a).color(pal.text_strong));
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            ui.label(RichText::new(b).size(12.5).color(pal.text_weak));
                        });
                    });
                    if sel {
                        resp.scroll_to_me(None);
                    }
                    if resp.clicked() {
                        chosen = Some(c.clone());
                    }
                }
                if filtered.is_empty() {
                    ui.label(RichText::new("No results").color(pal.text_weak));
                }
            });
            if ui.input(|i| i.key_pressed(Key::Enter)) {
                if let Some((_, _, c)) = filtered.get(p.selected) {
                    chosen = Some(c.clone());
                }
            }
            if ui.input(|i| i.key_pressed(Key::Escape)) {
                close = true;
            }
        });
        if modal.should_close() {
            close = true;
        }
        if let Some(c) = chosen {
            self.run_cmd(c, ctx, t);
            close = true;
        }
        if !close {
            self.palette = Some(p);
        }
    }

    fn toasts(&mut self, ctx: &egui::Context, t: f64) {
        self.toasts.retain(|(_, until)| *until > t);
        if self.toasts.is_empty() {
            return;
        }
        let pal = self.pal;
        egui::Area::new(egui::Id::new("toasts")).anchor(Align2::RIGHT_BOTTOM, Vec2::new(-20.0, -20.0)).show(ctx, |ui| {
            for (msg, _) in &self.toasts {
                egui::Frame::NONE
                    .fill(pal.primary_btn)
                    .corner_radius(8)
                    .inner_margin(egui::Margin::symmetric(14, 10))
                    .show(ui, |ui| {
                        ui.label(RichText::new(msg).color(pal.primary_text));
                    });
                ui.add_space(6.0);
            }
        });
        ctx.request_repaint_after(std::time::Duration::from_millis(250));
    }

    fn apply_theme(&mut self, ctx: &egui::Context) {
        let dark = match self.store.settings.color_scheme {
            Scheme::Dark => true,
            Scheme::Light => false,
            Scheme::System => ctx.system_theme().map(|t| t == egui::Theme::Dark).unwrap_or(false),
        };
        if self.applied_dark != Some(dark) {
            self.pal = if dark { Pal::dark() } else { Pal::light() };
            theme::apply(ctx, &self.pal);
            self.applied_dark = Some(dark);
        }
        let z = self.store.settings.zoom.clamp(0.5, 3.0);
        if (self.applied_zoom - z).abs() > 0.001 {
            ctx.set_zoom_factor(z);
            self.applied_zoom = z;
        }
    }

    fn screenshot_step(&mut self, ctx: &egui::Context) {
        let Some(shot) = &mut self.shot else { return };
        shot.frames += 1;
        ctx.request_repaint();
        if shot.frames >= 120 && !shot.requested {
            shot.requested = true;
            let slot = shot.image.clone();
            let ctx2 = ctx.clone();
            ctx.request_screenshot(move |img| {
                *slot.lock().unwrap() = Some(img);
                ctx2.request_repaint();
            });
        }
        let img = shot.image.lock().unwrap().take();
        if let Some(img) = img {
            let [w, h] = img.size;
            let mut buf = Vec::with_capacity(w * h * 4);
            for p in &img.pixels {
                buf.extend_from_slice(&[p.r(), p.g(), p.b(), 255]);
            }
            if let Some(dir) = shot.path.parent() {
                let _ = std::fs::create_dir_all(dir);
            }
            match image::save_buffer(&shot.path, &buf, w as u32, h as u32, image::ColorType::Rgba8) {
                Ok(()) => eprintln!("saved screenshot to {}", shot.path.display()),
                Err(e) => eprintln!("couldn't save screenshot: {e}"),
            }
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
        if shot.frames > 900 {
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
    }
}

impl eframe::App for App {
    fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
        let ctx = ui.ctx().clone();
        let t = ctx.input(|i| i.time);
        self.apply_theme(&ctx);
        self.pump(&ctx, t);
        if !self.settings_open && self.palette.is_none() && self.add_project.is_none() && self.rename.is_none() {
            self.shortcuts(&ctx, t);
        }
        self.ensure_tab_state();
        let pal = self.pal;
        let full = ui.max_rect();
        ui.painter().rect_filled(full, 0.0, pal.bg_base);
        let bar = Rect::from_min_size(full.min, Vec2::new(full.width(), TOPBAR_H));
        let body = Rect::from_min_max(Pos2::new(full.left() + INSET, bar.bottom()), Pos2::new(full.right() - INSET, full.bottom() - INSET));
        self.top_bar(ui, bar, &ctx, t);
        match self.screen {
            Screen::Home => self.home(ui, body, &ctx, t),
            Screen::Session(id) => self.session_screen(ui, body, id, &ctx, t),
        }
        self.dialogs(&ctx, t);
        self.toasts(&ctx, t);
        if self.dirty && t - self.last_save > 1.0 && self.shot.is_none() {
            self.store.save();
            self.dirty = false;
            self.last_save = t;
        }
        if !self.runs.is_empty() {
            ctx.request_repaint_after(std::time::Duration::from_millis(100));
        }
        self.screenshot_step(&ctx);
    }

    fn on_exit(&mut self) {
        for r in self.runs.values() {
            r.run.cancel.store(true, std::sync::atomic::Ordering::Relaxed);
        }
        if self.shot.is_none() {
            self.store.save();
        }
    }
}

// ------------------------------------------------------------ helpers

fn card(ui: &egui::Ui, pal: &Pal, rect: Rect) {
    ui.painter().rect(rect, 10.0, pal.bg_panel, Stroke::new(1.0, pal.border_weak), egui::StrokeKind::Inside);
}

fn section_label(ui: &mut egui::Ui, pal: &Pal, text: &str) {
    ui.label(RichText::new(text).font(bold(12.5)).color(pal.text_weak));
}

fn heading(ui: &mut egui::Ui, pal: &Pal, text: &str) {
    ui.add_space(10.0);
    ui.label(RichText::new(text).font(bold(15.0)).color(pal.text_strong));
    ui.add_space(4.0);
}

fn setting_row(ui: &mut egui::Ui, pal: &Pal, title: &str, desc: &str, add: impl FnOnce(&mut egui::Ui)) {
    ui.horizontal(|ui| {
        ui.vertical(|ui| {
            ui.set_width((ui.available_width() - 270.0).max(180.0));
            ui.label(RichText::new(title).color(pal.text_strong));
            if !desc.is_empty() {
                ui.label(RichText::new(desc).size(12.5).color(pal.text_weak));
            }
        });
        ui.with_layout(Layout::right_to_left(Align::Center), add);
    });
    ui.add_space(4.0);
    ui.separator();
}

fn primary_button(ui: &mut egui::Ui, pal: &Pal, text: &str, width: f32) -> egui::Response {
    ui.add(
        egui::Button::new(RichText::new(text).font(bold(14.0)).color(pal.primary_text))
            .fill(pal.primary_btn)
            .corner_radius(8)
            .min_size(Vec2::new(width, 32.0)),
    )
}

fn list_row(ui: &mut egui::Ui, pal: &Pal, selected: bool, h: f32, add: impl FnOnce(&mut egui::Ui)) -> egui::Response {
    let w = ui.available_width();
    let (rect, resp) = ui.allocate_exact_size(Vec2::new(w, h), Sense::click());
    if selected {
        ui.painter().rect_filled(rect, 6.0, pal.bg_weak);
    } else if resp.hovered() {
        ui.painter().rect_filled(rect, 6.0, pal.bg_hover.gamma_multiply(0.8));
    }
    let mut child = ui.new_child(egui::UiBuilder::new().max_rect(rect.shrink2(Vec2::new(8.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
    add(&mut child);
    resp
}

/// Returns (clicked, closed).
fn file_tab(ui: &mut egui::Ui, pal: &Pal, name: &str, active: bool, missing: Option<bool>) -> (bool, bool) {
    let galley = ui.painter().layout_no_wrap(name.to_string(), FontId::proportional(13.5), pal.text_strong);
    let closable = missing.is_some();
    let w = (galley.size().x + if closable { 44.0 } else { 20.0 }).min(220.0);
    let (r, resp) = ui.allocate_exact_size(Vec2::new(w, 30.0), Sense::click());
    if active {
        ui.painter().rect_filled(r, 6.0, pal.bg_weak);
    } else if resp.hovered() {
        ui.painter().rect_filled(r, 6.0, pal.bg_hover);
    }
    let col = if missing == Some(true) { pal.text_weak } else if active { pal.text_strong } else { pal.text_base };
    let text_rect = Rect::from_min_max(r.min + Vec2::new(10.0, 0.0), r.max - Vec2::new(if closable { 26.0 } else { 6.0 }, 0.0));
    let g2 = ui.painter().layout_no_wrap(name.to_string(), FontId::proportional(13.5), col);
    ui.painter().with_clip_rect(text_rect).galley(Pos2::new(text_rect.left(), r.center().y - g2.size().y / 2.0), g2, col);
    if missing == Some(true) {
        ui.painter().line_segment([Pos2::new(text_rect.left(), r.center().y), Pos2::new(text_rect.right(), r.center().y)], Stroke::new(1.0, pal.text_weak));
    }
    let mut closed = false;
    if closable {
        let cr = Rect::from_center_size(Pos2::new(r.right() - 14.0, r.center().y), Vec2::splat(18.0));
        let cresp = ui.interact(cr, ui.id().with(("ftc", name)), Sense::click());
        theme::icon_close(ui.painter(), cr.center(), if cresp.hovered() { pal.text_strong } else { pal.icon }, 3.5);
        closed = cresp.clicked();
    }
    ui.add_space(2.0);
    (resp.clicked() && !closed, closed)
}

fn output_box(ui: &mut egui::Ui, pal: &Pal, text: &str) {
    egui::Frame::NONE
        .fill(pal.code_bg)
        .corner_radius(6)
        .inner_margin(egui::Margin::symmetric(10, 8))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            egui::ScrollArea::vertical().max_height(260.0).id_salt(ui.next_auto_id()).show(ui, |ui| {
                let shown: String = text.chars().take(20_000).collect();
                ui.add(egui::Label::new(RichText::new(shown).monospace().size(12.0).color(pal.text_strong)).wrap());
            });
        });
    ui.add_space(4.0);
}

fn toggle<T: std::hash::Hash + Eq>(set: &mut HashSet<T>, v: T) {
    if !set.remove(&v) {
        set.insert(v);
    }
}

fn fxhash(s: &str) -> u64 {
    s.bytes().fold(1469598103934665603u64, |h, b| (h ^ b as u64).wrapping_mul(1099511628211))
}

fn read_text(p: &Path) -> Result<String, String> {
    match std::fs::read(p) {
        Ok(b) if b.iter().take(8000).any(|c| *c == 0) => Err(format!("{} is a binary file", p.display())),
        Ok(b) if b.len() > 2_000_000 => Err("This file is too large to show".into()),
        Ok(b) => Ok(String::from_utf8_lossy(&b).to_string()),
        Err(_) => Err(format!("File not found: {}", p.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default())),
    }
}

fn make_title(text: &str) -> String {
    let first = text.lines().find(|l| !l.trim().is_empty()).unwrap_or("New session").trim();
    let mut t: String = first.chars().take(TITLE_MAX_CHARS).collect();
    if first.chars().count() > TITLE_MAX_CHARS {
        t = t.trim_end().to_string() + "…";
    }
    t
}

fn cap(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
        None => String::new(),
    }
}

/// 136000 -> "136k", like the original's compact number format.
pub fn compact_num(n: u64) -> String {
    if n >= 1_000_000 {
        let v = n as f64 / 1e6;
        if v >= 10.0 { format!("{:.0}M", v) } else { format!("{:.1}M", v).replace(".0M", "M") }
    } else if n >= 1000 {
        let v = n as f64 / 1e3;
        if v >= 10.0 { format!("{:.0}k", v) } else { format!("{:.1}k", v).replace(".0k", "k") }
    } else {
        n.to_string()
    }
}

fn time_ago(ts: i64) -> String {
    let d = now() - ts;
    if d < 60 {
        "now".into()
    } else if d < 3600 {
        format!("{}m", d / 60)
    } else if d < 86400 {
        format!("{}h", d / 3600)
    } else if d < 86400 * 30 {
        format!("{}d", d / 86400)
    } else {
        chrono::DateTime::from_timestamp(ts, 0).map(|d| d.with_timezone(&chrono::Local).format("%b %-d").to_string()).unwrap_or_default()
    }
}

fn lerp_color(a: Color32, b: Color32, t: f32) -> Color32 {
    let l = |x: u8, y: u8| (x as f32 + (y as f32 - x as f32) * t) as u8;
    Color32::from_rgb(l(a.r(), b.r()), l(a.g(), b.g()), l(a.b(), b.b()))
}

fn open_in_file_manager(p: &Path) {
    #[cfg(windows)]
    let _ = std::process::Command::new("explorer").arg(p).spawn();
    #[cfg(target_os = "macos")]
    let _ = std::process::Command::new("open").arg(p).spawn();
    #[cfg(all(unix, not(target_os = "macos")))]
    let _ = std::process::Command::new("xdg-open").arg(p).spawn();
}

