/// Returns (clicked, closed).
fn file_tab(ui: &mut egui::Ui, pal: &Pal, name: &str, active: bool, missing: Option<bool>) -> (bool, bool) {
    let galley = ui.painter().layout_no_wrap(name.to_string(), FontId::proportional(13.5), pal.text_strong);
    let closable = missing.is_some();
    let w = (galley.size().x + if closable { 44.0 } else { 20.0 }).min(220.0);
    let (r, resp) = ui.allocate_exact_size(Vec2::new(w, 30.0), Sense::click());
    if active {
        ui.painter().rect_filled(r, 6.0, pal.bg_weak);
    } else if resp.hovered() {
        ui.painter().rect_filled(r, 6.0, pal.bg_hover);
    }
    let col = if missing == Some(true) { pal.text_weak } else if active { pal.text_strong } else { pal.text_base };
    let text_rect = Rect::from_min_max(r.min + Vec2::new(10.0, 0.0), r.max - Vec2::new(if closable { 26.0 } else { 6.0 }, 0.0));
    let g2 = ui.painter().layout_no_wrap(name.to_string(), FontId::proportional(13.5), col);
    ui.painter().with_clip_rect(text_rect).galley(Pos2::new(text_rect.left(), r.center().y - g2.size().y / 2.0), g2, col);
    if missing == Some(true) {
        ui.painter().line_segment([Pos2::new(text_rect.left(), r.center().y), Pos2::new(text_rect.right(), r.center().y)], Stroke::new(1.0, pal.text_weak));
    }
    let mut closed = false;
    if closable {
        let cr = Rect::from_center_size(Pos2::new(r.right() - 14.0, r.center().y), Vec2::splat(18.0));
        let cresp = ui.interact(cr, ui.id().with(("ftc", name)), Sense::click());
        theme::icon_close(ui.painter(), cr.center(), if cresp.hovered() { pal.text_strong } else { pal.icon }, 3.5);
        closed = cresp.clicked();
    }
    ui.add_space(2.0);
    (resp.clicked() && !closed, closed)
}

