//! Small drawing helpers shared by the screens.

use crate::store::now;
use crate::theme::{self, bold, Pal};
use eframe::egui::{self, Align, Color32, FontId, Layout, Pos2, Rect, RichText, Sense, Stroke, Vec2};
use std::collections::HashSet;
use std::path::Path;

pub fn card(ui: &egui::Ui, pal: &Pal, rect: Rect) {
    ui.painter().rect(rect, 10.0, pal.bg_panel, Stroke::new(1.0, pal.border_weak), egui::StrokeKind::Inside);
}

pub fn section_label(ui: &mut egui::Ui, pal: &Pal, text: &str) {
    ui.label(RichText::new(text).font(bold(12.5)).color(pal.text_weak));
}

pub fn heading(ui: &mut egui::Ui, pal: &Pal, text: &str) {
    ui.add_space(10.0);
    ui.label(RichText::new(text).font(bold(15.0)).color(pal.text_strong));
    ui.add_space(4.0);
}

pub fn setting_row(ui: &mut egui::Ui, pal: &Pal, title: &str, desc: &str, add: impl FnOnce(&mut egui::Ui)) {
    ui.horizontal(|ui| {
        ui.vertical(|ui| {
            ui.set_width((ui.available_width() - 270.0).max(180.0));
            ui.label(RichText::new(title).color(pal.text_strong));
            if !desc.is_empty() {
                ui.label(RichText::new(desc).size(12.5).color(pal.text_weak));
            }
        });
        ui.with_layout(Layout::right_to_left(Align::Center), add);
    });
    ui.add_space(4.0);
    ui.separator();
}

pub fn primary_button(ui: &mut egui::Ui, pal: &Pal, text: &str, width: f32) -> egui::Response {
    ui.add(
        egui::Button::new(RichText::new(text).font(bold(14.0)).color(pal.primary_text))
            .fill(pal.primary_btn)
            .corner_radius(8)
            .min_size(Vec2::new(width, 32.0)),
    )
}

pub fn list_row(ui: &mut egui::Ui, pal: &Pal, selected: bool, h: f32, add: impl FnOnce(&mut egui::Ui)) -> egui::Response {
    let w = ui.available_width();
    let (rect, resp) = ui.allocate_exact_size(Vec2::new(w, h), Sense::click());
    if selected {
        ui.painter().rect_filled(rect, 6.0, pal.bg_weak);
    } else if resp.hovered() {
        ui.painter().rect_filled(rect, 6.0, pal.bg_hover.gamma_multiply(0.8));
    }
    let mut child = ui.new_child(egui::UiBuilder::new().max_rect(rect.shrink2(Vec2::new(8.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
    add(&mut child);
    resp
}

/// A tab in the review pane. Returns (clicked, closed).
pub fn file_tab(ui: &mut egui::Ui, pal: &Pal, name: &str, active: bool, missing: Option<bool>) -> (bool, bool) {
    let closable = missing.is_some();
    let col = if missing == Some(true) {
        pal.text_weak
    } else if active {
        pal.text_strong
    } else {
        pal.text_base
    };
    let galley = ui.painter().layout_no_wrap(name.to_string(), FontId::proportional(13.5), col);
    let w = (galley.size().x + if closable { 44.0 } else { 20.0 }).min(220.0);
    let (r, resp) = ui.allocate_exact_size(Vec2::new(w, 30.0), Sense::click());
    if active {
        ui.painter().rect_filled(r, 6.0, pal.bg_weak);
    } else if resp.hovered() {
        ui.painter().rect_filled(r, 6.0, pal.bg_hover);
    }
    let text_rect = Rect::from_min_max(r.min + Vec2::new(10.0, 0.0), r.max - Vec2::new(if closable { 26.0 } else { 6.0 }, 0.0));
    let gh = galley.size().y;
    ui.painter().with_clip_rect(text_rect).galley(Pos2::new(text_rect.left(), r.center().y - gh / 2.0), galley, col);
    if missing == Some(true) {
        ui.painter().line_segment([Pos2::new(text_rect.left(), r.center().y), Pos2::new(text_rect.right(), r.center().y)], Stroke::new(1.0, pal.text_weak));
    }
    let mut closed = false;
    if closable {
        let cr = Rect::from_center_size(Pos2::new(r.right() - 14.0, r.center().y), Vec2::splat(18.0));
        let cresp = ui.interact(cr, ui.id().with(("ftc", name)), Sense::click());
        theme::icon_close(ui.painter(), cr.center(), if cresp.hovered() { pal.text_strong } else { pal.icon }, 3.5);
        closed = cresp.clicked();
    }
    ui.add_space(2.0);
    (resp.clicked() && !closed, closed)
}

pub fn output_box(ui: &mut egui::Ui, pal: &Pal, text: &str) {
    egui::Frame::NONE
        .fill(pal.code_bg)
        .corner_radius(6)
        .inner_margin(egui::Margin::symmetric(10, 8))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            let id = ui.next_auto_id();
            egui::ScrollArea::vertical().max_height(260.0).id_salt(id).show(ui, |ui| {
                let shown: String = text.chars().take(20_000).collect();
                ui.add(egui::Label::new(RichText::new(shown).monospace().size(12.0).color(pal.text_strong)).wrap());
            });
        });
    ui.add_space(4.0);
}

pub fn toggle<T: std::hash::Hash + Eq>(set: &mut HashSet<T>, v: T) {
    if !set.remove(&v) {
        set.insert(v);
    }
}

pub fn fxhash(s: &str) -> u64 {
    s.bytes().fold(1469598103934665603u64, |h, b| (h ^ b as u64).wrapping_mul(1099511628211))
}

pub fn read_text(p: &Path) -> Result<String, String> {
    match std::fs::read(p) {
        Ok(b) if b.iter().take(8000).any(|c| *c == 0) => Err(format!("{} is a binary file", p.display())),
        Ok(b) if b.len() > 2_000_000 => Err("This file is too large to show".into()),
        Ok(b) => Ok(String::from_utf8_lossy(&b).to_string()),
        Err(_) => Err(format!(
            "File not found: {}",
            p.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default()
        )),
    }
}

/// The first line of the first prompt, cut to `TITLE_MAX_CHARS`.
pub fn make_title(text: &str) -> String {
    let first = text.lines().find(|l| !l.trim().is_empty()).unwrap_or("New session").trim();
    let mut t: String = first.chars().take(super::TITLE_MAX_CHARS).collect();
    if first.chars().count() > super::TITLE_MAX_CHARS {
        t = t.trim_end().to_string() + "…";
    }
    t
}

pub fn cap(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
        None => String::new(),
    }
}

/// 136000 -> "136k", like the original's compact number format (one decimal at most).
pub fn compact_num(n: u64) -> String {
    let fmt = |v: f64, unit: &str| {
        if v >= 10.0 {
            format!("{:.0}{unit}", v)
        } else {
            let s = format!("{:.1}", v);
            format!("{}{unit}", s.trim_end_matches('0').trim_end_matches('.'))
        }
    };
    if n >= 1_000_000 {
        fmt(n as f64 / 1e6, "M")
    } else if n >= 1000 {
        fmt(n as f64 / 1e3, "k")
    } else {
        n.to_string()
    }
}

pub fn time_ago(ts: i64) -> String {
    let d = now() - ts;
    if d < 60 {
        "now".into()
    } else if d < 3600 {
        format!("{}m ago", d / 60)
    } else if d < 86400 {
        format!("{}h ago", d / 3600)
    } else if d < 86400 * 30 {
        format!("{}d ago", d / 86400)
    } else {
        chrono::DateTime::from_timestamp(ts, 0)
            .map(|d| d.with_timezone(&chrono::Local).format("%b %-d").to_string())
            .unwrap_or_default()
    }
}

pub fn lerp_color(a: Color32, b: Color32, t: f32) -> Color32 {
    let l = |x: u8, y: u8| (x as f32 + (y as f32 - x as f32) * t) as u8;
    Color32::from_rgb(l(a.r(), b.r()), l(a.g(), b.g()), l(a.b(), b.b()))
}

pub fn open_in_file_manager(p: &Path) {
    #[cfg(windows)]
    let _ = std::process::Command::new("explorer").arg(p).spawn();
    #[cfg(target_os = "macos")]
    let _ = std::process::Command::new("open").arg(p).spawn();
    #[cfg(all(unix, not(target_os = "macos")))]
    let _ = std::process::Command::new("xdg-open").arg(p).spawn();
}

