            p.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default()
        )),
    }
}

/// The first line of the first prompt, cut to `TITLE_MAX_CHARS`.
pub fn make_title(text: &str) -> String {
    let first = text.lines().find(|l| !l.trim().is_empty()).unwrap_or("New session").trim();
    let mut t: String = first.chars().take(super::TITLE_MAX_CHARS).collect();
    if first.chars().count() > super::TITLE_MAX_CHARS {
        t = t.trim_end().to_string() + "…";
    }
    t
}

pub fn cap(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
        None => String::new(),
    }
}

/// 136000 -> "136k", like the original's compact number format (one decimal at most).
pub fn compact_num(n: u64) -> String {
    let fmt = |v: f64, unit: &str| {
        if v >= 10.0 {
            format!("{:.0}{unit}", v)
        } else {
            let s = format!("{:.1}", v);
            format!("{}{unit}", s.trim_end_matches('0').trim_end_matches('.'))
        }
    };
    if n >= 1_000_000 {
        fmt(n as f64 / 1e6, "M")
    } else if n >= 1000 {
        fmt(n as f64 / 1e3, "k")
    } else {
        n.to_string()
    }
}

pub fn time_ago(ts: i64) -> String {
    let d = now() - ts;
    if d < 60 {
        "now".into()
    } else if d < 3600 {
        format!("{}m ago", d / 60)
    } else if d < 86400 {
        format!("{}h ago", d / 3600)
    } else if d < 86400 * 30 {
        format!("{}d ago", d / 86400)
    } else {
        chrono::DateTime::from_timestamp(ts, 0)
            .map(|d| d.with_timezone(&chrono::Local).format("%b %-d").to_string())
            .unwrap_or_default()
    }
}

pub fn lerp_color(a: Color32, b: Color32, t: f32) -> Color32 {
    let l = |x: u8, y: u8| (x as f32 + (y as f32 - x as f32) * t) as u8;
    Color32::from_rgb(l(a.r(), b.r()), l(a.g(), b.g()), l(a.b(), b.b()))
}

pub fn open_in_file_manager(p: &Path) {
    #[cfg(windows)]
    let _ = std::process::Command::new("explorer").arg(p).spawn();
    #[cfg(target_os = "macos")]
    let _ = std::process::Command::new("open").arg(p).spawn();
    #[cfg(all(unix, not(target_os = "macos")))]
    let _ = std::process::Command::new("xdg-open").arg(p).spawn();
}

