//! The window's state and actions. Drawing lives in the submodules:
//! `topbar` (tab bar), `home` (projects + sessions), `session` (chat,
//! composer, review pane) and `dialogs` (settings, palette, small modals).

mod dialogs;
mod home;
mod session;
mod topbar;
mod widgets;

use crate::agent::{self, AgentEvent, PermissionRequest};
use crate::store::{now, Message, Project, Role, Scheme, Session, Store};
use crate::theme::{self, Pal};
use eframe::egui::{self, Key, Modifiers, Pos2, Rect, Vec2};
use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use widgets::*;

/// Chat panel width before the person drags the divider (original: DEFAULT_SESSION_WIDTH).
pub const SESSION_WIDTH_DEFAULT: f32 = 600.0;
/// Narrowest the chat panel may be dragged (original: SESSION_PANEL_WIDTH_MIN).
pub const SESSION_WIDTH_MIN: f32 = 400.0;
/// Narrowest the review pane may be (original: SIDE_PANE_WIDTH_MIN).
pub const SIDE_PANE_MIN: f32 = 320.0;
/// File tree width inside the review pane (original: DEFAULT_FILE_TREE_WIDTH).
pub const FILE_TREE_WIDTH: f32 = 200.0;
pub const TOPBAR_H: f32 = 44.0;
/// Gap around the panels (original: --shell-inline-inset 8px).
pub const INSET: f32 = 8.0;
/// Home page grid (original: max-w 1080, columns 280px + 720px, gap 32px).
pub const HOME_MAX_W: f32 = 1080.0;
pub const HOME_PROJECTS_W: f32 = 280.0;
pub const HOME_SESSIONS_MAX_W: f32 = 720.0;
/// Session row height on the home page (original: h-10).
pub const SESSION_ROW_H: f32 = 40.0;
pub const TITLE_MAX_CHARS: usize = 50;
pub const MAX_TAB_W: f32 = 224.0;
pub const SCREENSHOT_FRAMES: u32 = 120;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Screen {
    Home,
    Session(u64),
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum SettingsTab {
    General,
    Models,
    Permissions,
    Shortcuts,
    About,
}

struct ActiveRun {
    run: agent::Run,
    status: String,
    pending: Option<PermissionRequest>,
    started: f64,
}

struct OpenFile {
    path: PathBuf,
    text: Result<String, String>,
}

struct Palette {
    query: String,
    selected: usize,
}

#[derive(Clone)]
enum Cmd {
    NewSession,
    Home,
    Settings,
    ToggleReview,
    ToggleShell,
    CycleAgent,
    ChooseModel(String),
    Undo,
    Compact,
    Rename,
    Delete,
    Export,
    AddProject,
    AutoAccept,
    OpenSession(u64),
    CloseTab,
}

struct Shot {
    path: PathBuf,
    frames: u32,
    requested: bool,
    image: Arc<Mutex<Option<Arc<egui::ColorImage>>>>,
}

pub struct App {
    store: Store,
    pal: Pal,
    applied_dark: Option<bool>,
    applied_zoom: f32,
    screen: Screen,
    drafts: HashMap<u64, String>,
    shell_mode: bool,
    runs: HashMap<u64, ActiveRun>,
    queues: HashMap<u64, Vec<String>>,
    always: HashMap<u64, HashSet<String>>,
    show_review: bool,
    show_tree: bool,
    session_width: f32,
    files: Vec<OpenFile>,
    active_file: Option<usize>,
    expanded: HashSet<PathBuf>,
    settings_open: bool,
    settings_tab: SettingsTab,
    palette: Option<Palette>,
    add_project: Option<String>,
    rename: Option<(u64, String)>,
    confirm_delete: Option<u64>,
    home_search: String,
    home_project: Option<u64>,
    toasts: Vec<(String, f64)>,
    shot: Option<Shot>,
    dirty: bool,
    last_save: f64,
    expanded_tools: HashSet<(u64, usize)>,
    stick_bottom: bool,
    focus_composer: bool,
    show_key: bool,
    models_text: String,
}

impl App {
    pub fn new(cc: &eframe::CreationContext<'_>, screenshot: Option<PathBuf>) -> Self {
        theme::fonts(&cc.egui_ctx);
        let store = Store::load();
        let screen = match store.active_tab {
            Some(id) if store.open_tabs.contains(&id) => Screen::Session(id),
            _ => Screen::Home,
        };
        let models_text = store.settings.models.join("\n");
        let mut app = Self {
            store,
            pal: Pal::light(),
            applied_dark: None,
            applied_zoom: 0.0,
            screen,
            drafts: HashMap::new(),
            shell_mode: false,
            runs: HashMap::new(),
            queues: HashMap::new(),
            always: HashMap::new(),
            show_review: true,
            show_tree: false,
            session_width: SESSION_WIDTH_DEFAULT,
            files: vec![],
            active_file: None,
            expanded: HashSet::new(),
            settings_open: false,
            settings_tab: SettingsTab::General,
            palette: None,
            add_project: None,
            rename: None,
            confirm_delete: None,
            home_search: String::new(),
            home_project: None,
            toasts: vec![],
            shot: screenshot.map(|path| Shot { path, frames: 0, requested: false, image: Arc::new(Mutex::new(None)) }),
            dirty: false,
            last_save: 0.0,
            expanded_tools: HashSet::new(),
            stick_bottom: true,
            focus_composer: true,
            show_key: false,
            models_text,
        };
        app.ensure_screen();
        app
    }

    fn ensure_screen(&mut self) {
        if let Screen::Session(id) = self.screen {
            if self.store.session(id).is_none() {
                self.screen = Screen::Home;
            }
        }
    }

    fn toast(&mut self, text: impl Into<String>, t: f64) {
        self.toasts.push((text.into(), t + 3.5));
    }

    fn project_of(&self, sid: u64) -> Option<&Project> {
        let pid = self.store.session(sid)?.project_id;
        self.store.project(pid)
    }

    fn open_palette(&mut self) {
        self.palette = Some(Palette { query: String::new(), selected: 0 });
    }

    // ------------------------------------------------------------ actions

    fn open_session(&mut self, id: u64) {
        if !self.store.open_tabs.contains(&id) {
            self.store.open_tabs.push(id);
        }
        self.store.closed_tabs.retain(|t| *t != id);
        self.store.active_tab = Some(id);
        if let Some(s) = self.store.session_mut(id) {
            s.unread = false;
        }
        if self.screen != Screen::Session(id) {
            self.files.clear();
            self.active_file = None;
        }
        self.screen = Screen::Session(id);
        self.stick_bottom = true;
        self.focus_composer = true;
        self.dirty = true;
    }

    fn new_session(&mut self, project: Option<u64>) {
        let pid = project
            .or(self.home_project)
            .or_else(|| match self.screen {
                Screen::Session(s) => self.store.session(s).map(|s| s.project_id),
                Screen::Home => None,
            })
            .or_else(|| self.store.projects.first().map(|p| p.id));
        let Some(pid) = pid else {
            self.add_project = Some(String::new());
            return;
        };
        let id = self.store.new_id();
        let t = now();
        self.store.sessions.push(Session {
            id,
            project_id: pid,
            title: "New session".into(),
            created: t,
            updated: t,
            messages: vec![],
            agent: "build".into(),
            context_tokens: 0,
            total_tokens: 0,
            cost: 0.0,
            todos: vec![],
            changed_files: vec![],
            unread: false,
        });
        self.open_session(id);
    }

    fn close_tab(&mut self, id: u64) {
        let idx = self.store.open_tabs.iter().position(|t| *t == id);
        self.store.open_tabs.retain(|t| *t != id);
        // An empty session that was never used goes away with its tab.
        let empty = self.store.session(id).map(|s| s.messages.is_empty()).unwrap_or(false);
        if empty && !self.runs.contains_key(&id) {
            self.store.sessions.retain(|s| s.id != id);
        } else {
            self.store.closed_tabs.retain(|t| *t != id);
            self.store.closed_tabs.push(id);
        }
        if self.screen == Screen::Session(id) {
            let next = idx.and_then(|i| {
                let n = self.store.open_tabs.len();
                if n == 0 {
                    None
                } else {
                    self.store.open_tabs.get(i.min(n - 1)).copied()
                }
            });
            match next {
                Some(n) => self.open_session(n),
                None => {
                    self.screen = Screen::Home;
                    self.store.active_tab = None;
                }
            }
        }
        self.dirty = true;
    }

    fn delete_session(&mut self, id: u64) {
        if let Some(r) = self.runs.remove(&id) {
            r.run.cancel.store(true, std::sync::atomic::Ordering::Relaxed);
        }
        self.store.open_tabs.retain(|t| *t != id);
        self.store.closed_tabs.retain(|t| *t != id);
        self.store.sessions.retain(|s| s.id != id);
        if self.screen == Screen::Session(id) {
            match self.store.open_tabs.last().copied() {
                Some(n) => self.open_session(n),
                None => self.screen = Screen::Home,
            }
        }
        self.dirty = true;
    }

    fn run_config(&self, sid: u64, compact: bool) -> Option<agent::RunConfig> {
        let s = self.store.session(sid)?;
        let p = self.store.project(s.project_id)?;
        let st = &self.store.settings;
        Some(agent::RunConfig {
            base_url: st.base_url.clone(),
            api_key: st.api_key.clone(),
            model: st.model.clone(),
            agent: s.agent.clone(),
            project_dir: PathBuf::from(&p.path),
            perms: st.perms.clone(),
            auto_accept: st.auto_accept,
            always: self.always.get(&sid).cloned().unwrap_or_default(),
            shell: st.shell.clone(),
            max_steps: st.max_steps,
            compact,
        })
    }

    fn submit(&mut self, sid: u64, ctx: &egui::Context, t: f64) {
        let text = self.drafts.get(&sid).cloned().unwrap_or_default().trim().to_string();
        if text.is_empty() {
            return;
        }
        self.drafts.insert(sid, String::new());
        if self.shell_mode {
            if self.runs.contains_key(&sid) {
                self.toast("Wait for the current work to finish", t);
                self.drafts.insert(sid, text);
                return;
            }
            self.run_user_shell(sid, text, ctx, t);
            return;
        }
        if text.starts_with('/') && self.slash(sid, &text, ctx, t) {
            return;
        }
        if self.runs.contains_key(&sid) {
            self.queues.entry(sid).or_default().push(text);
            return;
        }
        self.send_prompt(sid, text, ctx, t);
    }

    /// Built-in slash commands. Returns true when handled.
    fn slash(&mut self, sid: u64, text: &str, ctx: &egui::Context, t: f64) -> bool {
        match text.split_whitespace().next().unwrap_or("") {
            "/new" => self.new_session(None),
            "/compact" | "/summarize" => self.compact(sid, ctx, t),
            "/undo" => self.undo(sid),
            "/plan" => self.set_agent(sid, "plan"),
            "/build" => self.set_agent(sid, "build"),
            "/settings" => self.settings_open = true,
            "/export" => self.export(sid, t),
            _ => return false,
        }
        true
    }

    fn set_agent(&mut self, sid: u64, agent: &str) {
        if let Some(s) = self.store.session_mut(sid) {
            s.agent = agent.into();
            self.dirty = true;
        }
    }

    fn send_prompt(&mut self, sid: u64, text: String, ctx: &egui::Context, t: f64) {
        let model = self.store.settings.model.clone();
        let Some(s) = self.store.session_mut(sid) else { return };
        let mut m = Message::new(Role::User, text.clone());
        m.agent = s.agent.clone();
        m.model = model;
        s.messages.push(m);
        if s.title == "New session" || s.title.is_empty() {
            s.title = make_title(&text);
        }
        s.updated = now();
        let history = s.messages.clone();
        self.stick_bottom = true;
        self.dirty = true;
        if let Some(cfg) = self.run_config(sid, false) {
            let run = agent::spawn(cfg, history, ctx.clone());
            self.runs.insert(sid, ActiveRun { run, status: "Thinking".into(), pending: None, started: t });
        }
    }

    fn run_user_shell(&mut self, sid: u64, command: String, ctx: &egui::Context, t: f64) {
        let Some(p) = self.project_of(sid) else { return };
        let dir = PathBuf::from(&p.path);
        let shell = self.store.settings.shell.clone();
        let (tx, rx) = std::sync::mpsc::channel();
        let cancel = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let c2 = cancel.clone();
        let ctx2 = ctx.clone();
        std::thread::spawn(move || {
            let (out, ok) = match agent::run_shell(&shell, &command, &dir, agent::BASH_DEFAULT_TIMEOUT_MS, &c2) {
                Ok((o, code)) => (if code == 0 { o } else { format!("{o}\n\nCommand exited with code {code}") }, code == 0),
                Err(e) => (e, false),
            };
            let _ = tx.send(AgentEvent::ToolResult { call_id: String::new(), name: "user_shell".into(), title: command, output: out, ok });
            let _ = tx.send(AgentEvent::Done);
            ctx2.request_repaint();
        });
        self.runs.insert(sid, ActiveRun { run: agent::Run { rx, cancel }, status: "Running commands".into(), pending: None, started: t });
        self.stick_bottom = true;
    }

    fn compact(&mut self, sid: u64, ctx: &egui::Context, t: f64) {
        if self.runs.contains_key(&sid) {
            return;
        }
        let Some(s) = self.store.session(sid) else { return };
        if s.messages.is_empty() {
            return;
        }
        let history = s.messages.clone();
        if let Some(cfg) = self.run_config(sid, true) {
            let run = agent::spawn(cfg, history, ctx.clone());
            self.runs.insert(sid, ActiveRun { run, status: "Summarizing".into(), pending: None, started: t });
        }
    }

    /// Remove the last prompt and everything after it, and put the prompt back in the box.
    fn undo(&mut self, sid: u64) {
        if self.runs.contains_key(&sid) {
            return;
        }
        let Some(s) = self.store.session_mut(sid) else { return };
        if let Some(i) = s.messages.iter().rposition(|m| m.role == Role::User || m.role == Role::Shell) {
            let m = s.messages[i].clone();
            s.messages.truncate(i);
            let back = if m.role == Role::Shell { m.title } else { m.text };
            self.drafts.insert(sid, back);
            self.dirty = true;
        }
    }

    fn export(&mut self, sid: u64, t: f64) {
        let Some(s) = self.store.session(sid) else { return };
        let dir = dirs::download_dir().or_else(dirs::home_dir).unwrap_or_else(|| PathBuf::from("."));
        let safe: String = s.title.chars().map(|c| if c.is_alphanumeric() || c == ' ' || c == '-' { c } else { '_' }).collect();
        let path = dir.join(format!("session-{}.json", safe.trim().replace(' ', "-")));
        let res = serde_json::to_string_pretty(s)
            .map_err(|e| e.to_string())
            .and_then(|j| std::fs::write(&path, j).map_err(|e| e.to_string()));
        match res {
            Ok(()) => self.toast(format!("Exported to {}", path.display()), t),
            Err(e) => self.toast(format!("Export failed: {e}"), t),
        }
    }

    fn stop(&mut self, sid: u64) {
        if let Some(r) = self.runs.get(&sid) {
            r.run.cancel.store(true, std::sync::atomic::Ordering::Relaxed);
        }
    }

    fn add_project_path(&mut self, path: &str, t: f64) {
        let path = path.trim().trim_matches('"').to_string();
        let pb = PathBuf::from(&path);
        if !pb.is_dir() {
            self.toast("That folder doesn't exist", t);
            return;
        }
        if let Some(p) = self.store.projects.iter().find(|p| Path::new(&p.path) == pb.as_path()) {
            self.home_project = Some(p.id);
            return;
        }
        let name = pb.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_else(|| path.clone());
        let id = self.store.new_id();
        self.store.projects.push(Project { id, name, path });
        self.home_project = Some(id);
        self.dirty = true;
    }

    fn run_cmd(&mut self, cmd: Cmd, ctx: &egui::Context, t: f64) {
        let sid = match self.screen {
            Screen::Session(s) => Some(s),
            Screen::Home => None,
        };
        match cmd {
            Cmd::NewSession => self.new_session(None),
            Cmd::Home => self.screen = Screen::Home,
            Cmd::Settings => self.settings_open = true,
            Cmd::ToggleReview => self.show_review = !self.show_review,
            Cmd::ToggleShell => self.shell_mode = !self.shell_mode,
            Cmd::CycleAgent => {
                if let Some(s) = sid.and_then(|s| self.store.session_mut(s)) {
                    s.agent = if s.agent == "build" { "plan".into() } else { "build".into() };
                    self.dirty = true;
                }
            }
            Cmd::ChooseModel(m) => {
                self.store.settings.model = m;
                self.dirty = true;
            }
            Cmd::Undo => {
                if let Some(s) = sid {
                    self.undo(s)
                }
            }
            Cmd::Compact => {
                if let Some(s) = sid {
                    self.compact(s, ctx, t)
                }
            }
            Cmd::Rename => {
                if let Some(s) = sid.and_then(|s| self.store.session(s)) {
                    self.rename = Some((s.id, s.title.clone()));
                }
            }
            Cmd::Delete => self.confirm_delete = sid,
            Cmd::Export => {
                if let Some(s) = sid {
                    self.export(s, t)
                }
            }
            Cmd::AddProject => self.add_project = Some(String::new()),
            Cmd::AutoAccept => {
                self.store.settings.auto_accept = !self.store.settings.auto_accept;
                let msg = if self.store.settings.auto_accept { "Auto-accepting permissions" } else { "Stopped auto-accepting permissions" };
                self.toast(msg, t);
                self.dirty = true;
            }
            Cmd::OpenSession(id) => self.open_session(id),
            Cmd::CloseTab => {
                if let Some(s) = sid {
                    self.close_tab(s)
                }
            }
        }
    }

    // ------------------------------------------------------------ agent events

    fn pump(&mut self, ctx: &egui::Context, t: f64) {
        let ids: Vec<u64> = self.runs.keys().copied().collect();
        let mut finished = vec![];
        for sid in ids {
            loop {
                let ev = match self.runs.get(&sid) {
                    Some(r) => match r.run.rx.try_recv() {
                        Ok(e) => e,
                        Err(std::sync::mpsc::TryRecvError::Empty) => break,
                        Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                            finished.push(sid);
                            break;
                        }
                    },
                    None => break,
                };
                self.apply_event(sid, ev, &mut finished);
                self.dirty = true;
                if self.screen == Screen::Session(sid) {
                    self.stick_bottom = true;
                }
            }
        }
        for sid in finished {
            if self.runs.remove(&sid).is_some() {
                if self.screen != Screen::Session(sid) {
                    if let Some(s) = self.store.session_mut(sid) {
                        s.unread = true;
                    }
                }
                let next = self.queues.get_mut(&sid).and_then(|q| if q.is_empty() { None } else { Some(q.remove(0)) });
                if let Some(text) = next {
                    self.send_prompt(sid, text, ctx, t);
                }
            }
        }
    }

    fn apply_event(&mut self, sid: u64, ev: AgentEvent, finished: &mut Vec<u64>) {
        let model = self.store.settings.model.clone();
        let (pin, pout) = (self.store.settings.price_in, self.store.settings.price_out);
        let active = self.screen == Screen::Session(sid);
        match ev {
            AgentEvent::Assistant { text, tool_calls } => {
                if let Some(s) = self.store.session_mut(sid) {
                    let mut m = Message::new(Role::Assistant, text);
                    m.tool_calls = tool_calls;
                    m.agent = s.agent.clone();
                    m.model = model;
                    s.messages.push(m);
                    s.updated = now();
                }
            }
            AgentEvent::ToolResult { call_id, name, title, output, ok } => {
                if let Some(s) = self.store.session_mut(sid) {
                    let role = if name == "user_shell" { Role::Shell } else { Role::Tool };
                    let mut m = Message::new(role, output);
                    m.tool_call_id = call_id;
                    m.tool_name = name;
                    m.title = title;
                    m.ok = ok;
                    s.messages.push(m);
                    s.updated = now();
                }
                if let Some(r) = self.runs.get_mut(&sid) {
                    r.pending = None;
                }
            }
            AgentEvent::Permission(req) => {
                if let Some(r) = self.runs.get_mut(&sid) {
                    r.pending = Some(req);
                }
            }
            AgentEvent::Usage { prompt, completion } => {
                if let Some(s) = self.store.session_mut(sid) {
                    s.context_tokens = prompt + completion;
                    s.total_tokens += prompt + completion;
                    s.cost += prompt as f64 * pin / 1e6 + completion as f64 * pout / 1e6;
                }
            }
            AgentEvent::Todos(todos) => {
                if let Some(s) = self.store.session_mut(sid) {
                    s.todos = todos;
                }
            }
            AgentEvent::FileChanged(f) => {
                if let Some(s) = self.store.session_mut(sid) {
                    if !s.changed_files.contains(&f) {
                        s.changed_files.push(f);
                    }
                }
                if active {
                    for of in self.files.iter_mut() {
                        of.text = read_text(&of.path);
                    }
                }
            }
            AgentEvent::Status(st) => {
                if let Some(r) = self.runs.get_mut(&sid) {
                    r.status = st;
                }
            }
            AgentEvent::AlwaysAllowed(tool) => {
                self.always.entry(sid).or_default().insert(tool);
            }
            AgentEvent::Compacted(text) => {
                if let Some(s) = self.store.session_mut(sid) {
                    s.messages.clear();
                    s.messages.push(Message::new(Role::Notice, "Session compacted"));
                    let mut m = Message::new(Role::Assistant, format!("**Summary of the session so far**\n\n{text}"));
                    m.agent = s.agent.clone();
                    s.messages.push(m);
                }
            }
            AgentEvent::Done => finished.push(sid),
            AgentEvent::Error(e) => {
                if let Some(s) = self.store.session_mut(sid) {
                    let mut m = Message::new(Role::Notice, e);
                    m.ok = false;
                    s.messages.push(m);
                }
                finished.push(sid);
            }
        }
    }

    // ------------------------------------------------------------ keyboard

    fn shortcuts(&mut self, ctx: &egui::Context, t: f64) {
        let cmd = Modifiers::COMMAND;
        let cs = Modifiers::COMMAND | Modifiers::SHIFT;
        let mut todo: Vec<Cmd> = vec![];
        let mut palette = false;
        let mut tab_dir = 0;
        ctx.input_mut(|i| {
            if i.consume_key(cmd, Key::T) || i.consume_key(cmd, Key::N) {
                todo.push(Cmd::NewSession);
            }
            if i.consume_key(cmd, Key::Comma) {
                todo.push(Cmd::Settings);
            }
            if i.consume_key(cmd, Key::K) || i.consume_key(cs, Key::P) {
                palette = true;
            }
            if i.consume_key(cs, Key::R) {
                todo.push(Cmd::ToggleReview);
            }
            if i.consume_key(cs, Key::X) {
                todo.push(Cmd::ToggleShell);
            }
            if i.consume_key(cmd, Key::Period) {
                todo.push(Cmd::CycleAgent);
            }
            if i.consume_key(cmd, Key::W) {
                todo.push(Cmd::CloseTab);
            }
            if i.consume_key(cs, Key::A) {
                todo.push(Cmd::AutoAccept);
            }
            if i.consume_key(cmd, Key::OpenBracket) {
                tab_dir = -1;
            }
            if i.consume_key(cmd, Key::CloseBracket) {
                tab_dir = 1;
            }
            if i.consume_key(cs, Key::T) {
                if let Some(id) = self.store.closed_tabs.pop() {
                    todo.push(Cmd::OpenSession(id));
                }
            }
            if i.consume_key(cmd, Key::O) {
                todo.push(Cmd::AddProject);
            }
            if i.consume_key(cmd, Key::Quote) {
                let ms = self.store.settings.models.clone();
                if !ms.is_empty() {
                    let cur = ms.iter().position(|m| *m == self.store.settings.model).map(|p| (p + 1) % ms.len()).unwrap_or(0);
                    todo.push(Cmd::ChooseModel(ms[cur].clone()));
                }
            }
        });
        if palette {
            self.open_palette();
        }
        if tab_dir != 0 {
            self.cycle_tab(tab_dir);
        }
        if let Screen::Session(sid) = self.screen {
            if self.runs.contains_key(&sid) && ctx.input(|i| i.key_pressed(Key::Escape)) {
                self.stop(sid);
            }
        }
        for c in todo {
            self.run_cmd(c, ctx, t);
        }
    }

    fn cycle_tab(&mut self, dir: i32) {
        if self.store.open_tabs.is_empty() {
            return;
        }
        let n = self.store.open_tabs.len() as i32;
        let cur = match self.screen {
            Screen::Session(s) => self.store.open_tabs.iter().position(|t| *t == s).map(|p| p as i32).unwrap_or(-1),
            Screen::Home => -1,
        };
        let next = ((cur + dir) % n + n) % n;
        let id = self.store.open_tabs[next as usize];
        self.open_session(id);
    }

    fn apply_theme(&mut self, ctx: &egui::Context) {
        let dark = match self.store.settings.color_scheme {
            Scheme::Dark => true,
            Scheme::Light => false,
            Scheme::System => ctx.system_theme().map(|t| t == egui::Theme::Dark).unwrap_or(false),
        };
        if self.applied_dark != Some(dark) {
            self.pal = if dark { Pal::dark() } else { Pal::light() };
            theme::apply(ctx, &self.pal);
            self.applied_dark = Some(dark);
        }
        let z = self.store.settings.zoom.clamp(0.5, 3.0);
        if (self.applied_zoom - z).abs() > 0.001 {
            ctx.set_zoom_factor(z);
            self.applied_zoom = z;
        }
    }

    /// With --screenshot: draw SCREENSHOT_FRAMES frames, save the window as a PNG and quit.
    fn screenshot_step(&mut self, ctx: &egui::Context) {
        let Some(shot) = &mut self.shot else { return };
        shot.frames += 1;
        ctx.request_repaint();
        if shot.frames >= SCREENSHOT_FRAMES && !shot.requested {
            shot.requested = true;
            let slot = shot.image.clone();
            let ctx2 = ctx.clone();
            ctx.request_screenshot(move |img| {
                *slot.lock().unwrap() = Some(img);
                ctx2.request_repaint();
            });
        }
        let img = shot.image.lock().unwrap().take();
        if let Some(img) = img {
            let [w, h] = img.size;
            let mut buf = Vec::with_capacity(w * h * 4);
            for p in &img.pixels {
                buf.extend_from_slice(&[p.r(), p.g(), p.b(), 255]);
            }
            if let Some(dir) = shot.path.parent() {
                let _ = std::fs::create_dir_all(dir);
            }
            match image::save_buffer(&shot.path, &buf, w as u32, h as u32, image::ColorType::Rgba8) {
                Ok(()) => eprintln!("saved screenshot to {}", shot.path.display()),
                Err(e) => eprintln!("couldn't save screenshot: {e}"),
            }
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
        if shot.frames > SCREENSHOT_FRAMES * 8 {
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
    }
}

impl eframe::App for App {
    fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
        let ctx = ui.ctx().clone();
        let t = ctx.input(|i| i.time);
        self.apply_theme(&ctx);
        self.pump(&ctx, t);
        let modal_open = self.settings_open || self.palette.is_some() || self.add_project.is_some() || self.rename.is_some() || self.confirm_delete.is_some();
        if !modal_open {
            self.shortcuts(&ctx, t);
        }
        self.ensure_screen();
        let pal = self.pal;
        let full = ui.max_rect();
        ui.painter().rect_filled(full, 0.0, pal.bg_base);
        let bar = Rect::from_min_size(full.min, Vec2::new(full.width(), TOPBAR_H));
        let body = Rect::from_min_max(Pos2::new(full.left() + INSET, bar.bottom()), Pos2::new(full.right() - INSET, full.bottom() - INSET));
        self.top_bar(ui, bar, &ctx, t);
        match self.screen {
            Screen::Home => self.home(ui, body, &ctx, t),
            Screen::Session(id) => self.session_screen(ui, body, id, &ctx, t),
        }
        self.dialogs(&ctx, t);
        self.toasts(&ctx, t);
        if self.dirty && t - self.last_save > 1.0 && self.shot.is_none() {
            self.store.save();
            self.dirty = false;
            self.last_save = t;
        }
        if !self.runs.is_empty() {
            ctx.request_repaint_after(std::time::Duration::from_millis(100));
        }
        self.screenshot_step(&ctx);
    }

    fn on_exit(&mut self) {
        for r in self.runs.values() {
            r.run.cancel.store(true, std::sync::atomic::Ordering::Relaxed);
        }
        if self.shot.is_none() {
            self.store.save();
        }
    }
}

//! The bar across the top: menu, home, search, one tab per open session, new tab, settings.

use super::*;
use crate::theme::bold;
use eframe::egui::{Align, Align2, Color32, FontId, Layout, Sense};

impl App {
    pub(super) fn top_bar(&mut self, ui: &mut egui::Ui, rect: Rect, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        let mut bar = ui.new_child(egui::UiBuilder::new().max_rect(rect.shrink2(Vec2::new(10.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        let mut todo: Vec<Cmd> = vec![];
        let mut palette = false;
        let menu = theme::icon_button(&mut bar, &pal, 30.0, "Menu", theme::icon_menu);
        egui::Popup::menu(&menu).show(|ui| {
            ui.set_min_width(220.0);
            for (label, key, c) in [
                ("New session", "Ctrl+T", Some(Cmd::NewSession)),
                ("Add project…", "Ctrl+O", Some(Cmd::AddProject)),
                ("Search everything", "Ctrl+K", None),
                ("Settings", "Ctrl+,", Some(Cmd::Settings)),
            ] {
                if ui.add(egui::Button::new(label).shortcut_text(key)).clicked() {
                    match c {
                        Some(c) => todo.push(c),
                        None => palette = true,
                    }
                }
            }
        });
        bar.add_space(2.0);
        if theme::icon_button(&mut bar, &pal, 30.0, "Home", theme::icon_grid).clicked() {
            todo.push(Cmd::Home);
        }
        bar.add_space(2.0);
        if theme::icon_button(&mut bar, &pal, 30.0, "Search everything (Ctrl+K)", theme::icon_search).clicked() {
            palette = true;
        }
        bar.add_space(8.0);

        // One tab per open session
        let avail = (bar.available_width() - 80.0).max(80.0);
        let n = self.store.open_tabs.len().max(1) as f32;
        let tab_w = (avail / n - 4.0).clamp(90.0, MAX_TAB_W);
        let tabs = self.store.open_tabs.clone();
        let mut close: Option<u64> = None;
        for id in tabs {
            let Some(s) = self.store.session(id) else { continue };
            let pname = self.store.project(s.project_id).map(|p| p.name.clone()).unwrap_or_default();
            let title = s.title.clone();
            let unread = s.unread;
            let running = self.runs.contains_key(&id);
            let active = self.screen == Screen::Session(id);
            let (r, resp) = bar.allocate_exact_size(Vec2::new(tab_w, 30.0), Sense::click());
            let fill = if active {
                if pal.dark { pal.bg_weak } else { Color32::from_rgb(0xeb, 0xeb, 0xeb) }
            } else if resp.hovered() {
                pal.bg_hover
            } else {
                Color32::TRANSPARENT
            };
            bar.painter().rect_filled(r, 6.0, fill);
            let av = Rect::from_center_size(Pos2::new(r.left() + 16.0, r.center().y), Vec2::splat(16.0));
            bar.painter().rect_filled(av, 3.0, pal.avatar_bg);
            let letter = pname.chars().find(|c| c.is_alphanumeric()).unwrap_or('?').to_uppercase().to_string();
            bar.painter().text(av.center(), Align2::CENTER_CENTER, letter, bold(10.0), if pal.dark { Color32::BLACK } else { Color32::WHITE });
            if running {
                let pulse = ((t * 4.0).sin() * 0.5 + 0.5) as f32;
                bar.painter().circle_filled(av.right_top() + Vec2::new(-1.0, 1.0), 2.5 + pulse, pal.interactive);
            } else if unread {
                bar.painter().circle_filled(av.right_top() + Vec2::new(-1.0, 1.0), 3.0, pal.interactive);
            }
            let show_close = resp.hovered() || active;
            let text_rect = Rect::from_min_max(Pos2::new(r.left() + 30.0, r.top()), Pos2::new(r.right() - if show_close { 24.0 } else { 8.0 }, r.bottom()));
            let col = if active { pal.text_strong } else { pal.text_base };
            let galley = bar.painter().layout_no_wrap(title.clone(), FontId::proportional(13.5), col);
            let gh = galley.size().y;
            bar.painter().with_clip_rect(text_rect).galley(Pos2::new(text_rect.left(), r.center().y - gh / 2.0), galley, col);
            if show_close {
                let cr = Rect::from_center_size(Pos2::new(r.right() - 13.0, r.center().y), Vec2::splat(18.0));
                let cresp = bar.interact(cr, egui::Id::new(("tabclose", id)), Sense::click());
                if cresp.hovered() {
                    bar.painter().rect_filled(cr, 4.0, pal.bg_hover);
                }
                theme::icon_close(bar.painter(), cr.center(), if cresp.hovered() { pal.text_strong } else { pal.icon }, 3.5);
                if cresp.clicked() {
                    close = Some(id);
                }
            }
            if resp.middle_clicked() {
                close = Some(id);
            }
            if resp.clicked() && close.is_none() {
                todo.push(Cmd::OpenSession(id));
            }
            resp.on_hover_text(format!("{pname} / {title}"));
            bar.add_space(4.0);
        }
        if theme::icon_button(&mut bar, &pal, 28.0, "New session (Ctrl+T)", |p, c, col| theme::icon_plus(p, c, col, 5.5)).clicked() {
            todo.push(Cmd::NewSession);
        }
        bar.with_layout(Layout::right_to_left(Align::Center), |ui| {
            if theme::icon_button(ui, &pal, 30.0, "Settings (Ctrl+,)", theme::icon_gear).clicked() {
                todo.push(Cmd::Settings);
            }
        });
        if palette {
            self.open_palette();
        }
        if let Some(c) = close {
            self.close_tab(c);
        }
        for c in todo {
            self.run_cmd(c, ctx, t);
        }
    }
}

