                let pulse = ((t * 4.0).sin() * 0.5 + 0.5) as f32;
                bar.painter().circle_filled(av.right_top() + Vec2::new(-1.0, 1.0), 2.5 + pulse, pal.interactive);
            } else if unread {
                bar.painter().circle_filled(av.right_top() + Vec2::new(-1.0, 1.0), 3.0, pal.interactive);
            }
            let show_close = resp.hovered() || active;
            let text_rect = Rect::from_min_max(Pos2::new(r.left() + 30.0, r.top()), Pos2::new(r.right() - if show_close { 24.0 } else { 8.0 }, r.bottom()));
            let col = if active { pal.text_strong } else { pal.text_base };
            let galley = bar.painter().layout_no_wrap(title.clone(), FontId::proportional(13.5), col);
            let gh = galley.size().y;
            bar.painter().with_clip_rect(text_rect).galley(Pos2::new(text_rect.left(), r.center().y - gh / 2.0), galley, col);
            if show_close {
                let cr = Rect::from_center_size(Pos2::new(r.right() - 13.0, r.center().y), Vec2::splat(18.0));
                let cresp = bar.interact(cr, egui::Id::new(("tabclose", id)), Sense::click());
                if cresp.hovered() {
                    bar.painter().rect_filled(cr, 4.0, pal.bg_hover);
                }
                theme::icon_close(bar.painter(), cr.center(), if cresp.hovered() { pal.text_strong } else { pal.icon }, 3.5);
                if cresp.clicked() {
                    close = Some(id);
                }
            }
            if resp.middle_clicked() {
                close = Some(id);
            }
            if resp.clicked() && close.is_none() {
                todo.push(Cmd::OpenSession(id));
            }
            resp.on_hover_text(format!("{pname} / {title}"));
            bar.add_space(4.0);
        }
        if theme::icon_button(&mut bar, &pal, 28.0, "New session (Ctrl+T)", |p, c, col| theme::icon_plus(p, c, col, 5.5)).clicked() {
            todo.push(Cmd::NewSession);
        }
        bar.with_layout(Layout::right_to_left(Align::Center), |ui| {
            if theme::icon_button(ui, &pal, 30.0, "Settings (Ctrl+,)", theme::icon_gear).clicked() {
                todo.push(Cmd::Settings);
            }
        });
        if palette {
            self.open_palette();
        }
        if let Some(c) = close {
            self.close_tab(c);
        }
        for c in todo {
            self.run_cmd(c, ctx, t);
        }
    }
}

//! Home page: projects column on the left, sessions grouped Today / Yesterday /
//! Older on the right, with search.

use super::*;
use crate::theme::bold;
use eframe::egui::{Align, Align2, FontId, Layout, RichText, Sense};

impl App {
    pub(super) fn home(&mut self, ui: &mut egui::Ui, rect: Rect, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        card(ui, &pal, rect);
        let mut todo: Vec<Cmd> = vec![];
        let mut cui = ui.new_child(egui::UiBuilder::new().max_rect(rect.shrink(1.0)).layout(Layout::top_down(Align::Min)));
        egui::ScrollArea::vertical().id_salt("home-scroll").auto_shrink([false, false]).show(&mut cui, |ui| {
            let full = ui.available_width();
            let wide = full >= 900.0;
            let content_w = full.min(HOME_MAX_W) - if wide { 48.0 } else { 24.0 };
            let left_pad = ((full - content_w) / 2.0).max(12.0);
            ui.add_space(if wide { 48.0 } else { 24.0 });
            ui.horizontal_top(|ui| {
                ui.add_space(left_pad);
                if wide {
                    ui.allocate_ui_with_layout(Vec2::new(HOME_PROJECTS_W, 0.0), Layout::top_down(Align::Min), |ui| {
                        ui.set_width(HOME_PROJECTS_W);
                        self.home_projects(ui, &mut todo);
                    });
                    ui.add_space(32.0);
                }
                let sw = (content_w - if wide { HOME_PROJECTS_W + 32.0 } else { 0.0 }).min(HOME_SESSIONS_MAX_W);
                ui.allocate_ui_with_layout(Vec2::new(sw, 0.0), Layout::top_down(Align::Min), |ui| {
                    ui.set_width(sw);
                    if !wide {
                        self.home_projects_compact(ui, &mut todo);
                    }
                    self.home_sessions(ui, &mut todo);
                });
            });
            ui.add_space(64.0);
        });
        for c in todo {
            self.run_cmd(c, ctx, t);
        }
    }

    fn home_projects(&mut self, ui: &mut egui::Ui, todo: &mut Vec<Cmd>) {
        let pal = self.pal;
        if primary_button(ui, &pal, "New session", ui.available_width()).clicked() {
            todo.push(Cmd::NewSession);
        }
        ui.add_space(20.0);
        section_label(ui, &pal, "Projects");
        ui.add_space(4.0);
        let all_sel = self.home_project.is_none();
        if list_row(ui, &pal, all_sel, 32.0, |ui| {
            let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
            theme::icon_grid(ui.painter(), r.center(), pal.icon);
            ui.label(RichText::new("All projects").color(pal.text_strong));
        })
        .clicked()
        {
            self.home_project = None;
        }
        let projects = self.store.projects.clone();
        let mut remove: Option<u64> = None;
        for p in &projects {
            let sel = self.home_project == Some(p.id);
            let missing = !Path::new(&p.path).is_dir();
            let count = self.store.sessions.iter().filter(|s| s.project_id == p.id && !s.messages.is_empty()).count();
            let resp = list_row(ui, &pal, sel, 32.0, |ui| {
                theme::avatar(ui, &pal, &p.name, 16.0);
                ui.add(egui::Label::new(RichText::new(&p.name).color(if missing { pal.text_weak } else { pal.text_strong })).truncate().selectable(false));
                if count > 0 {
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        ui.label(RichText::new(count.to_string()).size(12.5).color(pal.text_weak));
                    });
                }
            });
            let resp = resp.on_hover_text(if missing { format!("Project folder not found\n{}", p.path) } else { p.path.clone() });
            if resp.clicked() {
                self.home_project = Some(p.id);
            }
            resp.context_menu(|ui| {
                if ui.button("New session here").clicked() {
                    self.home_project = Some(p.id);
                    todo.push(Cmd::NewSession);
                }
                if ui.button("Open folder").clicked() {
                    open_in_file_manager(Path::new(&p.path));
                }
                if ui.button("Remove from list").clicked() {
                    remove = Some(p.id);
                }
            });
        }
        if let Some(id) = remove {
            self.store.projects.retain(|p| p.id != id);
            let gone: Vec<u64> = self.store.sessions.iter().filter(|s| s.project_id == id).map(|s| s.id).collect();
            for g in gone {
                self.delete_session(g);
            }
            if self.home_project == Some(id) {
                self.home_project = None;
            }
            self.dirty = true;
        }
        if list_row(ui, &pal, false, 32.0, |ui| {
            let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
            theme::icon_plus(ui.painter(), r.center(), pal.icon, 5.0);
            ui.label(RichText::new("Add project").color(pal.text_base));
        })
        .clicked()
        {
            todo.push(Cmd::AddProject);
        }
        ui.add_space(24.0);
        egui::Frame::NONE.fill(pal.bg_weak).corner_radius(8).inner_margin(12).show(ui, |ui| {
            ui.set_width(ui.available_width());
            ui.label(RichText::new("Tip").font(bold(12.5)).color(pal.text_strong));
            ui.label(
                RichText::new("Connect any OpenAI-compatible service in Settings to use other models, including local ones.")
                    .size(12.5)
                    .color(pal.text_base),
            );
        });
        ui.add_space(12.0);
        ui.horizontal(|ui| {
            if ui.link(RichText::new("Settings").color(pal.text_base)).clicked() {
                todo.push(Cmd::Settings);
            }
            ui.label(RichText::new("·").color(pal.text_weaker));
            if ui.link(RichText::new("Shortcuts").color(pal.text_base)).clicked() {
                self.settings_tab = SettingsTab::Shortcuts;
                todo.push(Cmd::Settings);
            }
        });
    }

    fn home_projects_compact(&mut self, ui: &mut egui::Ui, todo: &mut Vec<Cmd>) {
        let pal = self.pal;
        ui.horizontal(|ui| {
            let label = self.home_project.and_then(|id| self.store.project(id)).map(|p| p.name.clone()).unwrap_or("All projects".into());
            let projects = self.store.projects.clone();
            egui::ComboBox::from_id_salt("home-proj").selected_text(label).show_ui(ui, |ui| {
                ui.selectable_value(&mut self.home_project, None, "All projects");
                for p in projects {
                    ui.selectable_value(&mut self.home_project, Some(p.id), p.name.clone());
                }
            });
            if ui.button("Add project").clicked() {
                todo.push(Cmd::AddProject);
            }
            if primary_button(ui, &pal, "New session", 120.0).clicked() {
                todo.push(Cmd::NewSession);
            }
        });
        ui.add_space(12.0);
    }

    fn home_sessions(&mut self, ui: &mut egui::Ui, todo: &mut Vec<Cmd>) {
        let pal = self.pal;
        let scope = self.home_project.and_then(|id| self.store.project(id)).map(|p| p.name.clone());
        let hint = match &scope {
            Some(n) => format!("Search sessions in {n}"),
            None => "Search sessions".into(),
        };
        let search = egui::Frame::NONE
            .fill(pal.bg_weak)
            .corner_radius(8)
            .inner_margin(egui::Margin::symmetric(10, 8))
            .show(ui, |ui| {
                ui.horizontal(|ui| {
                    let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
                    theme::icon_search(ui.painter(), r.center(), pal.icon);
                    ui.add(
                        egui::TextEdit::singleline(&mut self.home_search)
                            .hint_text(RichText::new(hint).color(pal.text_weak))
                            .frame(egui::Frame::NONE)
                            .desired_width(f32::INFINITY),
                    )
                })
                .inner
            })
            .inner;
        if ui.input(|i| i.modifiers.command && i.key_pressed(Key::F)) {
            search.request_focus();
        }
        ui.add_space(18.0);

        let q = self.home_search.to_lowercase();
        let mut list: Vec<&Session> = self
            .store
            .sessions
            .iter()
            .filter(|s| self.home_project.map(|p| s.project_id == p).unwrap_or(true))
            .filter(|s| !s.messages.is_empty())
            .filter(|s| q.is_empty() || s.title.to_lowercase().contains(&q) || s.messages.iter().any(|m| m.text.to_lowercase().contains(&q)))
            .collect();
        list.sort_by(|a, b| b.updated.cmp(&a.updated));

        if list.is_empty() {
            ui.add_space(40.0);
            ui.vertical_centered(|ui| {
                if q.is_empty() {
                    ui.label(RichText::new("Nothing here yet").font(bold(16.0)).color(pal.text_strong));
                    ui.label(RichText::new("Create a session to get started").color(pal.text_base));
                    ui.add_space(12.0);
                    if primary_button(ui, &pal, "New session", 140.0).clicked() {
                        todo.push(Cmd::NewSession);
                    }
                } else {
                    ui.label(RichText::new(format!("No sessions found for \"{}\"", self.home_search)).color(pal.text_base));
                }
            });
            return;
        }

        // Group by calendar day in local time, like the original.
        let today = chrono::Local::now().date_naive();
        let yesterday = today.pred_opt().unwrap_or(today);
        let day = |s: &Session| {
            chrono::DateTime::from_timestamp(s.updated, 0)
                .map(|d| d.with_timezone(&chrono::Local).date_naive())
                .unwrap_or(today)
        };
        let td: Vec<&Session> = list.iter().copied().filter(|s| day(s) == today).collect();
        let yd: Vec<&Session> = list.iter().copied().filter(|s| day(s) == yesterday).collect();
        let od: Vec<&Session> = list.iter().copied().filter(|s| day(s) != today && day(s) != yesterday).collect();
        let older_title = if td.is_empty() && yd.is_empty() { "Recent sessions" } else { "Older" };
        let groups: Vec<(&str, Vec<&Session>)> = vec![("Today", td), ("Yesterday", yd), (older_title, od)].into_iter().filter(|g| !g.1.is_empty()).collect();

        let mut delete: Option<u64> = None;
        let n_groups = groups.len();
        for (gi, (title, sessions)) in groups.into_iter().enumerate() {
            section_label(ui, &pal, title);
            ui.add_space(6.0);
            for s in sessions {
                let pname = self.store.project(s.project_id).map(|p| p.name.clone()).unwrap_or_default();
                let running = self.runs.contains_key(&s.id);
                let w = ui.available_width();
                let (r, resp) = ui.allocate_exact_size(Vec2::new(w, SESSION_ROW_H), Sense::click());
                if resp.hovered() {
                    ui.painter().rect_filled(r, 6.0, pal.bg_weak);
                }
                if s.unread || running {
                    ui.painter().circle_filled(Pos2::new(r.left() + 5.0, r.center().y), 3.0, pal.interactive);
                }
                let x = r.left() + 12.0;
                let tg = ui.painter().layout_no_wrap(s.title.clone(), bold(14.0), pal.text_strong);
                let max_title = (w * 0.6).max(120.0);
                let title_rect = Rect::from_min_size(Pos2::new(x, r.top()), Vec2::new(max_title, r.height()));
                let tw = tg.size().x.min(max_title);
                let th = tg.size().y;
                ui.painter().with_clip_rect(title_rect).galley(Pos2::new(x, r.center().y - th / 2.0), tg, pal.text_strong);
                if self.home_project.is_none() {
                    ui.painter().text(Pos2::new(x + tw + 10.0, r.center().y), Align2::LEFT_CENTER, &pname, FontId::proportional(13.0), pal.text_weak);
                }
                if resp.hovered() {
                    let cr = Rect::from_center_size(Pos2::new(r.right() - 16.0, r.center().y), Vec2::splat(22.0));
                    let cresp = ui.interact(cr, egui::Id::new(("hdel", s.id)), Sense::click()).on_hover_text("Delete session");
                    if cresp.hovered() {
                        ui.painter().rect_filled(cr, 4.0, pal.bg_hover);
                    }
                    theme::icon_close(ui.painter(), cr.center(), pal.icon, 4.0);
                    if cresp.clicked() {
                        delete = Some(s.id);
                    }
                } else {
                    let right = if running { "Working…".to_string() } else { time_ago(s.updated) };
                    ui.painter().text(Pos2::new(r.right() - 10.0, r.center().y), Align2::RIGHT_CENTER, right, FontId::proportional(13.0), pal.text_weak);
                }
                if resp.clicked() && delete.is_none() {
                    todo.push(Cmd::OpenSession(s.id));
                }
            }
            if gi + 1 < n_groups {
                ui.add_space(24.0);
            }
        }
        if let Some(d) = delete {
            self.confirm_delete = Some(d);
        }
    }
}

