                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        ui.label(RichText::new(count.to_string()).size(12.5).color(pal.text_weak));
                    });
                }
            });
            let resp = resp.on_hover_text(if missing { format!("Project folder not found\n{}", p.path) } else { p.path.clone() });
            if resp.clicked() {
                self.home_project = Some(p.id);
            }
            resp.context_menu(|ui| {
                if ui.button("New session here").clicked() {
                    self.home_project = Some(p.id);
                    todo.push(Cmd::NewSession);
                }
                if ui.button("Open folder").clicked() {
                    open_in_file_manager(Path::new(&p.path));
                }
                if ui.button("Remove from list").clicked() {
                    remove = Some(p.id);
                }
            });
