//! Session screen: chat panel (header, timeline, composer with permission
//! dock) and the review pane (changed files, file tree, file viewer).

use super::*;
use crate::agent::PermReply;
use crate::markdown;
use crate::theme::bold;
use eframe::egui::{Align, Color32, FontId, Layout, RichText, Sense, Stroke};

impl App {
    pub(super) fn session_screen(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        let avail = rect.width();
        let (left, right) = if self.show_review && avail >= SESSION_WIDTH_MIN + SIDE_PANE_MIN + INSET {
            let w = self.session_width.clamp(SESSION_WIDTH_MIN, (avail - SIDE_PANE_MIN - INSET).max(SESSION_WIDTH_MIN));
            let l = Rect::from_min_size(rect.min, Vec2::new(w, rect.height()));
            let r = Rect::from_min_max(Pos2::new(l.right() + INSET, rect.top()), rect.max);
            let handle = Rect::from_min_max(Pos2::new(l.right(), rect.top()), Pos2::new(r.left(), rect.bottom()));
            let hr = ui.interact(handle, egui::Id::new("divider"), Sense::drag()).on_hover_cursor(egui::CursorIcon::ResizeHorizontal);
            if hr.dragged() {
                self.session_width = (w + hr.drag_delta().x).clamp(SESSION_WIDTH_MIN, (avail - SIDE_PANE_MIN - INSET).max(SESSION_WIDTH_MIN));
            }
            if hr.hovered() || hr.dragged() {
                ui.painter().line_segment(
                    [handle.center_top() + Vec2::new(0.0, 12.0), handle.center_bottom() - Vec2::new(0.0, 12.0)],
                    Stroke::new(2.0, pal.interactive),
                );
            }
            (l, Some(r))
        } else {
            (rect, None)
        };
        self.chat_panel(ui, left, sid, ctx, t);
        if let Some(r) = right {
            self.side_pane(ui, r, sid);
        }
    }

    fn chat_panel(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        card(ui, &pal, rect);
        let Some(session) = self.store.session(sid).cloned() else { return };
        let project = self.store.project(session.project_id).cloned();
        let pname = project.as_ref().map(|p| p.name.clone()).unwrap_or("(no project)".into());
        let mut todo: Vec<Cmd> = vec![];

        // header: project / title ···            ring 136k · $0.00 [panel]
        let header = Rect::from_min_size(rect.min, Vec2::new(rect.width(), 48.0));
        let mut h = ui.new_child(egui::UiBuilder::new().max_rect(header.shrink2(Vec2::new(16.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        theme::avatar(&mut h, &pal, &pname, 16.0);
        h.add_space(2.0);
        let pl = h.add(egui::Label::new(RichText::new(&pname).color(pal.text_base)).sense(Sense::click()).selectable(false));
        if pl.on_hover_text("Show this project's sessions").clicked() {
            self.home_project = Some(session.project_id);
            todo.push(Cmd::Home);
        }
        h.label(RichText::new("/").color(pal.text_weaker));
        let title_full = h.fonts_mut(|f| f.layout_no_wrap(session.title.clone(), FontId::proportional(14.0), pal.text_strong).size().x);
        let title_w = title_full.min((h.available_width() - 190.0).max(40.0)) + 2.0;
        let tl = h.add_sized(
            Vec2::new(title_w, 20.0),
            egui::Label::new(RichText::new(&session.title).color(pal.text_strong)).truncate().sense(Sense::click()).selectable(false),
        );
        if tl.on_hover_text("Double-click to rename").double_clicked() {
            todo.push(Cmd::Rename);
        }
        let more = theme::icon_button(&mut h, &pal, 26.0, "Session actions", theme::icon_dots);
        egui::Popup::menu(&more).show(|ui| {
            ui.set_min_width(190.0);
            if ui.button("Rename session").clicked() {
                todo.push(Cmd::Rename);
            }
            if ui.button("Compact session").on_hover_text("Summarize the session to reduce context size").clicked() {
                todo.push(Cmd::Compact);
            }
            if ui.button("Undo last message").clicked() {
                todo.push(Cmd::Undo);
            }
            if ui.button("Export session").on_hover_text("Save the full transcript as JSON in Downloads").clicked() {
                todo.push(Cmd::Export);
            }
            ui.separator();
            if ui.button(RichText::new("Delete session").color(pal.critical)).clicked() {
                todo.push(Cmd::Delete);
            }
        });
        let limit = self.store.settings.context_limit.max(1);
        h.with_layout(Layout::right_to_left(Align::Center), |ui| {
            if !self.show_review && theme::icon_button(ui, &pal, 28.0, "Show review (Ctrl+Shift+R)", |p, c, col| theme::icon_panel(p, c, col, true)).clicked() {
                todo.push(Cmd::ToggleReview);
            }
            ui.add_space(4.0);
            ui.label(RichText::new(format!("${:.2}", session.cost)).color(pal.text_weak));
            ui.label(RichText::new("·").color(pal.text_weak));
            ui.label(RichText::new(compact_num(session.context_tokens)).color(pal.text_weak));
            let (r, resp) = ui.allocate_exact_size(Vec2::splat(18.0), Sense::hover());
            let frac = session.context_tokens as f32 / limit as f32;
            theme::context_ring(ui.painter(), r.center(), 7.0, frac, &pal);
            resp.on_hover_text(format!(
                "Context: {} of {} tokens ({:.0}%)\nTotal used: {} tokens\nCost: ${:.4}",
                session.context_tokens,
                limit,
                frac * 100.0,
                session.total_tokens,
                session.cost
            ));
        });

        // composer first (bottom), then the timeline takes the rest
        let content_w = (rect.width() - 40.0).min(760.0);
        let col_left = rect.center().x - content_w / 2.0;
        let comp_h = self.composer_height(sid, content_w);
        let comp_rect = Rect::from_min_size(Pos2::new(col_left, rect.bottom() - comp_h - 12.0), Vec2::new(content_w, comp_h));
        let tl_rect = Rect::from_min_max(Pos2::new(rect.left() + 1.0, header.bottom()), Pos2::new(rect.right() - 1.0, comp_rect.top() - 4.0));

        let mut tlui = ui.new_child(egui::UiBuilder::new().max_rect(tl_rect).layout(Layout::top_down(Align::Min)));
        let stick = std::mem::replace(&mut self.stick_bottom, false);
        let running = self.runs.get(&sid).map(|r| (r.status.clone(), r.started));
        egui::ScrollArea::vertical()
            .id_salt(("timeline", sid))
            .auto_shrink([false, false])
            .stick_to_bottom(true)
            .show(&mut tlui, |ui| {
                let pad = ((ui.available_width() - content_w) / 2.0).max(16.0);
                ui.add_space(8.0);
                ui.horizontal_top(|ui| {
                    ui.add_space(pad);
                    ui.vertical(|ui| {
                        ui.set_width(content_w);
                        if session.messages.is_empty() {
                            self.empty_session(ui, project.as_ref());
                        }
                        self.timeline(ui, &session);
                        if let Some((status, started)) = &running {
                            ui.add_space(6.0);
                            ui.horizontal(|ui| {
                                let phase = ((t - started) * 2.5).sin() as f32 * 0.5 + 0.5;
                                let col = lerp_color(pal.text_weak, pal.text_strong, phase);
                                ui.add(egui::Spinner::new().size(12.0).color(pal.text_weak));
                                ui.label(RichText::new(format!("{status}…")).color(col));
                                ui.label(RichText::new(format!("{}s", (t - started) as u64)).color(pal.text_weaker));
                            });
                            ctx.request_repaint_after(std::time::Duration::from_millis(50));
                        }
                        ui.add_space(24.0);
                    });
                });
                if stick {
                    ui.scroll_to_cursor(Some(Align::BOTTOM));
                }
            });

        self.composer(ui, comp_rect, sid, &session, ctx, t);
        for c in todo {
            self.run_cmd(c, ctx, t);
        }
    }

    fn empty_session(&self, ui: &mut egui::Ui, p: Option<&Project>) {
        let pal = self.pal;
        ui.add_space(60.0);
        ui.vertical_centered(|ui| {
            ui.label(RichText::new("New session").font(bold(20.0)).color(pal.text_strong));
            ui.add_space(4.0);
            if let Some(p) = p {
                ui.label(RichText::new(&p.path).monospace().color(pal.text_weak));
            }
            ui.add_space(16.0);
        });
        for (a, b) in [
            ("Build", "makes changes: edits files and runs commands, asking you first"),
            ("Plan", "only reads and explains. Switch with Ctrl+."),
            ("Shell", "type commands yourself. Toggle with Ctrl+Shift+X"),
        ] {
            ui.horizontal(|ui| {
                ui.add_space((ui.available_width() - 460.0).max(0.0) / 2.0);
                ui.label(RichText::new(a).font(bold(13.5)).color(pal.text_strong));
                ui.label(RichText::new(b).size(13.5).color(pal.text_base));
            });
        }
        ui.add_space(20.0);
    }

    fn timeline(&mut self, ui: &mut egui::Ui, s: &Session) {
        let pal = self.pal;
        let results: HashMap<&str, &Message> = s.messages.iter().filter(|m| m.role == Role::Tool).map(|m| (m.tool_call_id.as_str(), m)).collect();
        for (i, m) in s.messages.iter().enumerate() {
            match m.role {
                Role::User => {
                    ui.add_space(14.0);
                    let maxw = ui.available_width() * 0.82;
                    ui.with_layout(Layout::right_to_left(Align::Min), |ui| {
                        egui::Frame::NONE
                            .fill(pal.bg_weak)
                            .corner_radius(10)
                            .inner_margin(egui::Margin::symmetric(14, 10))
                            .show(ui, |ui| {
                                ui.set_max_width(maxw);
                                ui.add(egui::Label::new(RichText::new(&m.text).color(pal.text_strong)).wrap());
                            });
                    });
                    if !m.agent.is_empty() && !m.model.is_empty() {
                        ui.with_layout(Layout::right_to_left(Align::Min), |ui| {
                            ui.label(RichText::new(format!("{} · {}", cap(&m.agent), m.model)).size(11.5).color(pal.text_weaker));
                        });
                    }
                    ui.add_space(8.0);
                }
                Role::Assistant => {
                    if !m.text.is_empty() {
                        ui.add_space(4.0);
                        markdown::show(ui, &pal, &m.text);
                    }
                    for (ci, c) in m.tool_calls.iter().enumerate() {
                        let res = results.get(c.id.as_str()).copied();
                        self.tool_row(ui, s.id, i * 64 + ci, &c.name, &c.args, res);
                    }
                }
                Role::Tool => {} // drawn with the call that asked for it
                Role::Shell => {
                    let key = (s.id, i * 64 + 63);
                    let open = self.expanded_tools.contains(&key);
                    ui.add_space(6.0);
                    let resp = ui
                        .horizontal(|ui| {
                            let lab = if m.ok { "Shell finished" } else { "Shell failed" };
                            ui.label(RichText::new(lab).color(if m.ok { pal.interactive } else { pal.critical }));
                            ui.label(RichText::new("·").color(pal.text_weak));
                            ui.add(egui::Label::new(RichText::new(&m.title).color(pal.text_weak)).truncate().selectable(false));
                        })
                        .response
                        .interact(Sense::click())
                        .on_hover_cursor(egui::CursorIcon::PointingHand);
                    if resp.clicked() {
                        toggle(&mut self.expanded_tools, key);
                    }
                    if open {
                        output_box(ui, &pal, &format!("$ {}\n{}", m.title, m.text));
                    }
                }
                Role::Notice => {
                    ui.add_space(8.0);
                    let col = if m.ok { pal.text_base } else { pal.critical };
                    egui::Frame::NONE
                        .stroke(Stroke::new(1.0, if m.ok { pal.border_weak } else { pal.critical.gamma_multiply(0.5) }))
                        .corner_radius(8)
                        .inner_margin(egui::Margin::symmetric(12, 8))
                        .show(ui, |ui| {
                            ui.set_width(ui.available_width());
                            ui.add(egui::Label::new(RichText::new(&m.text).color(col)).wrap());
                        });
                    ui.add_space(8.0);
                }
            }
        }
    }

    fn tool_row(&mut self, ui: &mut egui::Ui, sid: u64, slot: usize, name: &str, args: &str, res: Option<&Message>) {
        let pal = self.pal;
        let a: serde_json::Value = serde_json::from_str(args).unwrap_or_default();
        let get = |k: &str| a[k].as_str().unwrap_or("").to_string();
        let subject = match name {
            "bash" => {
                let d = get("description");
                if d.is_empty() { get("command") } else { d }
            }
            "glob" | "grep" => get("pattern"),
            "webfetch" => get("url"),
            "todowrite" => format!("{} todos", a["todos"].as_array().map(|v| v.len()).unwrap_or(0)),
            _ => {
                let p = if a["filePath"].is_string() { get("filePath") } else { get("path") };
                if p.is_empty() { ".".into() } else { p }
            }
        };
        let key = (sid, slot);
        let open = self.expanded_tools.contains(&key);
        let label = agent::tool_label(name);
        let (status_col, label) = match res {
            None => (pal.text_weak, label),
            Some(r) if !r.ok => (pal.critical, format!("{label} failed")),
            Some(_) if name == "bash" => (pal.interactive, "Shell finished".to_string()),
            Some(_) => (pal.text_strong, label),
        };
        ui.add_space(3.0);
        let resp = ui
            .horizontal(|ui| {
                if res.is_none() {
                    ui.add(egui::Spinner::new().size(11.0).color(pal.text_weak));
                }
                ui.label(RichText::new(label).color(status_col));
                ui.label(RichText::new("·").color(pal.text_weak));
                ui.add(egui::Label::new(RichText::new(&subject).color(pal.text_weak)).truncate().selectable(false));
            })
            .response
            .interact(Sense::click())
            .on_hover_cursor(egui::CursorIcon::PointingHand);
        if resp.clicked() {
            toggle(&mut self.expanded_tools, key);
        }
        if open {
            let mut body = String::new();
            match name {
                "bash" => body.push_str(&format!("$ {}\n", get("command"))),
                "edit" => body.push_str(&format!(
                    "- {}\n+ {}\n\n",
                    get("oldString").replace('\n', "\n- "),
                    get("newString").replace('\n', "\n+ ")
                )),
                "write" => body.push_str(&format!("{}\n\n", get("content").chars().take(4000).collect::<String>())),
                _ => {}
            }
            body.push_str(res.map(|r| r.text.as_str()).unwrap_or("Running…"));
            output_box(ui, &pal, &body);
        }
    }

    fn composer_height(&self, sid: u64, w: f32) -> f32 {
        let text = self.drafts.get(&sid).map(|s| s.as_str()).unwrap_or("");
        let wrapped: f32 = text.lines().map(|l| (l.chars().count() as f32 * 7.4 / (w - 40.0).max(50.0)).floor()).sum();
        let lines = text.lines().count().max(1) as f32 + wrapped + if text.ends_with('\n') { 1.0 } else { 0.0 };
        let input_h = (lines.clamp(2.0, 10.0) * 19.0).max(40.0);
        let mut h = input_h + 22.0 + 42.0;
        if self.runs.get(&sid).map(|r| r.pending.is_some()).unwrap_or(false) {
            h += 124.0;
        }
        if self.queues.get(&sid).map(|q| !q.is_empty()).unwrap_or(false) {
            h += 30.0;
        }
        if let Some(s) = self.store.session(sid) {
            if s.todos.iter().any(|t| t.status != "completed" && t.status != "cancelled") {
                h += 36.0;
            }
        }
        h
    }

    fn composer(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64, s: &Session, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        let mut c = ui.new_child(egui::UiBuilder::new().max_rect(rect).layout(Layout::top_down(Align::Min)));
        c.set_width(rect.width());

        // todo pill
        let open_todos: Vec<_> = s.todos.iter().filter(|t| t.status != "completed" && t.status != "cancelled").collect();
        if !open_todos.is_empty() {
            let done = s.todos.iter().filter(|t| t.status == "completed").count();
            let current = s.todos.iter().find(|t| t.status == "in_progress").or(open_todos.first().copied());
            let resp = egui::Frame::NONE
                .fill(pal.bg_weak)
                .corner_radius(8)
                .inner_margin(egui::Margin::symmetric(10, 6))
                .show(&mut c, |ui| {
                    ui.horizontal(|ui| {
                        let word = if s.todos.len() == 1 { "todo" } else { "todos" };
                        ui.label(RichText::new(format!("{done} of {} {word} done", s.todos.len())).size(12.5).color(pal.text_base));
                        if let Some(cur) = current {
                            ui.label(RichText::new("·").color(pal.text_weak));
                            ui.add(egui::Label::new(RichText::new(&cur.content).size(12.5).color(pal.text_strong)).truncate());
                        }
                    });
                })
                .response;
            resp.on_hover_ui(|ui| {
                for t in &s.todos {
                    let mark = match t.status.as_str() {
                        "completed" => "[x]",
                        "in_progress" => "[>]",
                        "cancelled" => "[-]",
                        _ => "[ ]",
                    };
                    ui.label(format!("{mark} {}", t.content));
                }
            });
            c.add_space(6.0);
        }

        // queued prompts
        if let Some(q) = self.queues.get(&sid).cloned() {
            if !q.is_empty() {
                let mut clear = false;
                c.horizontal(|ui| {
                    ui.label(RichText::new(format!("{} queued", q.len())).size(12.5).color(pal.text_base));
                    ui.add(egui::Label::new(RichText::new(&q[0]).size(12.5).color(pal.text_weak)).truncate());
                    if ui.small_button("Remove").clicked() {
                        clear = true;
                    }
                });
                if clear {
                    self.queues.remove(&sid);
                }
                c.add_space(4.0);
            }
        }

        // permission dock
        let mut reply: Option<PermReply> = None;
        if let Some(req) = self.runs.get(&sid).and_then(|r| r.pending.as_ref()) {
            egui::Frame::NONE
                .fill(pal.bg_panel)
                .stroke(Stroke::new(1.0, pal.border_base))
                .corner_radius(10)
                .inner_margin(egui::Margin::symmetric(14, 12))
                .show(&mut c, |ui| {
                    ui.set_width(ui.available_width());
                    ui.horizontal(|ui| {
                        let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
                        theme::icon_warning(ui.painter(), r.center(), pal.warning);
                        ui.label(RichText::new(format!("Permission required · {}", req.title)).font(bold(14.0)).color(pal.text_strong));
                    });
                    ui.add_space(2.0);
                    ui.add(egui::Label::new(RichText::new(&req.detail).monospace().color(pal.text_base)).truncate());
                    ui.add_space(8.0);
                    ui.horizontal(|ui| {
                        if primary_button(ui, &pal, "Allow once", 100.0).clicked() {
                            reply = Some(PermReply::Once);
                        }
                        if ui
                            .add(egui::Button::new("Allow always").min_size(Vec2::new(100.0, 32.0)))
                            .on_hover_text("Allow this kind of action for the rest of this session")
                            .clicked()
                        {
                            reply = Some(PermReply::Always);
                        }
                        if ui.add(egui::Button::new(RichText::new("Deny").color(pal.critical)).min_size(Vec2::new(70.0, 32.0))).clicked() {
                            reply = Some(PermReply::Deny);
                        }
                    });
                });
            c.add_space(6.0);
        }
        if let Some(rp) = reply {
            if let Some(req) = self.runs.get_mut(&sid).and_then(|r| r.pending.take()) {
                let _ = req.reply.send(rp);
            }
        }

        // the input box
        let shell = self.shell_mode;
        let running = self.runs.contains_key(&sid);
        let mut send = false;
        let mut toggle_shell = false;
        let mut toggle_agent = false;
        let mut open_models = false;
        let block_focus = self.palette.is_some() || self.settings_open || self.add_project.is_some() || self.rename.is_some();
        egui::Frame::NONE
            .fill(pal.bg_panel)
            .stroke(Stroke::new(1.0, if shell { pal.interactive.gamma_multiply(0.6) } else { pal.border_base }))
            .corner_radius(10)
            .inner_margin(egui::Margin { left: 12, right: 8, top: 10, bottom: 6 })
            .shadow(egui::Shadow { offset: [0, 2], blur: 8, spread: 0, color: Color32::from_black_alpha(if pal.dark { 60 } else { 10 }) })
            .show(&mut c, |ui| {
                ui.set_width(ui.available_width());
                let focus = std::mem::replace(&mut self.focus_composer, false);
                let draft = self.drafts.entry(sid).or_default();
                let hint = if shell { "Enter shell command… \"git status\"" } else { "Ask anything, / for commands…" };
                let out = ui.add(
                    egui::TextEdit::multiline(draft)
                        .id_salt(("composer", sid))
                        .hint_text(RichText::new(hint).color(pal.text_weak))
                        .frame(egui::Frame::NONE)
                        .desired_rows(2)
                        .desired_width(f32::INFINITY)
                        .font(if shell { egui::TextStyle::Monospace } else { egui::TextStyle::Body })
                        .return_key(egui::KeyboardShortcut::new(Modifiers::SHIFT, Key::Enter)),
                );
                if focus && !block_focus {
                    out.request_focus();
                }
                if out.has_focus() && ui.input(|i| i.key_pressed(Key::Enter) && !i.modifiers.shift) {
                    send = true;
                }
                if shell && out.has_focus() && draft.is_empty() && ui.input(|i| i.key_pressed(Key::Backspace)) {
                    toggle_shell = true;
                }
                if !shell && draft == "!" {
                    draft.clear();
                    toggle_shell = true;
                }
                ui.add_space(4.0);
                ui.horizontal(|ui| {
                    if shell {
                        let r = ui.add(egui::Button::new(RichText::new("Shell").color(pal.interactive)).fill(pal.interactive_bg));
                        if r.on_hover_text("Back to prompt (Ctrl+Shift+X)").clicked() {
                            toggle_shell = true;
                        }
                    } else {
                        let r = ui.add(egui::Button::new(RichText::new(cap(&s.agent)).font(bold(13.5)).color(pal.text_strong)).fill(Color32::TRANSPARENT));
                        if r.on_hover_text("Switch agent: Build makes changes, Plan only looks (Ctrl+.)").clicked() {
                            toggle_agent = true;
                        }
                        let model = self.store.settings.model.clone();
                        let mr = ui
                            .add(egui::Button::new(RichText::new(&model).color(pal.text_base)).fill(Color32::TRANSPARENT))
                            .on_hover_text("Choose model (Ctrl+')");
                        egui::Popup::menu(&mr).show(|ui| {
                            ui.set_min_width(220.0);
                            ui.label(RichText::new("Models").size(12.0).color(pal.text_weak));
                            for m in self.store.settings.models.clone() {
                                if ui.selectable_label(m == self.store.settings.model, &m).clicked() {
                                    self.store.settings.model = m;
                                    self.dirty = true;
                                }
                            }
                            ui.separator();
                            if ui.button("Manage models…").clicked() {
                                open_models = true;
                            }
                        });
                        if self.store.settings.auto_accept {
                            ui.label(RichText::new("auto-accept").size(12.0).color(pal.warning))
                                .on_hover_text("Permission requests are approved automatically (Ctrl+Shift+A)");
                        }
                    }
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        let (r, resp) = ui.allocate_exact_size(Vec2::splat(30.0), Sense::click());
                        let empty = self.drafts.get(&sid).map(|d| d.trim().is_empty()).unwrap_or(true);
                        if running && empty {
                            ui.painter().circle_filled(r.center(), 15.0, pal.primary_btn);
                            theme::icon_stop(ui.painter(), r.center(), pal.primary_text);
                            if resp.on_hover_text("Stop (Esc)").clicked() {
                                self.stop(sid);
                            }
                        } else {
                            ui.painter().circle_filled(r.center(), 15.0, if empty { pal.text_weaker } else { pal.primary_btn });
                            theme::icon_arrow_up(ui.painter(), r.center(), pal.primary_text);
                            if resp.on_hover_text(if running { "Queue (Enter)" } else { "Send (Enter)" }).clicked() {
                                send = true;
                            }
                        }
                        ui.add_space(2.0);
                        let tip = if shell { "Prompt mode (Ctrl+Shift+X)" } else { "Shell mode (Ctrl+Shift+X)" };
                        let col = if shell { pal.interactive } else { pal.icon };
                        if ui.add(egui::Button::new(RichText::new(">_").monospace().color(col)).fill(Color32::TRANSPARENT)).on_hover_text(tip).clicked() {
                            toggle_shell = true;
                        }
                    });
                });
            });
        if toggle_shell {
            self.shell_mode = !self.shell_mode;
            self.focus_composer = true;
        }
        if toggle_agent {
            self.set_agent(sid, if s.agent == "build" { "plan" } else { "build" });
        }
        if open_models {
            self.settings_tab = SettingsTab::Models;
            self.settings_open = true;
        }
        if send {
            if let Some(d) = self.drafts.get_mut(&sid) {
                *d = d.trim_end_matches(['\n', '\r']).to_string();
            }
            self.submit(sid, ctx, t);
            self.focus_composer = true;
        }
    }

    // ------------------------------------------------------------ review / files

    fn side_pane(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64) {
        let pal = self.pal;
        card(ui, &pal, rect);
        let Some(session) = self.store.session(sid).cloned() else { return };
        let Some(project) = self.store.project(session.project_id).cloned() else { return };
        let root = PathBuf::from(&project.path);

        // tab row
        let tabs_rect = Rect::from_min_size(rect.min, Vec2::new(rect.width(), 48.0));
        let mut tr = ui.new_child(egui::UiBuilder::new().max_rect(tabs_rect.shrink2(Vec2::new(12.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        let n_changed = session.changed_files.len();
        let review_label = if n_changed > 0 { format!("Review ({n_changed})") } else { "Review".to_string() };
        if file_tab(&mut tr, &pal, &review_label, self.active_file.is_none(), None).0 {
            self.active_file = None;
        }
        let mut close: Option<usize> = None;
        for (i, f) in self.files.iter().enumerate() {
            let name = f.path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
            let (clicked, closed) = file_tab(&mut tr, &pal, &name, self.active_file == Some(i), Some(f.text.is_err()));
            if clicked {
                self.active_file = Some(i);
            }
            if closed {
                close = Some(i);
            }
        }
        tr.with_layout(Layout::right_to_left(Align::Center), |ui| {
            if theme::icon_button(ui, &pal, 28.0, "Hide review (Ctrl+Shift+R)", |p, c, col| theme::icon_panel(p, c, col, true)).clicked() {
                self.show_review = false;
            }
        });
        if let Some(i) = close {
            self.files.remove(i);
            self.active_file = match self.active_file {
                Some(a) if a == i => {
                    if self.files.is_empty() {
                        None
                    } else {
                        Some(i.min(self.files.len() - 1))
                    }
                }
                Some(a) if a > i => Some(a - 1),
                other => other,
            };
        }
        let y1 = tabs_rect.bottom();
        ui.painter().line_segment([Pos2::new(rect.left(), y1), Pos2::new(rect.right(), y1)], Stroke::new(1.0, pal.border_weak));

        // project row
        let prow = Rect::from_min_size(Pos2::new(rect.left(), y1), Vec2::new(rect.width(), 46.0));
        let mut pr = ui.new_child(egui::UiBuilder::new().max_rect(prow.shrink2(Vec2::new(14.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        if theme::icon_button(&mut pr, &pal, 26.0, "Toggle file tree", theme::icon_tree).clicked() {
            self.show_tree = !self.show_tree;
        }
        pr.add_space(4.0);
        pr.label(RichText::new(&project.name).font(bold(14.0)).color(pal.text_strong));
        pr.add(egui::Label::new(RichText::new(&project.path).size(12.0).color(pal.text_weak)).truncate());
        let y2 = prow.bottom();
        ui.painter().line_segment([Pos2::new(rect.left(), y2), Pos2::new(rect.right(), y2)], Stroke::new(1.0, pal.border_weak));

        let body = Rect::from_min_max(Pos2::new(rect.left() + 1.0, y2 + 1.0), Pos2::new(rect.right() - 1.0, rect.bottom() - 6.0));
        let (tree_rect, view_rect) = if self.show_tree && body.width() > FILE_TREE_WIDTH + 160.0 {
            let trr = Rect::from_min_size(body.min, Vec2::new(FILE_TREE_WIDTH, body.height()));
            let vr = Rect::from_min_max(Pos2::new(trr.right() + 1.0, body.top()), body.max);
            ui.painter().line_segment([Pos2::new(trr.right(), body.top()), Pos2::new(trr.right(), body.bottom())], Stroke::new(1.0, pal.border_weak));
            (Some(trr), vr)
        } else {
            (None, body)
        };
        let mut open: Option<PathBuf> = None;
        if let Some(trr) = tree_rect {
            let mut tu = ui.new_child(egui::UiBuilder::new().max_rect(trr.shrink2(Vec2::new(6.0, 6.0))).layout(Layout::top_down(Align::Min)));
            egui::ScrollArea::vertical().id_salt("tree").auto_shrink([false, false]).show(&mut tu, |ui| {
                self.tree(ui, &root, 0, &mut open);
            });
        }
        let mut vu = ui.new_child(egui::UiBuilder::new().max_rect(view_rect.shrink2(Vec2::new(16.0, 10.0))).layout(Layout::top_down(Align::Min)));
        match self.active_file {
            Some(i) if i < self.files.len() => match &self.files[i].text {
                Ok(text) => {
                    egui::ScrollArea::both().id_salt(("file", i)).auto_shrink([false, false]).show(&mut vu, |ui| {
                        let digits = text.lines().count().to_string().len().max(2);
                        let mut job = egui::text::LayoutJob::default();
                        let num = egui::TextFormat { font_id: FontId::monospace(12.5), color: pal.text_weaker, ..Default::default() };
                        let code = egui::TextFormat { font_id: FontId::monospace(12.5), color: pal.text_strong, ..Default::default() };
                        for (n, line) in text.lines().enumerate().take(20_000) {
                            job.append(&format!("{:>w$}  ", n + 1, w = digits), 0.0, num.clone());
                            job.append(&line.replace('\t', "    "), 0.0, code.clone());
                            job.append("\n", 0.0, code.clone());
                        }
                        ui.add(egui::Label::new(job).extend());
                    });
                }
                Err(e) => {
                    vu.add_space(6.0);
                    vu.label(RichText::new(e).color(pal.text_weak));
                }
            },
            _ => {
                egui::ScrollArea::vertical().id_salt("review").auto_shrink([false, false]).show(&mut vu, |ui| {
                    if session.changed_files.is_empty() {
                        if tree_rect.is_none() {
                            ui.label(RichText::new("Files").font(bold(12.5)).color(pal.text_weak));
                            ui.add_space(4.0);
                            self.tree(ui, &root, 0, &mut open);
                        } else {
                            ui.add_space(30.0);
                            ui.vertical_centered(|ui| {
                                ui.label(RichText::new("No changes yet").color(pal.text_base));
                                ui.label(RichText::new("Files the assistant edits show up here.").size(12.5).color(pal.text_weak));
                            });
                        }
                    } else {
                        let n = session.changed_files.len();
                        ui.label(RichText::new(format!("{n} Changed file{}", if n == 1 { "" } else { "s" })).font(bold(14.0)).color(pal.text_strong));
                        ui.add_space(6.0);
                        for f in &session.changed_files {
                            let r = list_row(ui, &pal, false, 30.0, |ui| {
                                let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
                                theme::icon_file(ui.painter(), r.center(), pal.icon);
                                ui.label(RichText::new(f).color(pal.text_strong));
                            });
                            if r.clicked() {
                                let p = Path::new(f);
                                open = Some(if p.is_absolute() { p.to_path_buf() } else { root.join(f) });
                            }
                        }
                    }
                });
            }
        }
        if let Some(p) = open {
            self.open_file(p);
        }
    }

    fn tree(&mut self, ui: &mut egui::Ui, dir: &Path, depth: usize, open: &mut Option<PathBuf>) {
        let pal = self.pal;
        let Ok(rd) = std::fs::read_dir(dir) else {
            ui.label(RichText::new("Project folder not found").color(pal.text_weak));
            return;
        };
        let mut entries: Vec<(bool, String, PathBuf)> = rd
            .filter_map(|e| e.ok())
            .map(|e| (e.path().is_dir(), e.file_name().to_string_lossy().to_string(), e.path()))
            .filter(|(_, n, _)| !n.starts_with('.') && !agent::ignored(n))
            .collect();
        entries.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.to_lowercase().cmp(&b.1.to_lowercase())));
        for (is_dir, name, path) in entries.into_iter().take(500) {
            let expanded = self.expanded.contains(&path);
            let resp = list_row(ui, &pal, false, 24.0, |ui| {
                ui.add_space(depth as f32 * 12.0);
                let (r, _) = ui.allocate_exact_size(Vec2::splat(14.0), Sense::hover());
                if is_dir {
                    theme::icon_chevron(ui.painter(), r.center(), pal.icon, expanded);
                } else {
                    theme::icon_file(ui.painter(), r.center(), pal.text_weaker);
                }
                ui.add(
                    egui::Label::new(RichText::new(&name).size(13.0).color(if is_dir { pal.text_strong } else { pal.text_base }))
                        .truncate()
                        .selectable(false),
                );
            });
            if resp.clicked() {
                if is_dir {
                    toggle(&mut self.expanded, path.clone());
                } else {
                    *open = Some(path.clone());
                }
            }
            if is_dir && expanded {
                self.tree(ui, &path, depth + 1, open);
            }
        }
    }

    fn open_file(&mut self, p: PathBuf) {
        if let Some(i) = self.files.iter().position(|f| f.path == p) {
            self.files[i].text = read_text(&p);
            self.active_file = Some(i);
            return;
        }
        let text = read_text(&p);
        self.files.push(OpenFile { path: p, text });
        self.active_file = Some(self.files.len() - 1);
        self.show_review = true;
    }
}

toolUseResult.content:
//! Session screen: chat panel (header, timeline, composer with permission
//! dock) and the review pane (changed files, file tree, file viewer).

use super::*;
use crate::agent::PermReply;
use crate::markdown;
use crate::theme::bold;
use eframe::egui::{Align, Color32, FontId, Layout, RichText, Sense, Stroke};

impl App {
    pub(super) fn session_screen(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        let avail = rect.width();
        let (left, right) = if self.show_review && avail >= SESSION_WIDTH_MIN + SIDE_PANE_MIN + INSET {
            let w = self.session_width.clamp(SESSION_WIDTH_MIN, (avail - SIDE_PANE_MIN - INSET).max(SESSION_WIDTH_MIN));
            let l = Rect::from_min_size(rect.min, Vec2::new(w, rect.height()));
            let r = Rect::from_min_max(Pos2::new(l.right() + INSET, rect.top()), rect.max);
            let handle = Rect::from_min_max(Pos2::new(l.right(), rect.top()), Pos2::new(r.left(), rect.bottom()));
            let hr = ui.interact(handle, egui::Id::new("divider"), Sense::drag()).on_hover_cursor(egui::CursorIcon::ResizeHorizontal);
            if hr.dragged() {
                self.session_width = (w + hr.drag_delta().x).clamp(SESSION_WIDTH_MIN, (avail - SIDE_PANE_MIN - INSET).max(SESSION_WIDTH_MIN));
            }
            if hr.hovered() || hr.dragged() {
                ui.painter().line_segment(
                    [handle.center_top() + Vec2::new(0.0, 12.0), handle.center_bottom() - Vec2::new(0.0, 12.0)],
                    Stroke::new(2.0, pal.interactive),
                );
            }
            (l, Some(r))
        } else {
            (rect, None)
        };
        self.chat_panel(ui, left, sid, ctx, t);
        if let Some(r) = right {
            self.side_pane(ui, r, sid);
        }
    }

    fn chat_panel(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        card(ui, &pal, rect);
        let Some(session) = self.store.session(sid).cloned() else { return };
        let project = self.store.project(session.project_id).cloned();
        let pname = project.as_ref().map(|p| p.name.clone()).unwrap_or("(no project)".into());
        let mut todo: Vec<Cmd> = vec![];

        // header: project / title ···            ring 136k · $0.00 [panel]
        let header = Rect::from_min_size(rect.min, Vec2::new(rect.width(), 48.0));
        let mut h = ui.new_child(egui::UiBuilder::new().max_rect(header.shrink2(Vec2::new(16.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        theme::avatar(&mut h, &pal, &pname, 16.0);
        h.add_space(2.0);
        let pl = h.add(egui::Label::new(RichText::new(&pname).color(pal.text_base)).sense(Sense::click()).selectable(false));
        if pl.on_hover_text("Show this project's sessions").clicked() {
            self.home_project = Some(session.project_id);
            todo.push(Cmd::Home);
        }
        h.label(RichText::new("/").color(pal.text_weaker));
        let title_full = h.fonts_mut(|f| f.layout_no_wrap(session.title.clone(), FontId::proportional(14.0), pal.text_strong).size().x);
        let title_w = title_full.min((h.available_width() - 190.0).max(40.0)) + 2.0;
        let tl = h.add_sized(
            Vec2::new(title_w, 20.0),
            egui::Label::new(RichText::new(&session.title).color(pal.text_strong)).truncate().sense(Sense::click()).selectable(false),
        );
        if tl.on_hover_text("Double-click to rename").double_clicked() {
            todo.push(Cmd::Rename);
        }
        let more = theme::icon_button(&mut h, &pal, 26.0, "Session actions", theme::icon_dots);
        egui::Popup::menu(&more).show(|ui| {
            ui.set_min_width(190.0);
            if ui.button("Rename session").clicked() {
                todo.push(Cmd::Rename);
            }
            if ui.button("Compact session").on_hover_text("Summarize the session to reduce context size").clicked() {
                todo.push(Cmd::Compact);
            }
            if ui.button("Undo last message").clicked() {
                todo.push(Cmd::Undo);
            }
            if ui.button("Export session").on_hover_text("Save the full transcript as JSON in Downloads").clicked() {
                todo.push(Cmd::Export);
            }
            ui.separator();
            if ui.button(RichText::new("Delete session").color(pal.critical)).clicked() {
                todo.push(Cmd::Delete);
            }
        });
        let limit = self.store.settings.context_limit.max(1);
        h.with_layout(Layout::right_to_left(Align::Center), |ui| {
            if !self.show_review && theme::icon_button(ui, &pal, 28.0, "Show review (Ctrl+Shift+R)", |p, c, col| theme::icon_panel(p, c, col, true)).clicked() {
                todo.push(Cmd::ToggleReview);
            }
            ui.add_space(4.0);
            ui.label(RichText::new(format!("${:.2}", session.cost)).color(pal.text_weak));
            ui.label(RichText::new("·").color(pal.text_weak));
            ui.label(RichText::new(compact_num(session.context_tokens)).color(pal.text_weak));
            let (r, resp) = ui.allocate_exact_size(Vec2::splat(18.0), Sense::hover());
            let frac = session.context_tokens as f32 / limit as f32;
            theme::context_ring(ui.painter(), r.center(), 7.0, frac, &pal);
            resp.on_hover_text(format!(
                "Context: {} of {} tokens ({:.0}%)\nTotal used: {} tokens\nCost: ${:.4}",
                session.context_tokens,
                limit,
                frac * 100.0,
                session.total_tokens,
                session.cost
            ));
        });

        // composer first (bottom), then the timeline takes the rest
        let content_w = (rect.width() - 40.0).min(760.0);
        let col_left = rect.center().x - content_w / 2.0;
        let comp_h = self.composer_height(sid, content_w);
        let comp_rect = Rect::from_min_size(Pos2::new(col_left, rect.bottom() - comp_h - 12.0), Vec2::new(content_w, comp_h));
        let tl_rect = Rect::from_min_max(Pos2::new(rect.left() + 1.0, header.bottom()), Pos2::new(rect.right() - 1.0, comp_rect.top() - 4.0));

        let mut tlui = ui.new_child(egui::UiBuilder::new().max_rect(tl_rect).layout(Layout::top_down(Align::Min)));
        let stick = std::mem::replace(&mut self.stick_bottom, false);
        let running = self.runs.get(&sid).map(|r| (r.status.clone(), r.started));
        egui::ScrollArea::vertical()
            .id_salt(("timeline", sid))
            .auto_shrink([false, false])
            .stick_to_bottom(true)
            .show(&mut tlui, |ui| {
                let pad = ((ui.available_width() - content_w) / 2.0).max(16.0);
                ui.add_space(8.0);
                ui.horizontal_top(|ui| {
                    ui.add_space(pad);
                    ui.vertical(|ui| {
                        ui.set_width(content_w);
                        if session.messages.is_empty() {
                            self.empty_session(ui, project.as_ref());
                        }
                        self.timeline(ui, &session);
                        if let Some((status, started)) = &running {
                            ui.add_space(6.0);
                            ui.horizontal(|ui| {
                                let phase = ((t - started) * 2.5).sin() as f32 * 0.5 + 0.5;
                                let col = lerp_color(pal.text_weak, pal.text_strong, phase);
                                ui.add(egui::Spinner::new().size(12.0).color(pal.text_weak));
                                ui.label(RichText::new(format!("{status}…")).color(col));
                                ui.label(RichText::new(format!("{}s", (t - started) as u64)).color(pal.text_weaker));
                            });
                            ctx.request_repaint_after(std::time::Duration::from_millis(50));
                        }
                        ui.add_space(24.0);
                    });
                });
                if stick {
                    ui.scroll_to_cursor(Some(Align::BOTTOM));
                }
            });

        self.composer(ui, comp_rect, sid, &session, ctx, t);
        for c in todo {
            self.run_cmd(c, ctx, t);
        }
    }

    fn empty_session(&self, ui: &mut egui::Ui, p: Option<&Project>) {
        let pal = self.pal;
        ui.add_space(60.0);
        ui.vertical_centered(|ui| {
            ui.label(RichText::new("New session").font(bold(20.0)).color(pal.text_strong));
            ui.add_space(4.0);
            if let Some(p) = p {
                ui.label(RichText::new(&p.path).monospace().color(pal.text_weak));
            }
            ui.add_space(16.0);
        });
        for (a, b) in [
            ("Build", "makes changes: edits files and runs commands, asking you first"),
            ("Plan", "only reads and explains. Switch with Ctrl+."),
            ("Shell", "type commands yourself. Toggle with Ctrl+Shift+X"),
        ] {
            ui.horizontal(|ui| {
                ui.add_space((ui.available_width() - 460.0).max(0.0) / 2.0);
                ui.label(RichText::new(a).font(bold(13.5)).color(pal.text_strong));
                ui.label(RichText::new(b).size(13.5).color(pal.text_base));
            });
        }
        ui.add_space(20.0);
    }

    fn timeline(&mut self, ui: &mut egui::Ui, s: &Session) {
        let pal = self.pal;
        let results: HashMap<&str, &Message> = s.messages.iter().filter(|m| m.role == Role::Tool).map(|m| (m.tool_call_id.as_str(), m)).collect();
        for (i, m) in s.messages.iter().enumerate() {
            match m.role {
                Role::User => {
                    ui.add_space(14.0);
                    let maxw = ui.available_width() * 0.82;
                    ui.with_layout(Layout::right_to_left(Align::Min), |ui| {
                        egui::Frame::NONE
                            .fill(pal.bg_weak)
                            .corner_radius(10)
                            .inner_margin(egui::Margin::symmetric(14, 10))
                            .show(ui, |ui| {
                                ui.set_max_width(maxw);
                                ui.add(egui::Label::new(RichText::new(&m.text).color(pal.text_strong)).wrap());
                            });
                    });
                    if !m.agent.is_empty() && !m.model.is_empty() {
                        ui.with_layout(Layout::right_to_left(Align::Min), |ui| {
                            ui.label(RichText::new(format!("{} · {}", cap(&m.agent), m.model)).size(11.5).color(pal.text_weaker));
                        });
                    }
                    ui.add_space(8.0);
                }
                Role::Assistant => {
                    if !m.text.is_empty() {
                        ui.add_space(4.0);
                        markdown::show(ui, &pal, &m.text);
                    }
                    for (ci, c) in m.tool_calls.iter().enumerate() {
                        let res = results.get(c.id.as_str()).copied();
                        self.tool_row(ui, s.id, i * 64 + ci, &c.name, &c.args, res);
                    }
                }
                Role::Tool => {} // drawn with the call that asked for it
                Role::Shell => {
                    let key = (s.id, i * 64 + 63);
                    let open = self.expanded_tools.contains(&key);
                    ui.add_space(6.0);
                    let resp = ui
                        .horizontal(|ui| {
                            let lab = if m.ok { "Shell finished" } else { "Shell failed" };
                            ui.label(RichText::new(lab).color(if m.ok { pal.interactive } else { pal.critical }));
                            ui.label(RichText::new("·").color(pal.text_weak));
                            ui.add(egui::Label::new(RichText::new(&m.title).color(pal.text_weak)).truncate().selectable(false));
                        })
                        .response
                        .interact(Sense::click())
                        .on_hover_cursor(egui::CursorIcon::PointingHand);
                    if resp.clicked() {
                        toggle(&mut self.expanded_tools, key);
                    }
                    if open {
                        output_box(ui, &pal, &format!("$ {}\n{}", m.title, m.text));
                    }
                }
                Role::Notice => {
                    ui.add_space(8.0);
                    let col = if m.ok { pal.text_base } else { pal.critical };
                    egui::Frame::NONE
                        .stroke(Stroke::new(1.0, if m.ok { pal.border_weak } else { pal.critical.gamma_multiply(0.5) }))
                        .corner_radius(8)
                        .inner_margin(egui::Margin::symmetric(12, 8))
                        .show(ui, |ui| {
                            ui.set_width(ui.available_width());
                            ui.add(egui::Label::new(RichText::new(&m.text).color(col)).wrap());
                        });
                    ui.add_space(8.0);
                }
            }
        }
    }

    fn tool_row(&mut self, ui: &mut egui::Ui, sid: u64, slot: usize, name: &str, args: &str, res: Option<&Message>) {
        let pal = self.pal;
        let a: serde_json::Value = serde_json::from_str(args).unwrap_or_default();
        let get = |k: &str| a[k].as_str().unwrap_or("").to_string();
        let subject = match name {
            "bash" => {
                let d = get("description");
                if d.is_empty() { get("command") } else { d }
            }
            "glob" | "grep" => get("pattern"),
            "webfetch" => get("url"),
            "todowrite" => format!("{} todos", a["todos"].as_array().map(|v| v.len()).unwrap_or(0)),
            _ => {
                let p = if a["filePath"].is_string() { get("filePath") } else { get("path") };
                if p.is_empty() { ".".into() } else { p }
            }
        };
        let key = (sid, slot);
        let open = self.expanded_tools.contains(&key);
        let label = agent::tool_label(name);
        let (status_col, label) = match res {
            None => (pal.text_weak, label),
            Some(r) if !r.ok => (pal.critical, format!("{label} failed")),
            Some(_) if name == "bash" => (pal.interactive, "Shell finished".to_string()),
            Some(_) => (pal.text_strong, label),
        };
        ui.add_space(3.0);
        let resp = ui
            .horizontal(|ui| {
                if res.is_none() {
                    ui.add(egui::Spinner::new().size(11.0).color(pal.text_weak));
                }
                ui.label(RichText::new(label).color(status_col));
                ui.label(RichText::new("·").color(pal.text_weak));
                ui.add(egui::Label::new(RichText::new(&subject).color(pal.text_weak)).truncate().selectable(false));
            })
            .response
            .interact(Sense::click())
            .on_hover_cursor(egui::CursorIcon::PointingHand);
        if resp.clicked() {
            toggle(&mut self.expanded_tools, key);
        }
        if open {
            let mut body = String::new();
            match name {
                "bash" => body.push_str(&format!("$ {}\n", get("command"))),
                "edit" => body.push_str(&format!(
                    "- {}\n+ {}\n\n",
                    get("oldString").replace('\n', "\n- "),
                    get("newString").replace('\n', "\n+ ")
                )),
                "write" => body.push_str(&format!("{}\n\n", get("content").chars().take(4000).collect::<String>())),
                _ => {}
            }
            body.push_str(res.map(|r| r.text.as_str()).unwrap_or("Running…"));
            output_box(ui, &pal, &body);
        }
    }

    fn composer_height(&self, sid: u64, w: f32) -> f32 {
        let text = self.drafts.get(&sid).map(|s| s.as_str()).unwrap_or("");
        let wrapped: f32 = text.lines().map(|l| (l.chars().count() as f32 * 7.4 / (w - 40.0).max(50.0)).floor()).sum();
        let lines = text.lines().count().max(1) as f32 + wrapped + if text.ends_with('\n') { 1.0 } else { 0.0 };
        let input_h = (lines.clamp(2.0, 10.0) * 19.0).max(40.0);
        let mut h = input_h + 22.0 + 42.0;
        if self.runs.get(&sid).map(|r| r.pending.is_some()).unwrap_or(false) {
            h += 124.0;
        }
        if self.queues.get(&sid).map(|q| !q.is_empty()).unwrap_or(false) {
            h += 30.0;
        }
        if let Some(s) = self.store.session(sid) {
            if s.todos.iter().any(|t| t.status != "completed" && t.status != "cancelled") {
                h += 36.0;
            }
        }
        h
    }

    fn composer(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64, s: &Session, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        let mut c = ui.new_child(egui::UiBuilder::new().max_rect(rect).layout(Layout::top_down(Align::Min)));
        c.set_width(rect.width());

        // todo pill
        let open_todos: Vec<_> = s.todos.iter().filter(|t| t.status != "completed" && t.status != "cancelled").collect();
        if !open_todos.is_empty() {
            let done = s.todos.iter().filter(|t| t.status == "completed").count();
            let current = s.todos.iter().find(|t| t.status == "in_progress").or(open_todos.first().copied());
            let resp = egui::Frame::NONE
                .fill(pal.bg_weak)
                .corner_radius(8)
                .inner_margin(egui::Margin::symmetric(10, 6))
                .show(&mut c, |ui| {
                    ui.horizontal(|ui| {
                        let word = if s.todos.len() == 1 { "todo" } else { "todos" };
                        ui.label(RichText::new(format!("{done} of {} {word} done", s.todos.len())).size(12.5).color(pal.text_base));
                        if let Some(cur) = current {
                            ui.label(RichText::new("·").color(pal.text_weak));
                            ui.add(egui::Label::new(RichText::new(&cur.content).size(12.5).color(pal.text_strong)).truncate());
                        }
                    });
                })
                .response;
            resp.on_hover_ui(|ui| {
                for t in &s.todos {
                    let mark = match t.status.as_str() {
                        "completed" => "[x]",
                        "in_progress" => "[>]",
                        "cancelled" => "[-]",
                        _ => "[ ]",
                    };
                    ui.label(format!("{mark} {}", t.content));
                }
            });
            c.add_space(6.0);
        }

        // queued prompts
        if let Some(q) = self.queues.get(&sid).cloned() {
            if !q.is_empty() {
                let mut clear = false;
                c.horizontal(|ui| {
                    ui.label(RichText::new(format!("{} queued", q.len())).size(12.5).color(pal.text_base));
                    ui.add(egui::Label::new(RichText::new(&q[0]).size(12.5).color(pal.text_weak)).truncate());
                    if ui.small_button("Remove").clicked() {
                        clear = true;
                    }
                });
                if clear {
                    self.queues.remove(&sid);
                }
                c.add_space(4.0);
            }
        }

        // permission dock
        let mut reply: Option<PermReply> = None;
        if let Some(req) = self.runs.get(&sid).and_then(|r| r.pending.as_ref()) {
            egui::Frame::NONE
                .fill(pal.bg_panel)
                .stroke(Stroke::new(1.0, pal.border_base))
                .corner_radius(10)
                .inner_margin(egui::Margin::symmetric(14, 12))
                .show(&mut c, |ui| {
                    ui.set_width(ui.available_width());
                    ui.horizontal(|ui| {
                        let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
                        theme::icon_warning(ui.painter(), r.center(), pal.warning);
                        ui.label(RichText::new(format!("Permission required · {}", req.title)).font(bold(14.0)).color(pal.text_strong));
                    });
                    ui.add_space(2.0);
                    ui.add(egui::Label::new(RichText::new(&req.detail).monospace().color(pal.text_base)).truncate());
                    ui.add_space(8.0);
                    ui.horizontal(|ui| {
                        if primary_button(ui, &pal, "Allow once", 100.0).clicked() {
                            reply = Some(PermReply::Once);
                        }
                        if ui
                            .add(egui::Button::new("Allow always").min_size(Vec2::new(100.0, 32.0)))
                            .on_hover_text("Allow this kind of action for the rest of this session")
                            .clicked()
                        {
                            reply = Some(PermReply::Always);
                        }
                        if ui.add(egui::Button::new(RichText::new("Deny").color(pal.critical)).min_size(Vec2::new(70.0, 32.0))).clicked() {
                            reply = Some(PermReply::Deny);
                        }
                    });
                });
            c.add_space(6.0);
        }
        if let Some(rp) = reply {
            if let Some(req) = self.runs.get_mut(&sid).and_then(|r| r.pending.take()) {
                let _ = req.reply.send(rp);
            }
        }

        // the input box
        let shell = self.shell_mode;
        let running = self.runs.contains_key(&sid);
        let mut send = false;
        let mut toggle_shell = false;
        let mut toggle_agent = false;
        let mut open_models = false;
        let block_focus = self.palette.is_some() || self.settings_open || self.add_project.is_some() || self.rename.is_some();
        egui::Frame::NONE
            .fill(pal.bg_panel)
            .stroke(Stroke::new(1.0, if shell { pal.interactive.gamma_multiply(0.6) } else { pal.border_base }))
            .corner_radius(10)
            .inner_margin(egui::Margin { left: 12, right: 8, top: 10, bottom: 6 })
            .shadow(egui::Shadow { offset: [0, 2], blur: 8, spread: 0, color: Color32::from_black_alpha(if pal.dark { 60 } else { 10 }) })
            .show(&mut c, |ui| {
                ui.set_width(ui.available_width());
                let focus = std::mem::replace(&mut self.focus_composer, false);
                let draft = self.drafts.entry(sid).or_default();
                let hint = if shell { "Enter shell command… \"git status\"" } else { "Ask anything, / for commands…" };
                let out = ui.add(
                    egui::TextEdit::multiline(draft)
                        .id_salt(("composer", sid))
                        .hint_text(RichText::new(hint).color(pal.text_weak))
                        .frame(egui::Frame::NONE)
                        .desired_rows(2)
                        .desired_width(f32::INFINITY)
                        .font(if shell { egui::TextStyle::Monospace } else { egui::TextStyle::Body })
                        .return_key(egui::KeyboardShortcut::new(Modifiers::SHIFT, Key::Enter)),
                );
                if focus && !block_focus {
                    out.request_focus();
                }
                if out.has_focus() && ui.input(|i| i.key_pressed(Key::Enter) && !i.modifiers.shift) {
                    send = true;
                }
                if shell && out.has_focus() && draft.is_empty() && ui.input(|i| i.key_pressed(Key::Backspace)) {
                    toggle_shell = true;
                }
                if !shell && draft == "!" {
                    draft.clear();
                    toggle_shell = true;
                }
                ui.add_space(4.0);
                ui.horizontal(|ui| {
                    if shell {
                        let r = ui.add(egui::Button::new(RichText::new("Shell").color(pal.interactive)).fill(pal.interactive_bg));
                        if r.on_hover_text("Back to prompt (Ctrl+Shift+X)").clicked() {
                            toggle_shell = true;
                        }
                    } else {
                        let r = ui.add(egui::Button::new(RichText::new(cap(&s.agent)).font(bold(13.5)).color(pal.text_strong)).fill(Color32::TRANSPARENT));
                        if r.on_hover_text("Switch agent: Build makes changes, Plan only looks (Ctrl+.)").clicked() {
                            toggle_agent = true;
                        }
                        let model = self.store.settings.model.clone();
                        let mr = ui
                            .add(egui::Button::new(RichText::new(&model).color(pal.text_base)).fill(Color32::TRANSPARENT))
                            .on_hover_text("Choose model (Ctrl+')");
                        egui::Popup::menu(&mr).show(|ui| {
                            ui.set_min_width(220.0);
                            ui.label(RichText::new("Models").size(12.0).color(pal.text_weak));
                            for m in self.store.settings.models.clone() {
                                if ui.selectable_label(m == self.store.settings.model, &m).clicked() {
                                    self.store.settings.model = m;
                                    self.dirty = true;
                                }
                            }
                            ui.separator();
                            if ui.button("Manage models…").clicked() {
                                open_models = true;
                            }
                        });
                        if self.store.settings.auto_accept {
                            ui.label(RichText::new("auto-accept").size(12.0).color(pal.warning))
                                .on_hover_text("Permission requests are approved automatically (Ctrl+Shift+A)");
                        }
                    }
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        let (r, resp) = ui.allocate_exact_size(Vec2::splat(30.0), Sense::click());
                        let empty = self.drafts.get(&sid).map(|d| d.trim().is_empty()).unwrap_or(true);
                        if running && empty {
                            ui.painter().circle_filled(r.center(), 15.0, pal.primary_btn);
                            theme::icon_stop(ui.painter(), r.center(), pal.primary_text);
                            if resp.on_hover_text("Stop (Esc)").clicked() {
                                self.stop(sid);
                            }
                        } else {
                            ui.painter().circle_filled(r.center(), 15.0, if empty { pal.text_weaker } else { pal.primary_btn });
                            theme::icon_arrow_up(ui.painter(), r.center(), pal.primary_text);
                            if resp.on_hover_text(if running { "Queue (Enter)" } else { "Send (Enter)" }).clicked() {
                                send = true;
                            }
                        }
                        ui.add_space(2.0);
                        let tip = if shell { "Prompt mode (Ctrl+Shift+X)" } else { "Shell mode (Ctrl+Shift+X)" };
                        let col = if shell { pal.interactive } else { pal.icon };
                        if ui.add(egui::Button::new(RichText::new(">_").monospace().color(col)).fill(Color32::TRANSPARENT)).on_hover_text(tip).clicked() {
                            toggle_shell = true;
                        }
                    });
                });
            });
        if toggle_shell {
            self.shell_mode = !self.shell_mode;
            self.focus_composer = true;
        }
        if toggle_agent {
            self.set_agent(sid, if s.agent == "build" { "plan" } else { "build" });
        }
        if open_models {
            self.settings_tab = SettingsTab::Models;
            self.settings_open = true;
        }
        if send {
            if let Some(d) = self.drafts.get_mut(&sid) {
                *d = d.trim_end_matches(['\n', '\r']).to_string();
            }
            self.submit(sid, ctx, t);
            self.focus_composer = true;
        }
    }

    // ------------------------------------------------------------ review / files

    fn side_pane(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64) {
        let pal = self.pal;
        card(ui, &pal, rect);
        let Some(session) = self.store.session(sid).cloned() else { return };
        let Some(project) = self.store.project(session.project_id).cloned() else { return };
        let root = PathBuf::from(&project.path);

        // tab row
        let tabs_rect = Rect::from_min_size(rect.min, Vec2::new(rect.width(), 48.0));
        let mut tr = ui.new_child(egui::UiBuilder::new().max_rect(tabs_rect.shrink2(Vec2::new(12.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        let n_changed = session.changed_files.len();
        let review_label = if n_changed > 0 { format!("Review ({n_changed})") } else { "Review".to_string() };
        if file_tab(&mut tr, &pal, &review_label, self.active_file.is_none(), None).0 {
            self.active_file = None;
        }
        let mut close: Option<usize> = None;
        for (i, f) in self.files.iter().enumerate() {
            let name = f.path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
            let (clicked, closed) = file_tab(&mut tr, &pal, &name, self.active_file == Some(i), Some(f.text.is_err()));
            if clicked {
                self.active_file = Some(i);
            }
            if closed {
                close = Some(i);
            }
        }
        tr.with_layout(Layout::right_to_left(Align::Center), |ui| {
            if theme::icon_button(ui, &pal, 28.0, "Hide review (Ctrl+Shift+R)", |p, c, col| theme::icon_panel(p, c, col, true)).clicked() {
                self.show_review = false;
            }
        });
        if let Some(i) = close {
            self.files.remove(i);
            self.active_file = match self.active_file {
                Some(a) if a == i => {
                    if self.files.is_empty() {
                        None
                    } else {
                        Some(i.min(self.files.len() - 1))
                    }
                }
                Some(a) if a > i => Some(a - 1),
                other => other,
            };
        }
        let y1 = tabs_rect.bottom();
        ui.painter().line_segment([Pos2::new(rect.left(), y1), Pos2::new(rect.right(), y1)], Stroke::new(1.0, pal.border_weak));

        // project row
        let prow = Rect::from_min_size(Pos2::new(rect.left(), y1), Vec2::new(rect.width(), 46.0));
        let mut pr = ui.new_child(egui::UiBuilder::new().max_rect(prow.shrink2(Vec2::new(14.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        if theme::icon_button(&mut pr, &pal, 26.0, "Toggle file tree", theme::icon_tree).clicked() {
            self.show_tree = !self.show_tree;
        }
        pr.add_space(4.0);
        pr.label(RichText::new(&project.name).font(bold(14.0)).color(pal.text_strong));
        pr.add(egui::Label::new(RichText::new(&project.path).size(12.0).color(pal.text_weak)).truncate());
        let y2 = prow.bottom();
        ui.painter().line_segment([Pos2::new(rect.left(), y2), Pos2::new(rect.right(), y2)], Stroke::new(1.0, pal.border_weak));

        let body = Rect::from_min_max(Pos2::new(rect.left() + 1.0, y2 + 1.0), Pos2::new(rect.right() - 1.0, rect.bottom() - 6.0));
        let (tree_rect, view_rect) = if self.show_tree && body.width() > FILE_TREE_WIDTH + 160.0 {
            let trr = Rect::from_min_size(body.min, Vec2::new(FILE_TREE_WIDTH, body.height()));
            let vr = Rect::from_min_max(Pos2::new(trr.right() + 1.0, body.top()), body.max);
            ui.painter().line_segment([Pos2::new(trr.right(), body.top()), Pos2::new(trr.right(), body.bottom())], Stroke::new(1.0, pal.border_weak));
            (Some(trr), vr)
        } else {
            (None, body)
        };
        let mut open: Option<PathBuf> = None;
        if let Some(trr) = tree_rect {
            let mut tu = ui.new_child(egui::UiBuilder::new().max_rect(trr.shrink2(Vec2::new(6.0, 6.0))).layout(Layout::top_down(Align::Min)));
            egui::ScrollArea::vertical().id_salt("tree").auto_shrink([false, false]).show(&mut tu, |ui| {
                self.tree(ui, &root, 0, &mut open);
            });
        }
        let mut vu = ui.new_child(egui::UiBuilder::new().max_rect(view_rect.shrink2(Vec2::new(16.0, 10.0))).layout(Layout::top_down(Align::Min)));
        match self.active_file {
            Some(i) if i < self.files.len() => match &self.files[i].text {
                Ok(text) => {
                    egui::ScrollArea::both().id_salt(("file", i)).auto_shrink([false, false]).show(&mut vu, |ui| {
                        let digits = text.lines().count().to_string().len().max(2);
                        let mut job = egui::text::LayoutJob::default();
                        let num = egui::TextFormat { font_id: FontId::monospace(12.5), color: pal.text_weaker, ..Default::default() };
                        let code = egui::TextFormat { font_id: FontId::monospace(12.5), color: pal.text_strong, ..Default::default() };
                        for (n, line) in text.lines().enumerate().take(20_000) {
                            job.append(&format!("{:>w$}  ", n + 1, w = digits), 0.0, num.clone());
                            job.append(&line.replace('\t', "    "), 0.0, code.clone());
                            job.append("\n", 0.0, code.clone());
                        }
                        ui.add(egui::Label::new(job).extend());
                    });
                }
                Err(e) => {
                    vu.add_space(6.0);
                    vu.label(RichText::new(e).color(pal.text_weak));
                }
            },
            _ => {
                egui::ScrollArea::vertical().id_salt("review").auto_shrink([false, false]).show(&mut vu, |ui| {
                    if session.changed_files.is_empty() {
                        if tree_rect.is_none() {
                            ui.label(RichText::new("Files").font(bold(12.5)).color(pal.text_weak));
                            ui.add_space(4.0);
                            self.tree(ui, &root, 0, &mut open);
                        } else {
                            ui.add_space(30.0);
                            ui.vertical_centered(|ui| {
                                ui.label(RichText::new("No changes yet").color(pal.text_base));
                                ui.label(RichText::new("Files the assistant edits show up here.").size(12.5).color(pal.text_weak));
                            });
                        }
                    } else {
                        let n = session.changed_files.len();
                        ui.label(RichText::new(format!("{n} Changed file{}", if n == 1 { "" } else { "s" })).font(bold(14.0)).color(pal.text_strong));
                        ui.add_space(6.0);
                        for f in &session.changed_files {
                            let r = list_row(ui, &pal, false, 30.0, |ui| {
                                let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
                                theme::icon_file(ui.painter(), r.center(), pal.icon);
                                ui.label(RichText::new(f).color(pal.text_strong));
                            });
                            if r.clicked() {
                                let p = Path::new(f);
                                open = Some(if p.is_absolute() { p.to_path_buf() } else { root.join(f) });
                            }
                        }
                    }
                });
            }
        }
        if let Some(p) = open {
            self.open_file(p);
        }
    }

    fn tree(&mut self, ui: &mut egui::Ui, dir: &Path, depth: usize, open: &mut Option<PathBuf>) {
        let pal = self.pal;
        let Ok(rd) = std::fs::read_dir(dir) else {
            ui.label(RichText::new("Project folder not found").color(pal.text_weak));
            return;
        };
        let mut entries: Vec<(bool, String, PathBuf)> = rd
            .filter_map(|e| e.ok())
            .map(|e| (e.path().is_dir(), e.file_name().to_string_lossy().to_string(), e.path()))
            .filter(|(_, n, _)| !n.starts_with('.') && !agent::ignored(n))
            .collect();
        entries.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.to_lowercase().cmp(&b.1.to_lowercase())));
        for (is_dir, name, path) in entries.into_iter().take(500) {
            let expanded = self.expanded.contains(&path);
            let resp = list_row(ui, &pal, false, 24.0, |ui| {
                ui.add_space(depth as f32 * 12.0);
                let (r, _) = ui.allocate_exact_size(Vec2::splat(14.0), Sense::hover());
                if is_dir {
                    theme::icon_chevron(ui.painter(), r.center(), pal.icon, expanded);
                } else {
                    theme::icon_file(ui.painter(), r.center(), pal.text_weaker);
                }
                ui.add(
                    egui::Label::new(RichText::new(&name).size(13.0).color(if is_dir { pal.text_strong } else { pal.text_base }))
                        .truncate()
                        .selectable(false),
                );
            });
            if resp.clicked() {
                if is_dir {
                    toggle(&mut self.expanded, path.clone());
                } else {
                    *open = Some(path.clone());
                }
            }
            if is_dir && expanded {
                self.tree(ui, &path, depth + 1, open);
            }
        }
    }

    fn open_file(&mut self, p: PathBuf) {
        if let Some(i) = self.files.iter().position(|f| f.path == p) {
            self.files[i].text = read_text(&p);
            self.active_file = Some(i);
            return;
        }
        let text = read_text(&p);
        self.files.push(OpenFile { path: p, text });
        self.active_file = Some(self.files.len() - 1);
        self.show_review = true;
    }
}

input.content:
//! Session screen: chat panel (header, timeline, composer with permission
//! dock) and the review pane (changed files, file tree, file viewer).

use super::*;
use crate::agent::PermReply;
use crate::markdown;
use crate::theme::bold;
use eframe::egui::{Align, Color32, FontId, Layout, RichText, Sense, Stroke};

impl App {
    pub(super) fn session_screen(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        let avail = rect.width();
        let (left, right) = if self.show_review && avail >= SESSION_WIDTH_MIN + SIDE_PANE_MIN + INSET {
            let w = self.session_width.clamp(SESSION_WIDTH_MIN, (avail - SIDE_PANE_MIN - INSET).max(SESSION_WIDTH_MIN));
            let l = Rect::from_min_size(rect.min, Vec2::new(w, rect.height()));
            let r = Rect::from_min_max(Pos2::new(l.right() + INSET, rect.top()), rect.max);
            let handle = Rect::from_min_max(Pos2::new(l.right(), rect.top()), Pos2::new(r.left(), rect.bottom()));
            let hr = ui.interact(handle, egui::Id::new("divider"), Sense::drag()).on_hover_cursor(egui::CursorIcon::ResizeHorizontal);
            if hr.dragged() {
                self.session_width = (w + hr.drag_delta().x).clamp(SESSION_WIDTH_MIN, (avail - SIDE_PANE_MIN - INSET).max(SESSION_WIDTH_MIN));
            }
            if hr.hovered() || hr.dragged() {
                ui.painter().line_segment(
                    [handle.center_top() + Vec2::new(0.0, 12.0), handle.center_bottom() - Vec2::new(0.0, 12.0)],
                    Stroke::new(2.0, pal.interactive),
                );
            }
            (l, Some(r))
        } else {
            (rect, None)
        };
        self.chat_panel(ui, left, sid, ctx, t);
        if let Some(r) = right {
            self.side_pane(ui, r, sid);
        }
    }

    fn chat_panel(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        card(ui, &pal, rect);
        let Some(session) = self.store.session(sid).cloned() else { return };
        let project = self.store.project(session.project_id).cloned();
        let pname = project.as_ref().map(|p| p.name.clone()).unwrap_or("(no project)".into());
        let mut todo: Vec<Cmd> = vec![];

        // header: project / title ···            ring 136k · $0.00 [panel]
        let header = Rect::from_min_size(rect.min, Vec2::new(rect.width(), 48.0));
        let mut h = ui.new_child(egui::UiBuilder::new().max_rect(header.shrink2(Vec2::new(16.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        theme::avatar(&mut h, &pal, &pname, 16.0);
        h.add_space(2.0);
        let pl = h.add(egui::Label::new(RichText::new(&pname).color(pal.text_base)).sense(Sense::click()).selectable(false));
        if pl.on_hover_text("Show this project's sessions").clicked() {
            self.home_project = Some(session.project_id);
            todo.push(Cmd::Home);
        }
        h.label(RichText::new("/").color(pal.text_weaker));
        let title_full = h.fonts_mut(|f| f.layout_no_wrap(session.title.clone(), FontId::proportional(14.0), pal.text_strong).size().x);
        let title_w = title_full.min((h.available_width() - 190.0).max(40.0)) + 2.0;
        let tl = h.add_sized(
            Vec2::new(title_w, 20.0),
            egui::Label::new(RichText::new(&session.title).color(pal.text_strong)).truncate().sense(Sense::click()).selectable(false),
        );
        if tl.on_hover_text("Double-click to rename").double_clicked() {
            todo.push(Cmd::Rename);
        }
        let more = theme::icon_button(&mut h, &pal, 26.0, "Session actions", theme::icon_dots);
        egui::Popup::menu(&more).show(|ui| {
            ui.set_min_width(190.0);
            if ui.button("Rename session").clicked() {
                todo.push(Cmd::Rename);
            }
            if ui.button("Compact session").on_hover_text("Summarize the session to reduce context size").clicked() {
                todo.push(Cmd::Compact);
            }
            if ui.button("Undo last message").clicked() {
                todo.push(Cmd::Undo);
            }
            if ui.button("Export session").on_hover_text("Save the full transcript as JSON in Downloads").clicked() {
                todo.push(Cmd::Export);
            }
            ui.separator();
            if ui.button(RichText::new("Delete session").color(pal.critical)).clicked() {
                todo.push(Cmd::Delete);
            }
        });
        let limit = self.store.settings.context_limit.max(1);
        h.with_layout(Layout::right_to_left(Align::Center), |ui| {
            if !self.show_review && theme::icon_button(ui, &pal, 28.0, "Show review (Ctrl+Shift+R)", |p, c, col| theme::icon_panel(p, c, col, true)).clicked() {
                todo.push(Cmd::ToggleReview);
            }
            ui.add_space(4.0);
            ui.label(RichText::new(format!("${:.2}", session.cost)).color(pal.text_weak));
            ui.label(RichText::new("·").color(pal.text_weak));
            ui.label(RichText::new(compact_num(session.context_tokens)).color(pal.text_weak));
            let (r, resp) = ui.allocate_exact_size(Vec2::splat(18.0), Sense::hover());
            let frac = session.context_tokens as f32 / limit as f32;
            theme::context_ring(ui.painter(), r.center(), 7.0, frac, &pal);
            resp.on_hover_text(format!(
                "Context: {} of {} tokens ({:.0}%)\nTotal used: {} tokens\nCost: ${:.4}",
                session.context_tokens,
                limit,
                frac * 100.0,
                session.total_tokens,
                session.cost
            ));
        });

        // composer first (bottom), then the timeline takes the rest
        let content_w = (rect.width() - 40.0).min(760.0);
        let col_left = rect.center().x - content_w / 2.0;
        let comp_h = self.composer_height(sid, content_w);
        let comp_rect = Rect::from_min_size(Pos2::new(col_left, rect.bottom() - comp_h - 12.0), Vec2::new(content_w, comp_h));
        let tl_rect = Rect::from_min_max(Pos2::new(rect.left() + 1.0, header.bottom()), Pos2::new(rect.right() - 1.0, comp_rect.top() - 4.0));

        let mut tlui = ui.new_child(egui::UiBuilder::new().max_rect(tl_rect).layout(Layout::top_down(Align::Min)));
        let stick = std::mem::replace(&mut self.stick_bottom, false);
        let running = self.runs.get(&sid).map(|r| (r.status.clone(), r.started));
        egui::ScrollArea::vertical()
            .id_salt(("timeline", sid))
            .auto_shrink([false, false])
            .stick_to_bottom(true)
            .show(&mut tlui, |ui| {
                let pad = ((ui.available_width() - content_w) / 2.0).max(16.0);
                ui.add_space(8.0);
                ui.horizontal_top(|ui| {
                    ui.add_space(pad);
                    ui.vertical(|ui| {
                        ui.set_width(content_w);
                        if session.messages.is_empty() {
                            self.empty_session(ui, project.as_ref());
                        }
                        self.timeline(ui, &session);
                        if let Some((status, started)) = &running {
                            ui.add_space(6.0);
                            ui.horizontal(|ui| {
                                let phase = ((t - started) * 2.5).sin() as f32 * 0.5 + 0.5;
                                let col = lerp_color(pal.text_weak, pal.text_strong, phase);
                                ui.add(egui::Spinner::new().size(12.0).color(pal.text_weak));
                                ui.label(RichText::new(format!("{status}…")).color(col));
                                ui.label(RichText::new(format!("{}s", (t - started) as u64)).color(pal.text_weaker));
                            });
                            ctx.request_repaint_after(std::time::Duration::from_millis(50));
                        }
                        ui.add_space(24.0);
                    });
                });
                if stick {
                    ui.scroll_to_cursor(Some(Align::BOTTOM));
                }
            });

        self.composer(ui, comp_rect, sid, &session, ctx, t);
        for c in todo {
            self.run_cmd(c, ctx, t);
        }
    }

    fn empty_session(&self, ui: &mut egui::Ui, p: Option<&Project>) {
        let pal = self.pal;
        ui.add_space(60.0);
        ui.vertical_centered(|ui| {
            ui.label(RichText::new("New session").font(bold(20.0)).color(pal.text_strong));
            ui.add_space(4.0);
            if let Some(p) = p {
                ui.label(RichText::new(&p.path).monospace().color(pal.text_weak));
            }
            ui.add_space(16.0);
        });
        for (a, b) in [
            ("Build", "makes changes: edits files and runs commands, asking you first"),
            ("Plan", "only reads and explains. Switch with Ctrl+."),
            ("Shell", "type commands yourself. Toggle with Ctrl+Shift+X"),
        ] {
            ui.horizontal(|ui| {
                ui.add_space((ui.available_width() - 460.0).max(0.0) / 2.0);
                ui.label(RichText::new(a).font(bold(13.5)).color(pal.text_strong));
                ui.label(RichText::new(b).size(13.5).color(pal.text_base));
            });
        }
        ui.add_space(20.0);
    }

    fn timeline(&mut self, ui: &mut egui::Ui, s: &Session) {
        let pal = self.pal;
        let results: HashMap<&str, &Message> = s.messages.iter().filter(|m| m.role == Role::Tool).map(|m| (m.tool_call_id.as_str(), m)).collect();
        for (i, m) in s.messages.iter().enumerate() {
            match m.role {
                Role::User => {
                    ui.add_space(14.0);
                    let maxw = ui.available_width() * 0.82;
                    ui.with_layout(Layout::right_to_left(Align::Min), |ui| {
                        egui::Frame::NONE
                            .fill(pal.bg_weak)
                            .corner_radius(10)
                            .inner_margin(egui::Margin::symmetric(14, 10))
                            .show(ui, |ui| {
                                ui.set_max_width(maxw);
                                ui.add(egui::Label::new(RichText::new(&m.text).color(pal.text_strong)).wrap());
                            });
                    });
                    if !m.agent.is_empty() && !m.model.is_empty() {
                        ui.with_layout(Layout::right_to_left(Align::Min), |ui| {
                            ui.label(RichText::new(format!("{} · {}", cap(&m.agent), m.model)).size(11.5).color(pal.text_weaker));
                        });
                    }
                    ui.add_space(8.0);
                }
                Role::Assistant => {
                    if !m.text.is_empty() {
                        ui.add_space(4.0);
                        markdown::show(ui, &pal, &m.text);
                    }
                    for (ci, c) in m.tool_calls.iter().enumerate() {
                        let res = results.get(c.id.as_str()).copied();
                        self.tool_row(ui, s.id, i * 64 + ci, &c.name, &c.args, res);
                    }
                }
                Role::Tool => {} // drawn with the call that asked for it
                Role::Shell => {
                    let key = (s.id, i * 64 + 63);
                    let open = self.expanded_tools.contains(&key);
                    ui.add_space(6.0);
                    let resp = ui
                        .horizontal(|ui| {
                            let lab = if m.ok { "Shell finished" } else { "Shell failed" };
                            ui.label(RichText::new(lab).color(if m.ok { pal.interactive } else { pal.critical }));
                            ui.label(RichText::new("·").color(pal.text_weak));
                            ui.add(egui::Label::new(RichText::new(&m.title).color(pal.text_weak)).truncate().selectable(false));
                        })
                        .response
                        .interact(Sense::click())
                        .on_hover_cursor(egui::CursorIcon::PointingHand);
                    if resp.clicked() {
                        toggle(&mut self.expanded_tools, key);
                    }
                    if open {
                        output_box(ui, &pal, &format!("$ {}\n{}", m.title, m.text));
                    }
                }
                Role::Notice => {
                    ui.add_space(8.0);
                    let col = if m.ok { pal.text_base } else { pal.critical };
                    egui::Frame::NONE
                        .stroke(Stroke::new(1.0, if m.ok { pal.border_weak } else { pal.critical.gamma_multiply(0.5) }))
                        .corner_radius(8)
                        .inner_margin(egui::Margin::symmetric(12, 8))
                        .show(ui, |ui| {
                            ui.set_width(ui.available_width());
                            ui.add(egui::Label::new(RichText::new(&m.text).color(col)).wrap());
                        });
                    ui.add_space(8.0);
                }
            }
        }
    }

    fn tool_row(&mut self, ui: &mut egui::Ui, sid: u64, slot: usize, name: &str, args: &str, res: Option<&Message>) {
        let pal = self.pal;
        let a: serde_json::Value = serde_json::from_str(args).unwrap_or_default();
        let get = |k: &str| a[k].as_str().unwrap_or("").to_string();
        let subject = match name {
            "bash" => {
                let d = get("description");
                if d.is_empty() { get("command") } else { d }
            }
            "glob" | "grep" => get("pattern"),
            "webfetch" => get("url"),
            "todowrite" => format!("{} todos", a["todos"].as_array().map(|v| v.len()).unwrap_or(0)),
            _ => {
                let p = if a["filePath"].is_string() { get("filePath") } else { get("path") };
                if p.is_empty() { ".".into() } else { p }
            }
        };
        let key = (sid, slot);
        let open = self.expanded_tools.contains(&key);
        let label = agent::tool_label(name);
        let (status_col, label) = match res {
            None => (pal.text_weak, label),
            Some(r) if !r.ok => (pal.critical, format!("{label} failed")),
            Some(_) if name == "bash" => (pal.interactive, "Shell finished".to_string()),
            Some(_) => (pal.text_strong, label),
        };
        ui.add_space(3.0);
        let resp = ui
            .horizontal(|ui| {
                if res.is_none() {
                    ui.add(egui::Spinner::new().size(11.0).color(pal.text_weak));
                }
                ui.label(RichText::new(label).color(status_col));
                ui.label(RichText::new("·").color(pal.text_weak));
                ui.add(egui::Label::new(RichText::new(&subject).color(pal.text_weak)).truncate().selectable(false));
            })
            .response
            .interact(Sense::click())
            .on_hover_cursor(egui::CursorIcon::PointingHand);
        if resp.clicked() {
            toggle(&mut self.expanded_tools, key);
        }
        if open {
            let mut body = String::new();
            match name {
                "bash" => body.push_str(&format!("$ {}\n", get("command"))),
                "edit" => body.push_str(&format!(
                    "- {}\n+ {}\n\n",
                    get("oldString").replace('\n', "\n- "),
                    get("newString").replace('\n', "\n+ ")
                )),
                "write" => body.push_str(&format!("{}\n\n", get("content").chars().take(4000).collect::<String>())),
                _ => {}
            }
            body.push_str(res.map(|r| r.text.as_str()).unwrap_or("Running…"));
            output_box(ui, &pal, &body);
        }
    }

    fn composer_height(&self, sid: u64, w: f32) -> f32 {
        let text = self.drafts.get(&sid).map(|s| s.as_str()).unwrap_or("");
        let wrapped: f32 = text.lines().map(|l| (l.chars().count() as f32 * 7.4 / (w - 40.0).max(50.0)).floor()).sum();
        let lines = text.lines().count().max(1) as f32 + wrapped + if text.ends_with('\n') { 1.0 } else { 0.0 };
        let input_h = (lines.clamp(2.0, 10.0) * 19.0).max(40.0);
        let mut h = input_h + 22.0 + 42.0;
        if self.runs.get(&sid).map(|r| r.pending.is_some()).unwrap_or(false) {
            h += 124.0;
        }
        if self.queues.get(&sid).map(|q| !q.is_empty()).unwrap_or(false) {
            h += 30.0;
        }
        if let Some(s) = self.store.session(sid) {
            if s.todos.iter().any(|t| t.status != "completed" && t.status != "cancelled") {
                h += 36.0;
            }
        }
        h
    }

    fn composer(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64, s: &Session, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        let mut c = ui.new_child(egui::UiBuilder::new().max_rect(rect).layout(Layout::top_down(Align::Min)));
        c.set_width(rect.width());

        // todo pill
        let open_todos: Vec<_> = s.todos.iter().filter(|t| t.status != "completed" && t.status != "cancelled").collect();
        if !open_todos.is_empty() {
            let done = s.todos.iter().filter(|t| t.status == "completed").count();
            let current = s.todos.iter().find(|t| t.status == "in_progress").or(open_todos.first().copied());
            let resp = egui::Frame::NONE
                .fill(pal.bg_weak)
                .corner_radius(8)
                .inner_margin(egui::Margin::symmetric(10, 6))
                .show(&mut c, |ui| {
                    ui.horizontal(|ui| {
                        let word = if s.todos.len() == 1 { "todo" } else { "todos" };
                        ui.label(RichText::new(format!("{done} of {} {word} done", s.todos.len())).size(12.5).color(pal.text_base));
                        if let Some(cur) = current {
                            ui.label(RichText::new("·").color(pal.text_weak));
                            ui.add(egui::Label::new(RichText::new(&cur.content).size(12.5).color(pal.text_strong)).truncate());
                        }
                    });
                })
                .response;
            resp.on_hover_ui(|ui| {
                for t in &s.todos {
                    let mark = match t.status.as_str() {
                        "completed" => "[x]",
                        "in_progress" => "[>]",
                        "cancelled" => "[-]",
                        _ => "[ ]",
                    };
                    ui.label(format!("{mark} {}", t.content));
                }
            });
            c.add_space(6.0);
        }

        // queued prompts
        if let Some(q) = self.queues.get(&sid).cloned() {
            if !q.is_empty() {
                let mut clear = false;
                c.horizontal(|ui| {
                    ui.label(RichText::new(format!("{} queued", q.len())).size(12.5).color(pal.text_base));
                    ui.add(egui::Label::new(RichText::new(&q[0]).size(12.5).color(pal.text_weak)).truncate());
                    if ui.small_button("Remove").clicked() {
                        clear = true;
                    }
                });
                if clear {
                    self.queues.remove(&sid);
                }
                c.add_space(4.0);
            }
        }

        // permission dock
        let mut reply: Option<PermReply> = None;
        if let Some(req) = self.runs.get(&sid).and_then(|r| r.pending.as_ref()) {
            egui::Frame::NONE
                .fill(pal.bg_panel)
                .stroke(Stroke::new(1.0, pal.border_base))
                .corner_radius(10)
                .inner_margin(egui::Margin::symmetric(14, 12))
                .show(&mut c, |ui| {
                    ui.set_width(ui.available_width());
                    ui.horizontal(|ui| {
                        let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
                        theme::icon_warning(ui.painter(), r.center(), pal.warning);
                        ui.label(RichText::new(format!("Permission required · {}", req.title)).font(bold(14.0)).color(pal.text_strong));
                    });
                    ui.add_space(2.0);
                    ui.add(egui::Label::new(RichText::new(&req.detail).monospace().color(pal.text_base)).truncate());
                    ui.add_space(8.0);
                    ui.horizontal(|ui| {
                        if primary_button(ui, &pal, "Allow once", 100.0).clicked() {
                            reply = Some(PermReply::Once);
                        }
                        if ui
                            .add(egui::Button::new("Allow always").min_size(Vec2::new(100.0, 32.0)))
                            .on_hover_text("Allow this kind of action for the rest of this session")
                            .clicked()
                        {
                            reply = Some(PermReply::Always);
                        }
                        if ui.add(egui::Button::new(RichText::new("Deny").color(pal.critical)).min_size(Vec2::new(70.0, 32.0))).clicked() {
                            reply = Some(PermReply::Deny);
                        }
                    });
                });
            c.add_space(6.0);
        }
        if let Some(rp) = reply {
            if let Some(req) = self.runs.get_mut(&sid).and_then(|r| r.pending.take()) {
                let _ = req.reply.send(rp);
            }
        }

        // the input box
        let shell = self.shell_mode;
        let running = self.runs.contains_key(&sid);
        let mut send = false;
        let mut toggle_shell = false;
        let mut toggle_agent = false;
        let mut open_models = false;
        let block_focus = self.palette.is_some() || self.settings_open || self.add_project.is_some() || self.rename.is_some();
        egui::Frame::NONE
            .fill(pal.bg_panel)
            .stroke(Stroke::new(1.0, if shell { pal.interactive.gamma_multiply(0.6) } else { pal.border_base }))
            .corner_radius(10)
            .inner_margin(egui::Margin { left: 12, right: 8, top: 10, bottom: 6 })
            .shadow(egui::Shadow { offset: [0, 2], blur: 8, spread: 0, color: Color32::from_black_alpha(if pal.dark { 60 } else { 10 }) })
            .show(&mut c, |ui| {
                ui.set_width(ui.available_width());
                let focus = std::mem::replace(&mut self.focus_composer, false);
                let draft = self.drafts.entry(sid).or_default();
                let hint = if shell { "Enter shell command… \"git status\"" } else { "Ask anything, / for commands…" };
                let out = ui.add(
                    egui::TextEdit::multiline(draft)
                        .id_salt(("composer", sid))
                        .hint_text(RichText::new(hint).color(pal.text_weak))
                        .frame(egui::Frame::NONE)
                        .desired_rows(2)
                        .desired_width(f32::INFINITY)
                        .font(if shell { egui::TextStyle::Monospace } else { egui::TextStyle::Body })
                        .return_key(egui::KeyboardShortcut::new(Modifiers::SHIFT, Key::Enter)),
                );
                if focus && !block_focus {
                    out.request_focus();
                }
                if out.has_focus() && ui.input(|i| i.key_pressed(Key::Enter) && !i.modifiers.shift) {
                    send = true;
                }
                if shell && out.has_focus() && draft.is_empty() && ui.input(|i| i.key_pressed(Key::Backspace)) {
                    toggle_shell = true;
                }
                if !shell && draft == "!" {
                    draft.clear();
                    toggle_shell = true;
                }
                ui.add_space(4.0);
                ui.horizontal(|ui| {
                    if shell {
                        let r = ui.add(egui::Button::new(RichText::new("Shell").color(pal.interactive)).fill(pal.interactive_bg));
                        if r.on_hover_text("Back to prompt (Ctrl+Shift+X)").clicked() {
                            toggle_shell = true;
                        }
                    } else {
                        let r = ui.add(egui::Button::new(RichText::new(cap(&s.agent)).font(bold(13.5)).color(pal.text_strong)).fill(Color32::TRANSPARENT));
                        if r.on_hover_text("Switch agent: Build makes changes, Plan only looks (Ctrl+.)").clicked() {
                            toggle_agent = true;
                        }
                        let model = self.store.settings.model.clone();
                        let mr = ui
                            .add(egui::Button::new(RichText::new(&model).color(pal.text_base)).fill(Color32::TRANSPARENT))
                            .on_hover_text("Choose model (Ctrl+')");
                        egui::Popup::menu(&mr).show(|ui| {
                            ui.set_min_width(220.0);
                            ui.label(RichText::new("Models").size(12.0).color(pal.text_weak));
                            for m in self.store.settings.models.clone() {
                                if ui.selectable_label(m == self.store.settings.model, &m).clicked() {
                                    self.store.settings.model = m;
                                    self.dirty = true;
                                }
                            }
                            ui.separator();
                            if ui.button("Manage models…").clicked() {
                                open_models = true;
                            }
                        });
                        if self.store.settings.auto_accept {
                            ui.label(RichText::new("auto-accept").size(12.0).color(pal.warning))
                                .on_hover_text("Permission requests are approved automatically (Ctrl+Shift+A)");
                        }
                    }
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        let (r, resp) = ui.allocate_exact_size(Vec2::splat(30.0), Sense::click());
                        let empty = self.drafts.get(&sid).map(|d| d.trim().is_empty()).unwrap_or(true);
                        if running && empty {
                            ui.painter().circle_filled(r.center(), 15.0, pal.primary_btn);
                            theme::icon_stop(ui.painter(), r.center(), pal.primary_text);
                            if resp.on_hover_text("Stop (Esc)").clicked() {
                                self.stop(sid);
                            }
                        } else {
                            ui.painter().circle_filled(r.center(), 15.0, if empty { pal.text_weaker } else { pal.primary_btn });
                            theme::icon_arrow_up(ui.painter(), r.center(), pal.primary_text);
                            if resp.on_hover_text(if running { "Queue (Enter)" } else { "Send (Enter)" }).clicked() {
                                send = true;
                            }
                        }
                        ui.add_space(2.0);
                        let tip = if shell { "Prompt mode (Ctrl+Shift+X)" } else { "Shell mode (Ctrl+Shift+X)" };
                        let col = if shell { pal.interactive } else { pal.icon };
                        if ui.add(egui::Button::new(RichText::new(">_").monospace().color(col)).fill(Color32::TRANSPARENT)).on_hover_text(tip).clicked() {
                            toggle_shell = true;
                        }
                    });
                });
            });
        if toggle_shell {
            self.shell_mode = !self.shell_mode;
            self.focus_composer = true;
        }
        if toggle_agent {
            self.set_agent(sid, if s.agent == "build" { "plan" } else { "build" });
        }
        if open_models {
            self.settings_tab = SettingsTab::Models;
            self.settings_open = true;
        }
        if send {
            if let Some(d) = self.drafts.get_mut(&sid) {
                *d = d.trim_end_matches(['\n', '\r']).to_string();
            }
            self.submit(sid, ctx, t);
            self.focus_composer = true;
        }
    }

    // ------------------------------------------------------------ review / files

    fn side_pane(&mut self, ui: &mut egui::Ui, rect: Rect, sid: u64) {
        let pal = self.pal;
        card(ui, &pal, rect);
        let Some(session) = self.store.session(sid).cloned() else { return };
        let Some(project) = self.store.project(session.project_id).cloned() else { return };
        let root = PathBuf::from(&project.path);

        // tab row
        let tabs_rect = Rect::from_min_size(rect.min, Vec2::new(rect.width(), 48.0));
        let mut tr = ui.new_child(egui::UiBuilder::new().max_rect(tabs_rect.shrink2(Vec2::new(12.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        let n_changed = session.changed_files.len();
        let review_label = if n_changed > 0 { format!("Review ({n_changed})") } else { "Review".to_string() };
        if file_tab(&mut tr, &pal, &review_label, self.active_file.is_none(), None).0 {
            self.active_file = None;
        }
        let mut close: Option<usize> = None;
        for (i, f) in self.files.iter().enumerate() {
            let name = f.path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
            let (clicked, closed) = file_tab(&mut tr, &pal, &name, self.active_file == Some(i), Some(f.text.is_err()));
            if clicked {
                self.active_file = Some(i);
            }
            if closed {
                close = Some(i);
            }
        }
        tr.with_layout(Layout::right_to_left(Align::Center), |ui| {
            if theme::icon_button(ui, &pal, 28.0, "Hide review (Ctrl+Shift+R)", |p, c, col| theme::icon_panel(p, c, col, true)).clicked() {
                self.show_review = false;
            }
        });
        if let Some(i) = close {
            self.files.remove(i);
            self.active_file = match self.active_file {
                Some(a) if a == i => {
                    if self.files.is_empty() {
                        None
                    } else {
                        Some(i.min(self.files.len() - 1))
                    }
                }
                Some(a) if a > i => Some(a - 1),
                other => other,
            };
        }
        let y1 = tabs_rect.bottom();
        ui.painter().line_segment([Pos2::new(rect.left(), y1), Pos2::new(rect.right(), y1)], Stroke::new(1.0, pal.border_weak));

        // project row
        let prow = Rect::from_min_size(Pos2::new(rect.left(), y1), Vec2::new(rect.width(), 46.0));
        let mut pr = ui.new_child(egui::UiBuilder::new().max_rect(prow.shrink2(Vec2::new(14.0, 0.0))).layout(Layout::left_to_right(Align::Center)));
        if theme::icon_button(&mut pr, &pal, 26.0, "Toggle file tree", theme::icon_tree).clicked() {
            self.show_tree = !self.show_tree;
        }
        pr.add_space(4.0);
        pr.label(RichText::new(&project.name).font(bold(14.0)).color(pal.text_strong));
        pr.add(egui::Label::new(RichText::new(&project.path).size(12.0).color(pal.text_weak)).truncate());
        let y2 = prow.bottom();
        ui.painter().line_segment([Pos2::new(rect.left(), y2), Pos2::new(rect.right(), y2)], Stroke::new(1.0, pal.border_weak));

        let body = Rect::from_min_max(Pos2::new(rect.left() + 1.0, y2 + 1.0), Pos2::new(rect.right() - 1.0, rect.bottom() - 6.0));
        let (tree_rect, view_rect) = if self.show_tree && body.width() > FILE_TREE_WIDTH + 160.0 {
            let trr = Rect::from_min_size(body.min, Vec2::new(FILE_TREE_WIDTH, body.height()));
            let vr = Rect::from_min_max(Pos2::new(trr.right() + 1.0, body.top()), body.max);
            ui.painter().line_segment([Pos2::new(trr.right(), body.top()), Pos2::new(trr.right(), body.bottom())], Stroke::new(1.0, pal.border_weak));
            (Some(trr), vr)
        } else {
            (None, body)
        };
        let mut open: Option<PathBuf> = None;
        if let Some(trr) = tree_rect {
            let mut tu = ui.new_child(egui::UiBuilder::new().max_rect(trr.shrink2(Vec2::new(6.0, 6.0))).layout(Layout::top_down(Align::Min)));
            egui::ScrollArea::vertical().id_salt("tree").auto_shrink([false, false]).show(&mut tu, |ui| {
                self.tree(ui, &root, 0, &mut open);
            });
        }
        let mut vu = ui.new_child(egui::UiBuilder::new().max_rect(view_rect.shrink2(Vec2::new(16.0, 10.0))).layout(Layout::top_down(Align::Min)));
        match self.active_file {
            Some(i) if i < self.files.len() => match &self.files[i].text {
                Ok(text) => {
                    egui::ScrollArea::both().id_salt(("file", i)).auto_shrink([false, false]).show(&mut vu, |ui| {
                        let digits = text.lines().count().to_string().len().max(2);
                        let mut job = egui::text::LayoutJob::default();
                        let num = egui::TextFormat { font_id: FontId::monospace(12.5), color: pal.text_weaker, ..Default::default() };
                        let code = egui::TextFormat { font_id: FontId::monospace(12.5), color: pal.text_strong, ..Default::default() };
                        for (n, line) in text.lines().enumerate().take(20_000) {
                            job.append(&format!("{:>w$}  ", n + 1, w = digits), 0.0, num.clone());
                            job.append(&line.replace('\t', "    "), 0.0, code.clone());
                            job.append("\n", 0.0, code.clone());
                        }
                        ui.add(egui::Label::new(job).extend());
                    });
                }
                Err(e) => {
                    vu.add_space(6.0);
                    vu.label(RichText::new(e).color(pal.text_weak));
                }
            },
            _ => {
                egui::ScrollArea::vertical().id_salt("review").auto_shrink([false, false]).show(&mut vu, |ui| {
                    if session.changed_files.is_empty() {
                        if tree_rect.is_none() {
                            ui.label(RichText::new("Files").font(bold(12.5)).color(pal.text_weak));
                            ui.add_space(4.0);
                            self.tree(ui, &root, 0, &mut open);
                        } else {
                            ui.add_space(30.0);
                            ui.vertical_centered(|ui| {
                                ui.label(RichText::new("No changes yet").color(pal.text_base));
                                ui.label(RichText::new("Files the assistant edits show up here.").size(12.5).color(pal.text_weak));
                            });
                        }
                    } else {
                        let n = session.changed_files.len();
                        ui.label(RichText::new(format!("{n} Changed file{}", if n == 1 { "" } else { "s" })).font(bold(14.0)).color(pal.text_strong));
                        ui.add_space(6.0);
                        for f in &session.changed_files {
                            let r = list_row(ui, &pal, false, 30.0, |ui| {
                                let (r, _) = ui.allocate_exact_size(Vec2::splat(16.0), Sense::hover());
                                theme::icon_file(ui.painter(), r.center(), pal.icon);
                                ui.label(RichText::new(f).color(pal.text_strong));
                            });
                            if r.clicked() {
                                let p = Path::new(f);
                                open = Some(if p.is_absolute() { p.to_path_buf() } else { root.join(f) });
                            }
                        }
                    }
                });
            }
        }
        if let Some(p) = open {
            self.open_file(p);
        }
    }

    fn tree(&mut self, ui: &mut egui::Ui, dir: &Path, depth: usize, open: &mut Option<PathBuf>) {
        let pal = self.pal;
        let Ok(rd) = std::fs::read_dir(dir) else {
            ui.label(RichText::new("Project folder not found").color(pal.text_weak));
            return;
        };
        let mut entries: Vec<(bool, String, PathBuf)> = rd
            .filter_map(|e| e.ok())
            .map(|e| (e.path().is_dir(), e.file_name().to_string_lossy().to_string(), e.path()))
            .filter(|(_, n, _)| !n.starts_with('.') && !agent::ignored(n))
            .collect();
        entries.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.to_lowercase().cmp(&b.1.to_lowercase())));
        for (is_dir, name, path) in entries.into_iter().take(500) {
            let expanded = self.expanded.contains(&path);
            let resp = list_row(ui, &pal, false, 24.0, |ui| {
                ui.add_space(depth as f32 * 12.0);
                let (r, _) = ui.allocate_exact_size(Vec2::splat(14.0), Sense::hover());
                if is_dir {
                    theme::icon_chevron(ui.painter(), r.center(), pal.icon, expanded);
                } else {
                    theme::icon_file(ui.painter(), r.center(), pal.text_weaker);
                }
                ui.add(
                    egui::Label::new(RichText::new(&name).size(13.0).color(if is_dir { pal.text_strong } else { pal.text_base }))
                        .truncate()
                        .selectable(false),
                );
            });
            if resp.clicked() {
                if is_dir {
                    toggle(&mut self.expanded, path.clone());
                } else {
                    *open = Some(path.clone());
                }
            }
            if is_dir && expanded {
                self.tree(ui, &path, depth + 1, open);
            }
        }
    }

    fn open_file(&mut self, p: PathBuf) {
        if let Some(i) = self.files.iter().position(|f| f.path == p) {
            self.files[i].text = read_text(&p);
            self.active_file = Some(i);
            return;
        }
        let text = read_text(&p);
        self.files.push(OpenFile { path: p, text });
        self.active_file = Some(self.files.len() - 1);
        self.show_review = true;
    }
}

//! Modal windows: add project, rename, delete, settings, command palette; and toasts.

use super::*;
use crate::store::Perm;
use crate::theme::bold;
use eframe::egui::{Align, Align2, Color32, Layout, RichText};

impl App {
    pub(super) fn dialogs(&mut self, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        if let Some(mut path) = self.add_project.take() {
            let mut keep = true;
            let mut add = false;
            egui::Modal::new(egui::Id::new("addproj")).show(ctx, |ui| {
                ui.set_width(480.0);
                ui.label(RichText::new("Add project").font(bold(17.0)).color(pal.text_strong));
                ui.label(RichText::new("Pick the folder the assistant should work in.").color(pal.text_base));
                ui.add_space(10.0);
                ui.horizontal(|ui| {
                    let r = ui.add(egui::TextEdit::singleline(&mut path).hint_text("C:\\Users\\you\\my-project").desired_width(350.0));
                    if !r.has_focus() && path.is_empty() {
                        r.request_focus();
                    }
                    if r.lost_focus() && ui.input(|i| i.key_pressed(Key::Enter)) {
                        add = true;
                    }
                    if ui.button("Browse…").clicked() {
                        if let Some(p) = rfd::FileDialog::new().set_title("Choose a project folder").pick_folder() {
                            path = p.to_string_lossy().to_string();
                            add = true;
                        }
                    }
                });
                ui.add_space(12.0);
                ui.horizontal(|ui| {
                    if primary_button(ui, &pal, "Add project", 110.0).clicked() {
                        add = true;
                    }
                    if ui.button("Cancel").clicked() || ui.input(|i| i.key_pressed(Key::Escape)) {
                        keep = false;
                    }
                });
            });
            if add {
                self.add_project_path(&path, t);
                keep = false;
            }
            if keep {
                self.add_project = Some(path);
            }
        }

        if let Some((id, mut title)) = self.rename.take() {
            let mut keep = true;
            let mut save = false;
            egui::Modal::new(egui::Id::new("rename")).show(ctx, |ui| {
                ui.set_width(400.0);
                ui.label(RichText::new("Rename session").font(bold(17.0)).color(pal.text_strong));
                ui.add_space(8.0);
                let r = ui.add(egui::TextEdit::singleline(&mut title).id_salt("rename-field").desired_width(f32::INFINITY));
                if !r.has_focus() && !ui.memory(|m| m.focused().is_some()) {
                    r.request_focus();
                }
                if ui.input(|i| i.key_pressed(Key::Enter)) {
                    save = true;
                }
                ui.add_space(10.0);
                ui.horizontal(|ui| {
                    if primary_button(ui, &pal, "Save", 80.0).clicked() {
                        save = true;
                    }
                    if ui.button("Cancel").clicked() || ui.input(|i| i.key_pressed(Key::Escape)) {
                        keep = false;
                    }
                });
            });
            if save {
                if let Some(s) = self.store.session_mut(id) {
                    if !title.trim().is_empty() {
                        s.title = title.trim().to_string();
                    }
                }
                self.dirty = true;
                keep = false;
            }
            if keep {
                self.rename = Some((id, title));
            }
        }

        if let Some(id) = self.confirm_delete {
            let title = self.store.session(id).map(|s| s.title.clone()).unwrap_or_default();
            let mut close = false;
            let mut delete = false;
            egui::Modal::new(egui::Id::new("delete")).show(ctx, |ui| {
                ui.set_width(400.0);
                ui.label(RichText::new("Delete session?").font(bold(17.0)).color(pal.text_strong));
                ui.label(RichText::new(format!("\"{title}\" and its messages will be removed. Files on disk are not touched.")).color(pal.text_base));
                ui.add_space(12.0);
                ui.horizontal(|ui| {
                    if ui.add(egui::Button::new(RichText::new("Delete").color(Color32::WHITE)).fill(pal.critical).min_size(Vec2::new(80.0, 32.0))).clicked() {
                        delete = true;
                    }
                    if ui.button("Cancel").clicked() || ui.input(|i| i.key_pressed(Key::Escape)) {
                        close = true;
                    }
                });
            });
            if delete {
                self.delete_session(id);
                close = true;
            }
            if close {
                self.confirm_delete = None;
            }
        }

        if self.settings_open {
            self.settings(ctx);
        }
        if self.palette.is_some() {
            self.palette_ui(ctx, t);
        }
    }

    fn settings(&mut self, ctx: &egui::Context) {
        let pal = self.pal;
        let mut close = false;
        let screen = ctx.content_rect();
        egui::Modal::new(egui::Id::new("settings")).show(ctx, |ui| {
            let size = Vec2::new(780.0_f32.min(screen.width() - 60.0), 540.0_f32.min(screen.height() - 80.0));
            ui.set_min_size(size);
            ui.set_max_size(size);
            ui.horizontal_top(|ui| {
                ui.vertical(|ui| {
                    ui.set_width(160.0);
                    ui.set_min_height(size.y);
                    ui.label(RichText::new("Settings").font(bold(17.0)).color(pal.text_strong));
                    ui.add_space(10.0);
                    for (tab, name) in [
                        (SettingsTab::General, "General"),
                        (SettingsTab::Models, "Models"),
                        (SettingsTab::Permissions, "Permissions"),
                        (SettingsTab::Shortcuts, "Shortcuts"),
                        (SettingsTab::About, "About"),
                    ] {
                        if list_row(ui, &pal, self.settings_tab == tab, 30.0, |ui| {
                            ui.label(RichText::new(name).color(pal.text_strong));
                        })
                        .clicked()
                        {
                            self.settings_tab = tab;
                        }
                    }
                    ui.with_layout(Layout::bottom_up(Align::Min), |ui| {
                        if primary_button(ui, &pal, "Done", 100.0).clicked() {
                            close = true;
                        }
                    });
                });
                ui.separator();
                ui.vertical(|ui| {
                    egui::ScrollArea::vertical().id_salt("settings-body").auto_shrink([false, false]).show(ui, |ui| {
                        ui.set_width(ui.available_width() - 12.0);
                        self.settings_body(ui);
                    });
                });
            });
            if ui.input(|i| i.key_pressed(Key::Escape)) {
                close = true;
            }
        });
        if close {
            self.settings_open = false;
            self.dirty = true;
            self.focus_composer = true;
        }
    }

