                ui.add_space(10.0);
                ui.horizontal(|ui| {
                    if primary_button(ui, &pal, "Save", 80.0).clicked() {
                        save = true;
                    }
                    if ui.button("Cancel").clicked() || ui.input(|i| i.key_pressed(Key::Escape)) {
                        keep = false;
                    }
                });
            });
            if save {
                if let Some(s) = self.store.session_mut(id) {
                    if !title.trim().is_empty() {
                        s.title = title.trim().to_string();
                    }
                }
                self.dirty = true;
                keep = false;
            }
            if keep {
                self.rename = Some((id, title));
            }
        }

        if let Some(id) = self.confirm_delete {
            let title = self.store.session(id).map(|s| s.title.clone()).unwrap_or_default();
            let mut close = false;
            let mut delete = false;
            egui::Modal::new(egui::Id::new("delete")).show(ctx, |ui| {
                ui.set_width(400.0);
                ui.label(RichText::new("Delete session?").font(bold(17.0)).color(pal.text_strong));
                ui.label(RichText::new(format!("\"{title}\" and its messages will be removed. Files on disk are not touched.")).color(pal.text_base));
                ui.add_space(12.0);
                ui.horizontal(|ui| {
                    if ui.add(egui::Button::new(RichText::new("Delete").color(Color32::WHITE)).fill(pal.critical).min_size(Vec2::new(80.0, 32.0))).clicked() {
                        delete = true;
                    }
                    if ui.button("Cancel").clicked() || ui.input(|i| i.key_pressed(Key::Escape)) {
                        close = true;
                    }
                });
            });
            if delete {
                self.delete_session(id);
                close = true;
            }
            if close {
                self.confirm_delete = None;
            }
        }

        if self.settings_open {
            self.settings(ctx);
        }
        if self.palette.is_some() {
            self.palette_ui(ctx, t);
        }
    }

    fn settings(&mut self, ctx: &egui::Context) {
        let pal = self.pal;
        let mut close = false;
        let screen = ctx.content_rect();
        egui::Modal::new(egui::Id::new("settings")).show(ctx, |ui| {
            let size = Vec2::new(780.0_f32.min(screen.width() - 60.0), 540.0_f32.min(screen.height() - 80.0));
            ui.set_min_size(size);
            ui.set_max_size(size);
            ui.horizontal_top(|ui| {
                ui.vertical(|ui| {
                    ui.set_width(160.0);
                    ui.set_min_height(size.y);
                    ui.label(RichText::new("Settings").font(bold(17.0)).color(pal.text_strong));
                    ui.add_space(10.0);
                    for (tab, name) in [
                        (SettingsTab::General, "General"),
                        (SettingsTab::Models, "Models"),
                        (SettingsTab::Permissions, "Permissions"),
                        (SettingsTab::Shortcuts, "Shortcuts"),
                        (SettingsTab::About, "About"),
                    ] {
                        if list_row(ui, &pal, self.settings_tab == tab, 30.0, |ui| {
                            ui.label(RichText::new(name).color(pal.text_strong));
                        })
                        .clicked()
                        {
                            self.settings_tab = tab;
                        }
                    }
                    ui.with_layout(Layout::bottom_up(Align::Min), |ui| {
                        if primary_button(ui, &pal, "Done", 100.0).clicked() {
                            close = true;
                        }
                    });
                });
                ui.separator();
                ui.vertical(|ui| {
                    egui::ScrollArea::vertical().id_salt("settings-body").auto_shrink([false, false]).show(ui, |ui| {
                        ui.set_width(ui.available_width() - 12.0);
                        self.settings_body(ui);
                    });
                });
            });
            if ui.input(|i| i.key_pressed(Key::Escape)) {
                close = true;
            }
        });
        if close {
            self.settings_open = false;
            self.dirty = true;
            self.focus_composer = true;
        }
    }

    fn settings_body(&mut self, ui: &mut egui::Ui) {
        let pal = self.pal;
        let st = &mut self.store.settings;
        match self.settings_tab {
            SettingsTab::General => {
                heading(ui, &pal, "Appearance");
                setting_row(ui, &pal, "Color scheme", "Follow the system, or always light or dark", |ui| {
                    egui::ComboBox::from_id_salt("scheme")
                        .selected_text(match st.color_scheme {
                            Scheme::System => "System",
                            Scheme::Light => "Light",
                            Scheme::Dark => "Dark",
                        })
                        .show_ui(ui, |ui| {
                            ui.selectable_value(&mut st.color_scheme, Scheme::System, "System");
                            ui.selectable_value(&mut st.color_scheme, Scheme::Light, "Light");
                            ui.selectable_value(&mut st.color_scheme, Scheme::Dark, "Dark");
                        });
                });
                setting_row(ui, &pal, "Zoom", "Make text and controls larger across the app", |ui| {
                    egui::ComboBox::from_id_salt("zoom").selected_text(format!("{:.0}%", st.zoom * 100.0)).show_ui(ui, |ui| {
                        for z in [0.8_f32, 0.9, 1.0, 1.1, 1.25, 1.5] {
                            ui.selectable_value(&mut st.zoom, z, format!("{:.0}%", z * 100.0));
                        }
                    });
                });
                heading(ui, &pal, "General");
                setting_row(ui, &pal, "Terminal shell", "Used by shell mode and the assistant's commands. Empty = automatic", |ui| {
                    ui.add(egui::TextEdit::singleline(&mut st.shell).hint_text("Auto (Default)").desired_width(180.0));
                });
                setting_row(ui, &pal, "Auto-accept permissions", "Approve every permission request without asking", |ui| {
                    ui.checkbox(&mut st.auto_accept, "");
                });
                setting_row(ui, &pal, "Most steps per reply", "The assistant pauses after this many tool rounds", |ui| {
                    ui.add(egui::DragValue::new(&mut st.max_steps).range(1..=500));
                });
            }
            SettingsTab::Models => {
                heading(ui, &pal, "AI service");
                ui.label(
                    RichText::new("Any service that speaks the OpenAI chat format works: OpenAI, OpenRouter, Groq, a local Ollama or LM Studio, and others.")
                        .color(pal.text_base),
                );
                ui.add_space(6.0);
                setting_row(ui, &pal, "Service address", "Ends in /v1 for most services", |ui| {
                    ui.add(egui::TextEdit::singleline(&mut st.base_url).desired_width(260.0));
                });
                ui.horizontal(|ui| {
                    ui.label(RichText::new("Presets:").size(12.5).color(pal.text_weak));
                    for (name, url) in [
                        ("OpenAI", "https://api.openai.com/v1"),
                        ("OpenRouter", "https://openrouter.ai/api/v1"),
                        ("Ollama", "http://localhost:11434/v1"),
                        ("LM Studio", "http://localhost:1234/v1"),
                    ] {
                        if ui.small_button(name).clicked() {
                            st.base_url = url.into();
                        }
                    }
                });
                ui.add_space(4.0);
                let show = &mut self.show_key;
                setting_row(ui, &pal, "API key", "Kept on this computer only. Local services need none", |ui| {
                    if ui.small_button(if *show { "Hide" } else { "Show" }).clicked() {
                        *show = !*show;
                    }
                    ui.add(egui::TextEdit::singleline(&mut st.api_key).password(!*show).desired_width(220.0));
                });
                heading(ui, &pal, "Models");
                ui.label(RichText::new("One model name per line. The selected one answers new messages.").color(pal.text_base));
                if ui
                    .add(egui::TextEdit::multiline(&mut self.models_text).desired_rows(4).desired_width(f32::INFINITY).font(egui::TextStyle::Monospace))
                    .changed()
                {
                    st.models = self.models_text.lines().map(|l| l.trim().to_string()).filter(|l| !l.is_empty()).collect();
                    if !st.models.contains(&st.model) {
                        if let Some(first) = st.models.first() {
                            st.model = first.clone();
                        }
                    }
                }
                setting_row(ui, &pal, "Selected model", "", |ui| {
                    egui::ComboBox::from_id_salt("model").selected_text(st.model.clone()).show_ui(ui, |ui| {
                        for m in st.models.clone() {
                            ui.selectable_value(&mut st.model, m.clone(), m);
                        }
                    });
                });
                heading(ui, &pal, "Usage");
                setting_row(ui, &pal, "Input price ($ per million tokens)", "For the cost shown in the session header", |ui| {
                    ui.add(egui::DragValue::new(&mut st.price_in).speed(0.05).range(0.0..=1000.0));
                });
                setting_row(ui, &pal, "Output price ($ per million tokens)", "", |ui| {
                    ui.add(egui::DragValue::new(&mut st.price_out).speed(0.05).range(0.0..=1000.0));
                });
                setting_row(ui, &pal, "Context limit (tokens)", "What the ring in the session header measures against", |ui| {
                    ui.add(egui::DragValue::new(&mut st.context_limit).speed(1000).range(1000..=10_000_000));
                });
            }
            SettingsTab::Permissions => {
                heading(ui, &pal, "Permissions");
                ui.label(RichText::new("Choose what the assistant may do on its own, what it must ask about, and what it may never do.").color(pal.text_base));
                ui.add_space(6.0);
                for (name, desc, perm) in st.perms.rows() {
                    setting_row(ui, &pal, name, desc, |ui| {
                        for p in [Perm::Deny, Perm::Ask, Perm::Allow] {
                            ui.selectable_value(perm, p, p.label());
                        }
                    });
                }
            }
            SettingsTab::Shortcuts => {
                heading(ui, &pal, "Shortcuts");
                for (k, d) in [
                    ("Ctrl+T / Ctrl+N", "New session"),
                    ("Ctrl+W", "Close tab"),
                    ("Ctrl+Shift+T", "Reopen closed tab"),
                    ("Ctrl+[ / Ctrl+]", "Previous / next tab"),
                    ("Ctrl+K", "Search everything"),
                    ("Ctrl+F", "Search sessions (home)"),
                    ("Ctrl+O", "Add project"),
                    ("Ctrl+,", "Open settings"),
                    ("Ctrl+.", "Switch agent (Build / Plan)"),
                    ("Ctrl+'", "Next model"),
                    ("Ctrl+Shift+X", "Toggle shell mode (or type ! first)"),
                    ("Ctrl+Shift+R", "Toggle review pane"),
                    ("Ctrl+Shift+A", "Auto-accept permissions"),
                    ("Enter / Shift+Enter", "Send / new line"),
                    ("Esc", "Stop the assistant"),
                ] {
                    ui.horizontal(|ui| {
                        ui.add_sized(Vec2::new(170.0, 22.0), egui::Label::new(RichText::new(k).monospace().color(pal.text_strong)));
                        ui.label(RichText::new(d).color(pal.text_base));
                    });
                }
                heading(ui, &pal, "Commands in the message box");
                for (k, d) in [
                    ("/new", "Start a new session"),
                    ("/compact", "Summarize the session to save context"),
                    ("/undo", "Remove the last message and put it back in the box"),
                    ("/plan, /build", "Switch agent"),
                    ("/export", "Save the transcript to Downloads"),
                ] {
                    ui.horizontal(|ui| {
                        ui.add_sized(Vec2::new(170.0, 22.0), egui::Label::new(RichText::new(k).monospace().color(pal.text_strong)));
                        ui.label(RichText::new(d).color(pal.text_base));
                    });
                }
            }
            SettingsTab::About => {
                heading(ui, &pal, "About");
                ui.label(RichText::new("Codeloft 0.1").font(bold(15.0)).color(pal.text_strong));
                ui.label(
                    RichText::new("A desktop coding assistant: projects, sessions and an AI agent that reads, edits and runs commands in your project folder, with your permission.")
                        .color(pal.text_base),
                );
                ui.add_space(8.0);
                ui.label(RichText::new(format!("Data file: {}", crate::store::data_file().display())).size(12.0).color(pal.text_weak));
            }
        }
    }

    fn palette_ui(&mut self, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        let Some(mut p) = self.palette.take() else { return };
        let mut items: Vec<(String, String, Cmd)> = vec![
            ("New session".into(), "Ctrl+T".into(), Cmd::NewSession),
            ("Go home".into(), String::new(), Cmd::Home),
            ("Add project".into(), "Ctrl+O".into(), Cmd::AddProject),
            ("Open settings".into(), "Ctrl+,".into(), Cmd::Settings),
            ("Toggle review".into(), "Ctrl+Shift+R".into(), Cmd::ToggleReview),
            ("Toggle shell mode".into(), "Ctrl+Shift+X".into(), Cmd::ToggleShell),
            ("Cycle agent".into(), "Ctrl+.".into(), Cmd::CycleAgent),
            ("Auto-accept permissions".into(), "Ctrl+Shift+A".into(), Cmd::AutoAccept),
        ];
        if matches!(self.screen, Screen::Session(_)) {
            items.extend([
                ("Undo last message".to_string(), String::new(), Cmd::Undo),
                ("Compact session".into(), String::new(), Cmd::Compact),
                ("Rename session".into(), String::new(), Cmd::Rename),
                ("Export session".into(), String::new(), Cmd::Export),
                ("Delete session".into(), String::new(), Cmd::Delete),
                ("Close tab".into(), "Ctrl+W".into(), Cmd::CloseTab),
            ]);
        }
        for m in &self.store.settings.models {
            items.push((format!("Use model: {m}"), String::new(), Cmd::ChooseModel(m.clone())));
        }
        let mut sessions: Vec<&Session> = self.store.sessions.iter().filter(|s| !s.messages.is_empty()).collect();
        sessions.sort_by(|a, b| b.updated.cmp(&a.updated));
        for s in sessions.into_iter().take(200) {
            let pn = self.store.project(s.project_id).map(|p| p.name.clone()).unwrap_or_default();
            items.push((s.title.clone(), pn, Cmd::OpenSession(s.id)));
        }
        let q = p.query.to_lowercase();
        let filtered: Vec<(String, String, Cmd)> = items
            .into_iter()
            .filter(|(a, b, _)| q.is_empty() || a.to_lowercase().contains(&q) || b.to_lowercase().contains(&q))
            .collect();
        let mut chosen: Option<Cmd> = None;
        let mut close = false;
        let modal = egui::Modal::new(egui::Id::new("palette")).show(ctx, |ui| {
            ui.set_width(560.0);
            let r = ui.add(
                egui::TextEdit::singleline(&mut p.query)
                    .id_salt("palette-query")
                    .hint_text("Search commands and sessions")
                    .desired_width(f32::INFINITY),
            );
            r.request_focus();
            if r.changed() {
                p.selected = 0;
            }
            ui.input(|i| {
                if i.key_pressed(Key::ArrowDown) {
                    p.selected = (p.selected + 1).min(filtered.len().saturating_sub(1));
                }
                if i.key_pressed(Key::ArrowUp) {
                    p.selected = p.selected.saturating_sub(1);
                }
            });
            ui.add_space(6.0);
            egui::ScrollArea::vertical().max_height(360.0).show(ui, |ui| {
                for (i, (a, b, c)) in filtered.iter().enumerate() {
                    let sel = i == p.selected;
                    let resp = list_row(ui, &pal, sel, 30.0, |ui| {
                        ui.add(egui::Label::new(RichText::new(a).color(pal.text_strong)).truncate().selectable(false));
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            ui.label(RichText::new(b).size(12.5).color(pal.text_weak));
                        });
                    });
                    if sel && ui.input(|i| i.key_pressed(Key::ArrowDown) || i.key_pressed(Key::ArrowUp)) {
                        resp.scroll_to_me(None);
                    }
                    if resp.clicked() {
                        chosen = Some(c.clone());
                    }
                }
                if filtered.is_empty() {
                    ui.label(RichText::new("No results").color(pal.text_weak));
                }
            });
            if ui.input(|i| i.key_pressed(Key::Enter)) {
                if let Some((_, _, c)) = filtered.get(p.selected) {
                    chosen = Some(c.clone());
                }
            }
            if ui.input(|i| i.key_pressed(Key::Escape)) {
                close = true;
            }
        });
        if modal.should_close() {
            close = true;
        }
        if let Some(c) = chosen {
            self.run_cmd(c, ctx, t);
            close = true;
        }
        if !close {
            self.palette = Some(p);
        }
    }

    pub(super) fn toasts(&mut self, ctx: &egui::Context, t: f64) {
        self.toasts.retain(|(_, until)| *until > t);
        if self.toasts.is_empty() {
            return;
        }
        let pal = self.pal;
        egui::Area::new(egui::Id::new("toasts")).anchor(Align2::RIGHT_BOTTOM, Vec2::new(-20.0, -20.0)).show(ctx, |ui| {
            for (msg, _) in &self.toasts {
                egui::Frame::NONE
                    .fill(pal.primary_btn)
                    .corner_radius(8)
                    .inner_margin(egui::Margin::symmetric(14, 10))
                    .show(ui, |ui| {
                        ui.label(RichText::new(msg).color(pal.primary_text));
                    });
                ui.add_space(6.0);
            }
        });
        ctx.request_repaint_after(std::time::Duration::from_millis(250));
    }
}

input.content:
//! Modal windows: add project, rename, delete, settings, command palette; and toasts.

use super::*;
use crate::store::Perm;
use crate::theme::bold;
use eframe::egui::{Align, Align2, Color32, Layout, RichText};

impl App {
    pub(super) fn dialogs(&mut self, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        if let Some(mut path) = self.add_project.take() {
            let mut keep = true;
            let mut add = false;
            egui::Modal::new(egui::Id::new("addproj")).show(ctx, |ui| {
                ui.set_width(480.0);
                ui.label(RichText::new("Add project").font(bold(17.0)).color(pal.text_strong));
                ui.label(RichText::new("Pick the folder the assistant should work in.").color(pal.text_base));
                ui.add_space(10.0);
                ui.horizontal(|ui| {
                    let r = ui.add(egui::TextEdit::singleline(&mut path).hint_text("C:\\Users\\you\\my-project").desired_width(350.0));
                    if !r.has_focus() && path.is_empty() {
                        r.request_focus();
                    }
                    if r.lost_focus() && ui.input(|i| i.key_pressed(Key::Enter)) {
                        add = true;
                    }
                    if ui.button("Browse…").clicked() {
                        if let Some(p) = rfd::FileDialog::new().set_title("Choose a project folder").pick_folder() {
                            path = p.to_string_lossy().to_string();
                            add = true;
                        }
                    }
                });
                ui.add_space(12.0);
                ui.horizontal(|ui| {
                    if primary_button(ui, &pal, "Add project", 110.0).clicked() {
                        add = true;
                    }
                    if ui.button("Cancel").clicked() || ui.input(|i| i.key_pressed(Key::Escape)) {
                        keep = false;
                    }
                });
            });
            if add {
                self.add_project_path(&path, t);
                keep = false;
            }
            if keep {
                self.add_project = Some(path);
            }
        }

        if let Some((id, mut title)) = self.rename.take() {
            let mut keep = true;
            let mut save = false;
            egui::Modal::new(egui::Id::new("rename")).show(ctx, |ui| {
                ui.set_width(400.0);
                ui.label(RichText::new("Rename session").font(bold(17.0)).color(pal.text_strong));
                ui.add_space(8.0);
                let r = ui.add(egui::TextEdit::singleline(&mut title).id_salt("rename-field").desired_width(f32::INFINITY));
                if !r.has_focus() && !ui.memory(|m| m.focused().is_some()) {
                    r.request_focus();
                }
                if ui.input(|i| i.key_pressed(Key::Enter)) {
                    save = true;
                }
                ui.add_space(10.0);
                ui.horizontal(|ui| {
                    if primary_button(ui, &pal, "Save", 80.0).clicked() {
                        save = true;
                    }
                    if ui.button("Cancel").clicked() || ui.input(|i| i.key_pressed(Key::Escape)) {
                        keep = false;
                    }
                });
            });
            if save {
                if let Some(s) = self.store.session_mut(id) {
                    if !title.trim().is_empty() {
                        s.title = title.trim().to_string();
                    }
                }
                self.dirty = true;
                keep = false;
            }
            if keep {
                self.rename = Some((id, title));
            }
        }

        if let Some(id) = self.confirm_delete {
            let title = self.store.session(id).map(|s| s.title.clone()).unwrap_or_default();
            let mut close = false;
            let mut delete = false;
            egui::Modal::new(egui::Id::new("delete")).show(ctx, |ui| {
                ui.set_width(400.0);
                ui.label(RichText::new("Delete session?").font(bold(17.0)).color(pal.text_strong));
                ui.label(RichText::new(format!("\"{title}\" and its messages will be removed. Files on disk are not touched.")).color(pal.text_base));
                ui.add_space(12.0);
                ui.horizontal(|ui| {
                    if ui.add(egui::Button::new(RichText::new("Delete").color(Color32::WHITE)).fill(pal.critical).min_size(Vec2::new(80.0, 32.0))).clicked() {
                        delete = true;
                    }
                    if ui.button("Cancel").clicked() || ui.input(|i| i.key_pressed(Key::Escape)) {
                        close = true;
                    }
                });
            });
            if delete {
                self.delete_session(id);
                close = true;
            }
            if close {
                self.confirm_delete = None;
            }
        }

        if self.settings_open {
            self.settings(ctx);
        }
        if self.palette.is_some() {
            self.palette_ui(ctx, t);
        }
    }

    fn settings(&mut self, ctx: &egui::Context) {
        let pal = self.pal;
        let mut close = false;
        let screen = ctx.content_rect();
        egui::Modal::new(egui::Id::new("settings")).show(ctx, |ui| {
            let size = Vec2::new(780.0_f32.min(screen.width() - 60.0), 540.0_f32.min(screen.height() - 80.0));
            ui.set_min_size(size);
            ui.set_max_size(size);
            ui.horizontal_top(|ui| {
                ui.vertical(|ui| {
                    ui.set_width(160.0);
                    ui.set_min_height(size.y);
                    ui.label(RichText::new("Settings").font(bold(17.0)).color(pal.text_strong));
                    ui.add_space(10.0);
                    for (tab, name) in [
                        (SettingsTab::General, "General"),
                        (SettingsTab::Models, "Models"),
                        (SettingsTab::Permissions, "Permissions"),
                        (SettingsTab::Shortcuts, "Shortcuts"),
                        (SettingsTab::About, "About"),
                    ] {
                        if list_row(ui, &pal, self.settings_tab == tab, 30.0, |ui| {
                            ui.label(RichText::new(name).color(pal.text_strong));
                        })
                        .clicked()
                        {
                            self.settings_tab = tab;
                        }
                    }
                    ui.with_layout(Layout::bottom_up(Align::Min), |ui| {
                        if primary_button(ui, &pal, "Done", 100.0).clicked() {
                            close = true;
                        }
                    });
                });
                ui.separator();
                ui.vertical(|ui| {
                    egui::ScrollArea::vertical().id_salt("settings-body").auto_shrink([false, false]).show(ui, |ui| {
                        ui.set_width(ui.available_width() - 12.0);
                        self.settings_body(ui);
                    });
                });
            });
            if ui.input(|i| i.key_pressed(Key::Escape)) {
                close = true;
            }
        });
        if close {
            self.settings_open = false;
            self.dirty = true;
            self.focus_composer = true;
        }
    }

    fn settings_body(&mut self, ui: &mut egui::Ui) {
        let pal = self.pal;
        let st = &mut self.store.settings;
        match self.settings_tab {
            SettingsTab::General => {
                heading(ui, &pal, "Appearance");
                setting_row(ui, &pal, "Color scheme", "Follow the system, or always light or dark", |ui| {
                    egui::ComboBox::from_id_salt("scheme")
                        .selected_text(match st.color_scheme {
                            Scheme::System => "System",
                            Scheme::Light => "Light",
                            Scheme::Dark => "Dark",
                        })
                        .show_ui(ui, |ui| {
                            ui.selectable_value(&mut st.color_scheme, Scheme::System, "System");
                            ui.selectable_value(&mut st.color_scheme, Scheme::Light, "Light");
                            ui.selectable_value(&mut st.color_scheme, Scheme::Dark, "Dark");
                        });
                });
                setting_row(ui, &pal, "Zoom", "Make text and controls larger across the app", |ui| {
                    egui::ComboBox::from_id_salt("zoom").selected_text(format!("{:.0}%", st.zoom * 100.0)).show_ui(ui, |ui| {
                        for z in [0.8_f32, 0.9, 1.0, 1.1, 1.25, 1.5] {
                            ui.selectable_value(&mut st.zoom, z, format!("{:.0}%", z * 100.0));
                        }
                    });
                });
                heading(ui, &pal, "General");
                setting_row(ui, &pal, "Terminal shell", "Used by shell mode and the assistant's commands. Empty = automatic", |ui| {
                    ui.add(egui::TextEdit::singleline(&mut st.shell).hint_text("Auto (Default)").desired_width(180.0));
                });
                setting_row(ui, &pal, "Auto-accept permissions", "Approve every permission request without asking", |ui| {
                    ui.checkbox(&mut st.auto_accept, "");
                });
                setting_row(ui, &pal, "Most steps per reply", "The assistant pauses after this many tool rounds", |ui| {
                    ui.add(egui::DragValue::new(&mut st.max_steps).range(1..=500));
                });
            }
            SettingsTab::Models => {
                heading(ui, &pal, "AI service");
                ui.label(
                    RichText::new("Any service that speaks the OpenAI chat format works: OpenAI, OpenRouter, Groq, a local Ollama or LM Studio, and others.")
                        .color(pal.text_base),
                );
                ui.add_space(6.0);
                setting_row(ui, &pal, "Service address", "Ends in /v1 for most services", |ui| {
                    ui.add(egui::TextEdit::singleline(&mut st.base_url).desired_width(260.0));
                });
                ui.horizontal(|ui| {
                    ui.label(RichText::new("Presets:").size(12.5).color(pal.text_weak));
                    for (name, url) in [
                        ("OpenAI", "https://api.openai.com/v1"),
                        ("OpenRouter", "https://openrouter.ai/api/v1"),
                        ("Ollama", "http://localhost:11434/v1"),
                        ("LM Studio", "http://localhost:1234/v1"),
                    ] {
                        if ui.small_button(name).clicked() {
                            st.base_url = url.into();
                        }
                    }
                });
                ui.add_space(4.0);
                let show = &mut self.show_key;
                setting_row(ui, &pal, "API key", "Kept on this computer only. Local services need none", |ui| {
                    if ui.small_button(if *show { "Hide" } else { "Show" }).clicked() {
                        *show = !*show;
                    }
                    ui.add(egui::TextEdit::singleline(&mut st.api_key).password(!*show).desired_width(220.0));
                });
                heading(ui, &pal, "Models");
                ui.label(RichText::new("One model name per line. The selected one answers new messages.").color(pal.text_base));
                if ui
                    .add(egui::TextEdit::multiline(&mut self.models_text).desired_rows(4).desired_width(f32::INFINITY).font(egui::TextStyle::Monospace))
                    .changed()
                {
                    st.models = self.models_text.lines().map(|l| l.trim().to_string()).filter(|l| !l.is_empty()).collect();
                    if !st.models.contains(&st.model) {
                        if let Some(first) = st.models.first() {
                            st.model = first.clone();
                        }
                    }
                }
                setting_row(ui, &pal, "Selected model", "", |ui| {
                    egui::ComboBox::from_id_salt("model").selected_text(st.model.clone()).show_ui(ui, |ui| {
                        for m in st.models.clone() {
                            ui.selectable_value(&mut st.model, m.clone(), m);
                        }
                    });
                });
                heading(ui, &pal, "Usage");
                setting_row(ui, &pal, "Input price ($ per million tokens)", "For the cost shown in the session header", |ui| {
                    ui.add(egui::DragValue::new(&mut st.price_in).speed(0.05).range(0.0..=1000.0));
                });
                setting_row(ui, &pal, "Output price ($ per million tokens)", "", |ui| {
                    ui.add(egui::DragValue::new(&mut st.price_out).speed(0.05).range(0.0..=1000.0));
                });
                setting_row(ui, &pal, "Context limit (tokens)", "What the ring in the session header measures against", |ui| {
                    ui.add(egui::DragValue::new(&mut st.context_limit).speed(1000).range(1000..=10_000_000));
                });
            }
            SettingsTab::Permissions => {
                heading(ui, &pal, "Permissions");
                ui.label(RichText::new("Choose what the assistant may do on its own, what it must ask about, and what it may never do.").color(pal.text_base));
                ui.add_space(6.0);
                for (name, desc, perm) in st.perms.rows() {
                    setting_row(ui, &pal, name, desc, |ui| {
                        for p in [Perm::Deny, Perm::Ask, Perm::Allow] {
                            ui.selectable_value(perm, p, p.label());
                        }
                    });
                }
            }
            SettingsTab::Shortcuts => {
                heading(ui, &pal, "Shortcuts");
                for (k, d) in [
                    ("Ctrl+T / Ctrl+N", "New session"),
                    ("Ctrl+W", "Close tab"),
                    ("Ctrl+Shift+T", "Reopen closed tab"),
                    ("Ctrl+[ / Ctrl+]", "Previous / next tab"),
                    ("Ctrl+K", "Search everything"),
                    ("Ctrl+F", "Search sessions (home)"),
                    ("Ctrl+O", "Add project"),
                    ("Ctrl+,", "Open settings"),
                    ("Ctrl+.", "Switch agent (Build / Plan)"),
                    ("Ctrl+'", "Next model"),
                    ("Ctrl+Shift+X", "Toggle shell mode (or type ! first)"),
                    ("Ctrl+Shift+R", "Toggle review pane"),
                    ("Ctrl+Shift+A", "Auto-accept permissions"),
                    ("Enter / Shift+Enter", "Send / new line"),
                    ("Esc", "Stop the assistant"),
                ] {
                    ui.horizontal(|ui| {
                        ui.add_sized(Vec2::new(170.0, 22.0), egui::Label::new(RichText::new(k).monospace().color(pal.text_strong)));
                        ui.label(RichText::new(d).color(pal.text_base));
                    });
                }
                heading(ui, &pal, "Commands in the message box");
                for (k, d) in [
                    ("/new", "Start a new session"),
                    ("/compact", "Summarize the session to save context"),
                    ("/undo", "Remove the last message and put it back in the box"),
                    ("/plan, /build", "Switch agent"),
                    ("/export", "Save the transcript to Downloads"),
                ] {
                    ui.horizontal(|ui| {
                        ui.add_sized(Vec2::new(170.0, 22.0), egui::Label::new(RichText::new(k).monospace().color(pal.text_strong)));
                        ui.label(RichText::new(d).color(pal.text_base));
                    });
                }
            }
            SettingsTab::About => {
                heading(ui, &pal, "About");
                ui.label(RichText::new("Codeloft 0.1").font(bold(15.0)).color(pal.text_strong));
                ui.label(
                    RichText::new("A desktop coding assistant: projects, sessions and an AI agent that reads, edits and runs commands in your project folder, with your permission.")
                        .color(pal.text_base),
                );
                ui.add_space(8.0);
                ui.label(RichText::new(format!("Data file: {}", crate::store::data_file().display())).size(12.0).color(pal.text_weak));
            }
        }
    }

    fn palette_ui(&mut self, ctx: &egui::Context, t: f64) {
        let pal = self.pal;
        let Some(mut p) = self.palette.take() else { return };
        let mut items: Vec<(String, String, Cmd)> = vec![
            ("New session".into(), "Ctrl+T".into(), Cmd::NewSession),
            ("Go home".into(), String::new(), Cmd::Home),
            ("Add project".into(), "Ctrl+O".into(), Cmd::AddProject),
            ("Open settings".into(), "Ctrl+,".into(), Cmd::Settings),
            ("Toggle review".into(), "Ctrl+Shift+R".into(), Cmd::ToggleReview),
            ("Toggle shell mode".into(), "Ctrl+Shift+X".into(), Cmd::ToggleShell),
            ("Cycle agent".into(), "Ctrl+.".into(), Cmd::CycleAgent),
            ("Auto-accept permissions".into(), "Ctrl+Shift+A".into(), Cmd::AutoAccept),
        ];
        if matches!(self.screen, Screen::Session(_)) {
            items.extend([
                ("Undo last message".to_string(), String::new(), Cmd::Undo),
                ("Compact session".into(), String::new(), Cmd::Compact),
                ("Rename session".into(), String::new(), Cmd::Rename),
                ("Export session".into(), String::new(), Cmd::Export),
                ("Delete session".into(), String::new(), Cmd::Delete),
                ("Close tab".into(), "Ctrl+W".into(), Cmd::CloseTab),
            ]);
        }
        for m in &self.store.settings.models {
            items.push((format!("Use model: {m}"), String::new(), Cmd::ChooseModel(m.clone())));
        }
        let mut sessions: Vec<&Session> = self.store.sessions.iter().filter(|s| !s.messages.is_empty()).collect();
        sessions.sort_by(|a, b| b.updated.cmp(&a.updated));
        for s in sessions.into_iter().take(200) {
            let pn = self.store.project(s.project_id).map(|p| p.name.clone()).unwrap_or_default();
            items.push((s.title.clone(), pn, Cmd::OpenSession(s.id)));
        }
        let q = p.query.to_lowercase();
        let filtered: Vec<(String, String, Cmd)> = items
            .into_iter()
            .filter(|(a, b, _)| q.is_empty() || a.to_lowercase().contains(&q) || b.to_lowercase().contains(&q))
            .collect();
        let mut chosen: Option<Cmd> = None;
        let mut close = false;
        let modal = egui::Modal::new(egui::Id::new("palette")).show(ctx, |ui| {
            ui.set_width(560.0);
            let r = ui.add(
                egui::TextEdit::singleline(&mut p.query)
                    .id_salt("palette-query")
                    .hint_text("Search commands and sessions")
                    .desired_width(f32::INFINITY),
            );
            r.request_focus();
            if r.changed() {
                p.selected = 0;
            }
            ui.input(|i| {
                if i.key_pressed(Key::ArrowDown) {
                    p.selected = (p.selected + 1).min(filtered.len().saturating_sub(1));
                }
                if i.key_pressed(Key::ArrowUp) {
                    p.selected = p.selected.saturating_sub(1);
                }
            });
            ui.add_space(6.0);
            egui::ScrollArea::vertical().max_height(360.0).show(ui, |ui| {
                for (i, (a, b, c)) in filtered.iter().enumerate() {
                    let sel = i == p.selected;
                    let resp = list_row(ui, &pal, sel, 30.0, |ui| {
                        ui.add(egui::Label::new(RichText::new(a).color(pal.text_strong)).truncate().selectable(false));
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            ui.label(RichText::new(b).size(12.5).color(pal.text_weak));
                        });
                    });
                    if sel && ui.input(|i| i.key_pressed(Key::ArrowDown) || i.key_pressed(Key::ArrowUp)) {
                        resp.scroll_to_me(None);
                    }
                    if resp.clicked() {
                        chosen = Some(c.clone());
                    }
                }
                if filtered.is_empty() {
                    ui.label(RichText::new("No results").color(pal.text_weak));
                }
            });
            if ui.input(|i| i.key_pressed(Key::Enter)) {
                if let Some((_, _, c)) = filtered.get(p.selected) {
                    chosen = Some(c.clone());
                }
            }
            if ui.input(|i| i.key_pressed(Key::Escape)) {
                close = true;
            }
        });
        if modal.should_close() {
            close = true;
        }
        if let Some(c) = chosen {
            self.run_cmd(c, ctx, t);
            close = true;
        }
        if !close {
            self.palette = Some(p);
        }
    }

    pub(super) fn toasts(&mut self, ctx: &egui::Context, t: f64) {
        self.toasts.retain(|(_, until)| *until > t);
        if self.toasts.is_empty() {
            return;
        }
        let pal = self.pal;
        egui::Area::new(egui::Id::new("toasts")).anchor(Align2::RIGHT_BOTTOM, Vec2::new(-20.0, -20.0)).show(ctx, |ui| {
            for (msg, _) in &self.toasts {
                egui::Frame::NONE
                    .fill(pal.primary_btn)
                    .corner_radius(8)
                    .inner_margin(egui::Margin::symmetric(14, 10))
                    .show(ui, |ui| {
                        ui.label(RichText::new(msg).color(pal.primary_text));
                    });
                ui.add_space(6.0);
            }
        });
        ctx.request_repaint_after(std::time::Duration::from_millis(250));
    }
}

