#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]
//! Codeloft: a desktop coding assistant. Projects, sessions, and an AI agent
//! that reads, edits and runs commands in your project, with your permission.
//!
//! `--screenshot <file.png>` starts normally, draws about 120 frames, saves the
//! window as a PNG and exits (without taking focus).

mod agent;
mod app;
mod markdown;
mod store;
mod theme;

use eframe::egui;

fn main() -> eframe::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let screenshot = args
        .iter()
        .position(|a| a == "--screenshot")
        .and_then(|i| args.get(i + 1))
        .map(std::path::PathBuf::from);

    let mut viewport = egui::ViewportBuilder::default()
        .with_title("Codeloft")
        .with_inner_size([1440.0, 860.0])
        .with_min_inner_size([760.0, 480.0]);
    let mut options = eframe::NativeOptions::default();
    if screenshot.is_some() {
        viewport = viewport.with_active(false);
        #[cfg(windows)]
        {
            viewport = viewport.with_window_level(egui::WindowLevel::AlwaysOnBottom);
        }
        #[cfg(target_os = "macos")]
        {
            options.event_loop_builder = Some(Box::new(|builder| {
                use winit::platform::macos::EventLoopBuilderExtMacOS;
                builder.with_activate_ignoring_other_apps(false);
            }));
        }
        // Keep drawing while unfocused or covered.
        options.run_and_return = true;
    }
    options.viewport = viewport;
    eframe::run_native("Codeloft", options, Box::new(move |cc| Ok(Box::new(app::App::new(cc, screenshot)))))
}

