        if !para.trim().is_empty() {
            ui.label(inline(pal, para.trim(), 14.0, pal.text_strong));
            ui.add_space(6.0);
        }
        para.clear();
    };
    let mut table: Vec<Vec<String>> = vec![];
    let flush_table = |ui: &mut egui::Ui, table: &mut Vec<Vec<String>>| {
        if table.is_empty() {
            return;
        }
        let cols = table.iter().map(|r| r.len()).max().unwrap_or(0);
        egui::Frame::NONE
            .stroke(egui::Stroke::new(1.0, pal.border_weak))
            .corner_radius(6)
            .show(ui, |ui| {
                egui::Grid::new(ui.next_auto_id()).striped(false).spacing([28.0, 0.0]).min_col_width(40.0).show(ui, |ui| {
                    for (ri, row) in table.iter().enumerate() {
                        for c in 0..cols {
                            let cell = row.get(c).map(|s| s.as_str()).unwrap_or("");
                            ui.add_space(4.0);
                            let col = if ri == 0 { pal.text_strong } else { pal.text_strong };
                            let mut job = inline(pal, cell, 14.0, col);
                            if ri == 0 {
                                for s in job.sections.iter_mut() {
                                    s.format.font_id = bold(14.0);
                                }
                            }
                            egui::Frame::NONE.inner_margin(egui::Margin::symmetric(8, 8)).show(ui, |ui| ui.label(job));
                        }
                        ui.end_row();
                    }
                });
            });
        ui.add_space(8.0);
        table.clear();
    };

    for line in text.lines() {
        let t = line.trim_start();
        if t.starts_with("```") {
            if in_code {
                code_block(ui, pal, &code);
                code.clear();
                in_code = false;
            } else {
                flush(ui, &mut para);
                flush_table(ui, &mut table);
                in_code = true;
            }
            continue;
        }
        if in_code {
            code.push_str(line);
            code.push('\n');
            continue;
        }
        if t.starts_with('|') && t.ends_with('|') && t.len() > 1 {
            flush(ui, &mut para);
            let cells: Vec<String> = t[1..t.len() - 1].split('|').map(|c| c.trim().to_string()).collect();
            let separator = cells.iter().all(|c| !c.is_empty() && c.chars().all(|ch| ch == '-' || ch == ':'));
            if !separator {
                table.push(cells);
            }
            continue;
        } else {
            flush_table(ui, &mut table);
        }
        if t.is_empty() {
            flush(ui, &mut para);
            continue;
        }
        let hashes = t.chars().take_while(|c| *c == '#').count();
        if hashes > 0 && hashes <= 6 && t[hashes..].starts_with(' ') {
            flush(ui, &mut para);
            let size = match hashes {
                1 => 20.0,
                2 => 17.0,
                _ => 15.0,
            };
            ui.add_space(4.0);
            ui.label(egui::RichText::new(t[hashes..].trim()).font(bold(size)).color(pal.text_strong));
            ui.add_space(4.0);
            continue;
        }
        let bullet = (t.starts_with("- ") || t.starts_with("* ") || t.starts_with("+ ")).then(|| &t[2..]);
        let numbered = {
            let digits = t.chars().take_while(|c| c.is_ascii_digit()).count();
            (digits > 0 && t[digits..].starts_with(". ")).then(|| (&t[..digits], &t[digits + 2..]))
        };
        if bullet.is_some() || numbered.is_some() {
            flush(ui, &mut para);
            in_list = true;
            let indent = (line.len() - t.len()) as f32 * 4.0;
            let (mark, body) = match (bullet, numbered) {
                (Some(b), _) => ("•".to_string(), b),
                (None, Some((n, b))) => (format!("{n}."), b),
                _ => unreachable!(),
            };
            ui.horizontal_top(|ui| {
                ui.add_space(4.0 + indent);
                ui.label(egui::RichText::new(mark).color(pal.text_base));
                ui.add(egui::Label::new(inline(pal, body, 14.0, pal.text_strong)).wrap());
            });
            continue;
        }
        if in_list {
            ui.add_space(6.0);
            in_list = false;
        }
        if !para.is_empty() {
            para.push(' ');
        }
        para.push_str(t);
    }
    if in_code {
        code_block(ui, pal, &code);
    }
    flush_table(ui, &mut table);
    flush(ui, &mut para);
}

pub fn code_block(ui: &mut egui::Ui, pal: &Pal, code: &str) {
    egui::Frame::NONE
        .fill(pal.code_bg)
        .corner_radius(6)
        .inner_margin(egui::Margin::symmetric(12, 10))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            ui.add(egui::Label::new(egui::RichText::new(code.trim_end()).monospace().color(pal.text_strong)).wrap());
        });
    ui.add_space(8.0);
}

/// Inline formatting inside one paragraph.
pub fn inline(pal: &Pal, text: &str, size: f32, color: Color32) -> LayoutJob {
    let mut job = LayoutJob::default();
    let normal = TextFormat { font_id: FontId::proportional(size), color, ..Default::default() };
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;
    let mut buf = String::new();
    let mut is_bold = false;
    let mut italic = false;
    let push = |job: &mut LayoutJob, buf: &mut String, b: bool, it: bool| {
        if buf.is_empty() {
            return;
        }
        let mut f = normal.clone();
        if b {
            f.font_id = bold(size);
        }
        f.italics = it;
        job.append(buf, 0.0, f);
        buf.clear();
    };
    while i < chars.len() {
        let c = chars[i];
        if c == '`' {
            if let Some(end) = chars[i + 1..].iter().position(|x| *x == '`') {
                push(&mut job, &mut buf, is_bold, italic);
                let code: String = chars[i + 1..i + 1 + end].iter().collect();
                job.append(
                    &code,
                    2.0,
                    TextFormat {
                        font_id: FontId::monospace(size - 0.5),
                        color,
                        background: pal.code_bg,
                        ..Default::default()
                    },
                );
                i += end + 2;
                continue;
            }
        }
        if c == '*' && i + 1 < chars.len() && chars[i + 1] == '*' {
            push(&mut job, &mut buf, is_bold, italic);
            is_bold = !is_bold;
            i += 2;
            continue;
        }
        if (c == '*' || c == '_') && i + 1 < chars.len() && !chars[i + 1].is_whitespace() && (i == 0 || !chars[i - 1].is_alphanumeric()) {
            if chars[i + 1..].iter().any(|x| *x == c) {
                push(&mut job, &mut buf, is_bold, italic);
                italic = !italic;
                i += 1;
                continue;
            }
        }
        if (c == '*' || c == '_') && italic && (i + 1 == chars.len() || !chars[i + 1].is_alphanumeric()) {
            push(&mut job, &mut buf, is_bold, italic);
            italic = false;
            i += 1;
            continue;
        }
        if c == '[' {
            // [label](url) shows just the label, in link colour
            if let Some(close) = chars[i..].iter().position(|x| *x == ']') {
                let after = i + close + 1;
                if after < chars.len() && chars[after] == '(' {
                    if let Some(end) = chars[after..].iter().position(|x| *x == ')') {
                        push(&mut job, &mut buf, is_bold, italic);
                        let label: String = chars[i + 1..i + close].iter().collect();
                        let mut f = normal.clone();
                        f.color = pal.interactive;
                        job.append(&label, 0.0, f);
                        i = after + end + 1;
                        continue;
                    }
                }
            }
        }
        buf.push(c);
        i += 1;
    }
    push(&mut job, &mut buf, is_bold, italic);
    job.wrap.max_width = f32::INFINITY;
    job
}

