    fn agent_loop_reads_edits_and_asks_permission() {
        let d = tmpdir("loop");
        let (url, server) = mock_service(vec![
            call("c1", "read", json!({"filePath":"README.md"})),
            call("c2", "edit", json!({"filePath":"README.md","oldString":"world","newString":"agent"})),
            call("c3", "bash", json!({"command":"echo done"})),
            json!({"choices":[{"message":{"role":"assistant","content":"All done."}}],"usage":{"prompt_tokens":200,"completion_tokens":5}}),
        ]);
        let cfg = RunConfig {
            base_url: url,
            api_key: "k".into(),
            model: "m".into(),
            agent: "build".into(),
            project_dir: d.clone(),
            perms: Perms::default(),
            auto_accept: false,
            always: HashSet::new(),
            shell: String::new(),
            max_steps: 10,
            compact: false,
        };
        let history = vec![Message::new(Role::User, "change world to agent")];
        let (tx, rx) = channel();
        let cancel = AtomicBool::new(false);
        let t = std::thread::spawn(move || {
            let send = move |e: AgentEvent| {
                let _ = tx.send(e);
            };
            run_loop(cfg, history, &cancel, &send)
        });
        let mut texts = vec![];
        let mut perms = 0;
        let mut results = vec![];
        let mut usage = 0;
        let mut changed = vec![];
        while let Ok(e) = rx.recv_timeout(Duration::from_secs(20)) {
            match e {
                AgentEvent::Permission(p) => {
                    perms += 1;
                    p.reply.send(PermReply::Once).unwrap();
                }
                AgentEvent::Assistant { text, .. } => texts.push(text),
                AgentEvent::ToolResult { name, ok, .. } => results.push((name, ok)),
                AgentEvent::Usage { prompt, .. } => usage += prompt,
                AgentEvent::FileChanged(f) => changed.push(f),
                _ => {}
            }
        }
        t.join().unwrap().unwrap();
        let seen = server.join().unwrap();
        assert_eq!(perms, 2, "edit and bash ask; read doesn't");
        assert_eq!(results, vec![("read".into(), true), ("edit".into(), true), ("bash".into(), true)]);
        assert_eq!(texts.last().unwrap(), "All done.");
        assert_eq!(usage, 500);
        assert_eq!(changed, vec!["README.md".to_string()]);
        assert_eq!(std::fs::read_to_string(d.join("README.md")).unwrap(), "hello agent\n");
        // the last request carries the whole tool conversation
        let msgs = seen[3]["messages"].as_array().unwrap();
        assert_eq!(msgs[0]["role"], "system");
        assert_eq!(msgs.iter().filter(|m| m["role"] == "tool").count(), 3);
        assert!(seen[0]["tools"].as_array().unwrap().iter().any(|t| t["function"]["name"] == "edit"));
    }

    #[test]
    fn plan_agent_has_no_edit_tools_and_wire_closes_open_calls() {
        let names: Vec<String> = tool_specs("plan").as_array().unwrap().iter().map(|t| t["function"]["name"].as_str().unwrap().to_string()).collect();
        assert!(!names.contains(&"edit".to_string()) && !names.contains(&"write".to_string()));
        let mut a = Message::new(Role::Assistant, "");
        a.tool_calls = vec![ToolCall { id: "x".into(), name: "read".into(), args: "{}".into() }];
        let wire = to_wire(&[Message::new(Role::User, "hi"), a, Message::new(Role::User, "again")]);
        assert_eq!(wire[2]["role"], "tool");
        assert_eq!(wire[3]["role"], "user");
    }
}
