//! Ready-made AI services. The default needs no key at all; the local ones
//! run on this computer with no key and no limits; the rest have free keys.

use serde_json::Value;
use std::time::Duration;

pub struct Preset {
    pub name: &'static str,
    pub url: &'static str,
    pub models: &'static [&'static str],
    /// none, free or paid
    pub key: &'static str,
    pub note: &'static str,
    pub key_page: &'static str,
}

pub const FREE_NO_KEY_URL: &str = "https://text.pollinations.ai/openai";

pub const PRESETS: &[Preset] = &[
    Preset {
        name: "Free (no key)",
        url: FREE_NO_KEY_URL,
        models: &["openai", "openai-fast"],
        key: "none",
        note: "Works right away. No account, no key, no message limit (a shared public service, so it can be slow when busy).",
        key_page: "",
    },
    Preset {
        name: "Ollama (on this computer)",
        url: "http://localhost:11434/v1",
        models: &["qwen2.5-coder:7b", "llama3.1:8b"],
        key: "none",
        note: "Unlimited and private: runs on your own computer. Install Ollama, then e.g. `ollama pull qwen2.5-coder:7b`, and press Refresh models.",
        key_page: "https://ollama.com/download",
    },
    Preset {
        name: "LM Studio (on this computer)",
        url: "http://localhost:1234/v1",
        models: &["local-model"],
        key: "none",
        note: "Unlimited and private. Start LM Studio's local server, then press Refresh models.",
        key_page: "https://lmstudio.ai",
    },
    Preset {
        name: "Google Gemini (free key)",
        url: "https://generativelanguage.googleapis.com/v1beta/openai",
        models: &["gemini-2.5-flash", "gemini-2.5-flash-lite", "gemini-2.5-pro"],
        key: "free",
        note: "Free key from Google AI Studio, with a generous daily allowance.",
        key_page: "https://aistudio.google.com/apikey",
    },
    Preset {
        name: "Groq (free key)",
        url: "https://api.groq.com/openai/v1",
        models: &["llama-3.3-70b-versatile", "openai/gpt-oss-120b", "qwen/qwen3-32b"],
        key: "free",
        note: "Free key, very fast, with per-minute limits (the app waits and retries).",
        key_page: "https://console.groq.com/keys",
    },
    Preset {
        name: "OpenRouter (free models)",
        url: "https://openrouter.ai/api/v1",
        models: &["openai/gpt-oss-20b:free", "qwen/qwen3-coder:free", "deepseek/deepseek-chat-v3-0324:free"],
        key: "free",
        note: "Free key; models ending in :free cost nothing.",
        key_page: "https://openrouter.ai/keys",
    },
    Preset {
        name: "OpenAI (paid key)",
        url: "https://api.openai.com/v1",
        models: &["gpt-4.1-mini", "gpt-4.1", "gpt-4o"],
        key: "paid",
        note: "Paid key from OpenAI.",
        key_page: "https://platform.openai.com/api-keys",
    },
];

pub fn preset_for(url: &str) -> Option<&'static Preset> {
    let u = url.trim().trim_end_matches('/');
    PRESETS.iter().find(|p| p.url == u)
}

/// Ask a service which models it has (`GET {base}/models`, OpenAI format;
/// Ollama's own list as a fallback). Runs on the caller's thread.
pub fn fetch_models(base: &str, key: &str) -> Result<Vec<String>, String> {
    let base = base.trim().trim_end_matches('/');
    let mut urls = vec![format!("{base}/models")];
    if base.ends_with("/v1") {
        urls.push(format!("{}/api/tags", base.trim_end_matches("/v1")));
    }
    if base == FREE_NO_KEY_URL {
        urls.insert(0, "https://text.pollinations.ai/models".into());
    }
    let mut last = String::from("no answer");
    for url in urls {
        let mut req = ureq::get(&url).config().timeout_global(Some(Duration::from_secs(8))).http_status_as_error(false).build();
        if !key.trim().is_empty() {
            req = req.header("Authorization", &format!("Bearer {}", key.trim()));
        }
        match req.call() {
            Ok(mut r) if r.status().as_u16() < 400 => {
                let v: Value = match r.body_mut().read_json() {
                    Ok(v) => v,
                    Err(e) => {
                        last = e.to_string();
                        continue;
                    }
                };
                let mut out: Vec<String> = vec![];
                let arr = v["data"].as_array().or(v["models"].as_array()).or(v.as_array()).cloned().unwrap_or_default();
                for m in arr {
                    let tools_ok = m["tools"].as_bool().unwrap_or(true);
                    if let Some(id) = m["id"].as_str().or(m["name"].as_str()).or(m["model"].as_str()).or(m.as_str()) {
                        if tools_ok && !id.contains("embed") && !id.contains("whisper") && !id.contains("tts") {
                            out.push(id.to_string());
                        }
                    }
                }
                if !out.is_empty() {
                    return Ok(out);
                }
                last = "the service listed no models".into();
            }
            Ok(r) => last = format!("the service answered {}", r.status().as_u16()),
            Err(e) => last = e.to_string(),
        }
    }
    Err(format!("Couldn't get the model list: {last}"))
}

/// Whether a local service (Ollama or LM Studio) is running, with its models.
pub fn detect_local() -> Option<(&'static Preset, Vec<String>)> {
    for p in PRESETS.iter().filter(|p| p.url.starts_with("http://localhost")) {
        if let Ok(models) = fetch_models(p.url, "") {
            return Some((p, models));
        }
    }
    None
}

