#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Settings {
    pub base_url: String,
    pub api_key: String,
    pub models: Vec<String>,
    pub model: String,
    pub color_scheme: Scheme,
    pub zoom: f32,
    pub shell: String,
    pub auto_accept: bool,
    pub perms: Perms,
    /// Dollars per million input / output tokens, for the cost shown in the header.
    pub price_in: f64,
    pub price_out: f64,
    pub context_limit: u64,
    pub max_steps: u32,
}

impl Default for Settings {
    fn default() -> Self {
        Self {
            base_url: "https://api.openai.com/v1".into(),
            api_key: String::new(),
            models: vec!["gpt-4.1-mini".into(), "gpt-4.1".into(), "gpt-4o".into()],
            model: "gpt-4.1-mini".into(),
            color_scheme: Scheme::System,
            zoom: 1.0,
            shell: String::new(),
            auto_accept: false,
            perms: Perms::default(),
            price_in: 0.0,
            price_out: 0.0,
            context_limit: 128_000,
            max_steps: 50,
        }
    }
}

#[derive(Serialize, Deserialize, Clone, Debug, Default)]
pub struct Store {
    pub projects: Vec<Project>,
    pub sessions: Vec<Session>,
    #[serde(default)]
    pub settings: Settings,
    #[serde(default)]
    pub open_tabs: Vec<u64>,
    #[serde(default)]
    pub active_tab: Option<u64>,
    #[serde(default)]
    pub closed_tabs: Vec<u64>,
    #[serde(default)]
    pub next_id: u64,
}

pub fn data_file() -> PathBuf {
    let base = dirs::data_dir().unwrap_or_else(|| PathBuf::from("."));
    base.join("Codeloft").join("state.json")
}

impl Store {
    pub fn load() -> Self {
        let path = data_file();
        let mut store = std::fs::read_to_string(&path)
            .ok()
            .and_then(|t| serde_json::from_str::<Store>(&t).ok())
            .unwrap_or_else(Store::first_run);
        store.open_tabs.retain(|id| store.sessions.iter().any(|s| s.id == *id));

