new='''/// Waits between retries when a service is busy or rate-limited, in seconds.
pub const RETRY_WAITS: &[u64] = &[2, 4, 8, 15, 30, 30, 60, 60];

struct ChatError {
    msg: String,
    retry: bool,
    wait: Option<u64>,
}

fn chat_once(cfg: &RunConfig, body: &Value) -> Result<Value, ChatError> {
    let url = format!("{}/chat/completions", cfg.base_url.trim().trim_end_matches('/'));
    let mut req = ureq::post(&url)
        .config()
        .http_status_as_error(false)
        .timeout_global(Some(Duration::from_secs(600)))
        .build()
        .header("Content-Type", "application/json");
    if !cfg.api_key.trim().is_empty() {
        req = req.header("Authorization", &format!("Bearer {}", cfg.api_key.trim()));
    }
    let mut resp = req
        .send_json(body)
        .map_err(|e| ChatError { msg: format!("Couldn't reach the AI service: {e}"), retry: true, wait: None })?;
    let status = resp.status().as_u16();
    let wait = resp
        .headers()
        .get("retry-after")
        .and_then(|v| v.to_str().ok())
        .and_then(|v| v.trim().parse::<f64>().ok())
        .map(|v| v.ceil().clamp(1.0, 120.0) as u64);
    let text = resp
        .body_mut()
        .read_to_string()
        .map_err(|e| ChatError { msg: format!("Couldn't read the answer: {e}"), retry: true, wait: None })?;
    if status >= 400 {
        let msg = serde_json::from_str::<Value>(&text)
            .ok()
            .and_then(|v| v["error"]["message"].as_str().or(v["error"].as_str()).or(v["message"].as_str()).map(String::from))
            .unwrap_or_else(|| text.chars().take(400).collect());
        let hint = match status {
            401 | 403 if cfg.api_key.trim().is_empty() => " This service needs a key: add one in Settings → Models, or pick \\"Free (no key)\\" there.",
            401 | 403 => " Check the key in Settings → Models.",
            _ => "",
        };
        return Err(ChatError {
            msg: format!("The AI service answered {status}: {msg}{hint}"),
            retry: status == 408 || status == 409 || status == 425 || status == 429 || status >= 500,
            wait,
        });
    }
    serde_json::from_str(&text).map_err(|e| ChatError { msg: format!("The answer wasn't readable ({e})"), retry: true, wait: None })
}

/// One chat request. When the service is busy or rate-limited (free tiers often are),
/// wait and try again instead of giving up, so free services keep working.
fn chat(cfg: &RunConfig, messages: &[Value], tools: Option<&Value>, cancel: &AtomicBool, send: &dyn Fn(AgentEvent)) -> Result<Value, String> {
    if cfg.base_url.trim().is_empty() {
        return Err("No AI service is set. Open Settings → Models and pick one (\\"Free (no key)\\" needs nothing).".into());
    }
    let mut body = json!({"model": cfg.model, "messages": messages});
    if let Some(t) = tools {
        body["tools"] = t.clone();
    }
    let mut attempt = 0;
    loop {
        match chat_once(cfg, &body) {
            Ok(v) => return Ok(v),
            Err(e) if e.retry && attempt < RETRY_WAITS.len() => {
                let wait = e.wait.unwrap_or(RETRY_WAITS[attempt]);
                attempt += 1;
                for left in (1..=wait).rev() {
                    if cancel.load(Ordering::Relaxed) {
                        return Err("Interrupted".into());
                    }
                    send(AgentEvent::Status(format!("Service busy, trying again in {left}s (attempt {})", attempt + 1)));
                    std::thread::sleep(Duration::from_secs(1));
                }
            }
            Err(e) => return Err(e.msg),
        }
    }
}

