        let history = vec![Message::new(Role::User, "Read README.md in the project and tell me exactly what it says.")];
        let (tx, rx) = channel();
        let cancel = AtomicBool::new(false);
        let t = std::thread::spawn(move || run_loop(cfg, history, &cancel, &move |e| { let _ = tx.send(e); }));
        let mut tools = vec![];
        let mut last = String::new();
        while let Ok(e) = rx.recv_timeout(Duration::from_secs(240)) {
            match e {
                AgentEvent::ToolResult { name, ok, .. } => tools.push((name, ok)),
                AgentEvent::Assistant { text, .. } if !text.is_empty() => last = text,
                AgentEvent::Permission(p) => { let _ = p.reply.send(PermReply::Once); }
                AgentEvent::Status(s) => eprintln!("status: {s}"),
                _ => {}
            }
        }
        t.join().unwrap().unwrap();
        eprintln!("tools: {tools:?}\\nanswer: {last}");
        assert!(tools.iter().any(|(n, ok)| n == "read" && *ok));
        assert!(last.to_lowercase().contains("hello world"));
    }
}
