/// One place answers can come from.
#[derive(Clone, Debug)]
pub struct Endpoint {
    pub name: String,
    pub base_url: String,
    pub api_key: String,
    pub model: String,
}

/// Waits before trying a source again after a passing failure, in seconds.
pub const RETRY_WAITS: &[u64] = &[2, 5, 10, 20, 30];
/// How long to rest a source that is rate-limited but gave no time.
pub const DEFAULT_THROTTLE_SECS: u64 = 20;
/// Longest total time one request may spend waiting for a free source.
pub const MAX_WAIT_SECS: u64 = 30 * 60;

#[derive(Debug, PartialEq)]
enum Failure {
    /// Busy or rate-limited: usable again after this many seconds.
    Throttled(u64),
    /// Out of allowance, missing key, unknown model: skip it for this request.
    Exhausted,
    /// Network trouble or a server hiccup: try again soon.
    Transient,
}

struct ChatError {
    msg: String,
    kind: Failure,
}

/// Decide what an error means for switching sources.
fn classify(status: u16, msg: &str, retry_after: Option<u64>) -> Failure {
    let lower = msg.to_lowercase();
    let said_wait = regex::Regex::new(r"(?i)(?:retry after|try again in|retry in)\s*(\d+(?:\.\d+)?)\s*s")
        .ok()
        .and_then(|re| re.captures(msg))
        .and_then(|c| c[1].parse::<f64>().ok())
        .map(|v| v.ceil() as u64);
    let wait = retry_after.or(said_wait);
    let out_of_allowance = lower.contains("freeusagelimit")
        || lower.contains("usage limit")
        || lower.contains("quota")
        || lower.contains("limit reached")
        || lower.contains("insufficient");
    match (status, wait) {
        (429, w) => Failure::Throttled(w.unwrap_or(DEFAULT_THROTTLE_SECS).clamp(1, 600)),
        (402, Some(w)) => Failure::Throttled(w.clamp(1, 600)),
        (_, Some(w)) if out_of_allowance => Failure::Throttled(w.clamp(1, 600)),
        _ if out_of_allowance => Failure::Exhausted,
        (408 | 409 | 425, _) => Failure::Transient,
        (s, _) if s >= 500 => Failure::Transient,
        _ => Failure::Exhausted,
    }
}

fn chat_once(ep: &Endpoint, body: &Value) -> Result<Value, ChatError> {
    let url = format!("{}/chat/completions", ep.base_url.trim().trim_end_matches('/'));
    let mut body = body.clone();
    body["model"] = Value::String(ep.model.clone());
    let mut req = ureq::post(&url)
        .config()
        .http_status_as_error(false)
        .timeout_global(Some(Duration::from_secs(600)))
        .build()
        .header("Content-Type", "application/json");
    if !ep.api_key.trim().is_empty() {
        req = req.header("Authorization", &format!("Bearer {}", ep.api_key.trim()));
    }
    let mut resp = req
        .send_json(&body)
        .map_err(|e| ChatError { msg: format!("Couldn't reach {}: {e}", ep.name), kind: Failure::Transient })?;
    let status = resp.status().as_u16();
    let retry_after = resp
        .headers()
        .get("retry-after")
        .and_then(|v| v.to_str().ok())
        .and_then(|v| v.trim().parse::<f64>().ok())
        .map(|v| v.ceil().max(1.0) as u64);
    let text = resp
        .body_mut()
        .read_to_string()
        .map_err(|e| ChatError { msg: format!("Couldn't read the answer from {}: {e}", ep.name), kind: Failure::Transient })?;
    let parsed = serde_json::from_str::<Value>(&text).ok();
    // Some services report errors with a 200 status.
    let err_msg = parsed.as_ref().and_then(|v| {
        if v["choices"].is_array() {
            return None;
        }
        v["error"]["message"].as_str().or(v["error"].as_str()).or(v["message"].as_str()).map(String::from)
    });
    if status >= 400 || err_msg.is_some() {
        let msg = err_msg.unwrap_or_else(|| text.chars().take(400).collect());
        let kind = classify(if status >= 400 { status } else { 400 }, &msg, retry_after);
        return Err(ChatError { msg: format!("{} answered {status}: {msg}", ep.name), kind });
    }
    parsed.ok_or_else(|| ChatError { msg: format!("The answer from {} wasn't readable", ep.name), kind: Failure::Transient })
}

pub fn endpoints(cfg: &RunConfig) -> Vec<Endpoint> {
    if !cfg.endpoints.is_empty() {
        return cfg.endpoints.clone();
    }
    vec![Endpoint {
        name: "The AI service".into(),
        base_url: cfg.base_url.clone(),
        api_key: cfg.api_key.clone(),
        model: cfg.model.clone(),
    }]
}

