                if n > 1 {
                    msg.push_str("\n\nEvery free source is used up for now. Add a free key (Gemini, Groq or OpenRouter) in Settings → Models, or install Ollama for unlimited use on this computer.");
                } else if cfg.api_key.trim().is_empty() && msg.contains(" 40") {
                    msg.push_str("\n\nThis service may need a key: add one in Settings → Models, or pick \"Free (automatic)\".");
                }
                return Err(msg);
            }
            if started.elapsed().as_secs() > MAX_WAIT_SECS {
                return Err(format!("Waited {} minutes for a free source.\n{}", MAX_WAIT_SECS / 60, errors.join("\n")));
            }
            // Everyone left is resting: wait for the first one to be ready again.
            let (soon_k, soon) = (0..n)
                .filter(|&k| !dead[k])
                .filter_map(|k| ready_at[k].map(|t| (k, t)))
                .min_by_key(|(_, t)| *t)
                .unwrap();
            let gap = soon.saturating_duration_since(now);
            send(AgentEvent::Status(format!("Free limit: waiting {}s for {}", gap.as_secs().max(1), eps[soon_k].name)));
            std::thread::sleep(gap.min(Duration::from_millis(1000)) + Duration::from_millis(20));
            continue;
        };
        if k != current || tries[k] > 0 {
            send(AgentEvent::Status(format!("Asking {}", eps[k].name)));
        }
        current = k;
        cfg.current = k;
        match chat_once(&eps[k], &body) {
            Ok(v) => {
                send(AgentEvent::Source(format!("{} · {}", eps[k].name, eps[k].model)));
                return Ok(v);
            }
            Err(e) => {
                errors[k] = e.msg;
                match e.kind {
                    Failure::Throttled(secs) => ready_at[k] = Some(Instant::now() + Duration::from_secs(secs)),
                    Failure::Exhausted => dead[k] = true,
                    Failure::Transient => {
                        if tries[k] >= RETRY_WAITS.len() {
                            dead[k] = true;
                        } else {
                            ready_at[k] = Some(Instant::now() + Duration::from_secs(RETRY_WAITS[tries[k]]));
                        }
                    }
                }
                tries[k] += 1;
                // try the next source first
                current = (k + 1) % n;
            }
        }
    }
}

