fn chat(cfg: &mut RunConfig, messages: &[Value], tools: Option<&Value>, cancel: &AtomicBool, send: &dyn Fn(AgentEvent)) -> Result<Value, String> {
    let eps = endpoints(cfg);
    if eps.iter().all(|e| e.base_url.trim().is_empty()) {
