                send(AgentEvent::Source(format!("{} · {}", eps[k].name, eps[k].model)));
                return Ok(v);
            }
            Err(e) => {
                errors[k] = e.msg;
                match e.kind {
                    Failure::Throttled(secs) => ready_at[k] = Some(Instant::now() + Duration::from_secs(secs)),
